check('K1 leyendas: 16-24 inventadas, sin handles de pros reales ni generables por el motor, con rol, región y perfil válidos', () => {
  const minimo = 16;
  const maximo = 24;
  if (!Array.isArray(LEYENDAS_K1) || LEYENDAS_K1.length < minimo || LEYENDAS_K1.length > maximo) {
    throw new Error(`hay ${LEYENDAS_K1?.length} leyendas: tienen que ser entre ${minimo} y ${maximo}`);
  }
  const reales = new Set(HANDLES_REALES_K1.map((handle) => handle.toLowerCase()));
  const regiones = new Set(LIGAS.map((liga) => liga.region));
  const ids = new Set();
  const handles = new Set();
  // Lo que puede escupir `generarHandle`: prefijo + sufijo (+ número), o el fallback prefijo + número.
  const generable = (handle) => PREFIJOS_HANDLE.some((prefijo) => SUFIJOS_HANDLE.some((sufijo) => {
    const base = `${prefijo}${sufijo}`.toLowerCase();
    return handle.toLowerCase().startsWith(base) && /^\d*$/.test(handle.slice(base.length));
  })) || PREFIJOS_HANDLE.some((prefijo) => new RegExp(`^${prefijo}\\d+$`, 'i').test(handle));
  for (const leyenda of LEYENDAS_K1) {
    const donde = `leyenda ${leyenda.id}`;
    if (typeof leyenda.id !== 'string' || ids.has(leyenda.id)) {
      throw new Error(`${donde}: id inválido o repetido`);
    }
    ids.add(leyenda.id);
    if (typeof leyenda.handle !== 'string' || leyenda.handle.trim() === '' || handles.has(leyenda.handle.toLowerCase())) {
      throw new Error(`${donde}: handle inválido o repetido`);
    }
    handles.add(leyenda.handle.toLowerCase());
    if (reales.has(leyenda.handle.toLowerCase())) {
      throw new Error(`${donde}: "${leyenda.handle}" es el handle de un pro real`);
    }
    if (generable(leyenda.handle)) {
      throw new Error(`${donde}: "${leyenda.handle}" lo puede generar el motor (core/mundo.js, generarHandle)`);
    }
    if (!IDS_ROL.includes(leyenda.rol)) {
      throw new Error(`${donde}: rol "${leyenda.rol}" no es uno de ${IDS_ROL.join(', ')}`);
    }
    if (!regiones.has(leyenda.region)) {
      throw new Error(`${donde}: región "${leyenda.region}" no es una de leagues.json`);
    }
    for (const campo of ['anios', 'titulos', 'internacionales', 'rankPico']) {
      if (!Number.isInteger(leyenda[campo]) || leyenda[campo] < 0) {
        throw new Error(`${donde}: ${campo} = ${leyenda[campo]}`);
      }
    }
    if (leyenda.rankPico > BALANCE.topMundial.tamano) {
      throw new Error(`${donde}: rankPico ${leyenda.rankPico} fuera del Top ${BALANCE.topMundial.tamano}`);
    }
    if (typeof leyenda.historia !== 'string' || leyenda.historia.length < 40) {
      throw new Error(`${donde}: sin una línea de historia`);
    }
  }
  for (const rol of IDS_ROL) {
    if (!LEYENDAS_K1.some((leyenda) => leyenda.rol === rol)) {
      throw new Error(`ninguna leyenda juega de ${rol}`);
    }
  }
  // La red funciona: un handle real (en otra caja) y uno generable se detectan, y una leyenda no da falso positivo.
  if (!reales.has('FAKER'.toLowerCase()) || !generable('Kaken42') || !generable('Zen7') || generable(LEYENDAS_K1[0].handle)) {
    throw new Error('la detección de handles reales o generables no funciona');
  }
});

check('K1 leyenda comparada: la del perfil exacto de tu rol es esa misma, el empate se rompe por id, el rank pesa, y el perfil cuenta solo títulos de primera', () => {
  for (const leyenda of LEYENDAS_K1) {
    const perfil = { anios: leyenda.anios, titulos: leyenda.titulos, internacionales: leyenda.internacionales, rankPico: leyenda.rankPico };
    const elegida = leyendaMasCercana(perfil, leyenda.rol);
    if (elegida.id !== leyenda.id) {
      throw new Error(`una carrera de ${leyenda.rol} con el perfil exacto de ${leyenda.handle} se compara con ${elegida.handle}`);
    }
  }
  // Empate: dos leyendas sin carrera pro de otros roles, a la misma distancia de alguien de un tercer rol que no
  // llegó. Con el archivo dado vuelta tiene que salir la misma: el desempate es por `id`, no por el orden.
  const perfilVacio = { anios: 0, titulos: 0, internacionales: 0, rankPico: 0 };
  const vacias = LEYENDAS_K1.filter((l) => l.anios === 0 && l.titulos === 0 && l.internacionales === 0 && l.rankPico === 0);
  const rolDeAfuera = vacias.length >= 2 ? IDS_ROL.find((rol) => vacias.every((l) => l.rol !== rol)
    && LEYENDAS_K1.filter((l) => l.rol === rol).every((l) => leyendaMasCercana(perfilVacio, rol).id !== l.id)) : undefined;
  if (!rolDeAfuera) {
    throw new Error('check vacío: no hay un rol cuya leyenda más cercana sin carrera pro empate entre dos de otros roles');
  }
  const normal = leyendaMasCercana(perfilVacio, rolDeAfuera).id;
  const esperado = vacias.map((l) => l.id).sort()[0];
  LEYENDAS_K1.reverse();
  let alReves;
  try {
    alReves = leyendaMasCercana(perfilVacio, rolDeAfuera).id;
  } finally {
    LEYENDAS_K1.reverse();
  }
  if (normal !== esperado || alReves !== esperado) {
    throw new Error(`el empate se rompe por id (${esperado}): dio ${normal}, y con el archivo dado vuelta ${alReves}`);
  }
  // El eje del ranking pesa (mutante r17 de la revisión): con todo lo demás igual, alejarse del rank de una leyenda
  // la aleja, y acercarse la acerca. Afuera del Top 20 (0) es el extremo de abajo.
  const { tamano } = BALANCE.topMundial;
  for (const leyenda of LEYENDAS_K1) {
    const eje = (rank) => (rank > 0 ? tamano + 1 - rank : 0);
    const distancias = [0, tamano, Math.ceil(tamano / 2), 5, 2, 1]
      .map((rank) => ({ lejania: Math.abs(eje(rank) - eje(leyenda.rankPico)), d: distanciaDeLeyenda({ ...leyenda, rankPico: rank }, leyenda.rol, leyenda) }))
      .sort((a, b) => a.lejania - b.lejania);
    for (let i = 1; i < distancias.length; i += 1) {
      const [a, b] = [distancias[i - 1], distancias[i]];
      if (b.lejania > a.lejania && !(b.d > a.d)) {
        throw new Error(`${leyenda.handle}: más lejos en el ranking (${b.lejania} contra ${a.lejania} puestos de eje) no aleja la leyenda (${b.d} contra ${a.d})`);
      }
    }
  }
  // El perfil cuenta solo títulos de primera, igual que el `titulos` de las leyendas.
  const base = estadosDeReferenciaK1().find((estado) => estado.career.registro.porOrg.length > 0);
  const titulosDelPerfil = (mutar) => {
    const copia = structuredClone(base);
    mutar(copia.career.registro.titulos);
    return puntajeDeCarrera(copia).perfil.titulos;
  };
  const sinCambios = titulosDelPerfil(() => {});
  if (titulosDelPerfil((t) => t.push({ nombre: 'LCK_CL', anio: 2030, org: 'X', liga: 'LCK_CL', tier: 2 })) !== sinCambios
    || titulosDelPerfil((t) => t.push({ nombre: 'Copa', anio: 2030, org: 'X', liga: null, tier: 3 })) !== sinCambios
    || titulosDelPerfil((t) => t.push({ nombre: 'LCK', anio: 2030, org: 'X', liga: 'LCK', tier: 1 })) !== sinCambios + 1) {
    throw new Error('perfil.titulos tiene que contar solo los títulos de tier 1');
  }
});

check('K1 versión: la huella del juego (40 seeds × 60 splits, con puntaje, nivel y leyenda) coincide con HUELLA_JUEGO de src/data/version.js', () => {
  if (typeof VERSION_JUEGO !== 'string' || VERSION_JUEGO.trim() === '') {
    throw new Error(`VERSION_JUEGO inválida: ${JSON.stringify(VERSION_JUEGO)}`);
  }
  const { hash, lineas } = calcularHuellaJuego();
  if (lineas.length !== 40 || lineas.some((linea) => linea.split(':').length !== 7)) {
    throw new Error(`la huella del juego tiene que tener 40 líneas seed:fin:splitCount:elo:total:nivel:leyenda (tiene ${lineas.length})`);
  }
  if (Math.max(...lineas.map((linea) => Number(linea.split(':')[2]))) <= 30) {
    throw new Error('ninguna seed pasó de 30 splits: la huella del juego no ve la segunda mitad de la carrera');
  }
  if (hash !== HUELLA_JUEGO) {
    throw new Error(`la huella del juego cambió: actual ${hash}, registrada ${HUELLA_JUEGO} para la versión ${VERSION_JUEGO}. `
      + 'Cubre las carreras enteras (60 splits) y su puntaje: si el cambio es deliberado (un corrimiento del rng, '
      + 'balance que mueve las carreras, o BALANCE.puntaje/leyendas que mueven el número, el nivel o la leyenda), '
      + 'subí VERSION_JUEGO y registrá el hash nuevo en src/data/version.js en el mismo commit; si no, algo cambió '
      + 'sin querer (trampa T1: comparalo con `node src/dev/huella.js --contra=<árbol anterior>` y con la huella del juego del árbol anterior)');
  }
});

check('K1 dificultad: toda liga la tiene (número > 0) y cada tier 2 hereda la de la liga a la que asciende', () => {
  for (const liga of LIGAS) {
    if (typeof liga.dificultad !== 'number' || !Number.isFinite(liga.dificultad) || !(liga.dificultad > 0)) {
      throw new Error(`${liga.id}: dificultad ${JSON.stringify(liga.dificultad)}`);
    }
  }
  for (const tier2 of LIGAS.filter((liga) => liga.tier === 2)) {
    // K5-B: LRN y LRS no tienen primera arriba (`sinPrimera`): heredan la de la primera que alimentan (`alimentaA`).
    const madre = LIGAS.find((liga) => liga.tier === 1 && liga.desciendeA === tier2.id)
      ?? (tier2.sinPrimera ? LIGAS.find((liga) => liga.tier === 1 && liga.id === tier2.alimentaA) : null);
    if (!madre) {
      throw new Error(`${tier2.id}: ninguna liga tier 1 desciende ahí, no hay de quién heredar la dificultad`);
    }
    if (tier2.dificultad !== madre.dificultad) {
      throw new Error(`${tier2.id}: dificultad ${tier2.dificultad}, tiene que heredar la de ${madre.id} (${madre.dificultad})`);
    }
  }
});

// Los hechos de una carrera vacía, y los mínimos que cumplen un requisito (cada clave de requisito es un hecho,
// salvo `rankPicoHasta`, que se cumple con un pico de rank igual o mejor).
const HECHOS_VACIOS_K1 = { splitsJugados: 0, splitsTier1: 0, titulosTier1: 0, cierresEnTop20: 0, rankPico: 0, cierresNumeroUno: 0, mundialesGanados: 0 };
function hechosQueCumplenK1(requisito) {
  const hechos = { ...HECHOS_VACIOS_K1 };
  for (const [clave, n] of Object.entries(requisito)) {
    hechos[clave === 'rankPicoHasta' ? 'rankPico' : clave] = n;
  }
  return hechos;
}

// K5c-U2: los textos que ve el jugador no hacen plural con paréntesis ("14 título(s), 0 internacional(es)"): hay `plural()` en
// `core/formato.js`. Barato y estático: mira el código que arma textos (core, systems, ui y los datos de eventos), sin los
// comentarios.
check('Textos visibles: ningún plural con paréntesis ("título(s)", "internacional(es)")', () => {
  const PLURAL_CON_PARENTESIS = /[\p{L}]\((s|es)\)/u;
  const hallazgos = [];
  const recorrer = (dir) => {
    for (const entrada of fs.readdirSync(dir, { withFileTypes: true })) {
      const ruta = path.join(dir, entrada.name);
      if (entrada.isDirectory()) {
        recorrer(ruta);
      } else if (/\.(js|json)$/.test(entrada.name)) {
        fs.readFileSync(ruta, 'utf8').split('\n').forEach((linea, i) => {
          const codigo = linea.trim().startsWith('//') ? '' : linea.replace(/\s\/\/.*$/, '');
          if (PLURAL_CON_PARENTESIS.test(codigo)) {
            hallazgos.push(`${path.relative(srcDir, ruta)}:${i + 1}: ${codigo.trim().slice(0, 90)}`);
          }
        });
      }
    }
  };
  for (const carpeta of ['core', 'systems', 'ui', 'data']) {
    recorrer(path.join(srcDir, carpeta));
  }
  if (hallazgos.length > 0) {
    throw new Error(`${hallazgos.length} texto(s) con plural entre paréntesis: ${hallazgos.slice(0, 5).join(' | ')}`);
  }
});

check('K1 niveles por hechos: en orden y con requisitos válidos, cada nivel se gana justo con su requisito, gana el más alto que se cumple, el siguiente dice el hecho que faltó, y los cuantiles son crecientes', () => {
  const { niveles, cuantiles } = BALANCE.puntaje;
  if (JSON.stringify(niveles.map((n) => n.id)) !== JSON.stringify(NIVELES_K1.map((n) => n.id))) {
    throw new Error(`BALANCE.puntaje.niveles [${niveles.map((n) => n.id)}] no coincide con los niveles con nombre [${NIVELES_K1.map((n) => n.id)}]`);
  }
  if (NIVELES_K1.some((nivel) => typeof nivel.nombre !== 'string' || nivel.nombre.length === 0)) {
    throw new Error('un nivel no tiene nombre');
  }
  if (Object.keys(niveles[0].requisito).length !== 0) {
    throw new Error(`"${niveles[0].id}" es el piso: no puede pedir nada (pide ${JSON.stringify(niveles[0].requisito)})`);
  }
  // K5c: un nivel puede tener una `alternativa` (otra lista de hechos que también lo gana): "El GOAT".
  const caminosK1 = (nivel) => (nivel.alternativa ? [nivel.requisito, nivel.alternativa] : [nivel.requisito]);
  for (const nivel of niveles.slice(1)) {
    for (const requisito of caminosK1(nivel)) {
      const claves = Object.keys(requisito);
      if (claves.length === 0 || claves.some((clave) => !HECHOS_DE_REQUISITO.includes(clave) || !Number.isInteger(requisito[clave]) || requisito[clave] < 1)) {
        throw new Error(`${nivel.id}: requisito ${JSON.stringify(requisito)} (hechos válidos: ${HECHOS_DE_REQUISITO.join(', ')}, mínimos enteros >= 1)`);
      }
    }
  }
  if (niveles[0].alternativa !== undefined) {
    throw new Error(`"${niveles[0].id}" es el piso: no tiene alternativa`);
  }
  // Los requisitos son los de la tabla de PLAN.md ("K1 — lo que cambió la revisión de K1-A"): el nombre de un nivel
  // promete ese hecho. Lo único de balance es la N de "Fijo en primera" ("del orden de 3 años": entre 2 y 4 años).
  const nFijo = niveles.find((n) => n.id === 'fijo')?.requisito.splitsTier1;
  const { splitsPorEdad } = BALANCE.edad;
  if (!(nFijo >= 2 * splitsPorEdad && nFijo <= 4 * splitsPorEdad)) {
    throw new Error(`"Fijo en primera" pide ${nFijo} splits en primera: tiene que ser del orden de 3 años (${2 * splitsPorEdad}-${4 * splitsPorEdad})`);
  }
  const TABLA_DEL_PLAN_K1 = {
    no_llego: {}, circuito: { splitsJugados: 1 }, profesional: { splitsTier1: 1 }, fijo: { splitsTier1: nFijo },
    campeon: { titulosTier1: 1 }, figura: { cierresEnTop20: 1 }, leyenda: { titulosTier1: 3, rankPicoHasta: 5 },
    goat: { cierresNumeroUno: 3 }
  };
  // K5c: "El GOAT" es el nuevo Faker de §K.3b: también lo gana quien gana 2 o más Mundiales. Ningún otro nivel tiene alternativa.
  const ALTERNATIVAS_DEL_PLAN_K1 = { goat: { mundialesGanados: 2 } };
  const ordenado = (objeto) => JSON.stringify(Object.keys(objeto ?? {}).sort().map((clave) => [clave, objeto[clave]]));
  for (const nivel of niveles) {
    if (ordenado(nivel.requisito) !== ordenado(TABLA_DEL_PLAN_K1[nivel.id])) {
      throw new Error(`${nivel.id} pide ${JSON.stringify(nivel.requisito)} y la tabla de PLAN.md dice ${JSON.stringify(TABLA_DEL_PLAN_K1[nivel.id])}`);
    }
    if (ordenado(nivel.alternativa) !== ordenado(ALTERNATIVAS_DEL_PLAN_K1[nivel.id])) {
      throw new Error(`${nivel.id} tiene la alternativa ${JSON.stringify(nivel.alternativa ?? null)} y la tabla de PLAN.md dice ${JSON.stringify(ALTERNATIVAS_DEL_PLAN_K1[nivel.id] ?? null)}`);
    }
  }
  // Bordes: los hechos mínimos de cada nivel dan ese nivel; un escalón menos en cualquiera de sus requisitos, uno
  // más bajo. El siguiente nombra lo que faltó, en palabras y sin puntos.
  niveles.forEach((nivel, i) => {
    for (const requisito of caminosK1(nivel)) {
      const justoDelCamino = hechosQueCumplenK1(requisito);
      if (nivelDeCarrera(justoDelCamino).id !== nivel.id) {
        throw new Error(`con los hechos justos de ${nivel.id} (${JSON.stringify(justoDelCamino)}) el nivel es ${nivelDeCarrera(justoDelCamino).id}`);
      }
      for (const [clave, n] of Object.entries(requisito)) {
        const peores = clave === 'rankPicoHasta' ? [{ ...justoDelCamino, rankPico: n + 1 }, { ...justoDelCamino, rankPico: 0 }] : [{ ...justoDelCamino, [clave]: n - 1 }];
        for (const peor of peores) {
          if (INDICE_NIVEL_K1[nivelDeCarrera(peor).id] >= i) {
            throw new Error(`a ${nivel.id} le falta ${clave} (${JSON.stringify(peor)}) y el nivel sigue siendo ${nivelDeCarrera(peor).id}`);
          }
        }
      }
    }
    const justo = hechosQueCumplenK1(nivel.requisito);
    const dado = nivelDeCarrera(justo);
    const siguiente = niveles[i + 1];
    if (!siguiente) {
      if (dado.siguiente !== null) {
        throw new Error(`${nivel.id} es el techo: no tiene siguiente`);
      }
      return;
    }
    if (dado.siguiente?.id !== siguiente.id || dado.siguiente.nombre !== NIVELES_K1[i + 1].nombre) {
      throw new Error(`el siguiente de ${nivel.id} tiene que ser ${siguiente.id}, dio ${JSON.stringify(dado.siguiente)}`);
    }
    const texto = dado.siguiente.requisito;
    if (typeof texto !== 'string' || !/^Te falt(ó|aron) .+\.$/.test(texto) || /\bpts\b|puntos/.test(texto)) {
      throw new Error(`lo que faltó para ${siguiente.id} tiene que decirse como hecho ("Te faltó …."), sin puntos: "${texto}"`);
    }
  });
  // Gana el más alto que se cumple: no son escalones anidados.
  const soloTop20 = nivelDeCarrera({ ...HECHOS_VACIOS_K1, cierresEnTop20: 1 }).id;
  if (soloTop20 !== 'figura') {
    throw new Error(`un cierre en el Top 20 sin nada más tiene que ser "figura" (gana el más alto que se cumple), dio ${soloTop20}`);
  }
  // Más de cualquier hecho nunca baja el nivel.
  for (const base of niveles.map((nivel) => hechosQueCumplenK1(nivel.requisito))) {
    for (const clave of Object.keys(HECHOS_VACIOS_K1)) {
      const valores = clave === 'rankPico'
        ? [0, BALANCE.topMundial.tamano, 10, 5, 3, 2, 1]
        : Array.from({ length: 13 }, (_, v) => v);
      let anterior = -1;
      for (const valor of valores) {
        const indice = INDICE_NIVEL_K1[nivelDeCarrera({ ...base, [clave]: valor }).id];
        if (indice < anterior) {
          throw new Error(`con más ${clave} (${valor}) el nivel bajó desde ${JSON.stringify(base)}`);
        }
        anterior = indice;
      }
    }
  }
  // Cuantiles: arrancan en el percentil 0, crecen, y el percentil es monótono e interpola.
  if (cuantiles[0][0] !== 0 || cuantiles.some(([p, x], i) => i > 0 && !(p > cuantiles[i - 1][0] && x >= cuantiles[i - 1][1]))) {
    throw new Error(`la tabla de cuantiles tiene que arrancar en el percentil 0 y crecer: ${JSON.stringify(cuantiles)}`);
  }
  const techo = 2 * cuantiles[cuantiles.length - 1][1];
  let percentilAnterior = -1;
  for (let total = 0; total <= techo; total += 1) {
    const percentilActual = percentilDePuntaje(total);
    if (percentilActual < percentilAnterior || !Number.isInteger(percentilActual)
      || percentilActual < cuantiles[0][0] || percentilActual > cuantiles[cuantiles.length - 1][0]) {
      throw new Error(`con ${total} puntos el percentil es ${percentilActual} (no monótono o fuera de rango)`);
    }
    percentilAnterior = percentilActual;
  }
  for (let i = 1; i < cuantiles.length; i += 1) {
    const [pPrevio, xPrevio] = cuantiles[i - 1];
    const [p, x] = cuantiles[i];
    if (x > xPrevio) {
      const medio = (xPrevio + x) / 2;
      const esperado = Math.floor(pPrevio + (p - pPrevio) * ((medio - xPrevio) / (x - xPrevio)));
      if (percentilDePuntaje(medio) !== esperado) {
        throw new Error(`entre ${xPrevio} y ${x} puntos el percentil tiene que interpolar (${esperado}), dio ${percentilDePuntaje(medio)}`);
      }
    }
  }
  const [pPrimero, xPrimero] = cuantiles[0];
  const [pUltimo, xUltimo] = cuantiles[cuantiles.length - 1];
  if (percentilDePuntaje(xPrimero) !== pPrimero || percentilDePuntaje(xUltimo + 1) !== pUltimo) {
    throw new Error(`los extremos de la tabla de cuantiles son ${pPrimero} y ${pUltimo}: dio ${percentilDePuntaje(xPrimero)} y ${percentilDePuntaje(xUltimo + 1)}`);
  }
});

// ============================================================================
// K1-B — La pantalla del número (PLAN.md §K1, "K1 — decisiones de spec",
// Pantalla). La tarjeta y el inicio son DOM y se miran en un navegador; lo que
// se prueba acá es la lógica pura que comparten (`src/ui/resultado.js`): el
// texto para compartir, el link, la fecha del desafío y el historial local,
// que nunca puede romper la página aunque el `localStorage` falle.
// ============================================================================

const resultadoK1B = await import('../ui/resultado.js');

// Un estado mínimo con lo único que leen el texto y el historial.
function estadoK1B({ seed = 777, fecha = null, total = 1512, nivel = 'Campeón' } = {}) {
  return {
    seed,
    desafio: fecha ? { fecha } : null,
    player: { role: 'mid', name: 'Prueba' },
    tarjeta: { puntaje: { total, nivel: { id: 'campeon', nombre: nivel } } }
  };
}

check('K1-B compartir: el texto lleva juego, fecha del desafío, puntaje con miles, nivel, versión y el link del desafío; fuera del desafío, sin fecha y con el link de la seed', () => {
  const { textoParaCompartir, miles, desafioDeBusqueda, linkDeEstado } = resultadoK1B;
  const HREF = 'http://localhost:8000/?seed=9&otra=1#ancla';
  const conDesafio = textoParaCompartir(estadoK1B({ seed: seedDelDia('2026-10-02'), fecha: '2026-10-02' }), HREF);
  const esperadoDesafio = `Un Split Más · Desafío 2026-10-02 · 1.512 pts · Campeón · v ${VERSION_JUEGO} · http://localhost:8000/?desafio=2026-10-02`;
  if (conDesafio !== esperadoDesafio) {
    throw new Error(`desafío: esperaba\n  ${esperadoDesafio}\ndio\n  ${conDesafio}`);
  }
  const libre = textoParaCompartir(estadoK1B({ seed: 777 }), HREF);
  const esperadoLibre = `Un Split Más · 1.512 pts · Campeón · v ${VERSION_JUEGO} · http://localhost:8000/?seed=777`;
  if (libre !== esperadoLibre) {
    throw new Error(`carrera libre: esperaba\n  ${esperadoLibre}\ndio\n  ${libre}`);
  }
  // El link del desafío lo reproduce: la URL vuelve a dar la fecha, y la fecha la seed.
  const link = linkDeEstado(estadoK1B({ seed: seedDelDia('2024-02-29'), fecha: '2024-02-29' }), HREF);
  if (desafioDeBusqueda(new URL(link).search) !== '2024-02-29') {
    throw new Error(`el link del desafío no se lee de vuelta: ${link}`);
  }
  const casos = [[0, '0'], [999, '999'], [1000, '1.000'], [1512, '1.512'], [1234567, '1.234.567'], [-37, '−37'], [1647.6, '1.648']];
  for (const [numero, texto] of casos) {
    if (miles(numero) !== texto) {
      throw new Error(`miles(${numero}) tiene que ser "${texto}", dio "${miles(numero)}"`);
    }
  }
});

check('K1-B historial: tolera un localStorage que tira, JSON roto y formas raras; guarda a lo sumo 10 (el récord sobrevive al recorte); un desafío repetido queda en una fila con el mejor puntaje y los intentos', () => {
  const {
    leerHistorial, guardarHistorial, agregarAlHistorial, entradaDeResultado, mejorDelDesafio,
    lineaDeHistorial, historialVacio, almacenamientoLocal, CLAVE_HISTORIAL, MAX_HISTORIAL
  } = resultadoK1B;
  const enMemoria = (inicial = null) => {
    let valor = inicial;
    return { getItem: (clave) => (clave === CLAVE_HISTORIAL ? valor : null), setItem: (clave, v) => { valor = String(v); } };
  };
  const vacio = JSON.stringify(historialVacio());

  // 1. Un almacenamiento que tira en cada acceso, o que no existe: nada tira.
  const queTira = { getItem() { throw new Error('SecurityError'); }, setItem() { throw new Error('QuotaExceededError'); } };
  for (const almacen of [queTira, null, undefined]) {
    if (JSON.stringify(leerHistorial(almacen)) !== vacio) {
      throw new Error('con un almacenamiento que falla, leer tiene que dar el historial vacío');
    }
    if (guardarHistorial(almacen, historialVacio()) !== false) {
      throw new Error('con un almacenamiento que falla, guardar tiene que devolver false, no tirar');
    }
  }
  const descriptor = Object.getOwnPropertyDescriptor(globalThis, 'localStorage');
  Object.defineProperty(globalThis, 'localStorage', { configurable: true, get() { throw new Error('SecurityError'); } });
  try {
    if (almacenamientoLocal() !== null) {
      throw new Error('si leer window.localStorage tira, almacenamientoLocal() tiene que dar null');
    }
  } finally {
    if (descriptor) Object.defineProperty(globalThis, 'localStorage', descriptor);
    else delete globalThis.localStorage;
  }

  // 2. JSON roto, otra forma, entradas con basura: vacío o filtrado, nunca a medias.
  const entradaValida = entradaDeResultado(estadoK1B({ seed: 5, total: 300 }), '2026-10-01');
  for (const crudo of ['{roto', '"texto"', 'null', '{"forma":1,"entradas":"x"}', '{"forma":99,"entradas":[]}', '[]']) {
    if (JSON.stringify(leerHistorial(enMemoria(crudo))) !== vacio) {
      throw new Error(`lo guardado ${crudo} tiene que leerse como historial vacío`);
    }
  }
  const mezclado = leerHistorial(enMemoria(JSON.stringify({
    forma: 1, entradas: [entradaValida, { total: 'mucho' }, null, { ...entradaValida, desafio: '2026-02-30' }], record: { total: 1 }
  })));
  if (mezclado.entradas.length !== 1 || mezclado.entradas[0].total !== 300 || mezclado.record !== null) {
    throw new Error(`las entradas inválidas se descartan una por una: quedó ${JSON.stringify(mezclado)}`);
  }

  // 3. A lo sumo MAX_HISTORIAL, lo último primero, y el récord sobrevive al recorte.
  let historial = historialVacio();
  const totales = [2000, ...Array.from({ length: MAX_HISTORIAL + 1 }, (_, i) => 100 + i)];
  totales.forEach((total, i) => {
    historial = agregarAlHistorial(historial, entradaDeResultado(estadoK1B({ seed: 1000 + i, total }), '2026-10-02'));
  });
  if (historial.entradas.length !== MAX_HISTORIAL) {
    throw new Error(`el historial tiene que guardar ${MAX_HISTORIAL}, guardó ${historial.entradas.length}`);
  }
  if (historial.entradas[0].seed !== 1000 + totales.length - 1) {
    throw new Error('lo más reciente tiene que ir primero');
  }
  if (historial.entradas.some((e) => e.total === 2000) || historial.record?.total !== 2000) {
    throw new Error(`el récord (2000) quedó afuera de los últimos ${MAX_HISTORIAL} y tiene que sobrevivir aparte: ${JSON.stringify(historial.record)}`);
  }
  const almacen = enMemoria();
  if (!guardarHistorial(almacen, historial) || JSON.stringify(leerHistorial(almacen)) !== JSON.stringify(historial)) {
    throw new Error('guardar y volver a leer tiene que dar el mismo historial');
  }

  // 4. El mismo desafío, tres veces: una sola fila, el mejor puntaje, 3 intentos.
  const FECHA = '2026-10-02';
  const intento = (total, jugadoEn) => entradaDeResultado(estadoK1B({ seed: seedDelDia(FECHA), fecha: FECHA, total }), jugadoEn);
  let h = historialVacio();
  const lineas = [];
  for (const [total, dia] of [[800, '2026-10-02'], [1200, '2026-10-03'], [900, '2026-10-04']]) {
    lineas.push(lineaDeHistorial(h, intento(total, dia)));
    h = agregarAlHistorial(h, intento(total, dia));
  }
  const filas = h.entradas.filter((e) => e.desafio === FECHA);
  if (filas.length !== 1 || filas[0].total !== 1200 || filas[0].intentos !== 3 || filas[0].jugadoEn !== '2026-10-04') {
    throw new Error(`un desafío repetido tiene que quedar en una fila con el mejor (1200), 3 intentos y el último día: ${JSON.stringify(filas)}`);
  }
  if (mejorDelDesafio(h, FECHA)?.total !== 1200 || mejorDelDesafio(h, '2026-10-03') !== null) {
    throw new Error('mejorDelDesafio tiene que devolver la fila de esa fecha, y null si no se jugó');
  }
  if (!/^Primer intento/.test(lineas[0]) || !/Mejoraste.*antes 800 pts\. Intento 2\./.test(lineas[1])
    || !/sigue siendo 1\.200 pts \(Campeón\)\. Intento 3\./.test(lineas[2])) {
    throw new Error(`las líneas de la tarjeta no comparan bien con tu marca: ${JSON.stringify(lineas)}`);
  }
  // Con otra versión es otro juego: fila aparte.
  const otraVersion = agregarAlHistorial(h, { ...intento(50, '2026-10-05'), version: `${VERSION_JUEGO}-otra` });
  if (otraVersion.entradas.filter((e) => e.desafio === FECHA).length !== 2) {
    throw new Error('el mismo desafío con otra versión tiene que ir en una fila aparte');
  }
  // Carrera libre: sin récord no hay línea; contra el récord, sube o no.
  const libre = (total) => entradaDeResultado(estadoK1B({ seed: 1, total }), '2026-10-02');
  const conRecord = agregarAlHistorial(historialVacio(), libre(1000));
  if (lineaDeHistorial(historialVacio(), libre(10)) !== null
    || !/^Nuevo récord personal: superaste tus 1\.000 pts/.test(lineaDeHistorial(conRecord, libre(1001)))
    || !/^Tu récord personal: 1\.000 pts/.test(lineaDeHistorial(conRecord, libre(1000)))) {
    throw new Error('la línea del récord personal no compara bien');
  }
});

check('K1-B URL y fecha: ?desafio= válido se lee e inválido se ignora; la fecha de hoy es la del día UTC aunque el huso local sea otro', () => {
  const { desafioDeBusqueda, fechaUTC } = resultadoK1B;
  const casos = [
    ['?desafio=2026-10-02', '2026-10-02'], ['?seed=5&desafio=2024-02-29', '2024-02-29'], ['?desafio=2026-02-30', null],
    ['?desafio=2025-02-29', null], ['?desafio=hoy', null], ['?desafio=2026-10-2', null], ['?seed=5', null], ['', null]
  ];
  for (const [busqueda, esperado] of casos) {
    if (desafioDeBusqueda(busqueda) !== esperado) {
      throw new Error(`desafioDeBusqueda(${JSON.stringify(busqueda)}) tiene que ser ${esperado}, dio ${desafioDeBusqueda(busqueda)}`);
    }
  }
  // 01:30 UTC del 2 de octubre es todavía 1 de octubre en Buenos Aires: el
  // desafío es el del 2 (la misma fecha para todos), no el del huso local.
  const tzAntes = process.env.TZ;
  process.env.TZ = 'America/Argentina/Buenos_Aires';
  try {
    const madrugada = new Date(Date.UTC(2026, 9, 2, 1, 30));
    if (madrugada.getDate() !== 1) {
      throw new Error('el huso de prueba no se aplicó: el check no estaría probando nada');
    }
    if (fechaUTC(madrugada) !== '2026-10-02') {
      throw new Error(`fechaUTC tiene que dar el día UTC (2026-10-02), dio ${fechaUTC(madrugada)}`);
    }
  } finally {
    if (tzAntes === undefined) delete process.env.TZ;
    else process.env.TZ = tzAntes;
  }
});

// ============================================================================
// FASE K, K2a — El instrumento corregido (PLAN.md "K2 — lo que midió la investigación", viñeta K2a)
// ============================================================================
// Cuidan al INSTRUMENTO de K2, no al juego: que las filas corregidas de `simulate.js` (`temporadasData`, una por temporada
// jugada) y las de serie (`seriesData`, el Bo5 medido en el motor) sean lo que el motor usó. La verdad sale de un ESPÍA
// sobre el `aplicar` real de `temporada` y de `serie` (una envoltura puesta en `ETAPAS_SPLIT` solo mientras dura la
// corrida: misma llamada, mismos argumentos, mismo `rng`), con cálculos escritos acá aparte de `simulate.js`. Cada uno se
// verificó en rojo contra un mutante del observador o de lo que el motor expone (regla de proceso 7; la tabla está en el
// reporte de K2a). Las metas de K2 NO son checks: van en `nivel.metasK2` (ver `simulate.js`).

// Corre `correr()` con el `aplicar` del sistema `sistemaId` envuelto: `alAplicar(estadoDeEntrada, resultado)` ve cada
// llamada. Restaura el sistema original SIEMPRE.
function conEspiaDeSistemaK2a(sistemaId, alAplicar, correr) {
  const indice = ETAPAS_SPLIT.findIndex((sistema) => sistema.id === sistemaId);
  const original = ETAPAS_SPLIT[indice];
  ETAPAS_SPLIT[indice] = {
    ...original,
    aplicar: (state, rng) => {
      const resultado = original.aplicar(state, rng);
      alAplicar(state, resultado);
      return resultado;
    }
  };
  try {
    return correr();
  } finally {
    ETAPAS_SPLIT[indice] = original;
  }
}

// La media de nivel de la liga de la temporada como la midió la investigación de K2 (`k2inv/probe.mjs`): en el ARRANQUE
// de la temporada, la liga de `career.liga` (o la que tiene a tu org), sobre todos los jugadores de los planteles de sus
// orgs; sin liga en `mundo.ligas` o sin planteles, la constante `nivelLigaPorDefecto` y "no modelada".
function mediaDeLigaK2a(state, org) {
  const ligas = state.mundo.ligas ?? [];
  const liga = ligas.find((l) => l.id === state.career.liga) ?? ligas.find((l) => (l.orgs ?? []).some((o) => o.nombre === org));
  const niveles = (liga?.orgs ?? [])
    .flatMap((o) => Object.values(state.mundo.planteles?.[o.nombre] ?? {}))
    .filter((jugador) => typeof jugador?.nivel === 'number')
    .map((jugador) => jugador.nivel);
  return niveles.length > 0
    ? { media: mediaK0(niveles), modelada: true }
    : { media: BALANCE.mercado.nivelLigaPorDefecto, modelada: false };
}

// K2b — el nivel medio de los compañeros como lo define el motor desde K2b, reimplementado SIN las funciones del motor:
// en una liga modelada, el plantel ACTUAL de tu org menos el puesto de tu rol; sin plantel, el snapshot de `roster`.
function nivelDeCompanerosIndependienteK2b(state) {
  const plantel = state.mundo.planteles?.[state.career.currentOrg];
  const lista = plantel
    ? Object.entries(plantel).filter(([rol]) => rol !== state.player.role).map(([, npc]) => npc)
    : state.career.companeros;
  return lista.reduce((suma, c) => suma + c.nivel, 0) / lista.length;
}

// K2b — la fuerza de un partido reconstruida desde sus partes, con la fórmula de K2b y sin `fuerzaDelEquipo`: los
// compañeros pesan `1 − pesoJugadorEnEquipo`, tu rendimiento (acotado a 0-100) `pesoJugadorEnEquipo`, y la sinergia
// multiplica al equipo entero, centrada en `sinergiaReferencia`.
function fuerzaDesdeCamposK2b(nivelCompaneros, rendimientoSinAcotar, sinergia) {
  const r = BALANCE.rendimiento;
  const rendimiento = Math.min(BALANCE.stats.max, Math.max(BALANCE.stats.min, rendimientoSinAcotar));
  return (nivelCompaneros * (1 - r.pesoJugadorEnEquipo) + rendimiento * r.pesoJugadorEnEquipo)
    * (1 + (sinergia - r.sinergiaReferencia) / BALANCE.stats.max * r.sinergiaPesoEnEquipo);
}

// La guarda con la que `systems/temporada.js` arranca una temporada (copiada acá a propósito: si el observador detecta
// "corrió la temporada" por otro camino, los dos tienen que coincidir).
const arrancaTemporadaK2a = (state) => state.phase === 'profesional' && Boolean(state.career.currentOrg) && state.career.companeros.length > 0;

// Una carrera con el espía de `temporada` puesto: devuelve, por temporada, lo que vio `aplicar` al arrancarla y la posición
// final de su tabla, y por cada split que cerró en la etapa profesional si corrió la temporada. Además cuenta los casos
// que separan la definición corregida de una lectura al cierre del split (para que el check no pase vacío).
function verdadDeTemporadasK2a(seed, responder, splits, casos) {
  const temporadas = [];
  const splitsPro = [];
  conEspiaDeSistemaK2a('temporada', (entrada, resultado) => {
    if (!arrancaTemporadaK2a(entrada)) {
      return;
    }
    if (resultado.state.career.temporada === entrada.career.temporada) {
      throw new Error(`seed ${seed}: la guarda de temporada pasó y no se armó una temporada nueva`);
    }
    const org = entrada.career.currentOrg;
    const { media, modelada } = mediaDeLigaK2a(entrada, org);
    // K2b: los compañeros que usa el motor son los del plantel VIVO en una liga modelada (y el snapshot si no):
    // reimplementado acá, sin las funciones del motor.
    const nivelCompaneros = nivelDeCompanerosIndependienteK2b(entrada);
    // Identidad exacta (revisión de K2a): la fuerza del split que el motor puso en la temporada se reconstruye desde
    // los campos expuestos con la fórmula de K2b — sin pasar por `fuerzaDelEquipo` —, así un motor que usa otros
    // compañeros (o los corre) sin cambiar lo que expone no pasa.
    const t = resultado.state.career.temporada;
    temporadas.push({
      split: entrada.player.splitCount,
      org,
      nivel: nivelDelJugador(entrada),
      nivelCompaneros,
      mediaLiga: media,
      ligaModelada: modelada,
      desvioFuerzaPropia: Math.abs(t.fuerzaPropia - fuerzaDesdeCamposK2b(t.nivelCompaneros, t.rendimientoBase, entrada.career.sinergia)),
      desvioRendimientoBase: Math.abs(t.rendimientoBase - rendimientoBase(entrada))
    });
  }, () => {
    const rng = mulberry32(seed);
    let state = createInitialState(seed, rng);
    for (let i = 0; i < splits && !state.terminado; i += 1) {
      const antes = temporadas.length;
      state = avanzarSplitAuto(state, rng, responder ?? undefined).state;
      const jugo = temporadas.length > antes;
      if (jugo) {
        const fila = temporadas[temporadas.length - 1];
        const t = state.career.temporada;
        fila.posNorm = t.posicion && t.tabla.length > 1 ? 1 - (t.posicion - 1) / (t.tabla.length - 1) : null;
        // Lo que daría leer todo al cierre del split (la definición de K0): ¿difiere de lo del arranque?
        const alCierre = mediaDeLigaK2a(state, fila.org);
        casos.temporadas += 1;
        casos.noModeladas += fila.ligaModelada ? 0 : 1;
        casos.mundoMovidoDespues += Math.abs(alCierre.media - fila.mediaLiga) > 1e-9 ? 1 : 0;
        casos.nivelMovidoDespues += Math.abs(nivelDelJugador(state) - fila.nivel) > 1e-9 ? 1 : 0;
        const cierre = state.career.companeros;
        const companerosAlCierre = cierre.length > 0 ? cierre.reduce((suma, c) => suma + c.nivel, 0) / cierre.length : null;
        casos.companerosMovidosDespues += companerosAlCierre !== null && Math.abs(companerosAlCierre - fila.nivelCompaneros) > 1e-9 ? 1 : 0;
      }
      if (state.phase === 'profesional') {
        splitsPro.push({ jugo, conPosicion: Boolean(state.career.posicion) && state.career.temporada?.tabla?.length > 1 });
        casos.rancias += !jugo && Boolean(state.career.posicion) && state.career.temporada?.tabla?.length > 1 ? 1 : 0;
      }
    }
  });
  return { temporadas, splitsPro };
}

// Las carreras del check: `criterio` hasta encontrar los casos que separan las definiciones (al menos 40 seeds, como mucho
// 400), y 20 de cada uno de los otros tres bots.
const SEEDS_MIN_OBSERVADOR_K2A = 40;
const SEEDS_MAX_OBSERVADOR_K2A = 400;
const SEEDS_OTROS_BOTS_OBSERVADOR_K2A = 20;
const SPLITS_OBSERVADOR_K2A = 60;

checkLento('K2a observador: las filas corregidas de simulate.js son lo que vio temporada.aplicar al arrancar cada temporada (nivel, compañeros, liga, posición), y las de K0 marcan los splits pro sin temporada', () => {
  const casos = { temporadas: 0, noModeladas: 0, mundoMovidoDespues: 0, nivelMovidoDespues: 0, companerosMovidosDespues: 0, rancias: 0 };
  const problemas = [];
  const contrastar = (bot, seed) => {
    const responder = ESTRATEGIAS_K0[bot];
    const verdad = verdadDeTemporadasK2a(seed, responder, SPLITS_OBSERVADOR_K2A, casos);
    const { observacion } = correrCarreraSimulate(seed, SPLITS_OBSERVADOR_K2A, responder);
    const donde = `${bot} seed ${seed}`;
    if (observacion.temporadasData.length !== verdad.temporadas.length) {
      problemas.push(`${donde}: ${observacion.temporadasData.length} filas corregidas, el espía vio ${verdad.temporadas.length} temporadas`);
      return;
    }
    observacion.temporadasData.forEach((fila, i) => {
      const esperado = verdad.temporadas[i];
      if (!(esperado.desvioFuerzaPropia <= 1e-9) || !(esperado.desvioRendimientoBase <= 1e-9)) {
        problemas.push(`${donde}, temporada del split ${esperado.split}: la fuerza del split no se reconstruye desde lo expuesto `
          + `(desvío de fuerzaPropia ${esperado.desvioFuerzaPropia}, de rendimientoBase ${esperado.desvioRendimientoBase})`);
      }
      const columnas = {
        split: esperado.split,
        org: esperado.org,
        nivel: esperado.nivel,
        nivelCompaneros: esperado.nivelCompaneros,
        mediaLiga: esperado.mediaLiga,
        ligaModelada: esperado.ligaModelada,
        posNorm: esperado.posNorm,
        nivelRelativoJugador: esperado.nivel - esperado.mediaLiga,
        nivelRelativoCompaneros: esperado.nivelCompaneros - esperado.mediaLiga
      };
      for (const [columna, valor] of Object.entries(columnas)) {
        const igual = typeof valor === 'number' && typeof fila[columna] === 'number'
          ? Math.abs(fila[columna] - valor) <= 1e-9
          : fila[columna] === valor;
        if (!igual) {
          problemas.push(`${donde}, temporada del split ${esperado.split}: ${columna} es ${fila[columna]}, el espía dice ${valor}`);
        }
      }
    });
    // Las filas de K0 (`splitsProData`) son una por split que cierra en la etapa profesional, y `temporadaJugada` dice si
    // en ese split corrió la temporada.
    const marcas = observacion.splitsProData.map((d) => d.temporadaJugada);
    const esperadas = verdad.splitsPro.map((d) => d.jugo);
    if (JSON.stringify(marcas) !== JSON.stringify(esperadas)) {
      problemas.push(`${donde}: splitsProData.temporadaJugada = ${JSON.stringify(marcas)}, el espía dice ${JSON.stringify(esperadas)}`);
    }
  };

  const casosQueSeparan = () => casos.noModeladas > 0 && casos.mundoMovidoDespues > 0 && casos.nivelMovidoDespues > 0 && casos.rancias > 0;
  let seedCriterio = 0;
  for (let seed = 1; seed <= SEEDS_MAX_OBSERVADOR_K2A && (seed <= SEEDS_MIN_OBSERVADOR_K2A || !casosQueSeparan()); seed += 1) {
    contrastar('criterio', seed);
    seedCriterio = seed;
    if (problemas.length > 0) {
      break;
    }
  }
  for (const bot of ['equilibrado', 'azar', 'malas']) {
    for (let seed = 1; seed <= SEEDS_OTROS_BOTS_OBSERVADOR_K2A && problemas.length === 0; seed += 1) {
      contrastar(bot, seed);
    }
  }
  if (problemas.length > 0) {
    throw new Error(`${problemas.slice(0, 4).join('; ')}${problemas.length > 4 ? ` (+${problemas.length - 4} más)` : ''}`);
  }
  // No vacío: tiene que haber temporadas de liga no modelada (tier 3), splits pro sin temporada (las filas rancias de K0),
  // temporadas en las que el nivel cambió después de arrancar, y alguna en la que el mundo se movió después (`plantel`
  // envejeciendo el mundo en el cierre de edad: el caso por el que existe `mundoDeLaTemporada`).
  if (!casosQueSeparan()) {
    throw new Error(`check vacío: en ${seedCriterio} carreras de criterio y ${SEEDS_OTROS_BOTS_OBSERVADOR_K2A} de cada otro bot, casos ${JSON.stringify(casos)}`);
  }
});

// Una carrera con los espías del Bo5: el `aplicar` de `serie` (la primera serie de cada split arranca ahí) y las
// decisiones de draft del primer mapa (cualquier ronda). En los dos lugares la fuerza que el motor expone para el
// arranque de la serie tiene que ser la de tu equipo con el campeón del split y el rendimiento determinista acotado, y la
// del rival la de su org.
// K2b: la fuerza de arranque se reconstruye con la fórmula (compañeros en vivo, sinergia una sola vez), no con
// `fuerzaDelEquipo`: un motor que corre la fuerza sin cambiar lo que expone no pasa (revisión de K2a).
const fuerzaDeArranqueK2a = (state) => fuerzaDesdeCamposK2b(
  nivelDeCompanerosIndependienteK2b(state), rendimientoBase(state), state.career.sinergia
);
const fuerzaDeOrgK2a = (state, nombre) => state.mundo.ligas.flatMap((liga) => liga.orgs).find((org) => org.nombre === nombre)?.fuerza;

const SEEDS_BO5_K2A = 30;

checkLento('K2a Bo5 del motor: cada serie cerrada deja una fila con la fuerza de tu equipo y la del rival al arrancar la serie, y las filas son los logs de cierre', () => {
  const problemas = [];
  const vistos = { primeraDelSplit: 0, rondasPosteriores: 0, draftDelPrimerMapa: 0, series: 0, bo5: 0, cierresTrasPausa: 0 };
  for (const bot of ['criterio', 'malas']) {
    for (let seed = 1; seed <= SEEDS_BO5_K2A && problemas.length === 0; seed += 1) {
      const donde = `${bot} seed ${seed}`;
      // Revisión de K2a: el arranque de cada serie que se vio en curso (pausada en `aplicar`, o en el draft del mapa 1)
      // queda anotado por (split, ronda, rival), y el log de cierre de ESA serie —llegue cuando llegue— se compara
      // contra él. Antes, el cierre de una serie que había pausado no se comparaba con nada.
      const arranques = new Map();
      const claveDeSerie = (split, ronda, rival) => `${split}|${ronda}|${rival}`;
      const espiaDecisiones = (sistema, st, decision, rng) => {
        if (sistema.id === 'serie' && decision.datos?.motivo === 'plan' && !decision.datos.replan) {
          vistos.draftDelPrimerMapa += 1;
          const arranque = fuerzaDeArranqueK2a(st);
          arranques.set(claveDeSerie(st.player.splitCount, st.serie.ronda, st.serie.rival.org), arranque);
          if (Math.abs(st.serie.fuerzaInicial - arranque) > 1e-9) {
            problemas.push(`${donde}, draft del mapa 1 (${st.serie.ronda}): serie.fuerzaInicial ${st.serie.fuerzaInicial}, el arranque da ${arranque}`);
          }
        }
        const bot_ = ESTRATEGIAS_K0[bot];
        return bot_ ? bot_(sistema, st, decision, rng) : sistema.resolverAuto(st, decision, rng);
      };
      const { observacion, state } = conEspiaDeSistemaK2a('serie', (entrada, resultado) => {
        // K2c: la fuente que existe SIEMPRE, con o sin pausas de draft (el meta en 0,9-1,1 y la maestría en 0,1 dejaron al
        // draft sin pausar, y este check dependía de eso: 0 filas `draftDelPrimerMapa`). Es el estado de entrada de este
        // `aplicar`: las series que arrancan dentro de la misma llamada, cierren o queden en curso, arrancan con la
        // fuerza que ese estado da, porque entre una serie y la siguiente un mapa solo mueve el registro y ganar una ronda
        // no mueve nada. Se excluye el internacional, que arranca después de `aplicarTitulo` / `aplicarEliminacionDomestica`.
        const cierres = resultado.logs.filter((log) => log.type === 'serie' && log.postSerie === true);
        const enCurso = resultado.state.serie.activa ? resultado.state.serie : null;
        const series = [
          ...cierres.map((log) => ({ ronda: log.ronda, rival: log.rival, fuerzaInicial: log.fuerzaInicial, fuerzaRival: log.fuerzaRival, enCurso: false })),
          ...(enCurso ? [{ ronda: enCurso.ronda, rival: enCurso.rival.org, fuerzaInicial: enCurso.fuerzaInicial, fuerzaRival: enCurso.rival.fuerza, enCurso: true }] : [])
        ];
        const arranqueDeEntrada = fuerzaDeArranqueK2a(entrada);
        series.filter((serie) => serie.ronda !== 'internacional').forEach((serie, indice) => {
          if (indice === 0) {
            vistos.primeraDelSplit += 1;
          } else {
            vistos.rondasPosteriores += 1;
          }
          if (serie.enCurso) {
            arranques.set(claveDeSerie(entrada.player.splitCount, serie.ronda, serie.rival), arranqueDeEntrada);
          }
          if (Math.abs(serie.fuerzaInicial - arranqueDeEntrada) > 1e-9) {
            problemas.push(`${donde}: la serie ${serie.ronda} vs ${serie.rival} (la ${indice + 1}ª de la llamada) arranca con fuerza ${serie.fuerzaInicial}, el estado de entrada de serie da ${arranqueDeEntrada}`);
          }
          if (serie.fuerzaRival !== fuerzaDeOrgK2a(entrada, serie.rival)) {
            problemas.push(`${donde}: el rival ${serie.rival} figura con fuerza ${serie.fuerzaRival}, su org tiene ${fuerzaDeOrgK2a(entrada, serie.rival)}`);
          }
        });
      }, () => correrCarreraSimulate(seed, 60, espiaDecisiones));
      // Las filas son exactamente los logs de cierre de serie, en orden, y cada serie cerrada tiene la suya.
      const cierres = state.logs.filter((log) => log.type === 'serie' && log.postSerie === true);
      const filas = observacion.seriesData;
      const registro = state.career.registro;
      if (filas.length !== cierres.length || filas.length !== registro.seriesGanadas + registro.seriesPerdidas
        || cuentaK0(filas, (f) => f.gano) !== registro.seriesGanadas) {
        problemas.push(`${donde}: ${filas.length} filas de serie, ${cierres.length} logs de cierre, registro ${registro.seriesGanadas}-${registro.seriesPerdidas}`);
        continue;
      }
      filas.forEach((fila, i) => {
        const log = cierres[i];
        const ganadas = Math.ceil(log.formato / 2);
        const arranque = arranques.get(claveDeSerie(fila.split, log.ronda, log.rival));
        if (arranque !== undefined) {
          vistos.cierresTrasPausa += 1;
          if (Math.abs(log.fuerzaInicial - arranque) > 1e-9) {
            problemas.push(`${donde}, serie ${i} (${log.ronda} vs ${log.rival}): el log de cierre dice fuerzaInicial ${log.fuerzaInicial}, al arrancar era ${arranque}`);
          }
        }
        if (fila.ronda !== log.ronda || fila.formato !== log.formato || fila.fuerzaInicial !== log.fuerzaInicial
          || fila.fuerzaRival !== log.fuerzaRival || fila.delta !== log.fuerzaInicial - log.fuerzaRival || fila.gano !== log.gano
          || Math.max(...log.marcador) !== ganadas || log.gano !== (log.marcador[0] > log.marcador[1])
          || typeof fila.fuerzaInicial !== 'number' || !Number.isFinite(fila.delta)) {
          problemas.push(`${donde}, serie ${i}: fila ${JSON.stringify(fila)} contra el log ${JSON.stringify({ ronda: log.ronda, formato: log.formato, fuerzaInicial: log.fuerzaInicial, fuerzaRival: log.fuerzaRival, gano: log.gano, marcador: log.marcador })}`);
        }
      });
      vistos.series += filas.length;
      vistos.bo5 += cuentaK0(filas, (f) => f.formato === 5);
    }
  }
  if (problemas.length > 0) {
    throw new Error(`${problemas.slice(0, 4).join('; ')}${problemas.length > 4 ? ` (+${problemas.length - 4} más)` : ''}`);
  }
  // `draftDelPrimerMapa` ya no entra en el piso: depende de que el draft pause, y esa frecuencia la re-fija K3c. Si el draft
  // pausa, esa rama sigue comparando la fuerza del log contra la del arranque; si no, `rondasPosteriores` cubre el resto.
  if (vistos.primeraDelSplit < 20 || vistos.rondasPosteriores < 20 || vistos.bo5 < 50 || vistos.cierresTrasPausa < 20) {
    throw new Error(`check vacío: ${JSON.stringify(vistos)}`);
  }
});

// ============================================================================
// K2b — estructura (PLAN.md "K2 — lo que midió la investigación", viñeta K2b): el partido es UNA tirada contra la p
// declarada, `ruidoEfectivo` es el único lector del σ, los compañeros en vivo, el traspaso con el plantel nuevo.
// ============================================================================

// Un rng que anota cada número que entrega (el espía de "una tirada por partido").
function rngEspiaK2b(seed) {
  const base = mulberry32(seed);
  const valores = [];
  return { valores, rng: () => { const u = base(); valores.push(u); return u; } };
}

// Estados reales al arrancar una temporada (la entrada de `temporada.aplicar` cuando su guarda pasa), de carreras de
// `criterio` (seeds 1 en adelante, 40 splits), hasta `maximo`.
function entradasDeTemporadaK2b(maximo) {
  const entradas = [];
  conEspiaDeSistemaK2a('temporada', (entrada) => {
    if (arrancaTemporadaK2a(entrada) && entradas.length < maximo) {
      entradas.push(entrada);
    }
  }, () => {
    for (let seed = 1; seed <= SEEDS_MAX_K2B && entradas.length < maximo; seed += 1) {
      correrCarreraSimulate(seed, SPLITS_ENTRADAS_K2B, ESTRATEGIAS_K0.criterio);
    }
  });
  return entradas;
}

const SEEDS_MAX_K2B = 60;
const SPLITS_ENTRADAS_K2B = 40;
const ENTRADAS_TEMPORADA_K2B = 40;

check('K2b una tirada por partido: temporada.aplicar tira exactamente un rng() por fecha propia y uno por cruce ajeno, cada resultado es rng() < p con la p de probabilidadDePartido, y el rendimiento del split lo cuentan esas fechas', () => {
  const entradas = entradasDeTemporadaK2b(ENTRADAS_TEMPORADA_K2B);
  if (entradas.length < ENTRADAS_TEMPORADA_K2B) {
    throw new Error(`check vacío: solo ${entradas.length} temporadas en ${SEEDS_MAX_K2B} carreras`);
  }
  const problemas = [];
  const vistos = { fechas: 0, cruces: 0, bajas: 0 };
  // Sin fechas marcadas, la temporada entera corre en `aplicar` sin pausar ni sortear contenido: todo `rng()` que
  // consuma es de un partido.
  const marcadasOriginal = BALANCE.temporada.fechasMarcadasPorSplit;
  try {
    BALANCE.temporada.fechasMarcadasPorSplit = 0;
    entradas.forEach((entrada, i) => {
      const donde = `temporada ${i} (seed de la carrera ?, split ${entrada.player.splitCount}, ${entrada.career.currentOrg})`;
      const { rng, valores } = rngEspiaK2b(9000 + i);
      const resultado = sistemaPorId('temporada').aplicar(entrada, rng);
      const t = resultado.state.career.temporada;
      if (resultado.decision || t.activa) {
        problemas.push(`${donde}: sin fechas marcadas la temporada pausó`);
        return;
      }
      const totalCruces = t.cruces.reduce((suma, jornada) => suma + jornada.length, 0);
      if (valores.length !== t.calendario.length + totalCruces) {
        problemas.push(`${donde}: ${valores.length} rng() para ${t.calendario.length} fechas y ${totalCruces} cruces`);
        return;
      }
      // Re-jugada independiente con los mismos números: fecha propia, y después los cruces de su jornada.
      const filas = new Map();
      const sumar = (org, gano) => {
        const fila = filas.get(org) ?? { ganados: 0, perdidos: 0 };
        filas.set(org, gano ? { ...fila, ganados: fila.ganados + 1 } : { ...fila, perdidos: fila.perdidos + 1 });
      };
      let k = 0;
      let bajas = entrada.flags.fechasBajaLesion ?? 0;
      const propios = { fechas: 0, ganados: 0, esperados: 0, varianza: 0 };
      t.calendario.forEach((fecha, j) => {
        const fuerza = bajas > 0 ? t.fuerzaPropia * BALANCE.salud.factorFuerzaLesionado : t.fuerzaPropia;
        const pFecha = probabilidadDePartido(entrada, fuerza, fecha.fuerzaRival, 'fecha');
        const gano = valores[k] < pFecha;
        k += 1;
        if (bajas > 0) {
          bajas -= 1;
          vistos.bajas += 1;
        } else {
          propios.fechas += 1;
          propios.ganados += gano ? 1 : 0;
          propios.esperados += pFecha;
          propios.varianza += pFecha * (1 - pFecha);
        }
        sumar(entrada.career.currentOrg, gano);
        sumar(fecha.rival, !gano);
        vistos.fechas += 1;
        for (const cruce of t.cruces[j]) {
          const ganaLocal = valores[k] < probabilidadDePartido(null, cruce.fuerzaLocal, cruce.fuerzaVisitante, 'fecha');
          k += 1;
          sumar(cruce.local, ganaLocal);
          sumar(cruce.visitante, !ganaLocal);
          vistos.cruces += 1;
        }
      });
      for (const fila of t.tabla) {
        const esperada = filas.get(fila.org) ?? { ganados: 0, perdidos: 0 };
        if (fila.ganados !== esperada.ganados || fila.perdidos !== esperada.perdidos) {
          problemas.push(`${donde}: ${fila.org} terminó ${fila.ganados}-${fila.perdidos}; con rng() < p da ${esperada.ganados}-${esperada.perdidos}`);
          return;
        }
      }
      const rp = t.resultadosPropios;
      if (rp.fechas !== propios.fechas || rp.ganados !== propios.ganados
        || Math.abs(rp.esperados - propios.esperados) > 1e-9 || Math.abs(rp.varianza - propios.varianza) > 1e-9) {
        problemas.push(`${donde}: resultadosPropios ${JSON.stringify(rp)}, la re-jugada da ${JSON.stringify(propios)}`);
        return;
      }
      // El rendimiento del split: el base más `puntosPorDesvioDeResultados` × z, acotado.
      const z = propios.varianza > 0 ? (propios.ganados - propios.esperados) / Math.sqrt(propios.varianza) : 0;
      const lectura = Math.min(BALANCE.stats.max, Math.max(BALANCE.stats.min,
        t.rendimientoBase + BALANCE.rendimiento.puntosPorDesvioDeResultados * z));
      if (Math.abs(t.rendimiento - lectura) > 1e-9) {
        problemas.push(`${donde}: el rendimiento del split es ${t.rendimiento}, lo que cuentan sus fechas da ${lectura}`);
      }
    });
  } finally {
    BALANCE.temporada.fechasMarcadasPorSplit = marcadasOriginal;
  }
  if (problemas.length > 0) {
    throw new Error(`${problemas.slice(0, 4).join('; ')}${problemas.length > 4 ? ` (+${problemas.length - 4} más)` : ''}`);
  }
  if (vistos.fechas < 200 || vistos.cruces < 600) {
    throw new Error(`check vacío: ${JSON.stringify(vistos)}`);
  }
});

const SERIES_K2B = 60;
const REPLICAS_MAPA_K2B = 20;

// Estados reales con una serie en curso: las pausas del plan de Fearless al arrancar la serie (K4-B; antes, los drafts
// de cada mapa), de `criterio`, hasta `maximo`.
function draftsDeSerieK2b(maximo) {
  const casos = [];
  const espia = (sistema, st, decision, rng) => {
    if (sistema.id === 'serie' && decision.datos?.motivo === 'plan' && !decision.datos.replan && casos.length < maximo) {
      casos.push({ st, decision });
    }
    return ESTRATEGIAS_K0.criterio(sistema, st, decision, rng);
  };
  for (let seed = 1; seed <= SEEDS_MAX_K2B * 2 && casos.length < maximo; seed += 1) {
    correrCarreraSimulate(seed, 60, espia);
  }
  return casos;
}

check('K2b una tirada por mapa: el mapa es rng() < p con la p de probabilidadDePartido sobre la fuerza de partido del campeón elegido, y un mapa que cierra una serie perdida sin internacional tira un solo rng()', () => {
  // Cada serie se juega con el plan del coach (sin tiradas de lectura) en el marcador del desempate de unos cuartos de
  // un equipo que no clasifica al internacional, desde el mapa 1 (no es el mapa decisivo por índice: no frena): si se
  // pierde, después del mapa no queda nada que sortear.
  const casos = draftsDeSerieK2b(SERIES_K2B);
  if (casos.length < SERIES_K2B) {
    throw new Error(`check vacío: solo ${casos.length} drafts de serie`);
  }
  // Cada escenario se juega con `REPLICAS_MAPA_K2B` streams distintos: con una sola tirada por escenario, una p corrida
  // un par de puntos (la fuerza sin el tope de 100, otro σ) casi nunca cambia un resultado.
  const problemas = [];
  let derrotas = 0;
  let victorias = 0;
  casos.forEach(({ st, decision }, i) => {
    const liga = st.mundo.ligas.find((l) => l.id === st.career.liga);
    const necesarias = Math.ceil(st.serie.formato / 2);
    const escenario = {
      ...st,
      career: { ...st.career, posicion: (liga?.cuposInternacionales ?? 0) + 1 },
      serie: { ...st.serie, ronda: 'cuartos', marcador: [necesarias - 1, necesarias - 1] }
    };
    // K4-B: el campeón que juega el plan del coach, y el rival de ESE mapa (también quema: `fuerzaRivalDeMapa`).
    const proximo = estadoDelProximoMapa(conPlan(escenario, 'coach'));
    const elegido = mapaDelPlan(proximo).campeon;
    const fuerza = fuerzaDesdeCamposK2b(
      nivelDeCompanerosIndependienteK2b(escenario),
      rendimientoBase({ ...escenario, player: { ...escenario.player, campeonDelSplit: elegido } }),
      escenario.career.sinergia
    );
    const pMapa = probabilidadDePartido(escenario, fuerza, fuerzaRivalDeMapa(proximo), 'mapa');
    for (let replica = 0; replica < REPLICAS_MAPA_K2B; replica += 1) {
      const { rng, valores } = rngEspiaK2b(7000 + i * REPLICAS_MAPA_K2B + replica);
      const resultado = sistemaPorId('serie').resolver(escenario, decision, { opcionId: 'coach' }, rng);
      // El primer mapa que se jugó en esta llamada es el primer log de mapa (si la serie se ganó, `serie.mapas` ya es
      // el de la ronda siguiente).
      const mapa = resultado.logs.find((log) => log.type === 'serie' && (log.resultado === 'W' || log.resultado === 'L'));
      if (!mapa || (mapa.resultado === 'W') !== (valores[0] < pMapa)) {
        problemas.push(`draft ${i}, réplica ${replica}: el mapa salió ${mapa?.resultado}, el primer rng() fue ${valores[0]} contra p = ${pMapa}`);
        return;
      }
      if (mapa.resultado === 'L') {
        derrotas += 1;
        if (valores.length !== 1) {
          problemas.push(`draft ${i}: el mapa que cerró la serie (perdida, sin internacional) tiró ${valores.length} rng()`);
          return;
        }
      } else {
        victorias += 1;
      }
    }
  });
  if (problemas.length > 0) {
    throw new Error(`${problemas.slice(0, 4).join('; ')}${problemas.length > 4 ? ` (+${problemas.length - 4} más)` : ''}`);
  }
  if (derrotas < 10 || victorias < 10) {
    throw new Error(`check vacío: ${derrotas} derrotas y ${victorias} victorias`);
  }
});

// Los σ de partido, con sus nombres de antes de K2b: ninguno puede volver a leerse fuera de `ruidoEfectivo`.
const PATRON_SIGMA_DE_PARTIDO_K2B = /\b(sigmaFecha|sigmaMapa|ruidoFecha|ruidoRivalFecha|ruidoMapa|ruidoRivalSerie|ruidoRendimiento)\b|BALANCE\s*(\.\s*partido\b|\[\s*['"`]partido['"`]\s*\])|\{[^}]*\bpartido\b[^}]*\}\s*=\s*BALANCE\b/;
// Archivos del motor que no pueden importar `gauss`: los que arman o resuelven un partido.
const SIN_GAUSS_K2B = ['src/core/partido.js', 'src/core/fuerza.js', 'src/core/temporada.js', 'src/systems/temporada.js'];

check('K2b ruidoEfectivo es el único lector del σ de partido (estático), y los archivos que arman un partido no importan gauss', () => {
  const raiz = path.join(srcDir, '..');
  const rel = (p) => path.relative(raiz, p).replace(/\\/g, '/');
  const archivos = (dir) => fs.readdirSync(dir, { withFileTypes: true }).flatMap((e) => {
    const p = path.join(dir, e.name);
    if (e.isDirectory()) return e.name === 'dev' ? [] : archivos(p);
    return /\.js$/.test(p) && rel(p) !== 'src/data/balance.js' ? [p] : [];
  });
  // Bloques y comentarios `//` se vacían conservando los saltos de línea (como el check de vocabulario de K0-C).
  const sinComentarios = (txt) => txt
    .replace(/(^|\s)\/\*[\s\S]*?\*\/|<!--[\s\S]*?-->/g, (bloque) => bloque.replace(/[^\n]/g, ''))
    .split(/\r?\n/).map((l) => l.replace(/(^|\s)\/\/.*$/, '$1'));
  // El cuerpo de `ruidoEfectivo` en `core/partido.js`: el único lugar permitido.
  const partidoJs = fs.readFileSync(path.join(srcDir, 'core', 'partido.js'), 'utf8').split(/\r?\n/);
  const inicio = partidoJs.findIndex((linea) => /^export function ruidoEfectivo\(/.test(linea));
  const fin = inicio < 0 ? -1 : partidoJs.findIndex((linea, i) => i > inicio && /^}/.test(linea));
  if (inicio < 0 || fin < 0) {
    throw new Error('no encontré `export function ruidoEfectivo(` en src/core/partido.js');
  }
  const lecturas = [];
  let dentro = 0;
  for (const archivo of [...archivos(srcDir), path.join(raiz, 'index.html')]) {
    const lineas = sinComentarios(fs.readFileSync(archivo, 'utf8'));
    lineas.forEach((linea, i) => {
      if (!PATRON_SIGMA_DE_PARTIDO_K2B.test(linea)) return;
      if (rel(archivo) === 'src/core/partido.js' && i > inicio && i < fin) {
        dentro += 1;
        return;
      }
      lecturas.push(`${rel(archivo)}:${i + 1}: ${linea.trim()}`);
    });
  }
  if (lecturas.length > 0) {
    throw new Error(`σ de partido leído fuera de ruidoEfectivo: ${lecturas.slice(0, 5).join(' | ')}`);
  }
  if (dentro < 2) {
    throw new Error(`ruidoEfectivo lee ${dentro} σ (se esperaban el de fecha y el de mapa): el patrón no está viendo nada`);
  }
  const conGauss = SIN_GAUSS_K2B.filter((archivo) => sinComentarios(fs.readFileSync(path.join(raiz, archivo), 'utf8')).some((linea) => /\bgauss\b/.test(linea)));
  if (conGauss.length > 0) {
    throw new Error(`usan gauss y arman o resuelven un partido: ${conGauss.join(', ')}`);
  }
});

check('K2b compañeros en vivo: en una liga modelada la fuerza lee el nivel ACTUAL del plantel (no la foto de roster); sin plantel, la foto', () => {
  const entradas = entradasDeTemporadaK2b(ENTRADAS_TEMPORADA_K2B);
  const modelada = entradas.find((e) => e.mundo.planteles?.[e.career.currentOrg]);
  if (!modelada) {
    throw new Error('check vacío: ninguna temporada en una org con plantel');
  }
  const SUBA = 10;
  const org = modelada.career.currentOrg;
  const plantel = modelada.mundo.planteles[org];
  const subido = Object.fromEntries(Object.entries(plantel).map(([rol, npc]) => [rol, rol === modelada.player.role ? npc : { ...npc, nivel: npc.nivel + SUBA }]));
  const conPlantelSubido = { ...modelada, mundo: { ...modelada.mundo, planteles: { ...modelada.mundo.planteles, [org]: subido } } };
  const antes = nivelDeCompaneros(modelada);
  const despues = nivelDeCompaneros(conPlantelSubido);
  if (Math.abs(antes - nivelDeCompanerosIndependienteK2b(modelada)) > 1e-9 || Math.abs(despues - antes - SUBA) > 1e-9) {
    throw new Error(`con el plantel vivo +${SUBA} (y la foto de roster igual), los compañeros pasaron de ${antes} a ${despues}`);
  }
  const fuerzaAntes = fuerzaDelEquipo(modelada, 70);
  const fuerzaDespues = fuerzaDelEquipo(conPlantelSubido, 70);
  const esperado = fuerzaDesdeCamposK2b(antes + SUBA, 70, modelada.career.sinergia) - fuerzaDesdeCamposK2b(antes, 70, modelada.career.sinergia);
  if (Math.abs((fuerzaDespues - fuerzaAntes) - esperado) > 1e-9) {
    throw new Error(`la fuerza del equipo no siguió al plantel vivo: +${fuerzaDespues - fuerzaAntes}, se esperaba +${esperado}`);
  }
  // Sin plantel (una org que el mundo no modela): manda la foto de `roster`.
  const companeros = [{ handle: 'a', role: 'top', nivel: 40 }, { handle: 'b', role: 'mid', nivel: 50 }, { handle: 'c', role: 'adc', nivel: 60 }, { handle: 'd', role: 'support', nivel: 70 }];
  const sinPlantel = { ...modelada, player: { ...modelada.player, role: 'jungla' }, career: { ...modelada.career, currentOrg: 'Org Inventada K2b', companeros } };
  if (companerosDelPlantel(sinPlantel, 'Org Inventada K2b') !== null || nivelDeCompaneros(sinPlantel) !== 55) {
    throw new Error(`sin plantel los compañeros tenían que salir de la foto (55): dio ${nivelDeCompaneros(sinPlantel)}`);
  }
});

const TRASPASOS_MINIMOS_K2B = 30;
const SPLITS_MISMO_EQUIPO_MINIMOS_K2B = 300;

const SINERGIAS_SEGUIDAS_MINIMAS_K2B = 10;

check('K2b un traspaso juega su primer split con el plantel nuevo, y en una liga modelada los compañeros son siempre el plantel vivo (probCambioDeRoster no inventa), y la sinergia es la del plantel nuevo', () => {
  const problemas = [];
  const vistos = { traspasos: 0, mismoEquipoModelado: 0, cambiosDePlantilla: 0, sinergiaFijada: 0, sinergiaSeguida: 0 };
  // El último traspaso visto: el split siguiente, `armarRoster` tiene que dejar la misma química.
  let pendiente = null;
  const porRol = (lista) => JSON.stringify([...lista].map((c) => [c.role, c.handle, c.nivel]).sort());
  conEspiaDeSistemaK2a('temporada', (entrada, resultado) => {
    if (!arrancaTemporadaK2a(entrada)) {
      return;
    }
    const org = entrada.career.currentOrg;
    const plantel = entrada.mundo.planteles?.[org];
    if (!plantel) {
      return;
    }
    const vivos = Object.entries(plantel).filter(([rol]) => rol !== entrada.player.role).map(([rol, npc]) => ({ role: rol, handle: npc.handle, nivel: npc.nivel }));
    const traspaso = entrada.career.rosterDeOrg !== org;
    if (traspaso) {
      vistos.traspasos += 1;
      // La química también es la del plantel nuevo: la firma la fijó (`sinergiaAlFichar`, la regla de `armarRoster`) y
      // este split se juega con ella, no con la del vestuario anterior (que `armarRoster` recién reseteaba al split
      // siguiente).
      const fijada = entrada.flags.sinergiaProyectadaAlFichar;
      if (fijada === null || fijada === undefined || entrada.career.sinergia !== Math.round(fijada)) {
        problemas.push(`traspaso a ${org} (split ${entrada.player.splitCount}): se juega con sinergia ${entrada.career.sinergia}, la que fijó la firma es ${fijada}`);
      } else {
        vistos.sinergiaFijada += 1;
      }
      pendiente = { org, split: entrada.player.splitCount, sinergia: entrada.career.sinergia, plantel: porRol(entrada.career.companeros) };
    } else {
      vistos.mismoEquipoModelado += 1;
      // El split siguiente al traspaso: `armarRoster` no vuelve a tirar la química (misma que se jugó), salvo que el
      // plantel haya cambiado de nuevo (ahí el mundo la resetea con `sinergiaRetenidaAlCambiar`, y no se compara).
      if (pendiente && pendiente.org === org && entrada.player.splitCount === pendiente.split + 1
        && porRol(entrada.career.companeros) === pendiente.plantel) {
        vistos.sinergiaSeguida += 1;
        if (entrada.career.sinergia !== pendiente.sinergia) {
          problemas.push(`${org} (split ${entrada.player.splitCount}): el traspaso jugó con sinergia ${pendiente.sinergia} y el roster armado dejó ${entrada.career.sinergia}`);
        }
      }
      pendiente = null;
    }
    if (porRol(entrada.career.companeros) !== porRol(vivos)) {
      problemas.push(`${traspaso ? 'traspaso' : 'mismo equipo'} a ${org} (split ${entrada.player.splitCount}): se juega con ${porRol(entrada.career.companeros)}, el plantel de la org es ${porRol(vivos)}`);
    }
    const nivelVivo = vivos.reduce((suma, c) => suma + c.nivel, 0) / vivos.length;
    if (Math.abs(resultado.state.career.temporada.nivelCompaneros - nivelVivo) > 1e-9) {
      problemas.push(`${org} (split ${entrada.player.splitCount}): la temporada usó compañeros de nivel ${resultado.state.career.temporada.nivelCompaneros}, el plantel vivo es ${nivelVivo}`);
    }
  }, () => {
    for (let seed = 1; seed <= SEEDS_MAX_K2B && (vistos.traspasos < TRASPASOS_MINIMOS_K2B || vistos.mismoEquipoModelado < SPLITS_MISMO_EQUIPO_MINIMOS_K2B); seed += 1) {
      const { state } = correrCarreraSimulate(seed, 60, ESTRATEGIAS_K0.criterio);
      vistos.cambiosDePlantilla += state.logs.filter((log) => log.type === 'roster' && /se va del equipo|al equipo\. Hay que volver/.test(log.message)).length;
    }
  });
  if (problemas.length > 0) {
    throw new Error(`${problemas.slice(0, 3).join('; ')}${problemas.length > 3 ? ` (+${problemas.length - 3} más)` : ''}`);
  }
  if (vistos.traspasos < TRASPASOS_MINIMOS_K2B || vistos.mismoEquipoModelado < SPLITS_MISMO_EQUIPO_MINIMOS_K2B || vistos.cambiosDePlantilla === 0
    || vistos.sinergiaFijada < TRASPASOS_MINIMOS_K2B || vistos.sinergiaSeguida < SINERGIAS_SEGUIDAS_MINIMAS_K2B) {
    throw new Error(`check vacío: ${JSON.stringify(vistos)}`);
  }
});

// K2b (revisión) — los checks que matan a los mutantes que sobrevivían. Cada uno se probó rojo contra su mutante.

const BAJAS_SINTETICAS_K2B = 2;
const ENTRADAS_BAJA_K2B = 6;

check('K2b una fecha de baja por lesión no cuenta para tu rendimiento: con fechasBajaLesion = 2, resultadosPropios.fechas es las fechas del calendario menos 2 y ganados/esperados/varianza suman solo las otras', () => {
  // Caso sintético: en carreras reales una lesión que cae dentro de la temporada pasa en 7 de 13.759, y ahí un
  // mutante que cuente esas fechas sobrevivía. Se fuerza la baja sobre estados reales al arrancar la temporada.
  const entradas = entradasDeTemporadaK2b(ENTRADAS_BAJA_K2B);
  if (entradas.length < ENTRADAS_BAJA_K2B) {
    throw new Error(`check vacío: solo ${entradas.length} temporadas`);
  }
  const problemas = [];
  const marcadasOriginal = BALANCE.temporada.fechasMarcadasPorSplit;
  try {
    BALANCE.temporada.fechasMarcadasPorSplit = 0;
    entradas.forEach((original, i) => {
      const entrada = { ...original, flags: { ...original.flags, fechasBajaLesion: BAJAS_SINTETICAS_K2B } };
      const donde = `temporada ${i} (${entrada.career.currentOrg}, split ${entrada.player.splitCount})`;
      const { rng, valores } = rngEspiaK2b(9500 + i);
      const resultado = sistemaPorId('temporada').aplicar(entrada, rng);
      const t = resultado.state.career.temporada;
      if (resultado.decision || t.activa || t.calendario.length <= BAJAS_SINTETICAS_K2B) {
        problemas.push(`${donde}: la temporada pausó o el calendario es más corto que la baja`);
        return;
      }
      if (resultado.state.flags.fechasBajaLesion !== 0) {
        problemas.push(`${donde}: quedaron ${resultado.state.flags.fechasBajaLesion} fechas de baja sin consumir`);
      }
      // Re-jugada independiente con los mismos números: las primeras fechas se juegan sin vos (fuerza penalizada) y no
      // entran a `resultadosPropios`; el resto sí.
      let k = 0;
      const propios = { fechas: 0, ganados: 0, esperados: 0, varianza: 0 };
      t.calendario.forEach((fecha, j) => {
        const enBaja = j < BAJAS_SINTETICAS_K2B;
        const fuerza = enBaja ? t.fuerzaPropia * BALANCE.salud.factorFuerzaLesionado : t.fuerzaPropia;
        const pFecha = probabilidadDePartido(entrada, fuerza, fecha.fuerzaRival, 'fecha');
        const gano = valores[k] < pFecha;
        k += 1 + t.cruces[j].length;
        if (!enBaja) {
          propios.fechas += 1;
          propios.ganados += gano ? 1 : 0;
          propios.esperados += pFecha;
          propios.varianza += pFecha * (1 - pFecha);
        }
      });
      const rp = t.resultadosPropios;
      if (rp.fechas !== t.calendario.length - BAJAS_SINTETICAS_K2B
        || rp.fechas !== propios.fechas || rp.ganados !== propios.ganados
        || Math.abs(rp.esperados - propios.esperados) > 1e-9 || Math.abs(rp.varianza - propios.varianza) > 1e-9) {
        problemas.push(`${donde}: con ${BAJAS_SINTETICAS_K2B} fechas de baja de ${t.calendario.length}, resultadosPropios es ${JSON.stringify(rp)} y debería ser ${JSON.stringify(propios)}`);
      }
    });
  } finally {
    BALANCE.temporada.fechasMarcadasPorSplit = marcadasOriginal;
  }
  if (problemas.length > 0) {
    throw new Error(`${problemas.slice(0, 3).join('; ')}${problemas.length > 3 ? ` (+${problemas.length - 3} más)` : ''}`);
  }
});

const DRAFTS_P_K2B = 12;
const DRAFTS_MAX_K2B = 60;
const OPCIONES_POR_DRAFT_K2B = 3;
const EPSILON_P_K2B = 1e-9;
const SOBRE_EL_TOPE_MINIMO_K2B = 5;

// K4-B (regla 17): el check "K2b la p del draft (probabilidadConCampeon) es exactamente la p que tira el mapa del
// campeón elegido..." se borró junto con el draft de serie. Lo reemplaza "K4-B regla 15: la p por mapa que declara
// cada plan...", que compara contra la tirada sobre series reales; el tope de 100 lo sigue cuidando la fuerza de
// partido (`fuerzaDePartido`, checks de K2b).

check('K2b ruidoEfectivo por tipo coincide con BALANCE.partido (fecha → sigmaFecha, mapa → sigmaMapa), y la p de partido usa el σ de su tipo', () => {
  const sigmaDeTipo = { fecha: BALANCE.partido.sigmaFecha, mapa: BALANCE.partido.sigmaMapa };
  const estados = [null, createInitialState(1, mulberry32(1))];
  for (const tipo of Object.keys(sigmaDeTipo)) {
    for (const estado of estados) {
      // σ_tipo · g(m): con la perilla de K3 en 0 el factor es 1 (σ = el de BALANCE.partido); con k ≠ 0 pesa la mentalidad.
      // Sin jugador (`null`) el factor es 1.
      const esperadoSigma = sigmaDeTipo[tipo] * factorDeConsistencia(estado?.player?.stats?.mentalidad);
      if (ruidoEfectivo(estado, tipo) !== esperadoSigma) {
        throw new Error(`ruidoEfectivo(${estado ? 'estado' : 'null'}, '${tipo}') = ${ruidoEfectivo(estado, tipo)}, σ_tipo · g(m) da ${esperadoSigma}`);
      }
      // La p con ese σ, escrita a mano: Φ logística de (F − f) / σ.
      for (const delta of [-30, -8, 0, 5, 14, 40]) {
        const p = 1 / (1 + Math.exp(-BALANCE.numeros.factorLogisticoNormal * (delta / esperadoSigma)));
        const dada = probabilidadDePartido(estado, 50 + delta, 50, tipo);
        if (Math.abs(dada - p) > 1e-12) {
          throw new Error(`probabilidadDePartido(Δ ${delta}, '${tipo}') = ${dada}, con σ ${esperadoSigma} da ${p}`);
        }
      }
    }
  }
  let tiro = false;
  try {
    ruidoEfectivo(null, 'serie');
  } catch {
    tiro = true;
  }
  if (!tiro) {
    throw new Error('un tipo de partido desconocido no tiró');
  }
});

check('K2b la sinergia no entra a tu rendimiento: rendimientoBase no cambia cuando solo cambia career.sinergia (la fuerza del equipo sí)', () => {
  const entradas = entradasDeTemporadaK2b(8);
  if (entradas.length < 8) {
    throw new Error(`check vacío: solo ${entradas.length} temporadas`);
  }
  for (const entrada of entradas) {
    const base = rendimientoBase(entrada);
    for (const sinergia of [0, 25, 50, 75, 100]) {
      const variante = { ...entrada, career: { ...entrada.career, sinergia } };
      if (rendimientoBase(variante) !== base) {
        throw new Error(`rendimientoBase pasó de ${base} a ${rendimientoBase(variante)} al cambiar solo la sinergia a ${sinergia} (${entrada.career.currentOrg}, split ${entrada.player.splitCount})`);
      }
    }
    const baja = fuerzaDelEquipo({ ...entrada, career: { ...entrada.career, sinergia: 0 } }, 70);
    const alta = fuerzaDelEquipo({ ...entrada, career: { ...entrada.career, sinergia: 100 } }, 70);
    if (!(alta > baja)) {
      throw new Error(`la sinergia dejó de contar en la fuerza del equipo: ${baja} con 0, ${alta} con 100`);
    }
  }
});

// ============================================================================
// K2d — la previa (PLAN.md "K2d — la previa (pantalla)" y "K2d — decisiones de spec"): la p que la pantalla
// muestra antes de una fecha marcada y antes de un mapa es exactamente la que el motor tira (regla 15).
// ============================================================================

const SEEDS_MAX_K2D = 80;
const CASOS_K2D = 30;
// La cosecha depende del balance con el que se juegan las carreras: una por valor de `consistencia.k`.
const cosechasK2d = new Map();

// PLAN.md "K3, tal como quedó y lo que se decide al integrar": cada check de K2d corre dos veces, con BALANCE tal
// cual y con `consistencia.k = 1` en memoria (restaurado después). Una pieza neutra (k = 0) no puede esconder un
// check que se rompe con el valor real: con k ≠ 0 el momento de una fecha marcada mueve la mentalidad entre la
// previa y la tirada.
const K_CONSISTENCIA_K2D = 1;
function checkK2d(nombre, fn) {
  check(nombre, fn);
  check(`${nombre} — con consistencia.k = ${K_CONSISTENCIA_K2D} en memoria`, () => conBalanceK3A([['consistencia', 'k', K_CONSISTENCIA_K2D]], fn));
}

// Las pausas reales antes de un partido, de carreras de `criterio` (seeds 1 en adelante, 60 splits): el momento de
// una fecha marcada (con el campeón ya elegido), el draft de un mapa y el minijuego de un mapa. Cada caso guarda el
// estado de la pausa, la decisión, el sistema que la resuelve y la respuesta de `criterio`.
function cosechaDePreviasK2d() {
  const clave = BALANCE.consistencia.k;
  if (cosechasK2d.has(clave)) {
    return cosechasK2d.get(clave);
  }
  const c = { fechas: [], drafts: [], minijuegos: [] };
  const espia = (sistema, st, decision, rng) => {
    const respuesta = ESTRATEGIAS_K0.criterio(sistema, st, decision, rng);
    const datos = decision.datos ?? {};
    const caso = { sistema, st, decision, respuesta };
    if (st.serie?.activa) {
      // K4-B: el draft de mapa ya no existe; su lugar lo toma la pausa del mapa decisivo sin minijuego (con o sin
      // la charla del coach), que también trae la p de cada opción.
      if (datos.motivo === 'decisivo' && c.drafts.length < CASOS_K2D) {
        c.drafts.push(caso);
      } else if (datos.motivo === 'minijuego' && minijuegoPorId(datos.minijuego)?.efecto?.tipo === 'mapa'
        && c.minijuegos.length < CASOS_K2D) {
        c.minijuegos.push(caso);
      }
    } else {
      const fecha = st.career.temporada?.activa ? st.career.temporada.fechaEnCurso : null;
      // K4-A: la fecha marcada ya no tiene draft; su única pausa es el momento.
      if (fecha && 'campeonElegido' in fecha && c.fechas.length < CASOS_K2D * 2) {
        c.fechas.push(caso);
      }
    }
    return respuesta;
  };
  const llena = () => c.fechas.length >= CASOS_K2D * 2
    && c.drafts.length >= CASOS_K2D && c.minijuegos.length >= CASOS_K2D;
  for (let seed = 1; seed <= SEEDS_MAX_K2D && !llena(); seed += 1) {
    correrCarreraSimulate(seed, 60, espia);
  }
  if (c.fechas.length < CASOS_K2D || c.drafts.length < 10 || c.minijuegos.length < 10) {
    throw new Error(`cosecha vacía: ${c.fechas.length} fechas marcadas, ${c.drafts.length} drafts de mapa y ${c.minijuegos.length} minijuegos de mapa`);
  }
  cosechasK2d.set(clave, c);
  return c;
}

const esLogDeMapaK2d = (log) => log.type === 'serie' && (log.resultado === 'W' || log.resultado === 'L');
const esLogDeFechaK2d = (log) => log.type === 'temporada' && Number.isFinite(log.p);

function fallarSiK2d(problemas) {
  if (problemas.length > 0) {
    throw new Error(`${problemas.slice(0, 4).join('; ')}${problemas.length > 4 ? ` (+${problemas.length - 4} más)` : ''}`);
  }
}

// K3 (PLAN.md "K3, tal como quedó y lo que se decide al integrar"): en una fecha marcada la previa es la p de ANTES
// de decidir, que la pausa guarda (`pAntesDeDecidir`) y el log reporta como `pSinMomento`; la tirada es la del estado
// de DESPUÉS del momento (su `ajustePartido` y, con `consistencia.k` ≠ 0, su mentalidad), y es exactamente la previa
// de ese estado.
checkK2d('K2d previa 1: la p de la previa es exactamente la que el motor tira (===), en fechas marcadas (y la de cada opción de su draft corto) y en mapas con el minijuego neutro, sobre partidos de carreras reales', () => {
  const { fechas, drafts, minijuegos } = cosechaDePreviasK2d();
  const problemas = [];
  let fechasNeutras = 0;
  let fechasConMomento = 0;
  fechas.forEach(({ sistema, st, decision, respuesta }, i) => {
    const previa = previaDeDecision(st, decision);
    const res = sistema.resolver(st, decision, respuesta, mulberry32(31000 + i));
    const log = res.logs.find(esLogDeFechaK2d);
    if (!previa || !log) {
      problemas.push(`fecha ${i}: ${previa ? 'sin log de la fecha con su p' : 'sin previa en la pausa'}`);
      return;
    }
    if (decision.datos.pAntesDeDecidir !== previa.p) {
      problemas.push(`fecha ${i}: la previa dice p = ${previa.p}, la pausa guardó ${decision.datos.pAntesDeDecidir}`);
    }
    if (log.pSinMomento !== previa.p) {
      problemas.push(`fecha ${i}: la previa dice p = ${previa.p}, el log reporta ${log.pSinMomento} antes del momento`);
    }
    // El estado de después del momento, con el mismo azar que usó el motor (el momento tira antes que el partido).
    const evento = TODOS_LOS_EVENTOS.find((candidato) => candidato.id === decision.datos.eventoId);
    if (decision.datos.motivo !== 'momento' || !evento) {
      problemas.push(`fecha ${i}: la pausa no es el momento de la fecha (${decision.datos.motivo})`);
      return;
    }
    const despues = previaDePartido(resolverOpcion(st, evento, respuesta.opcionId, mulberry32(31000 + i)).state, { tipo: 'fecha' });
    if (log.p !== despues.p) problemas.push(`fecha ${i} (ajuste ${log.ajustePartido}): previa de después ${despues.p}, tirada ${log.p}`);
    if (log.ajustePartido === 0) {
      fechasNeutras += 1;
    } else {
      fechasConMomento += 1;
    }
  });

  let mapasSinMinijuego = 0;
  let mapasConMinijuego = 0;
  drafts.forEach(({ sistema, st, decision }, i) => {
    const previa = previaDeDecision(st, decision);
    const elegido = decision.opciones[0].id;
    const directa = previaDePartido(st, {
      tipo: 'mapa', campeon: decision.datos.campeonElegido, entradaExtra: decision.datos.entradaExtra ?? null,
      ajustePlan: decision.datos.ajustePlan, charla: elegido === 'charla'
    });
    if (!previa || previa.opciones?.[0]?.p !== directa.p) {
      problemas.push(`decisivo ${i}: la previa del mapa decisivo no es la de la primera opción`);
      return;
    }
    let res = sistema.resolver(st, decision, { opcionId: elegido }, mulberry32(32000 + i));
    // Si el mapa no se jugó todavía, la pausa que vino es la de su minijuego (la del mapa siguiente o la de después
    // de la serie llegan con el log de este mapa ya escrito).
    if (!res.logs.some(esLogDeMapaK2d) && res.decision?.datos?.motivo === 'minijuego') {
      const antes = previaDeDecision(res.state, res.decision);
      if (antes?.p !== directa.p) problemas.push(`draft ${i}: la previa del minijuego (${antes?.p}) no es la del draft (${directa.p})`);
      res = sistema.resolver(res.state, res.decision, { resultado: 0.5 }, mulberry32(33000 + i));
      mapasConMinijuego += 1;
    } else {
      mapasSinMinijuego += 1;
    }
    const log = res.logs.find(esLogDeMapaK2d);
    if (!log || log.p !== directa.p) problemas.push(`draft ${i}: previa ${directa.p}, tirada ${log?.p}`);
  });
  minijuegos.forEach(({ sistema, st, decision }, i) => {
    const previa = previaDeDecision(st, decision);
    const res = sistema.resolver(st, decision, { resultado: 0.5 }, mulberry32(34000 + i));
    const log = res.logs.find(esLogDeMapaK2d);
    mapasConMinijuego += 1;
    if (!previa || !log || log.p !== previa.p) problemas.push(`minijuego ${i} (neutro): previa ${previa?.p}, tirada ${log?.p}`);
  });
  fallarSiK2d(problemas);
  // Todo momento del catálogo trae un efecto `partido`: en carreras reales casi ninguna fecha marcada llega sin
  // ajuste. La p de antes del momento (la que muestra la previa) se compara igual en todas, contra `pSinMomento`.
  if (fechasNeutras + fechasConMomento < 20 || mapasSinMinijuego < 5 || mapasConMinijuego < 10) {
    throw new Error(`check vacío: ${fechasNeutras} fechas sin ajuste, ${fechasConMomento} con ajuste, ${mapasSinMinijuego} mapas sin minijuego, ${mapasConMinijuego} con minijuego`);
  }
});

checkK2d('K2d previa 2: la p final que muestra el mapa después del minijuego es exactamente la tirada (===), y el minijuego la mueve', () => {
  const { minijuegos } = cosechaDePreviasK2d();
  const problemas = [];
  let movidas = 0;
  minijuegos.forEach(({ sistema, st, decision }, i) => {
    const antes = previaDeDecision(st, decision);
    for (const resultado of [0.1, 0.85]) {
      const final = previaDeDecision(st, decision, { resultadoMinijuego: resultado });
      const res = sistema.resolver(st, decision, { resultado }, mulberry32(35000 + i));
      const log = res.logs.find(esLogDeMapaK2d);
      if (!final || !log || log.p !== final.p) {
        problemas.push(`minijuego ${i} (resultado ${resultado}): la pantalla muestra ${final?.p}, se tiró ${log?.p}`);
      }
      if (final && antes && final.p !== antes.p) movidas += 1;
    }
  });
  // K4 (revisión): con la charla del coach elegida en la misma pausa (K4-B) la pantalla muestra la p con la charla y el
  // minijuego, y el motor tira con esa misma p — una charla aplicada dos veces (o ninguna) en cualquiera de los dos lados
  // rompe el ===. Solo en las pausas que la ofrecen y con la charla todavía sin usar esta temporada.
  let conCharla = 0;
  minijuegos.forEach(({ sistema, st, decision }, i) => {
    if (decision.datos.charla?.disponible !== true || !charlaDisponible(st)) return;
    for (const resultado of [0.1, 0.85]) {
      const sinElla = previaDeDecision(st, decision, { resultadoMinijuego: resultado });
      const final = previaDeDecision(st, decision, { resultadoMinijuego: resultado, charla: true });
      const res = sistema.resolver(st, decision, { resultado, charla: true }, mulberry32(35500 + i));
      const log = res.logs.find(esLogDeMapaK2d);
      if (!final || !log || log.p !== final.p) {
        problemas.push(`minijuego ${i} con charla (resultado ${resultado}): la pantalla muestra ${final?.p}, se tiró ${log?.p}`);
      }
      if (!final || !sinElla || final.p === sinElla.p) {
        problemas.push(`minijuego ${i} con charla (resultado ${resultado}): la charla no mueve la p que muestra la pantalla`);
      }
      conCharla += 1;
    }
  });
  fallarSiK2d(problemas);
  if (movidas < minijuegos.length) {
    throw new Error(`el minijuego movió la p en solo ${movidas} de ${minijuegos.length * 2} casos`);
  }
  if (conCharla < 4) {
    throw new Error(`check vacío: solo ${conCharla} casos de minijuego decisivo con la charla disponible`);
  }
});

checkK2d('K2d previa 3: el desglose reproduce el total de la fuerza que usa el motor (fecha: la del split; mapa: la del minijuego) y sus partes suman el total', () => {
  const { fechas, drafts, minijuegos } = cosechaDePreviasK2d();
  const problemas = [];
  const sumaDePartes = (previa) => Object.values(previa.aportes).reduce((s, v) => s + v, 0);
  const revisar = (nombre, previa, fuerzaDelMotor) => {
    if (previa.fuerzaBase !== fuerzaDelMotor) {
      problemas.push(`${nombre}: la previa arma ${previa.fuerzaBase}, el motor juega con ${fuerzaDelMotor}`);
    }
    if (Math.abs(sumaDePartes(previa) - previa.fuerzaFinal) > 1e-9) {
      problemas.push(`${nombre}: las partes suman ${sumaDePartes(previa)}, el total es ${previa.fuerzaFinal}`);
    }
    if (previa.propio.fuerza !== previa.fuerzaFinal) {
      problemas.push(`${nombre}: la tarjeta muestra ${previa.propio.fuerza} y la fuerza del partido es ${previa.fuerzaFinal}`);
    }
  };
  fechas.forEach(({ st, decision }, i) => {
    const previa = previaDeDecision(st, decision);
    revisar(`fecha ${i}`, previa, st.career.temporada.fuerzaPropia);
    if (previa.desglose.total !== st.career.temporada.fuerzaPropia) {
      problemas.push(`fecha ${i}: el desglose da ${previa.desglose.total}, la fuerza del split es ${st.career.temporada.fuerzaPropia}`);
    }
    const conMomento = previaDePartido(st, { tipo: 'fecha', ajustePartido: 0.1 });
    if (Math.abs(sumaDePartes(conMomento) - conMomento.fuerzaFinal) > 1e-9) problemas.push(`fecha ${i}: con momento, las partes no suman el total`);
  });
  minijuegos.forEach(({ st, decision }, i) => {
    revisar(`minijuego ${i}`, previaDeDecision(st, decision), decision.datos.fuerzaPropia);
    const final = previaDeDecision(st, decision, { resultadoMinijuego: 0.9 });
    if (Math.abs(sumaDePartes(final) - final.fuerzaFinal) > 1e-9) problemas.push(`minijuego ${i}: con el minijuego jugado, las partes no suman el total`);
  });
  drafts.forEach(({ st, decision }, i) => {
    // La fuerza con la que el motor juega el mapa: la misma cuenta que hace `systems/serie.js` al jugarlo
    // (`fuerzaDePartido(estadoDelMapa(...))`), no una reconstrucción. Antes se comparaba (===) contra la fórmula de
    // K2b reescrita acá (`fuerzaDesdeCamposK2b`), que agrupa la sinergia en otro orden y difiere en el último bit
    // en algunos estados (con `consistencia.k = 1` aparecieron dos). Que la fórmula del motor sea la de K2b lo
    // cuidan los checks de K2b.
    const { campeonElegido, entradaExtra = null, ajustePlan } = decision.datos;
    revisar(`decisivo ${i}`, previaDePartido(st, { tipo: 'mapa', campeon: campeonElegido, entradaExtra, ajustePlan, charla: true }),
      fuerzaDePartido(estadoDelMapa(st, campeonElegido, entradaExtra)));
  });
  fallarSiK2d(problemas);
});

function congelarK2d(objeto) {
  if (objeto && typeof objeto === 'object' && !Object.isFrozen(objeto)) {
    Object.freeze(objeto);
    Object.values(objeto).forEach(congelarK2d);
  }
  return objeto;
}

checkK2d('K2d previa 4: la previa no toca el estado ni llama al azar (estado congelado y Math.random que tira)', () => {
  const { fechas, drafts, minijuegos } = cosechaDePreviasK2d();
  // La previa no recibe rng (su firma es (state, decision, opciones)): el azar que podría usar a escondidas es
  // Math.random, que acá tira. Lo que hace morder el check es eso y el estado congelado (escribir en él tira).
  const randomOriginal = Math.random;
  const problemas = [];
  Math.random = () => { throw new Error('la previa llamó a Math.random'); };
  try {
    [...fechas.slice(0, 10), ...drafts.slice(0, 10), ...minijuegos.slice(0, 10)].forEach(({ st, decision }, i) => {
      const antes = JSON.stringify(st);
      const congelado = congelarK2d(structuredClone(st));
      try {
        previaDeDecision(congelado, decision);
        if (decision.datos?.motivo === 'minijuego') previaDeDecision(congelado, decision, { resultadoMinijuego: 0.8 });
      } catch (error) {
        problemas.push(`caso ${i}: ${error.message}`);
      }
      if (JSON.stringify(congelado) !== antes) problemas.push(`caso ${i}: el estado cambió`);
    });
  } finally {
    Math.random = randomOriginal;
  }
  fallarSiK2d(problemas);
});

checkK2d('K2d previa 6: ningún texto de la previa ni de la probabilidad jugada muestra ids crudos (ligas, rondas, motivos, minijuegos, roles, snake_case)', () => {
  const { fechas, drafts, minijuegos } = cosechaDePreviasK2d();
  // Palabras que nunca son texto (roles, ids de liga, restos de un valor vacío) y, como texto ENTERO, los ids de
  // ronda, motivo y minijuego: "final" o "semis" son palabras de verdad, pero un campo que dice solo "semis" es el id.
  const ids = new Set([...IDS_ROL, 'undefined', 'null', 'NaN']);
  const enteros = new Set(['cuartos', 'semis', 'final', 'internacional']);
  const problemas = [];
  const textosDe = (previa) => [
    previa.titulo, previa.subtitulo, previa.porQue, previa.nota, previa.textoProbabilidad, previa.propio.nombre, previa.propio.texto,
    previa.rival.nombre, previa.rival.texto,
    ...previa.filas.flatMap((fila) => [fila.etiqueta, fila.texto]),
    ...(previa.opciones ?? []).flatMap((opcion) => [opcion.id, opcion.texto])
  ].filter((texto) => texto !== null);
  const revisar = (nombre, textos, st, extras) => {
    (st.mundo?.ligas ?? []).forEach((liga) => ids.add(liga.id));
    extras.forEach((id) => { const crudo = typeof id === 'string' ? id : id?.id; if (crudo) enteros.add(crudo); });
    for (const texto of textos) {
      const crudo = typeof texto !== 'string' ? String(texto)
        : enteros.has(texto.trim()) ? texto
          : texto.split(/[^\p{L}\p{N}_]+/u).find((palabra) => ids.has(palabra) || /^[a-z0-9]+_[a-z0-9_]+$/.test(palabra));
      if (crudo) problemas.push(`${nombre}: "${texto}" muestra "${crudo}"`);
    }
  };
  fechas.forEach(({ sistema, st, decision, respuesta }, i) => {
    const fecha = st.career.temporada.fechaEnCurso;
    const res = sistema.resolver(st, decision, respuesta, mulberry32(36000 + i));
    const log = res.logs.find(esLogDeFechaK2d);
    revisar(`fecha ${i}`, [...textosDe(previaDeDecision(st, decision)), textoDeProbabilidadJugada(log)], st, fecha.motivos ?? []);
  });
  [...drafts, ...minijuegos].forEach(({ st, decision }, i) => {
    const previas = [previaDeDecision(st, decision), previaDeDecision(st, decision, { resultadoMinijuego: 0.9 })];
    revisar(`mapa ${i}`, previas.flatMap(textosDe), st, [decision.datos?.minijuego, decision.datos?.momento, st.serie.ronda]);
  });
  fallarSiK2d(problemas);
});

// ============================================================================
// K4-B — la serie como plan (PLAN.md "K4 — decisiones de spec", K4-B; reemplaza a J6 y a D63): la tarjeta del plan
// de Fearless declara la p de cada mapa y es la que el motor tira (regla 15); el rival también quema; el juego frena
// solo en lo importante.
// ============================================================================

const CASOS_K4B = 24;
const PLANES_K4B = ['guardar', 'conTodo', 'sorpresa', 'coach'];
const SEEDS_MAX_K4B = 80;
const cosechasK4b = new Map();

// Las pausas reales del plan de Fearless (al arrancar y al re-planear), de `criterio`. Una cosecha por valor de
// `consistencia.k`, como la de K2d.
function cosechaDePlanesK4b() {
  const clave = BALANCE.consistencia.k;
  if (cosechasK4b.has(clave)) {
    return cosechasK4b.get(clave);
  }
  const casos = [];
  const espia = (sistema, st, decision, rng) => {
    if (sistema.id === 'serie' && decision.datos?.motivo === 'plan' && casos.length < CASOS_K4B) {
      casos.push({ st, decision });
    }
    return ESTRATEGIAS_K0.criterio(sistema, st, decision, rng);
  };
  for (let seed = 1; seed <= SEEDS_MAX_K4B && casos.length < CASOS_K4B; seed += 1) {
    correrCarreraSimulate(seed, 60, espia);
  }
  if (casos.length < 10) {
    throw new Error(`cosecha vacía: ${casos.length} pausas del plan`);
  }
  cosechasK4b.set(clave, casos);
  return casos;
}

const esLogDeMapaK4b = (log) => log.type === 'serie' && (log.resultado === 'W' || log.resultado === 'L');

// Juega la serie desde la pausa del plan con `opcionId` y devuelve los logs de los mapas tirados, hasta que la serie
// cierra o vuelve a frenar a re-planear. El mapa decisivo va sin charla y con el minijuego neutro (0,5): lo que esos
// dos mueven lo comparan los checks de K2d.
function jugarPlanK4b(st, decision, opcionId, semilla) {
  const serie = sistemaPorId('serie');
  const rng = mulberry32(semilla);
  let res = serie.resolver(st, decision, { opcionId }, rng);
  const mapas = [];
  for (let paso = 0; paso < 12; paso += 1) {
    const cierre = res.logs.findIndex((log) => log.postSerie);
    mapas.push(...(cierre < 0 ? res.logs : res.logs.slice(0, cierre)).filter(esLogDeMapaK4b));
    const datos = res.decision?.datos;
    if (cierre >= 0 || !res.decision || datos?.motivo === 'plan') {
      return mapas;
    }
    const respuesta = datos.motivo === 'decisivo' ? { opcionId: 'sinCharla' } : { resultado: 0.5, charla: false };
    res = serie.resolver(res.state, res.decision, respuesta, rng);
  }
  throw new Error('la serie no cerró en 12 pasos');
}

checkK2d('K4-B regla 15: la p por mapa que declara cada plan de Fearless es exactamente la que tira el motor (===), en todos los planes ofrecidos, sobre series de carreras reales', () => {
  const casos = cosechaDePlanesK4b();
  const problemas = [];
  let comparados = 0;
  let decisivos = 0;
  const planesVistos = new Set();
  casos.forEach(({ st, decision }, i) => {
    const previa = previaDeDecision(st, decision);
    decision.opciones.forEach((opcion, j) => {
      const declarada = previa?.opciones?.find((o) => o.id === opcion.id);
      if (!declarada?.pMapas) {
        problemas.push(`plan ${i} (${opcion.id}): la tarjeta no declara su p por mapa`);
        return;
      }
      if (declarada.pMapas.length !== opcion.pMapas.length || declarada.pMapas.some((p, k) => p !== opcion.pMapas[k])) {
        problemas.push(`plan ${i} (${opcion.id}): la tarjeta muestra [${declarada.pMapas}] y la decisión del motor [${opcion.pMapas}]`);
      }
      const primero = st.serie.mapaActual + 1;
      for (const log of jugarPlanK4b(st, decision, opcion.id, 41000 + i * 10 + j)) {
        const k = log.mapa - primero;
        comparados += 1;
        if (k === declarada.pMapas.length - 1) {
          decisivos += 1;
        }
        if (declarada.pMapas[k] !== log.p) {
          problemas.push(`plan ${i} (${opcion.id}), mapa ${log.mapa}: la tarjeta dice ${declarada.pMapas[k]}, se tiró ${log.p}`);
        }
      }
      planesVistos.add(opcion.id);
    });
  });
  fallarSiK2d(problemas);
  if (comparados < 100 || decisivos < 5 || planesVistos.size < PLANES_K4B.length) {
    throw new Error(`check vacío: ${comparados} mapas comparados, ${decisivos} decisivos, planes vistos: ${[...planesVistos].join(', ')}`);
  }
});


check('K4-B el rival también quema: con el Fearless su fuerza de mapa cae mapa a mapa (misma regla que la tuya), y en el mapa 1 es la de la serie', () => {
  let caidas = 0;
  for (let seed = 1; seed <= 40; seed += 1) {
    const base = createInitialState(seed, mulberry32(seed));
    let st = {
      ...base,
      serie: { ...base.serie, activa: true, rival: { org: 'Rival', fuerza: 60 }, formato: 5, quemados: [], mapaActual: 0, rivalJuega: null, rivalJuegaEnMapa: -1 }
    };
    const fuerzas = [];
    for (let i = 0; i < 5; i += 1) {
      st = conQuemaDelRival(st, objetivoDelRival(st, st.serie.quemados));
      fuerzas.push(fuerzaRivalDeMapa(st));
      st = { ...st, serie: { ...st.serie, mapaActual: i + 1 } };
    }
    if (Math.abs(fuerzas[0] - 60) > 1e-9) {
      throw new Error(`seed ${seed}: en el mapa 1, con el mejor del meta, el rival juega con ${fuerzas[0]} y no con su fuerza de serie (60)`);
    }
    for (let k = 1; k < 5; k += 1) {
      if (fuerzas[k] > fuerzas[k - 1] + 1e-12) {
        throw new Error(`seed ${seed}: la fuerza del rival sube del mapa ${k} al ${k + 1} (${fuerzas.map((x) => x.toFixed(2)).join(' → ')})`);
      }
    }
    if (fuerzas[4] < fuerzas[0] - 0.5) {
      caidas += 1;
    }
  }
  if (caidas < 40) {
    throw new Error(`el Fearless degradó al rival en solo ${caidas} de 40 series`);
  }
});

// K6a-R reemplaza a "el plan al arrancar" en toda serie (K6a-M), que exigía que cada serie arrancara por su plan: una serie de
// eliminación cantada no frena en el plan (lo arma el coach) y su única pausa es el mapa decisivo. Protege, desde K4-B, que una serie
// no sea una maratón de pausas.
checkLento('K4-B pausas por serie: el plan al arrancar (K6a-R: salvo la cantada, que no frena en el plan) y después como mucho 2 (te leyeron el guardado, el mapa decisivo; la cantada, solo el decisivo); ninguna serie queda «sin nada en juego» (K6a-M: todas son de eliminación); minijuegos de serie solo en el mapa decisivo de semis, final e internacional; la charla del coach como mucho una por temporada', () => {
  const series = new Map();
  const cantadas = new Set();
  const problemas = [];
  let sinNada = 0;
  let charlas = 0;
  let decisivas = 0;
  for (let seed = 1; seed <= 60; seed += 1) {
    const usadas = new Set();
    // `resolverAuto`, salvo la charla: este bot la usa SIEMPRE que se la ofrecen (si se ofreciera dos veces en una
    // temporada, se vería).
    const responder = (sistema, st, decision, rng) => {
      if (sistema.id !== 'serie') {
        return sistema.resolverAuto(st, decision, rng);
      }
      const datos = decision.datos ?? {};
      const clave = `${seed}|${st.player.splitCount}|${st.serie.ronda}|${st.career.seriesJugadas}`;
      const tipo = datos.motivo === 'minijuego' ? datos.momento : (datos.replan ? 'replan' : datos.motivo);
      if (!series.has(clave)) {
        series.set(clave, []);
      }
      series.get(clave).push(tipo);
      if (st.serie.cantada) {
        cantadas.add(clave);
      }
      if (tipo !== 'post_serie' && st.serie.sinNadaEnJuego) {
        problemas.push(`seed ${seed}: una serie sin nada en juego frenó (${tipo})`);
      }
      if (datos.motivo === 'minijuego' && tipo !== 'post_serie') {
        if (tipo !== 'mapa_decisivo' || !esMapaDeDesempate(st.serie.marcador, st.serie.formato)
          || !['semis', 'final', 'internacional'].includes(st.serie.ronda)) {
          problemas.push(`seed ${seed}: minijuego ${tipo} en ${st.serie.ronda} con ${st.serie.marcador.join('-')}`);
        }
      }
      if (tipo === 'mapa_decisivo' || tipo === 'decisivo') {
        decisivas += 1;
      }
      const ofreceCharla = datos.charla?.disponible === true || (decision.opciones ?? []).some((o) => o.id === 'charla');
      if (ofreceCharla) {
        if (!charlaDisponible(st) || usadas.has(st.calendario.anio)) {
          problemas.push(`seed ${seed}: la charla del coach se ofreció de nuevo en ${st.calendario.anio}`);
        }
        usadas.add(st.calendario.anio);
        charlas += 1;
        return datos.motivo === 'minijuego' ? { resultado: 0.5, charla: true } : { opcionId: 'charla' };
      }
      return sistema.resolverAuto(st, decision, rng);
    };
    const rng = mulberry32(seed);
    let state = createInitialState(seed, rng);
    for (let i = 0; i < 60 && !state.terminado; i += 1) {
      const paso = avanzarSplitAuto(state, rng, responder);
      sinNada += paso.logs.filter((log) => log.postSerie && log.sinNadaEnJuego).length;
      state = paso.state;
    }
  }
  for (const [clave, lista] of series) {
    const enSerie = lista.filter((tipo) => tipo !== 'post_serie');
    if (enSerie.length === 0) {
      continue;
    }
    if (cantadas.has(clave)) {
      if (enSerie.length !== 1 || !['decisivo', 'mapa_decisivo'].includes(enSerie[0])) {
        problemas.push(`${clave}: una serie cantada frenó en algo que no es su mapa decisivo (${enSerie.join(', ')})`);
      }
      continue;
    }
    if (enSerie[0] !== 'plan' || enSerie.filter((tipo) => tipo === 'plan').length !== 1) {
      problemas.push(`${clave}: la serie no arrancó por un solo plan (${enSerie.join(', ')})`);
    }
    if (enSerie.length - 1 > 2 || enSerie.filter((tipo) => tipo === 'replan').length > 1) {
      problemas.push(`${clave}: ${enSerie.length - 1} pausas además del plan (${enSerie.join(', ')})`);
    }
  }
  // K6a-M reemplaza a `sinNada < 20` del check vacío (cuando el umbral dejaba series sin frenar): ahora tienen que ser 0.
  if (sinNada > 0) {
    problemas.push(`${sinNada} series quedaron sin nada en juego: una serie de eliminación no se resuelve sola (K6a-M)`);
  }
  fallarSiK2d(problemas);
  if (series.size < 100 || charlas < 20 || decisivas < 40) {
    throw new Error(`check vacío: ${series.size} series que frenaron, ${sinNada} sin nada en juego, ${charlas} charlas, ${decisivas} mapas decisivos`);
  }
});

// ============================================================================
// K6a-M (PLAN.md "K6a — el ensayo de K6", K6a-M): lo que el ensayo encontró en el motor. Una cosecha de carreras de
// `criterio` (con la prueba de ingreso siempre clavada) alimenta cuatro checks: las series que frenan, la previa con el
// rival del resultado, la prueba clavada con su desenlace, y "si ganás, entrás a playoffs" solo cuando siembra.
// ============================================================================
const CARRERAS_K6AM = 40;
// K6c-fix: la línea del desenlace de la prueba del amateur dejó de decir "la prueba" en K6c ("pasaste = firmás"): ahora dice
// "Te firman: sacaste X% y la vara era Y%." o "No llegaste: ... la vara era Y% ...". El check había quedado viejo frente a ese texto
// (buscaba "prueba" y "te firman" en minúscula: 58 problemas falsos en la validación completa de `6dc0ff8`). La de la prueba del
// mercado sigue diciendo "prueba". Rojo con la línea del desenlace sacada del log de `resolverLaPrueba`.
const RE_PRUEBA_K6AM = /prueba|la vara era/i;
const RE_TE_FIRMAN_K6AM = /te firman/i;
let cosechaK6aM = null;
function cosechaDeCarrerasK6aM() {
  if (cosechaK6aM) {
    return cosechaK6aM;
  }
  const c = {
    series: 0, mundial: 0, mundialPorTope: 0, finalesTier2: 0, sinParada: [], titulos: 0, titulosSinFinal: [],
    // K6a-R: las finales (y las que no frenaron en el plan), las cantadas (las que frenaron en el plan, las que llegaron al
    // mapa decisivo y las que ahí no frenaron), los planes que frenaron una serie cantada, y las líneas del feed de cada cantada.
    finales: 0, finalesSinPlan: [], cantadas: 0, cantadasConPlan: [], cantadasAlDecisivo: 0, cantadasSinDecisivo: [],
    cantadasPorTopeDelMundial: 0, planEnCantada: [], lineasCantadas: [], cantadasSinLinea: [],
    previas: 0, previaDistinta: [], defineFueraDeCierre: [], defineEnCierre: 0,
    pruebas: 0, firmasAmateur: 0, jugaron: 0, pruebaSinDesenlace: [], firmoYNoJugo: []
  };
  for (let seed = 1; seed <= CARRERAS_K6AM; seed += 1) {
    const rng = mulberry32(seed);
    let state = createInitialState(seed, rng);
    let firmaPendiente = null;
    for (let i = 0; i < 60 && !state.terminado; i += 1) {
      const planes = new Set();
      const decisivos = new Set();
      let paradasDelMundialAntesDeLaFinal = 0;
      const previas = [];
      const pruebas = [];
      const responder = (sistema, st, decision, r) => {
        const datos = decision.datos ?? {};
        if (datos.motivo === 'plan' && !datos.replan && st.serie?.activa) {
          planes.add(`${st.serie.ronda}|${st.serie.etapa ?? null}|${st.serie.rival.org}`);
          // K6a-R: un plan que frena al arrancar una serie que no es final tiene que ser de una serie abierta (la p del coach
          // en la franja), medido acá con la misma vara y no con lo que el motor guardó.
          if (st.serie.mapaActual === 0 && !esFinalK6aR(st.serie) && ladoCantadoK6aR(pSerieDelCoachK6aR(st)) !== null) {
            c.planEnCantada.push(`seed ${seed} split ${i}: ${st.serie.ronda} vs ${st.serie.rival.org} frenó en el plan con p ${pSerieDelCoachK6aR(st).toFixed(3)}`);
          }
        }
        if (st.serie?.activa && (datos.motivo === 'decisivo' || (datos.motivo === 'minijuego' && datos.momento === 'mapa_decisivo'))) {
          decisivos.add(`${st.serie.ronda}|${st.serie.etapa ?? null}|${st.serie.rival.org}`);
        }
        // Las paradas del Mundial antes de su final (el Swiss y el bracket): con menos de las que deja el tope T9 antes de la
        // reserva de la final, el tope no cortó ninguna.
        if (sistema.id === 'internacional' && !(st.serie?.activa && st.serie.torneo === 'mundial' && st.serie.etapa === 'final')) {
          paradasDelMundialAntesDeLaFinal += 1;
        }
        if (sistema.id === 'temporada' && datos.motivo === 'momento') {
          previas.push(previaDeDecision(st, decision)?.rival?.nombre ?? null);
          if (motivoPrincipal(st.career.temporada.fechaEnCurso?.motivos ?? []) === 'define_clasificacion') {
            if (esCierreK6aM(st.player.splitCount)) {
              c.defineEnCierre += 1;
            } else {
              c.defineFueraDeCierre.push(`seed ${seed} split ${i} (splitCount ${st.player.splitCount})`);
            }
          }
        }
        if (datos.momento === 'tryout') {
          pruebas.push({ sistema: sistema.id, org: datos.oferta?.org?.nombre ?? null });
          return { resultado: 1 };
        }
        return ESTRATEGIAS_K0.criterio(sistema, st, decision, r);
      };
      const titulosAntes = state.career.registro.titulos.length;
      const paso = avanzarSplitAuto(state, rng, responder);
      state = paso.state;

      const posts = paso.logs.filter((log) => log.postSerie);
      const lineas = paso.logs.filter((log) => log.type === 'serie' && log.cantada && !log.postSerie);
      c.lineasCantadas.push(...lineas.map((log) => ({ donde: `seed ${seed} split ${i}`, message: log.message, cantada: log.cantada, pSerie: log.pSerie })));
      const cantadasDelSplit = posts.filter((log) => log.cantada).length;
      if (lineas.length !== cantadasDelSplit) {
        c.cantadasSinLinea.push(`seed ${seed} split ${i}: ${cantadasDelSplit} series cantadas y ${lineas.length} líneas que lo dicen`);
      }
      const topeDelMundialAntesDeLaFinal = BALANCE.mundial.maxInterrupciones - BALANCE.mundial.reservaParaLaFinal;
      for (const log of posts) {
        const clave = `${log.ronda}|${log.etapa ?? null}|${log.rival}`;
        const donde = `seed ${seed} split ${i}: ${log.ronda}${log.etapa ? ` (${log.etapa})` : ''} vs ${log.rival} ${log.marcador.join('-')}`;
        // K6a-R (a): toda final frena en su plan (la del Mundial tiene su reserva: el tope T9 no la corta). Se reconoce por el log,
        // no con `esFinalDeSerie`, para que el check no dependa de la función que mide.
        if (log.ronda === 'final' || (log.torneo === 'mundial' && log.etapa === 'final')) {
          c.finales += 1;
          if (!planes.has(clave)) {
            c.finalesSinPlan.push(donde);
          }
        }
        // K6a-R (b): la cantada no frena en el plan y frena en su mapa decisivo si llega (salvo que el tope T9 del Mundial ya
        // estuviera lleno antes de la final).
        if (log.cantada) {
          c.cantadas += 1;
          if (planes.has(clave)) {
            c.cantadasConPlan.push(`${donde} (${log.cantada})`);
          }
          if (log.mapas.length === log.formato) {
            if (decisivos.has(clave)) {
              c.cantadasAlDecisivo += 1;
            } else if (log.torneo === 'mundial' && paradasDelMundialAntesDeLaFinal >= topeDelMundialAntesDeLaFinal) {
              c.cantadasPorTopeDelMundial += 1;
            } else {
              c.cantadasSinDecisivo.push(`${donde} (${log.cantada})`);
            }
          }
        }
        c.series += 1;
        if (log.torneo === 'mundial') {
          c.mundial += 1;
        } else if (log.ronda === 'final' && state.career.tier === 2) {
          c.finalesTier2 += 1;
        }
        if (log.cantada) {
          // K6a-R: la cantada no frena en el plan; lo que le toca lo mide el check K6a-R (b).
          continue;
        }
        // El tope de paradas del Mundial (T9) puede poner el plan del coach en cuartos y semis del Mundial —con su aviso en el
        // feed—, nunca en la final (que tiene su reserva): esa es la única serie que puede no frenar.
        const porElTopeDelMundial = log.torneo === 'mundial' && log.etapa !== 'final'
          && paso.logs.some((l) => l.type === 'internacional' && l.message.startsWith('Este Mundial ya no frena más'));
        if (porElTopeDelMundial && !planes.has(`${log.ronda}|${log.etapa ?? null}|${log.rival}`)) {
          c.mundialPorTope += 1;
          continue;
        }
        if (!planes.has(clave) || log.sinNadaEnJuego) {
          c.sinParada.push(donde);
        }
      }
      for (const titulo of state.career.registro.titulos.slice(titulosAntes)) {
        if (titulo.tier === 1 || titulo.tier === 2) {
          c.titulos += 1;
          if (!posts.some((log) => log.ronda === 'final' && log.gano && log.torneo !== 'mundial')) {
            c.titulosSinFinal.push(`seed ${seed} split ${i}: ${titulo.nombre} (tier ${titulo.tier}) sin una final que frenó`);
          }
        }
      }

      const resultados = paso.logs.filter((log) => log.type === 'temporada' && typeof log.p === 'number');
      previas.forEach((rival, k) => {
        c.previas += 1;
        const encabezado = encabezadoDeResultado(resultados[k]);
        if (!rival || encabezado?.rival !== rival || !resultados[k].message.includes(rival)) {
          c.previaDistinta.push(`seed ${seed} split ${i}: la previa dijo ${rival}, el resultado ${encabezado?.rival ?? 'sin rival'}`);
        }
      });

      for (const prueba of pruebas) {
        c.pruebas += 1;
        const desenlace = paso.logs.filter((log) => (log.type === 'amateur' || log.type === 'mercado') && RE_PRUEBA_K6AM.test(log.message));
        if (desenlace.length === 0) {
          c.pruebaSinDesenlace.push(`seed ${seed} split ${i}: prueba con ${prueba.org ?? '?'} (${prueba.sistema}) sin una línea de cómo terminó`);
        }
        if (prueba.sistema === 'amateur' && prueba.org) {
          const firmo = desenlace.some((log) => RE_TE_FIRMAN_K6AM.test(log.message));
          if (firmo !== state.career.orgs.includes(prueba.org)) {
            c.pruebaSinDesenlace.push(`seed ${seed} split ${i}: el feed dice que ${firmo ? '' : 'no '}firmó con ${prueba.org} y el estado no`);
          }
          if (firmo) {
            c.firmasAmateur += 1;
            firmaPendiente = { org: prueba.org, desde: i };
          }
        }
      }
      if (firmaPendiente && i > firmaPendiente.desde) {
        if (state.career.currentOrg === firmaPendiente.org && jugasteUnSplitConLaOrg(state)) {
          c.jugaron += 1;
          firmaPendiente = null;
        } else if (state.career.currentOrg !== firmaPendiente.org) {
          const jugo = state.career.registro.porOrg.some((fila) => fila.org === firmaPendiente.org
            && Object.values(fila.splitsPorTier).some((n) => n > 0));
          if (jugo) {
            c.jugaron += 1;
          } else {
            c.firmoYNoJugo.push(`seed ${seed}: firmó con ${firmaPendiente.org} en el split ${firmaPendiente.desde} y se fue sin jugar un split`);
          }
          firmaPendiente = null;
        }
      }
    }
  }
  cosechaK6aM = c;
  return c;
}

// K6a-R reemplaza a "K6a-M ninguna serie de eliminación ni final se resuelve sin parada: cada serie (...) frena en su plan", que
// exigía el plan en TODA serie de eliminación: la cantada (la p del plan del coach fuera de la franja `pAbiertaEliminacion`) ya no
// frena en el plan sino en su mapa decisivo si llega, y eso lo miden los checks "K6a-R" de abajo. Este sigue protegiendo, desde
// K6a-M, que una serie de eliminación abierta no se resuelva sola, que ninguna se diga "sin nada en juego" y que cada título salga de
// una final que frenó.
checkLento(`K6a-M ninguna serie de eliminación abierta se resuelve sin parada ni se dice "sin nada en juego": cada serie que no está cantada (playoffs de tier 1, la final de tier 2, el bracket del Mundial salvo lo que corta su tope T9) frena en su plan, y cada título de tier 1 o 2 sale de una final que frenó (criterio, ${CARRERAS_K6AM} carreras)`, () => {
  const c = cosechaDeCarrerasK6aM();
  fallarSiK2d([...c.sinParada, ...c.titulosSinFinal]);
  if (c.series < 150 || c.mundial < 20 || c.finalesTier2 < 5 || c.titulos < 10 || c.series - c.cantadas < 50) {
    throw new Error(`check vacío: ${c.series} series (${c.cantadas} cantadas), ${c.mundial} del Mundial (${c.mundialPorTope} por el tope T9), ${c.finalesTier2} finales de tier 2, ${c.titulos} títulos`);
  }
  // La regla sobre series sintéticas: ninguna diferencia de fuerza vuelve "sin nada en juego" a una serie de eliminación.
  for (const ronda of ['cuartos', 'semis', 'final', 'internacional']) {
    const serie = { ronda, fuerzaInicial: 90, rival: { fuerza: 10 } };
    if (!esSerieDeEliminacion(serie) || esSerieSinNadaEnJuegoK6aM(serie)) {
      throw new Error(`una serie de ${ronda} con 80 puntos de diferencia se diría "sin nada en juego"`);
    }
  }
});

// ============================================================================
// K6a-R (PLAN.md, "Decisión del supervisor (K6a-R, el ritmo de la eliminación)"): una serie de eliminación frena en lo que
// decide. Toda final frena en el plan; una abierta (la p de serie del plan del coach entre `pAbiertaEliminacion` y su
// complemento) frena en el plan; una cantada no: el coach arma el plan, el feed lo dice, y frena en el mapa decisivo si llega.
// Los tres miden la misma cosecha de K6a-M (criterio, con la prueba clavada).
// ============================================================================

// Protege, desde K6a-R, que ninguna final (la doméstica de tier 1, la de tier 2 y la del Mundial) se resuelva sin frenar en su plan,
// por más cantada que esté (regla 7: rojo con `esFinalDeSerie` que siempre dice que no).
checkLento(`K6a-R ninguna final se resuelve sin frenar en el plan: la doméstica de tier 1, la de tier 2 y la del Mundial, por más despareja que sea (criterio, ${CARRERAS_K6AM} carreras)`, () => {
  const c = cosechaDeCarrerasK6aM();
  fallarSiK2d(c.finalesSinPlan.map((donde) => `${donde}: una final que no frenó en el plan`));
  for (const serie of [{ ronda: 'final', etapa: null }, { ronda: 'internacional', etapa: 'final' }]) {
    if (!esFinalK6aR(serie)) {
      throw new Error(`${serie.ronda}/${serie.etapa}: no se reconoce como final`);
    }
  }
  for (const serie of [{ ronda: 'semis', etapa: null }, { ronda: 'cuartos', etapa: null }, { ronda: 'internacional', etapa: 'semis' }]) {
    if (esFinalK6aR(serie)) {
      throw new Error(`${serie.ronda}/${serie.etapa}: se toma por una final`);
    }
  }
  if (c.finales < 30) {
    throw new Error(`check vacío: ${c.finales} finales`);
  }
});

// Protege, desde K6a-R, el ritmo de la eliminación: una serie cantada no frena en el plan (nadie le pregunta al jugador algo que
// el plan casi no mueve), pero sí en el mapa decisivo cuando llega (regla 7: rojo con la cantada frenando en el plan, y con su mapa
// decisivo resuelto solo). Un plan que frena al arrancar una serie que no es final se mide con la misma vara: tiene que estar abierta.
checkLento(`K6a-R una serie de eliminación cantada no frena en el plan, pero sí en su mapa decisivo cuando llega; la que frena en el plan está abierta (criterio, ${CARRERAS_K6AM} carreras)`, () => {
  const c = cosechaDeCarrerasK6aM();
  fallarSiK2d([
    ...c.cantadasConPlan.map((donde) => `${donde}: una serie cantada frenó en el plan`),
    ...c.cantadasSinDecisivo.map((donde) => `${donde}: una serie cantada llegó al mapa decisivo y no frenó`),
    ...c.planEnCantada
  ]);
  if (c.cantadas < 30 || c.cantadasAlDecisivo < 3) {
    throw new Error(`check vacío: ${c.cantadas} series cantadas, ${c.cantadasAlDecisivo} llegaron al mapa decisivo y frenaron (${c.cantadasPorTopeDelMundial} cortadas por el tope T9 del Mundial)`);
  }
});

// Protege, desde K6a-R, que el feed no mienta sobre una serie que no te preguntó: no dice "sin nada en juego" (una serie de
// eliminación siempre tiene algo), nombra si sos favorito o no con la p del plan del coach, y cada cantada tiene su línea
// (regla 7: rojo con las líneas de favorito y de underdog cruzadas, y con la de "sin nada en juego").
checkLento(`K6a-R el feed de una serie cantada no dice "sin nada en juego" y nombra si sos favorito o no, coherente con la p de la serie (criterio, ${CARRERAS_K6AM} carreras)`, () => {
  const c = cosechaDeCarrerasK6aM();
  const pAbierta = BALANCE.serie.plan.pAbiertaEliminacion;
  const problemas = [...c.cantadasSinLinea];
  let favoritos = 0;
  for (const linea of c.lineasCantadas) {
    const dice = `${linea.donde}: "${linea.message}"`;
    if (/sin nada en juego/i.test(linea.message)) {
      problemas.push(`${dice} dice "sin nada en juego"`);
    }
    if (typeof linea.pSerie !== 'number' || !linea.message.includes(`${Math.round(linea.pSerie * 100)}%`)) {
      problemas.push(`${dice} no dice su p (${linea.pSerie})`);
    }
    const diceFavorito = /sos el favorito claro/i.test(linea.message) && !/no sos el favorito/i.test(linea.message);
    const diceUnderdog = /no sos el favorito/i.test(linea.message) && !/sos el favorito claro/i.test(linea.message);
    if (linea.cantada === 'favorito') {
      favoritos += 1;
      if (!(linea.pSerie > 1 - pAbierta) || !diceFavorito) {
        problemas.push(`${dice}: favorito con p ${linea.pSerie}`);
      }
    } else if (linea.cantada === 'underdog') {
      if (!(linea.pSerie < pAbierta) || !diceUnderdog) {
        problemas.push(`${dice}: underdog con p ${linea.pSerie}`);
      }
    } else {
      problemas.push(`${dice}: cantada de un lado que no existe (${linea.cantada})`);
    }
  }
  fallarSiK2d(problemas);
  if (c.lineasCantadas.length < 30 || favoritos < 10) {
    throw new Error(`check vacío: ${c.lineasCantadas.length} líneas de series cantadas, ${favoritos} de favorito`);
  }
});

checkLento(`K6a-M la previa y el resultado nombran al mismo rival: la tarjeta lee la fecha de su log, no del estado de cuando se pinta (criterio, ${CARRERAS_K6AM} carreras)`, () => {
  const c = cosechaDeCarrerasK6aM();
  fallarSiK2d(c.previaDistinta);
  if (c.previas < 100) {
    throw new Error(`check vacío: ${c.previas} previas de fecha marcada`);
  }
  if (encabezadoDeResultado({ type: 'temporada', message: 'Cerrás el split 7º de 8.' }) !== null) {
    throw new Error('la línea de cierre del split no es una fecha: no puede llevar un "GANARON vs" prestado');
  }
});

checkLento(`K6a-M toda prueba clavada termina con su desenlace dicho en el feed y coherente con el estado, y si firmaste, jugás un split con ese equipo (criterio con la prueba clavada, ${CARRERAS_K6AM} carreras)`, () => {
  const c = cosechaDeCarrerasK6aM();
  fallarSiK2d([...c.pruebaSinDesenlace, ...c.firmoYNoJugo]);
  if (c.pruebas < 30 || c.firmasAmateur < 10 || c.jugaron < 10) {
    throw new Error(`check vacío: ${c.pruebas} pruebas, ${c.firmasAmateur} firmas de tier 3, ${c.jugaron} que jugaron`);
  }
});

checkLento(`K6a-M regla 15: "si ganás, entrás a playoffs" solo en el split que siembra los playoffs, y "Clasificaron al torneo de mitad de año" solo con el equipo primero (criterio, ${CARRERAS_K6AM} carreras)`, () => {
  const c = cosechaDeCarrerasK6aM();
  fallarSiK2d(c.defineFueraDeCierre);
  if (c.defineEnCierre < 20) {
    throw new Error(`check vacío: ${c.defineEnCierre} fechas que definen la clasificación en el split de cierre`);
  }
  // La tabla que define de K4-A (Propio pelea el sexto puesto), escrita acá: este check corre antes de que existan sus constantes.
  const t = temporadaSinteticaK4A([8, 12, 12, 12, 12, 12, 8, 5, 5, 7]);
  const liga = { tier: 1, formatoPlayoffs: { clasifican: 6, byes: 2, bo: 5 } };
  if (defineClasificacion({ player: { splitCount: BALANCE.edad.splitsPorEdad - 1 } }, liga, t) === null) {
    throw new Error('en el split de cierre la tabla de K4-A define la clasificación');
  }
  if (defineClasificacion({ player: { splitCount: BALANCE.edad.splitsPorEdad } }, liga, t) !== null) {
    throw new Error('en un split que no cierra la temporada no hay playoffs que definir');
  }
  const evento = TODOS_LOS_EVENTOS.find((e) => e.id === 'el_internacional_de_mitad_de_ano');
  const conPosicion = (posicion) => ({ player: { splitCount: 30 }, career: { posicion } });
  if (cumpleCondicionesK6aM(conPosicion(7), evento.conditions) || !cumpleCondicionesK6aM(conPosicion(1), evento.conditions)) {
    throw new Error('"Clasificaron al torneo de mitad de año" tiene que pedir el equipo primero del split');
  }
});

// ============================================================================
// K3-A (PLAN.md "K3 — decisiones de spec", K3-A): las barras que no se saturan. Estructura con constantes neutras
// (k = 0, r = 0, rH = 0, topeDescanso = 100): la huella no se mueve (check "K1 versión"). Estos checks prueban que la
// estructura hace lo que dice CUANDO K3c mueva las constantes: cada uno mueve una constante EN MEMORIA, mide un paso y
// la devuelve a su valor.
// ============================================================================

const barrasK3A = await import('../core/barras.js');
const { conMarcasDeRutina: conMarcasDeRutinaK3B } = await import('../core/curvas.js');
const { aplicarStatsDeMinijuego: aplicarStatsDeMinijuegoK3B } = await import('../systems/serie.js');
const { ligaOZonaDeCarrera: ligaDeCarreraK3A } = await import('../core/competicion.js');
const TIPOS_K3A = ['fecha', 'mapa'];

// Mueve constantes de BALANCE en memoria mientras corre `fn`, y las devuelve siempre.
function conBalanceK3A(cambios, fn) {
  const previos = cambios.map(([bloque, clave]) => [bloque, clave, BALANCE[bloque][clave]]);
  try {
    for (const [bloque, clave, valor] of cambios) BALANCE[bloque][clave] = valor;
    return fn();
  } finally {
    for (const [bloque, clave, valor] of previos) BALANCE[bloque][clave] = valor;
  }
}

// Estados reales entre splits (carreras con `avanzarSplitAuto`): pro con equipo y temporada jugada, y amateurs.
let estadosK3A = null;
function estadosDeCarreraK3A() {
  if (!estadosK3A) {
    const pro = [];
    const amateur = [];
    for (let seed = 1; seed <= 8; seed += 1) {
      const rng = mulberry32(9300 + seed);
      let st = createInitialState(9300 + seed, rng);
      for (let i = 0; i < 30 && !st.terminado; i += 1) {
        st = avanzarSplitAuto(st, rng).state;
        if (st.terminado || st.pendiente) continue;
        if (st.phase === 'profesional' && st.career.currentOrg && st.career.companeros.length > 0
          && (st.career.temporada?.tabla?.length ?? 0) > 0 && i % 3 === 0) pro.push(structuredClone(st));
        if (st.phase === 'amateur' && i % 4 === 0) amateur.push(structuredClone(st));
      }
    }
    estadosK3A = { pro, amateur };
  }
  return { pro: estadosK3A.pro.map((s) => structuredClone(s)), amateur: estadosK3A.amateur.map((s) => structuredClone(s)) };
}

const conBarrasK3A = (st, cambios) => ({ ...st, player: { ...st.player, ...cambios.player, stats: { ...st.player.stats, ...cambios.stats } } });

check('K3-A consistencia 1: ruidoEfectivo pasa su σ por factorDeConsistencia, y BALANCE.consistencia se lee solo adentro de factorDeConsistencia (estático)', () => {
  const raiz = path.join(srcDir, '..');
  const rel = (p) => path.relative(raiz, p).replace(/\\/g, '/');
  const archivos = (dir) => fs.readdirSync(dir, { withFileTypes: true }).flatMap((e) => {
    const p = path.join(dir, e.name);
    if (e.isDirectory()) return e.name === 'dev' ? [] : archivos(p);
    return /\.js$/.test(p) && rel(p) !== 'src/data/balance.js' ? [p] : [];
  });
  const sinComentarios = (txt) => txt
    .replace(/(^|\s)\/\*[\s\S]*?\*\//g, (bloque) => bloque.replace(/[^\n]/g, ''))
    .split(/\r?\n/).map((l) => l.replace(/(^|\s)\/\/.*$/, '$1'));
  const partidoJs = sinComentarios(fs.readFileSync(path.join(srcDir, 'core', 'partido.js'), 'utf8'));
  const cuerpo = (nombre) => {
    const inicio = partidoJs.findIndex((linea) => new RegExp(`^export function ${nombre}\\(`).test(linea));
    const fin = inicio < 0 ? -1 : partidoJs.findIndex((linea, i) => i > inicio && /^}/.test(linea));
    if (inicio < 0 || fin < 0) throw new Error(`no encontré \`export function ${nombre}(\` en src/core/partido.js`);
    return [inicio, fin];
  };
  const [iRuido, fRuido] = cuerpo('ruidoEfectivo');
  const [iFactor, fFactor] = cuerpo('factorDeConsistencia');
  const ruido = partidoJs.slice(iRuido + 1, fRuido);
  // El factor se calcula con la mentalidad del jugador y multiplica a los DOS σ que devuelve.
  if (!ruido.some((l) => /\bg\s*=\s*factorDeConsistencia\(\s*state\?\.player\?\.stats\?\.mentalidad\s*\)/.test(l))) {
    throw new Error('ruidoEfectivo no calcula g = factorDeConsistencia(state?.player?.stats?.mentalidad)');
  }
  const retornos = ruido.filter((l) => /^\s*return\b/.test(l));
  const sinFactor = retornos.filter((l) => !/\*\s*g\s*;/.test(l));
  if (retornos.length < 2 || sinFactor.length > 0) {
    throw new Error(`un σ de ruidoEfectivo sale sin el factor de consistencia: ${sinFactor.map((l) => l.trim()).join(' | ') || `(${retornos.length} return)`}`);
  }
  const PATRON = /BALANCE\s*(\.\s*consistencia\b|\[\s*['"`]consistencia['"`]\s*\])|\{[^}]*\bconsistencia\b[^}]*\}\s*=\s*BALANCE\b/;
  const afuera = [];
  let dentro = 0;
  for (const archivo of [...archivos(srcDir), path.join(raiz, 'index.html')]) {
    sinComentarios(fs.readFileSync(archivo, 'utf8')).forEach((linea, i) => {
      if (!PATRON.test(linea)) return;
      if (rel(archivo) === 'src/core/partido.js' && i > iFactor && i < fFactor) {
        dentro += 1;
        return;
      }
      afuera.push(`${rel(archivo)}:${i + 1}: ${linea.trim()}`);
    });
  }
  if (afuera.length > 0) throw new Error(`BALANCE.consistencia leído fuera de factorDeConsistencia: ${afuera.slice(0, 5).join(' | ')}`);
  if (dentro < 1) throw new Error('factorDeConsistencia no lee BALANCE.consistencia: el patrón no está viendo nada');
});

check('K3-A consistencia 2: g(mRef) = 1, g no crece con la mentalidad y respeta [gMin, gMax]; con k = 0 el σ es el de hoy para toda mentalidad; con k > 0 (en memoria) σ = σ_tipo · g(m) y con 20 hay más ruido que con 80', () => {
  const c = BALANCE.consistencia;
  if (!(c.gMin <= 1 && 1 <= c.gMax)) throw new Error(`[gMin, gMax] = [${c.gMin}, ${c.gMax}] no contiene a 1`);
  const sigma = { fecha: BALANCE.partido.sigmaFecha, mapa: BALANCE.partido.sigmaMapa };
  const conM = (m) => ({ player: { stats: { mentalidad: m } } });
  const inicial = createInitialState(1, mulberry32(1));
  for (const k of [0, 0.5, 1, 3, 8]) {
    conBalanceK3A([['consistencia', 'k', k]], () => {
      if (factorDeConsistencia(c.mRef) !== 1) throw new Error(`k ${k}: g(mRef = ${c.mRef}) = ${factorDeConsistencia(c.mRef)}`);
      for (const nada of [null, undefined, Number.NaN]) {
        if (factorDeConsistencia(nada) !== 1) throw new Error(`k ${k}: g(${nada}) = ${factorDeConsistencia(nada)}, sin mentalidad tiene que ser 1`);
      }
      for (let m = 0; m <= BALANCE.stats.max; m += 1) {
        const g = factorDeConsistencia(m);
        const aMano = Math.min(c.gMax, Math.max(c.gMin, 1 + k * (c.mRef - m) / 100));
        if (g !== aMano) throw new Error(`k ${k}: g(${m}) = ${g}, la fórmula da ${aMano}`);
        if (m > 0 && g > factorDeConsistencia(m - 1)) throw new Error(`k ${k}: g crece de ${m - 1} a ${m}`);
        for (const tipo of TIPOS_K3A) {
          const s = ruidoEfectivo(conM(m), tipo);
          if (s !== sigma[tipo] * g) throw new Error(`k ${k}: ruidoEfectivo(m ${m}, ${tipo}) = ${s}, σ·g = ${sigma[tipo] * g}`);
          if (k === 0 && s !== sigma[tipo]) throw new Error(`con k = 0 el σ (${tipo}, m ${m}) cambió: ${s} ≠ ${sigma[tipo]}`);
        }
      }
      for (const tipo of TIPOS_K3A) {
        if (ruidoEfectivo(null, tipo) !== sigma[tipo]) throw new Error(`k ${k}: el cruce ajeno (null) no tiene el σ de su tipo`);
        // El camino real: la mentalidad del estado del jugador.
        const real = ruidoEfectivo(inicial, tipo);
        if (real !== sigma[tipo] * factorDeConsistencia(inicial.player.stats.mentalidad)) {
          throw new Error(`k ${k}: con un estado real, σ ${real} no es σ·g(${inicial.player.stats.mentalidad})`);
        }
        if (k > 0 && !(ruidoEfectivo(conM(20), tipo) > ruidoEfectivo(conM(80), tipo))) {
          throw new Error(`k ${k}: con mentalidad 20 el σ (${ruidoEfectivo(conM(20), tipo)}) no supera al de 80 (${ruidoEfectivo(conM(80), tipo)})`);
        }
      }
    });
  }
});

check('K3-A descanso: con un topeDescanso bajo (en memoria) ningún camino de descanso lo pasa — el sueño de atributos (amateur y pro) y el descansar del receso —, y descansar no baja a quien ya está arriba', () => {
  // K4-D: la sonda parte de TOPE - 2 (antes TOPE - 5): con el corrimiento del stream la muestra de estados dejó de traer un
  // sueño con ganancia > 5, y la sonda quedaba vacía por muestreo. Con 2 de margen sigue probando que el tope corta.
  const TOPE = 30;
  const { pro, amateur } = estadosDeCarreraK3A();
  if (pro.length < 3 || amateur.length < 3) throw new Error(`muestra corta: ${pro.length} pro, ${amateur.length} amateur`);
  const atributos = sistemaPorId('atributos');
  const practica = sistemaPorId('practica');
  const rutina = { id: 'k3a_descanso', reparto: { pulir: 0, nuevo: 0, mecanica: 0, macro: 0, descansar: BALANCE.practica.puntos } };
  const decision = { datos: { rutinas: [rutina] } };
  const correr = () => {
    const sueno = [...pro, ...amateur].map((st, i) => atributos.aplicar(
      conBarrasK3A(st, { player: { sleep: BALANCE.stats.max, deudaSueno: 0 }, stats: { mentalidad: TOPE - 2 } }), mulberry32(9400 + i)
    ).state.player.stats.mentalidad);
    const receso = pro.map((st, i) => resolverPreparacion(
      conBarrasK3A(st, { stats: { mentalidad: TOPE - 2 } }), [rutina], rutina.id, mulberry32(9500 + i)
    ).state.player.stats.mentalidad);
    const arriba = pro.map((st, i) => resolverPreparacion(
      conBarrasK3A(st, { stats: { mentalidad: TOPE + 20 } }), [rutina], rutina.id, mulberry32(9600 + i)
    ).state.player.stats.mentalidad);
    return { sueno, receso, arriba };
  };
  // Sin tope (el de hoy), los dos caminos pasan el tope de la sonda: la sonda ve algo.
  // Fija r = 0 en las dos ramas (bajada y subida): el retorno a la base no debe levantar el sueño sobre el tope.
  const SIN_RETORNO = [['atributos', 'mentalidadRetornoBase', 0], ['atributos', 'mentalidadRetornoBaseSubida', 0]];
  const libre = conBalanceK3A(SIN_RETORNO, correr);
  if (!libre.sueno.some((m) => m > TOPE) || !libre.receso.some((m) => m > TOPE)) {
    throw new Error(`sonda vacía: sin tope ningún descanso pasa ${TOPE} (sueño máx ${Math.max(...libre.sueno)}, receso máx ${Math.max(...libre.receso)})`);
  }
  const topeado = conBalanceK3A([...SIN_RETORNO, ['atributos', 'topeDescanso', TOPE]], correr);
  const pasados = [
    ...topeado.sueno.map((m, i) => [`sueño ${i}`, m]),
    ...topeado.receso.map((m, i) => [`receso ${i}`, m])
  ].filter(([, m]) => m > TOPE + 1e-9);
  if (pasados.length > 0) throw new Error(`con topeDescanso ${TOPE} el descanso lo pasa: ${pasados.slice(0, 5).map(([d, m]) => `${d} → ${m}`).join(', ')}`);
  const bajados = topeado.arriba.filter((m) => m !== TOPE + 20);
  if (bajados.length > 0) throw new Error(`descansar con mentalidad ${TOPE + 20} sobre un tope de ${TOPE} la movió: ${bajados.slice(0, 5).join(', ')}`);
  conBalanceK3A([['atributos', 'topeDescanso', TOPE]], () => {
    const casos = [[20, 50, TOPE], [TOPE - 1, 0.5, TOPE - 0.5], [50, 10, 50], [10, 5, 15]];
    for (const [actual, ganancia, esperado] of casos) {
      const dado = barrasK3A.recuperarPorDescanso(actual, ganancia);
      if (dado !== esperado) throw new Error(`recuperarPorDescanso(${actual}, +${ganancia}) con tope ${TOPE} = ${dado}, se esperaba ${esperado}`);
    }
  });
});

check('K3-A vuelta a la base: con r y rH > 0 (en memoria) un paso de atributos lleva la mentalidad a m + r·(base − m) y uno de rendimiento corre el hype en rH·(baseH − h), con baseH = h0 + a·z + b·(prestigio/100 + extra si hubo internacional)', () => {
  const R = 0.5;
  const a = BALANCE.atributos;
  const r = BALANCE.rendimiento;
  // La vuelta simétrica (bajada = subida = R); la asimétrica la prueba el check que sigue.
  const retornoM = (valor) => [['atributos', 'mentalidadRetornoBase', valor], ['atributos', 'mentalidadRetornoBaseSubida', valor]];
  conBalanceK3A(retornoM(R), () => {
    for (const m of [0, 20, a.mentalidadBase, 90, 100]) {
      const dado = barrasK3A.mentalidadHaciaSuBase(m);
      if (dado !== m + R * (a.mentalidadBase - m)) throw new Error(`mentalidadHaciaSuBase(${m}) = ${dado}`);
    }
  });
  const { pro } = estadosDeCarreraK3A();
  const atributos = sistemaPorId('atributos');
  const rendimiento = sistemaPorId('rendimiento');
  let comparadasM = 0;
  let comparadasH = 0;
  pro.forEach((base, i) => {
    const st = conBarrasK3A(base, { player: { sleep: a.suenoConfortable, deudaSueno: 0 }, stats: { mentalidad: 50, hype: 50 } });
    const m0 = conBalanceK3A(retornoM(0), () => atributos.aplicar(st, mulberry32(9700 + i)).state.player.stats.mentalidad);
    const m1 = conBalanceK3A(retornoM(R), () => atributos.aplicar(st, mulberry32(9700 + i)).state.player.stats.mentalidad);
    // Lejos del piso de caída neta (50 − maxCaida) y de los bordes, el paso es exacto.
    if (m0 > 50 - a.maxCaidaMentalPorSplit + 1 && m0 < BALANCE.stats.max) {
      comparadasM += 1;
      if (Math.abs(m1 - (m0 + R * (a.mentalidadBase - m0))) > 1e-9) {
        throw new Error(`estado ${i}: mentalidad con r 0 → ${m0}, con r ${R} → ${m1}; la fórmula da ${m0 + R * (a.mentalidadBase - m0)}`);
      }
    }
    // La base del hype, a mano.
    const res = st.career.temporada.resultadosPropios;
    const z = res.varianza > 0 ? (res.ganados - res.esperados) / Math.sqrt(res.varianza) : 0;
    const liga = ligaDeCarreraK3A(st);
    const internacional = st.career.registro.internacionales.some((e) => e.anio >= st.calendario.anio - r.hypeAniosInternacional);
    const visibilidad = (liga?.prestigio ?? 0) / 100 + (internacional ? r.hypeVisibilidadPorInternacional : 0);
    const baseH = r.hypeBaseInicial + r.hypeBasePorDesvio * z + r.hypeBasePorVisibilidad * visibilidad;
    if (Math.abs(barrasK3A.baseDeHype(st, liga) - baseH) > 1e-9) throw new Error(`estado ${i}: baseDeHype ${barrasK3A.baseDeHype(st, liga)}, a mano ${baseH}`);
    const h0 = conBalanceK3A([['rendimiento', 'hypeRetornoBase', 0]], () => rendimiento.aplicar(st, mulberry32(9800 + i)).state.player.stats.hype);
    const h1 = conBalanceK3A([['rendimiento', 'hypeRetornoBase', R]], () => rendimiento.aplicar(st, mulberry32(9800 + i)).state.player.stats.hype);
    const esperado = h0 + R * (baseH - 50);
    if (h0 > 0 && h0 < BALANCE.stats.max && esperado > 0 && esperado < BALANCE.stats.max) {
      comparadasH += 1;
      if (Math.abs(h1 - esperado) > 1e-9) throw new Error(`estado ${i}: hype con rH 0 → ${h0}, con rH ${R} → ${h1}; la fórmula da ${esperado} (baseH ${baseH})`);
    }
  });
  if (comparadasM < 3 || comparadasH < 3) throw new Error(`check vacío: ${comparadasM} pasos de mentalidad y ${comparadasH} de hype comparados`);
  // La rama del internacional, sobre un estado sintético (las carreras cortas casi no viajan).
  const st = structuredClone(pro[0]);
  const liga = ligaDeCarreraK3A(st);
  const conInternacionales = (lista) => ({ ...st, career: { ...st.career, registro: { ...st.career.registro, internacionales: lista } } });
  const sin = barrasK3A.visibilidadDeCarrera(conInternacionales([]), liga);
  const con = barrasK3A.visibilidadDeCarrera(conInternacionales([{ anio: st.calendario.anio - r.hypeAniosInternacional }]), liga);
  const viejo = barrasK3A.visibilidadDeCarrera(conInternacionales([{ anio: st.calendario.anio - r.hypeAniosInternacional - 1 }]), liga);
  if (Math.abs(con - sin - r.hypeVisibilidadPorInternacional) > 1e-12 || viejo !== sin) {
    throw new Error(`visibilidad: sin internacional ${sin}, con uno reciente ${con}, con uno viejo ${viejo}`);
  }
});

check('K3c vuelta asimétrica: con bajada 0,3 y subida 0 (en memoria) una mentalidad sobre la base va hacia ella y una debajo no se mueve — en el helper y en un paso de atributos', () => {
  // PLAN.md K3c, "Lo que rompen los valores elegidos", punto 1: la vuelta simétrica subía gratis una mentalidad
  // hundida (perdonaba las malas decisiones y borraba el burnout). Desde abajo se sube descansando o decidiendo.
  const BAJADA = 0.3;
  const a = BALANCE.atributos;
  const asimetrica = [['atributos', 'mentalidadRetornoBase', BAJADA], ['atributos', 'mentalidadRetornoBaseSubida', 0]];
  const sinRetorno = [['atributos', 'mentalidadRetornoBase', 0], ['atributos', 'mentalidadRetornoBaseSubida', 0]];
  conBalanceK3A(asimetrica, () => {
    for (const m of [a.mentalidadBase + 1, 75, 90, BALANCE.stats.max]) {
      const dado = barrasK3A.mentalidadHaciaSuBase(m);
      if (dado !== m + BAJADA * (a.mentalidadBase - m)) throw new Error(`sobre la base: mentalidadHaciaSuBase(${m}) = ${dado}, se esperaba ${m + BAJADA * (a.mentalidadBase - m)}`);
    }
    for (const m of [0, 20, 45, a.mentalidadBase - 1, a.mentalidadBase]) {
      const dado = barrasK3A.mentalidadHaciaSuBase(m);
      if (dado !== m) throw new Error(`debajo de la base (o en ella) la subida 0 la movió: mentalidadHaciaSuBase(${m}) = ${dado}`);
    }
  });
  const { pro } = estadosDeCarreraK3A();
  const atributos = sistemaPorId('atributos');
  let arriba = 0;
  let abajo = 0;
  pro.forEach((base, i) => {
    for (const inicial of [85, 35]) {
      const st = conBarrasK3A(base, { player: { sleep: a.suenoConfortable, deudaSueno: 0 }, stats: { mentalidad: inicial } });
      const m0 = conBalanceK3A(sinRetorno, () => atributos.aplicar(st, mulberry32(9900 + i)).state.player.stats.mentalidad);
      const m1 = conBalanceK3A(asimetrica, () => atributos.aplicar(st, mulberry32(9900 + i)).state.player.stats.mentalidad);
      if (m0 > a.mentalidadBase) {
        const esperado = m0 + BAJADA * (a.mentalidadBase - m0);
        // Lejos del piso de caída neta, el paso es exacto.
        if (esperado > inicial - a.maxCaidaMentalPorSplit + 1) {
          arriba += 1;
          if (Math.abs(m1 - esperado) > 1e-9) throw new Error(`estado ${i} (desde ${inicial}): sin retorno ${m0}, asimétrica ${m1}; la bajada da ${esperado}`);
        }
      } else if (m0 < a.mentalidadBase) {
        abajo += 1;
        if (m1 !== m0) throw new Error(`estado ${i} (desde ${inicial}): debajo de la base, sin retorno ${m0} y asimétrica ${m1}: la subida 0 la movió`);
      }
    }
  });
  if (arriba < 3 || abajo < 3) throw new Error(`check vacío: ${arriba} pasos sobre la base y ${abajo} debajo comparados`);
});

// --- K3c: las metas del bloque A, como checks duros (PLAN.md "K3c — cómo se hace", paso 3) ---
//
// Hasta K3b eran REPORTE (`nivel.metasK2` y `metasK3` de simulate.js, con la meta al lado). K3c fijó las perillas
// (consistencia, vuelta a la base de mentalidad y hype, efectos que duran) y las metas pasan a checks duros, con las
// mismas constantes `META_*` que el reporte. Regla de proceso 17, qué protege cada uno: "tus decisiones construyen tu
// nivel" (K.2) — que el nivel se note en la posición (r, R²) y en la serie (el favorito gana), que la cabeza gobierne
// la consistencia (el batacazo de mentalidad 20 contra 80), que las barras no se saturen (mentalidad, hype) y que un
// efecto dure (retención). Cada check dice en su nombre cuál es su muestra. Los de lote (r, R², Bo5, mentalidad, hype) se
// miden con `criterio` (el bot que juega bien), 800 seeds × 60 splits: el barrido de K3c eligió los valores con 400 × 60,
// pero con 400 el Bo5 del jugador (83,8% ±1,7) quedaba a 0,7 errores estándar del techo de 85; con 800 el error baja a
// ±1,2. La retención es una sonda aparte (`SONDA_RETENCION`, con sus propios casos) y el batacazo es analítico (la p de
// mapa del motor, sin muestra). El check duro del Bo5 es el del lado del JUGADOR (Δ0 >= 0): el de la investigación de K2
// y el que K2c calibró, lo que el bloque A controla. El del rival (≈ 94%) y el conjunto (≈ 87%) pesan la asimetría de
// Fearless, que es de K4: el conjunto tiene su check ("K3c meta Bo5 favorito claro (conjunto)") y está en
// `bandasPendientes.js` como bloque B; el del rival solo se reporta.
const SEEDS_METAS_A = 800;
let loteMetasA = null;
function loteDeLasMetasA() {
  if (loteMetasA === null) {
    loteMetasA = correrLote(SEEDS_METAS_A, SPLITS_LOTE_K0, 'criterio');
    // La ablación (`varianzaExplicada`) se calcula al leerla: se fuerza acá para chequear el balance justo después.
    void loteMetasA.nivel.varianzaExplicada;
    afirmarRuidoIntactoK0(`después de correrLote(${SEEDS_METAS_A}, criterio)`);
  }
  return loteMetasA;
}

function valoresDeLasMetasA(lote) {
  const claro = lote.nivel.bo5Motor.favoritoClaro;
  return {
    rMismaLiga: lote.nivel.corregida.rNivelPosicionMismaLiga,
    r2SinRuido: lote.nivel.varianzaExplicada.corregida.soloLigaModelada.r2NivelYEquipoSinRuido,
    bo5Jugador: claro.jugadorFavorito.ganaFavoritoPct,
    bo5Rival: claro.rivalFavorito.ganaFavoritoPct,
    bo5Juntos: claro.ambos.ganaFavoritoPct,
    mentalidadMediana: lote.economia.mentalidad.p50,
    mentalidadSaturada: lote.economia.mentalidad.pctMayorIgual90,
    hypeSaturado: lote.economia.hype.pctMayorIgual90,
    retencion: lote.metasK3.retencion4Splits.valor,
    batacazo: lote.metasK3.desvioMapaMentalidad20vs80.valor
  };
}

// El juez: null si la meta se cumple, el motivo si no. Un valor que no existe (muestra chica) no cumple.
function juezDeLasMetasA(v) {
  const hay = (x) => typeof x === 'number' && Number.isFinite(x);
  const [medMin, medMax] = META_K3_MENTALIDAD_MEDIANA;
  const [bo5Min, bo5Max] = META_K2_BO5_FAVORITO_CLARO_PCT;
  // K5c (paso 3b-3): el lado del jugador se juzga contra el techo re-basado (ver `BO5_JUGADOR_TECHO_K5C`); el conjunto, contra la meta.
  const bo5MaxJugador = Math.max(bo5Max, BO5_JUGADOR_TECHO_K5C);
  const bo5MaxJuntos = Math.max(bo5Max, BO5_CONJUNTO_TECHO_K6B);
  const juzgar = (ok, motivo) => (ok ? null : motivo);
  return {
    rMismaLiga: juzgar(hay(v.rMismaLiga) && v.rMismaLiga >= META_K2_R_MISMA_LIGA,
      `la r nivel–posición en la misma liga (corregida) es ${v.rMismaLiga}, la meta pide >= ${META_K2_R_MISMA_LIGA}`),
    r2SinRuido: juzgar(hay(v.r2SinRuido) && v.r2SinRuido >= META_K2_R2_SIN_RUIDO,
      `el R² sin ruido (corregido) es ${v.r2SinRuido}, la meta pide >= ${META_K2_R2_SIN_RUIDO}`),
    bo5Jugador: juzgar(hay(v.bo5Jugador) && v.bo5Jugador >= bo5Min && v.bo5Jugador <= bo5MaxJugador,
      `el favorito claro (Δ0 ≈ 10, el jugador favorito) gana el Bo5 el ${v.bo5Jugador}%, la banda es ${bo5Min}-${bo5MaxJugador}% (meta ${bo5Min}-${bo5Max}%, re-basada en K5c; del lado del rival ${v.bo5Rival}%, juntos ${v.bo5Juntos}%: el conjunto lo juzga su propio check)`),
    bo5Juntos: juzgar(hay(v.bo5Juntos) && v.bo5Juntos >= bo5Min && v.bo5Juntos <= bo5MaxJuntos,
      `el favorito claro (Δ0 ≈ 10, conjunto: los dos lados) gana el Bo5 el ${v.bo5Juntos}%, la banda es ${bo5Min}-${bo5MaxJuntos}% (meta ${bo5Min}-${bo5Max}%, re-basada en K6b; jugador ${v.bo5Jugador}%, rival ${v.bo5Rival}%)`),
    mentalidadMediana: juzgar(hay(v.mentalidadMediana) && v.mentalidadMediana >= medMin && v.mentalidadMediana <= medMax,
      `la mentalidad mediana de los splits pro es ${v.mentalidadMediana}, la meta es ${medMin}-${medMax}`),
    mentalidadSaturada: juzgar(hay(v.mentalidadSaturada) && v.mentalidadSaturada < META_K3_MENTALIDAD_SATURADA_PCT,
      `el ${v.mentalidadSaturada}% de los splits pro tiene mentalidad >= 90, la meta es < ${META_K3_MENTALIDAD_SATURADA_PCT}%`),
    hypeSaturado: juzgar(hay(v.hypeSaturado) && v.hypeSaturado < META_K3_HYPE_SATURADO_PCT,
      `el ${v.hypeSaturado}% de los splits pro tiene hype >= 90, la meta es < ${META_K3_HYPE_SATURADO_PCT}%`),
    retencion: juzgar(hay(v.retencion) && v.retencion >= META_K3_RETENCION_4_SPLITS,
      `un efecto conserva ${v.retencion} a 4 splits, la meta pide >= ${META_K3_RETENCION_4_SPLITS}`),
    batacazo: juzgar(hay(v.batacazo) && v.batacazo >= META_K3_DIFERENCIA_BATACAZO_PP,
      `el batacazo con mentalidad 20 sube ${v.batacazo} pp contra mentalidad 80, la meta pide >= ${META_K3_DIFERENCIA_BATACAZO_PP} pp`)
  };
}

// K5c (paso 3b-3) — regla 17: el techo del Bo5 del favorito claro, lado del jugador (criterio con plan neutro, 800 × 60). Meta 75-85;
// medido 86,3 ± 1,6 (el error estándar que imprime el check); re-basado por decisión del usuario 2026-10-05, K6 juzga: el techo pasa a
// lo medido más 2 σ (86,3 + 3,2 = 89,5). Lo sacó de banda el bloque C (Final2: planteles más parejos dentro de cada liga y la
// jerarquía del Mundial). El conjunto (84,4) sigue con la meta.
const BO5_JUGADOR_TECHO_K5C = 89.5;
// Arreglos de K6b (la validación completa de `58db231`), regla 17, corrimiento declarado de K6b: el conjunto, meta 75-85; medido
// 84,4 en K5c y 86,0 ± 1,4 (n = 620, la misma muestra: criterio con plan neutro, 800 × 60) sobre `58db231`, una suba de 1,1 σ
// (jugador 87,8, rival 82,6). Re-basado como el lado del jugador: el techo pasa a lo medido más 2 σ (86,0 + 2,8 = 88,8). Ojo: el
// rojo de antes (la asimetría del Fearless de K4, ≈ 87%) queda adentro de esta banda.
const BO5_CONJUNTO_TECHO_K6B = 88.8;
// `bo5Juntos` va dentro de banda (84): son valores que CUMPLEN. El Bo5 conjunto real da ≈ 87% y por eso está pendiente.
const VALORES_DE_LAS_METAS_A_OK = {
  rMismaLiga: 0.6, r2SinRuido: 0.52, bo5Jugador: 83, bo5Rival: 93, bo5Juntos: 84, mentalidadMediana: 72, mentalidadSaturada: 2.7,
  hypeSaturado: 20, retencion: 0.49, batacazo: 4.3
};

function problemasDeLasMetasA(claves) {
  const juicio = juezDeLasMetasA(valoresDeLasMetasA(loteDeLasMetasA()));
  return claves.map((clave) => juicio[clave]).filter((motivo) => motivo !== null);
}

check('K3c metas del bloque A: el juez acepta los valores del bloque A y rechaza, uno por uno, cada valor fuera de meta o inexistente (regla 7)', () => {
  const sano = Object.values(juezDeLasMetasA(VALORES_DE_LAS_METAS_A_OK)).filter((motivo) => motivo !== null);
  if (sano.length > 0) throw new Error(`el juez rechaza valores que cumplen: ${sano.join('; ')}`);
  const malos = {
    rMismaLiga: [0.3, null], r2SinRuido: [0.3, null], bo5Jugador: [90, 70, null], bo5Juntos: [BO5_CONJUNTO_TECHO_K6B + 0.1, 70, null], mentalidadMediana: [97.8, 30, null],
    mentalidadSaturada: [77.7, 20, null], hypeSaturado: [40, 25, null], retencion: [0.28, null], batacazo: [0, 1.9, null]
  };
  for (const [clave, valores] of Object.entries(malos)) {
    for (const valor of valores) {
      const juicio = juezDeLasMetasA({ ...VALORES_DE_LAS_METAS_A_OK, [clave]: valor });
      const rechazados = Object.entries(juicio).filter(([, motivo]) => motivo !== null).map(([k]) => k);
      if (rechazados.length !== 1 || rechazados[0] !== clave) {
        throw new Error(`${clave} = ${valor}: el juez rechazó [${rechazados.join(', ')}], tenía que rechazar solo ${clave}`);
      }
    }
  }
});

checkLento(`K3c meta de K2 (criterio, ${SEEDS_METAS_A} × ${SPLITS_LOTE_K0}): r nivel–posición en la misma liga >= 0,5 y R² sin ruido >= 0,5, ambos corregidos`, () => {
  const problemas = problemasDeLasMetasA(['rMismaLiga', 'r2SinRuido']);
  if (problemas.length > 0) throw new Error(problemas.join('; '));
});

// K4c (paso 3a) — regla 17: este check REEMPLAZA a la medición con `criterio` ("el favorito claro gana el Bo5 entre 75% y
// 85%", lado del jugador, con el bot que contesta cada plan de serie con la mejor opción), que sumaba la agencia del plan
// al nivel: con un plan que pesa (el ×3 de K4c) esa medición sale de 75-85 por construcción. El bloque A controla nivel →
// resultado, así que ahora el bot contesta cada plan con la opción de p MEDIANA (`criterioConPlanNeutro`). La banda no
// cambia: cambia lo que se le pide medir. La palanca del plan se mide como palanca (bloque B, Δp del instrumento) y
// `criterio` contra `azar` en series ganadas la muestra. Mismas seeds y splits que el lote de las demás metas de A.
let bo5PlanNeutroA = null;
function bo5ConPlanNeutroDeLasMetasA() {
  if (bo5PlanNeutroA === null) {
    const observaciones = [];
    for (let seed = 1; seed <= SEEDS_METAS_A; seed += 1) {
      observaciones.push(correrCarreraSimulate(seed, SPLITS_LOTE_K0, criterioConPlanNeutro).observacion);
    }
    afirmarRuidoIntactoK0(`después de las ${SEEDS_METAS_A} carreras con el plan neutro`);
    bo5PlanNeutroA = bloqueBo5Motor(observaciones).favoritoClaro;
  }
  return bo5PlanNeutroA;
}

checkLento(`K3c meta de K2 (criterio con plan neutro, ${SEEDS_METAS_A} × ${SPLITS_LOTE_K0}): el favorito claro (Δ0 ≈ 10) gana el Bo5 entre 75% y ${BO5_JUGADOR_TECHO_K5C}% (meta 75-85, re-basada en K5c; lado del jugador; el rival solo se reporta, el conjunto tiene su check)`, () => {
  const claro = bo5ConPlanNeutroDeLasMetasA();
  const v = {
    ...valoresDeLasMetasA(loteDeLasMetasA()),
    bo5Jugador: claro.jugadorFavorito.ganaFavoritoPct, bo5Rival: claro.rivalFavorito.ganaFavoritoPct, bo5Juntos: claro.ambos.ganaFavoritoPct
  };
  console.log(`     (informe, plan neutro) Bo5 con |Δ0| ≈ 10: jugador favorito ${v.bo5Jugador}% ± ${claro.jugadorFavorito.eePct} (se mide), rival favorito ${v.bo5Rival}% (solo se reporta), juntos ${v.bo5Juntos}% (su propio check, sobre esta misma muestra)`);
  const motivo = juezDeLasMetasA(v).bo5Jugador;
  if (motivo !== null) throw new Error(motivo);
});

// K4c (paso 3a): el bot de la vara de medir. Estructural y rápido: en cada parada de plan responde con la opción de p mediana
// y en todo lo demás es `criterio`, sobre carreras enteras (3 seeds, la observación entera tiene que coincidir con la regla
// escrita a mano). Mutante: `criterio` en el plan (la mejor opción) o la mediana mal elegida lo ponen rojo.
check('K4c el plan neutro del bloque A: criterioConPlanNeutro contesta cada plan con la opción de p mediana y todo lo demás como criterio', () => {
  const opciones = (...ps) => ps.map((pSerie, i) => ({ id: `o${i}`, pSerie }));
  const plan = (...ps) => ({ opciones: opciones(...ps), datos: { motivo: 'plan' } });
  const sinSistema = {};
  const respuesta = (decision) => criterioConPlanNeutro(sinSistema, {}, decision, null).opcionId;
  // Tres opciones: la del medio (no la primera ni la última); cuatro: la mediana inferior; dos: la inferior; una sola: esa.
  if (respuesta(plan(0.5, 0.9, 0.6)) !== 'o2' || respuesta(plan(0.9, 0.5, 0.6, 0.7)) !== 'o2' || respuesta(plan(0.8, 0.4)) !== 'o1' || respuesta(plan(0.7)) !== 'o0') {
    throw new Error(`la mediana por pSerie: [0,5 0,9 0,6] → ${respuesta(plan(0.5, 0.9, 0.6))} (o2), [0,9 0,5 0,6 0,7] → ${respuesta(plan(0.9, 0.5, 0.6, 0.7))} (o2), [0,8 0,4] → ${respuesta(plan(0.8, 0.4))} (o1)`);
  }
  let planes = 0;
  let planesDondeDifiere = 0;
  // Las 3 primeras seeds siempre; si con ellas no alcanzan las paradas (el contenido que corre el stream de rng las mueve), se
  // suman seeds, con tope, hasta tener las 10 paradas de plan y las 3 donde la mediana difiere. El tope no relaja la regla: si con
  // `TOPE_DE_SEEDS` sigue vacío, falla igual.
  const SEEDS_MINIMAS = 3;
  const TOPE_DE_SEEDS = 12;
  for (let seed = 1; seed <= TOPE_DE_SEEDS && (seed <= SEEDS_MINIMAS || planes < 10 || planesDondeDifiere < 3); seed += 1) {
    // La misma regla escrita a mano: en el plan, la opción cuya pSerie es la mediana inferior; todo lo demás, criterio.
    const aMano = (sistema, estado, decision, rngLocal) => {
      if (decision.datos?.motivo === 'plan') {
        const ps = decision.opciones.map((o) => o.pSerie).sort((x, y) => x - y);
        const mediana = ps[Math.floor((ps.length - 1) / 2)];
        planes += 1;
        if (decision.opciones.find((o) => o.pSerie === mediana).id !== ESTRATEGIAS_K0.criterio(sistema, estado, decision, rngLocal).opcionId) {
          planesDondeDifiere += 1;
        }
        return { opcionId: decision.opciones.find((o) => o.pSerie === mediana).id };
      }
      return ESTRATEGIAS_K0.criterio(sistema, estado, decision, rngLocal);
    };
    const neutro = JSON.stringify(correrCarreraSimulate(seed, 60, criterioConPlanNeutro).observacion);
    const manual = JSON.stringify(correrCarreraSimulate(seed, 60, aMano).observacion);
    if (neutro !== manual) {
      throw new Error(`seed ${seed}: la carrera con criterioConPlanNeutro no es la de "mediana en el plan, criterio en lo demás" escrita a mano`);
    }
  }
  if (planes < 10 || planesDondeDifiere < 3) {
    throw new Error(`check vacío: ${planes} paradas de plan y ${planesDondeDifiere} donde la mediana difiere de la mejor opción (hacen falta 10 y 3)`);
  }
});

// El conjunto (los dos lados) es un check de BANDA. La asimetría del Fearless (solo te degradaba a vos) lo llevaba a ≈ 87%
// y la resolvió el plan de Fearless de K4: volvió a su banda y su entrada de `bandasPendientes.js` se borró.
// K4c (paso 3a) — regla 17, la misma línea que el del lado del jugador (af79e04): este check REEMPLAZA a la medición con
// `criterio` (el bot que contesta cada plan de serie con la mejor opción), que sumaba la agencia del plan al nivel. Ahora
// mide con el plan neutro (`criterioConPlanNeutro`, la opción de p mediana), sobre la misma muestra que el del lado del
// jugador (`bo5ConPlanNeutroDeLasMetasA`, 800 × 60, se corre una vez para los dos). La banda no cambia.
checkLento('K3c meta Bo5 favorito claro (conjunto) ∈ [75, 85]', () => {
  const claro = bo5ConPlanNeutroDeLasMetasA();
  const v = { bo5Jugador: claro.jugadorFavorito.ganaFavoritoPct, bo5Rival: claro.rivalFavorito.ganaFavoritoPct, bo5Juntos: claro.ambos.ganaFavoritoPct };
  console.log(`     (muestra: criterio con plan neutro, ${SEEDS_METAS_A} × ${SPLITS_LOTE_K0}) Bo5 conjunto ${v.bo5Juntos}% ± ${claro.ambos.eePct} (n = ${claro.ambos.n}; jugador ${v.bo5Jugador}%, rival ${v.bo5Rival}%)`);
  const motivo = juezDeLasMetasA(v).bo5Juntos;
  if (motivo !== null) throw new Error(motivo);
});

checkLento(`K3c meta de K3 (criterio, ${SEEDS_METAS_A} × ${SPLITS_LOTE_K0}): mentalidad pro con mediana en [45, 75] y < 20% de los splits pro con mentalidad >= 90`, () => {
  const problemas = problemasDeLasMetasA(['mentalidadMediana', 'mentalidadSaturada']);
  if (problemas.length > 0) throw new Error(problemas.join('; '));
});

checkLento(`K3c meta de K3 (criterio, ${SEEDS_METAS_A} × ${SPLITS_LOTE_K0}): < 25% de los splits pro con hype >= 90`, () => {
  const problemas = problemasDeLasMetasA(['hypeSaturado']);
  if (problemas.length > 0) throw new Error(problemas.join('; '));
});

checkLento(`K3c meta de K3 (sonda de retención, ${SONDA_RETENCION.seeds} seeds sin los casos que tocan el clamp): un efecto sobre un stat de curva conserva >= 40% a ${SONDA_RETENCION.splitsDespues} splits`, () => {
  const problemas = problemasDeLasMetasA(['retencion']);
  if (problemas.length > 0) throw new Error(problemas.join('; '));
});

checkLento('K3c meta de K3 (analítico, sin muestra: p de mapa del motor): la brecha de sorpresas entre mentalidad 20 y 80 es >= 2 pp', () => {
  const problemas = problemasDeLasMetasA(['batacazo']);
  if (problemas.length > 0) throw new Error(problemas.join('; '));
});

// ============================================================================
// PLAN.md §K.4 — los tres custodios del registro de bandas pendientes (`src/dev/bandasPendientes.js`). Van al FINAL:
// el primero mira cómo terminó cada check de esta corrida. Cada uno se prueba primero contra un registro sintético
// que tiene que rechazar (trampa T5: un custodio que no ve nada pasa siempre).
// ============================================================================

const ENTRADA_SINTETICA_K2B = {
  check: 'Sin aleatoriedad nativa fuera del RNG inyectado (src/ + index.html)', bloque: 'A',
  medido: '0 usos', banda: '0 usos', commit: 'K2b', rebasea: 'K3c'
};

// --- K4 (revisión): el guardado en CADA tipo de pausa ---
// La pausa vive en `state.pendiente` y la página la guarda con JSON (`core/guardado.js`): todo lo que una pausa deja
// en el estado tiene que sobrevivir `JSON.stringify`/`JSON.parse`. La prueba del salto (K4-C) guardaba un `Set` en
// `decision.datos.ofrecidas`; JSON lo vuelve `{}` y al recargar `cerrarAsientosCongelados` tiraba "has is not a
// function" — ningún check lo veía porque todos resuelven la pausa en memoria. Este la resuelve dos veces desde el
// mismo punto: de corrido y tras serializar/deserializar (estado + RNG), y exige el mismo próximo estado, los mismos
// logs y el mismo RNG. Además barre el estado en cada pausa buscando valores que JSON no conserva (`Set`, `Map`,
// funciones, instancias de clase, `undefined` en arrays, números no finitos), aunque esa pausa no los lea al volver.
// Los tipos de pausa que el lote TIENE que cubrir (sistema:motivo[:momento][:replan]); si un cambio de balance deja
// alguno sin aparecer en estas seeds, el check lo dice en vez de pasar con la cobertura achicada. Un tipo nuevo que
// aparece queda cubierto igual (se lo nombra en el mensaje de cobertura si falta otro).
const TIPOS_DE_PAUSA_GUARDADO_K4 = [
  'amateur:reparto', 'amateur:negociacion', 'amateur:oferta', 'amateur:minijuego:tryout', 'amateur:salida_amateur',
  // K6c: el plan del año del amateur.
  'amateur:plan_amateur',
  'amateur:nocturno', 'edadCierre:?', 'eventos:?', 'eventos:minijuego:post_escandalo', 'mercado:oferta',
  'mercado:minijuego:tryout', 'mercado:traspaso', 'temporada:momento', 'serie:plan',
  'serie:plan:replan', 'serie:decisivo', 'serie:minijuego:mapa_decisivo',
  // K4c (plan anual), regla 17: se fue `practica:practica` (reemplaza a la pausa de la práctica, que este lote exigía
  // cubrir): la práctica ya no frena.
  // K4c (paso 3a), regla 17: se fue `serie:minijuego:post_serie` (la prensa tras una serie): con `BALANCE.serie.rondasConPrensa: []` la
  // serie ya no la pide nunca; la prensa tras un escándalo (`eventos:minijuego:post_escandalo`, arriba) sigue cubierta.
  'retiro:retiro_declive', 'retiro:retiro_vuelta', 'servicioMilitar:servicio_te_vas',
  'servicioMilitar:servicio_adentro', 'servicioMilitar:servicio_volver',
  // K5: el 2-2 del Swiss del Mundial, el plan de una serie del bracket y la bifurcación del final por mercado.
  'internacional:swiss', 'internacional:plan', 'mercado:fin_mercado'
];
const SEEDS_GUARDADO_K4 = Array.from({ length: 30 }, (_, i) => 1 + i);
const SPLITS_GUARDADO_K4 = 60;
const SEEDS_GUARDADO_TOPE_K4 = 200;
// Revisión de K5: las seeds fijas [10, 14] dejaron de llegar a la bifurcación con el corrimiento de la revisión (el lote
// no cubría `mercado:fin_mercado`). Ahora se buscan, en orden, hasta ver la pausa `FIN_MERCADO_GUARDADO_MINIMO` veces, con
// tope `SEEDS_FIN_MERCADO_TOPE_K5` seeds.
const SEEDS_FIN_MERCADO_TOPE_K5 = 40;
const FIN_MERCADO_GUARDADO_MINIMO = 2;

function tipoDePausaGuardadoK4(pendiente) {
  const datos = pendiente.decision.datos ?? {};
  return `${pendiente.sistemaId}:${datos.motivo ?? pendiente.decision.presentacion ?? '?'}`
    + `${datos.momento ? `:${datos.momento}` : ''}${datos.replan ? ':replan' : ''}`;
}

// Rutas (con los índices colapsados a `[]`) de los valores que JSON no devuelve iguales.
function valoresNoJsonK4(valor, ruta, encontrados) {
  if (valor === undefined) {
    encontrados.add(`${ruta} es undefined dentro de un array`);
    return;
  }
  if (valor === null || typeof valor === 'string' || typeof valor === 'boolean') {
    return;
  }
  if (typeof valor === 'number') {
    if (!Number.isFinite(valor)) {
      encontrados.add(`${ruta} = ${valor}`);
    }
    return;
  }
  if (typeof valor !== 'object') {
    encontrados.add(`${ruta} es ${typeof valor}`);
    return;
  }
  if (Array.isArray(valor)) {
    valor.forEach((elemento) => valoresNoJsonK4(elemento, `${ruta}[]`, encontrados));
    return;
  }
  if (Object.getPrototypeOf(valor) !== Object.prototype) {
    encontrados.add(`${ruta} es un ${valor.constructor?.name ?? 'objeto sin prototipo'}`);
    return;
  }
  for (const [clave, sub] of Object.entries(valor)) {
    if (sub !== undefined) {
      valoresNoJsonK4(sub, `${ruta}.${clave}`, encontrados);
    }
  }
}

checkLento('K4 (revisión) guardado: en cada tipo de pausa, guardar y recargar (JSON) y seguir da el mismo próximo estado, logs y RNG que seguir de corrido (criterio, 30 carreras × 60)', () => {
  const vistos = new Map();
  const problemas = [];
  const noJson = new Set();
  // `degradado`: la carrera de los checks de K5-C (stats topeados al llegar a primera, `carreraDegradadaK5C`), la que
  // se queda sin ofertas en su tier y llega a la bifurcación del final por mercado.
  const recorrer = (seeds, { degradado = false } = {}) => {
    for (const seed of seeds) {
      const rng = mulberry32(seed);
      let state = createInitialState(seed, rng);
      let techo = null;
      for (let i = 0; i < SPLITS_GUARDADO_K4 && !state.terminado; i += 1) {
        if (degradado && !techo && state.phase === 'profesional' && state.career.tier === 1) {
          const factor = FACTORES_DEGRADADO_K5C[seed % FACTORES_DEGRADADO_K5C.length];
          techo = Object.fromEntries(Object.entries(state.player.stats).map(([stat, valor]) => [stat, valor * factor]));
        }
        if (techo && state.phase === 'profesional') {
          state = topearStats(state, techo);
        }
        let paso = avanzarSplit(state, rng);
        let vueltas = 0;
        while (paso.state.pendiente) {
          const tipo = tipoDePausaGuardadoK4(paso.state.pendiente);
          vistos.set(tipo, (vistos.get(tipo) ?? 0) + 1);
          valoresNoJsonK4(paso.state, 'state', noJson);
          const guardado = serializarGuardado(paso.state, rng);
          // De corrido.
          const { sistemaId, decision } = paso.state.pendiente;
          const respuesta = ESTRATEGIAS_K0.criterio(sistemaPorId(sistemaId), paso.state, decision, rng);
          const seguido = resolverDecision(paso.state, respuesta, rng);
          // Recargado: el estado y el RNG salen del JSON, y el bot responde desde lo recargado, como la página.
          let recargado;
          let rngRecargado;
          try {
            const datos = deserializarGuardado(guardado);
            if (!datos) {
              throw new Error('deserializar devolvió null');
            }
            rngRecargado = mulberry32(datos.seed);
            rngRecargado.restaurar(datos.rngEstado);
            const pendiente = datos.state.pendiente;
            const respuestaRecargada = ESTRATEGIAS_K0.criterio(sistemaPorId(pendiente.sistemaId), datos.state,
              pendiente.decision, rngRecargado);
            recargado = resolverDecision(datos.state, respuestaRecargada, rngRecargado);
          } catch (error) {
            problemas.push(`seed ${seed}, pausa ${tipo}: al recargar tira "${error.message}"`);
            recargado = null;
          }
          // `estado()` del RNG vivo no está truncado a 32 bits (`restaurar` sí trunca); la secuencia es la misma.
          if (recargado && (JSON.stringify([seguido.state, seguido.logs]) !== JSON.stringify([recargado.state, recargado.logs])
            || (rng.estado() >>> 0) !== (rngRecargado.estado() >>> 0))) {
            problemas.push(`seed ${seed}, pausa ${tipo}: recargado no da el mismo próximo estado/logs/RNG`);
          }
          paso = seguido;
          vueltas += 1;
          if (vueltas > 200) {
            throw new Error(`seed ${seed}: más de 200 pausas seguidas en un split`);
          }
        }
        state = paso.state;
      }
    }
  };
  recorrer(SEEDS_GUARDADO_K4);
  // K5-C: la bifurcación del final por mercado está apagada (N neutro en balance.js) hasta su calibración; su pausa se
  // cubre con el umbral bajado y las carreras degradadas de los checks de K5-C.
  conUmbralK5C(UMBRAL_K5C, () => {
    for (let seed = 1; seed <= SEEDS_FIN_MERCADO_TOPE_K5 && (vistos.get('mercado:fin_mercado') ?? 0) < FIN_MERCADO_GUARDADO_MINIMO; seed += 1) {
      recorrer([seed], { degradado: true });
    }
  });
  if (noJson.size > 0 || problemas.length > 0) {
    throw new Error(`${problemas.length} pausas rotas al recargar (${problemas.slice(0, 4).join(' | ')}); `
      + `valores que JSON no conserva en el estado al pausar: ${[...noJson].slice(0, 8).join('; ') || 'ninguno'}`);
  }
  // K6c-fix: si a las 30 carreras les falta algún tipo, se siguen corriendo seeds (tope `SEEDS_GUARDADO_TOPE_K4`) hasta verlo. En
  // la validación completa de `6dc0ff8` faltaron `amateur:reparto` (desde K6c la semana frena solo con riesgo nuevo: ~0,1 paradas
  // por carrera de `criterio`) y los tres de `servicioMilitar` (las 30 carreras ya no llevaban a ningún coreano al servicio).
  for (let seed = SEEDS_GUARDADO_K4.length + 1; seed <= SEEDS_GUARDADO_TOPE_K4 && TIPOS_DE_PAUSA_GUARDADO_K4.some((tipo) => !vistos.has(tipo)); seed += 1) {
    recorrer([seed]);
  }
  const faltan = TIPOS_DE_PAUSA_GUARDADO_K4.filter((tipo) => !vistos.has(tipo));
  if (faltan.length > 0) {
    throw new Error(`el lote no cubrió ${faltan.join(', ')} (vistos: ${[...vistos.keys()].join(', ')}): cambiá las seeds, `
      + 'no saques el tipo de la lista');
  }
});

// K4 (revisión, la del navegador): la ficha mostraba `top_mundial` como chip y `LCK_CL` en su línea de contexto. Toda
// marca que `core/contexto.js` puede producir (leída del fuente, para cubrir las raras como `mejor_del_mundo`, y además
// las vistas en carreras reales) tiene etiqueta en `LABEL_MARCA` de la ficha, y la línea de contexto nunca muestra el
// id de una liga cuyo nombre visible es otro.
check('K4 (revisión) ficha sin ids crudos: toda marca de contexto tiene etiqueta y la línea de contexto muestra el nombre visible de la liga', () => {
  const fuente = fs.readFileSync(new URL('../core/contexto.js', import.meta.url), 'utf8');
  const delFuente = [...fuente.matchAll(/marcas\.push\('([a-z0-9_]+)'\)/g)].map((m) => m[1]);
  if (delFuente.length < 10) throw new Error(`solo ${delFuente.length} marcas leídas de core/contexto.js: cambió la forma de armarlas`);
  const sinEtiqueta = new Set(delFuente.filter((id) => !LABEL_MARCA_FICHA[id]));
  const idsCrudos = LIGAS.filter((liga) => liga.nombre !== liga.id).map((liga) => liga.id);
  const problemas = [];
  let lineas = 0;
  for (const seed of [1, 2, 3, 4]) {
    const rng = mulberry32(seed);
    let state = createInitialState(seed, rng);
    for (let i = 0; i < 40 && !state.terminado; i += 1) {
      state = avanzarSplitAuto(state, rng).state;
      for (const id of state.contexto?.marcas ?? []) {
        if (!LABEL_MARCA_FICHA[id]) sinEtiqueta.add(id);
      }
      const linea = lineaDeContextoFicha(state);
      lineas += 1;
      const crudo = idsCrudos.find((id) => new RegExp(`(^|[^A-Za-z0-9_])${id}([^A-Za-z0-9_]|$)`).test(linea));
      if (crudo) problemas.push(`seed ${seed}, split ${i}: "${linea}" muestra el id ${crudo}`);
    }
  }
  // Y en cada liga del mundo cuyo id no es su nombre (las carreras de arriba no pasan por todas): misma línea, puesta ahí.
  const base = correrCarrera(1, 14);
  let sinteticas = 0;
  for (const liga of base.mundo.ligas.filter((l) => idsCrudos.includes(l.id))) {
    const linea = lineaDeContextoFicha({ ...base, career: { ...base.career, liga: liga.id } });
    const nombre = LIGAS.find((l) => l.id === liga.id).nombre;
    if (!linea.includes(nombre) || new RegExp(`(^|[^A-Za-z0-9_])${liga.id}([^A-Za-z0-9_]|$)`).test(linea)) {
      problemas.push(`en ${liga.id} la línea es "${linea}" (tiene que decir "${nombre}")`);
    }
    sinteticas += 1;
  }
  if (sinEtiqueta.size > 0) problemas.push(`marcas sin etiqueta en la ficha: ${[...sinEtiqueta].join(', ')}`);
  if (problemas.length > 0) throw new Error(problemas.slice(0, 5).join(' | '));
  if (lineas < 100 || sinteticas < 3) throw new Error(`check vacío: ${lineas} líneas de contexto, ${sinteticas} ligas con id distinto del nombre`);
});

// --- K4-C: solo frenan las bifurcaciones; lo demás lo resuelve tu perfil (PLAN.md "K4 — decisiones de spec") ---

// Una corrida instrumentada: cada pausa con su sistema, la respuesta del criterio por defecto y el estado al
// pausar. Compartida por los checks de K4-C para no correr las mismas carreras cinco veces.
function correrCarrerasK4c(seeds, splits) {
  const carreras = [];
  for (const seed of seeds) {
    const rng = mulberry32(seed);
    let state = createInitialState(seed, rng);
    const pausas = [];
    const responder = (sistema, st, decision, rngLocal) => {
      const respuesta = sistema.resolverAuto(st, decision, rngLocal);
      pausas.push({ sistema: sistema.id, decision, respuesta, st });
      return respuesta;
    };
    for (let i = 0; i < splits && !state.terminado; i += 1) {
      state = avanzarSplitAuto(state, rng, responder).state;
    }
    carreras.push({ seed, pausas, final: state });
  }
  return carreras;
}
let carrerasK4cCache = null;
function carrerasK4c() {
  carrerasK4cCache ??= correrCarrerasK4c(Array.from({ length: 40 }, (_, i) => 4400 + i), 60);
  return carrerasK4cCache;
}

// El encaje recalculado ACÁ, desde la previa que muestra la tarjeta y la tabla de `data/perfiles.json` — sin
// llamar a `core/perfil.js`, para que un error en el motor no se tape con el mismo error en el check.
function opcionEsperadaK4c(perfil, decision) {
  const tabla = PERFILES_K4C;
  const forzada = decision.opciones.find((opcion) => {
    const original = decision.datos.evento.options.find((o) => o.id === opcion.id);
    return original?.perfil === perfil.actual;
  });
  if (forzada) {
    return forzada.id;
  }
  const mag = BALANCE.perfil.pesoMagnitud;
  let mejor = null;
  let mejorValor = -Infinity;
  for (const opcion of decision.opciones) {
    let valor = 0;
    for (const id of tabla.orden) {
      const p = tabla.perfiles[id];
      let encaje = p.riesgo[opcion.riesgo] ?? 0;
      for (const fila of opcion.previa) {
        const familia = tabla.familiaDeCampo[fila.campo];
        if (!familia) continue;
        encaje += (p.familias[familia] ?? 0) * (fila.signo === '-' ? -1 : 1) * (mag[fila.magnitud] ?? 0);
      }
      valor += (perfil.pesos[id] ?? 0) * encaje;
    }
    if (valor > mejorValor) {
      mejor = opcion.id;
      mejorValor = valor;
    }
  }
  return mejor;
}

check('K4-C solo frenan las bifurcaciones: toda pausa de eventos es un evento con bifurcacion: true (40 carreras × 60)', () => {
  let pausasEvento = 0;
  let cronicas = 0;
  for (const { seed, pausas, final } of carrerasK4c()) {
    for (const { sistema, decision } of pausas) {
      if (sistema !== 'eventos' || decision.datos?.motivo === 'minijuego') continue;
      pausasEvento += 1;
      if (decision.datos?.evento?.bifurcacion !== true) {
        throw new Error(`seed ${seed}: frenó un evento que no es bifurcación (${decision.titulo})`);
      }
    }
    cronicas += final.logs.filter((log) => log.cronica).length;
  }
  if (cronicas === 0) {
    throw new Error('ningún evento se resolvió por perfil: no hay líneas de crónica');
  }
  if (pausasEvento === 0) {
    throw new Error('ninguna bifurcación frenó en 40 carreras: el marcado no llega al motor');
  }
});

check('K4-C el perfil elige la opción de mejor encaje (recalculado desde la previa y la tabla perfil × familia)', () => {
  // Estados reales de mitad de carrera, cada evento no-bifurcación con opciones vivas, y los cuatro perfiles puros
  // más una mezcla (la deriva). La opción esperada sale de la previa que muestra la tarjeta (`decisionDesdeEvento`).
  const estados = carrerasK4c().slice(0, 6).map(({ pausas }) => pausas[Math.floor(pausas.length / 2)]?.st).filter(Boolean);
  const perfiles = [
    ...PERFILES_K4C.orden.map((id) => ({ actual: id, pesos: Object.fromEntries(PERFILES_K4C.orden.map((q) => [q, q === id ? 1 : 0])) })),
    { actual: 'hambriento', pesos: { profesional: 0.3, hambriento: 0.4, showman: 0.2, leal: 0.1 } }
  ];
  let comparadas = 0;
  for (const base of estados) {
    for (const perfil of perfiles) {
      const st = { ...base, player: { ...base.player, perfil } };
      for (const evento of TODOS_LOS_EVENTOS.filter((e) => !e.bifurcacion && !e.cierreDeEdad)) {
        const decision = decisionDesdeEvento(st, evento, { franja: 'normal', slot: 1 });
        if (decision.opciones.length < 2) continue;
        const esperada = opcionEsperadaK4c(perfil, decision);
        const motor = opcionDelPerfilPara(st, evento);
        if (motor !== esperada) {
          throw new Error(`${evento.id} con perfil ${JSON.stringify(perfil.pesos)}: el motor eligió ${motor}, el encaje da ${esperada}`);
        }
        comparadas += 1;
      }
    }
  }
  if (comparadas < 1000) {
    throw new Error(`muy pocas comparaciones (${comparadas})`);
  }
});

check('K4-C los overrides de perfil del dato ganan', () => {
  const rng = mulberry32(17);
  const base = createInitialState(17, rng);
  let probados = 0;
  for (const evento of TODOS_LOS_EVENTOS) {
    for (const opcion of evento.options.filter((o) => o.perfil)) {
      if (!PERFILES_K4C.orden.includes(opcion.perfil)) {
        throw new Error(`${evento.id}/${opcion.id}: perfil desconocido "${opcion.perfil}"`);
      }
      const st = { ...base, player: { ...base.player, perfil: { actual: opcion.perfil, pesos: Object.fromEntries(PERFILES_K4C.orden.map((q) => [q, q === opcion.perfil ? 1 : 0])) } } };
      const elegida = opcionDelPerfilPara(st, evento);
      if (elegida !== opcion.id) {
        throw new Error(`${evento.id}: el override perfil "${opcion.perfil}" pide ${opcion.id} y el motor eligió ${elegida}`);
      }
      probados += 1;
    }
  }
  if (probados === 0) {
    throw new Error('no hay ningún override de perfil en el dato');
  }
});

check('K4-C la opción del perfil resuelve su outcome con la tirada con pesos (regla 8)', () => {
  // Un evento no-bifurcación cuya opción del perfil tenga dos outcomes con textos distintos: 600 tiradas por el camino
  // de crónica tienen que repartir los textos según los pesos efectivos (±0,06), no salir siempre el mismo.
  const rng0 = mulberry32(23);
  const base = createInitialState(23, rng0);
  const evento = TODOS_LOS_EVENTOS.find((e) => !e.bifurcacion && !e.cierreDeEdad && e.options.length >= 2
    && e.options.every((o) => o.outcomes.length >= 2 && !o.outcomes.some((x) => x.modificadores) && new Set(o.outcomes.map((x) => x.texto)).size === o.outcomes.length
      && o.outcomes.every((x) => x.effects.every((ef) => ef.type === 'stat'))));
  const opcionId = opcionDelPerfilPara(base, evento);
  const opcion = evento.options.find((o) => o.id === opcionId);
  const total = opcion.outcomes.reduce((s, x) => s + x.weight, 0);
  const cuenta = new Map();
  const N = 600;
  for (let i = 0; i < N; i += 1) {
    const { logs } = resolverOpcion(base, evento, opcionId, mulberry32(9000 + i), { cronica: base.player.perfil.actual });
    cuenta.set(logs[0].cuerpo, (cuenta.get(logs[0].cuerpo) ?? 0) + 1);
  }
  for (const outcome of opcion.outcomes) {
    const visto = (cuenta.get(resolverTexto(outcome.texto, base)) ?? 0) / N;
    const esperado = outcome.weight / total;
    if (Math.abs(visto - esperado) > 0.06) {
      throw new Error(`${evento.id}/${opcionId}: un outcome de peso ${esperado.toFixed(2)} salió ${visto.toFixed(2)} (¿el rng no decide?)`);
    }
  }
});

check('K4-C el perfil está completo en el estado desde el arranque y se corre con las bifurcaciones', () => {
  for (const seed of [1, 2, 3, 4, 5, 6, 7, 8]) {
    const st = createInitialState(seed, mulberry32(seed));
    const { perfil } = st.player;
    if (!perfil || !PERFILES_K4C.orden.includes(perfil.actual)) {
      throw new Error(`seed ${seed}: perfil inicial inválido ${JSON.stringify(perfil)}`);
    }
    if (PERFILES_K4C.orden.some((id) => typeof perfil.pesos[id] !== 'number') || Math.abs(Object.values(perfil.pesos).reduce((a, b) => a + b, 0) - 1) > 1e-9) {
      throw new Error(`seed ${seed}: pesos incompletos o que no suman 1: ${JSON.stringify(perfil.pesos)}`);
    }
  }
  const elegido = createInitialState(9, mulberry32(9), { perfil: 'leal' });
  if (elegido.player.perfil.actual !== 'leal') {
    throw new Error(`elegir "leal" en el inicio no llega al estado (${elegido.player.perfil.actual})`);
  }
  // Una bifurcación cuya opción tenga afinidad distinta de "leal": decidirla 4 veces corre los pesos hacia ella y
  // cambia la palabra (α = derivaPorBifurcacion: 0,8^4 < 0,5).
  const afinidadesDe = (evento) => decisionDesdeEvento(elegido, evento, { franja: 'normal', slot: 2 }).opciones.map((o) => {
    let mejor = null;
    let mejorValor = -Infinity;
    for (const id of PERFILES_K4C.orden) {
      const t = PERFILES_K4C.perfiles[id];
      let v = t.riesgo[o.riesgo] ?? 0;
      for (const f of o.previa) {
        const fam = PERFILES_K4C.familiaDeCampo[f.campo];
        if (fam) v += (t.familias[fam] ?? 0) * (f.signo === '-' ? -1 : 1) * BALANCE.perfil.pesoMagnitud[f.magnitud];
      }
      if (v > mejorValor) { mejor = id; mejorValor = v; }
    }
    return { id: o.id, afinidad: evento.options.find((x) => x.id === o.id).perfil ?? mejor };
  });
  const fork = TODOS_LOS_EVENTOS.find((e) => e.bifurcacion && !e.escandalo && afinidadesDe(e).some((a) => a.afinidad !== 'leal'));
  if (!fork) {
    throw new Error('ninguna bifurcación con una opción de afinidad distinta de leal para probar la deriva');
  }
  const afinidades = afinidadesDe(fork);
  const otra = afinidades.find((a) => a.afinidad !== 'leal');
  if (!otra) {
    throw new Error(`${fork.id}: ninguna opción con afinidad distinta de leal para probar la deriva`);
  }
  let st = elegido;
  for (let i = 0; i < 4; i += 1) {
    const d = decisionDesdeEvento(st, fork, { franja: 'normal', slot: 2 });
    st = resolverEventos(st, d, { opcionId: otra.id }, mulberry32(70 + i)).state;
  }
  if (!(st.player.perfil.pesos[otra.afinidad] > 0.5) || st.player.perfil.actual !== otra.afinidad) {
    throw new Error(`cuatro bifurcaciones hacia ${otra.afinidad} no corrieron el perfil: ${JSON.stringify(st.player.perfil)}`);
  }
});

check('K4-C cada evento resuelto por perfil deja una línea de crónica, sin ids crudos', () => {
  const ids = new Set(TODOS_LOS_EVENTOS.flatMap((e) => [e.id, ...e.options.map((o) => o.id)]));
  let vistas = 0;
  for (const { seed, final } of carrerasK4c().slice(0, 15)) {
    const cronicas = final.logs.filter((log) => log.cronica);
    for (const log of cronicas) {
      vistas += 1;
      if (!log.titulo || !log.opcion || !log.cuerpo || typeof log.descripcion !== 'string' || !log.perfil) {
        throw new Error(`seed ${seed}: línea de crónica incompleta: ${JSON.stringify(log).slice(0, 200)}`);
      }
      const crudo = log.message.match(/\b[a-z0-9]+(?:_[a-z0-9]+)+\b/g)?.find((t) => ids.has(t) || /_/.test(t));
      if (crudo || /\{[a-zA-Z]+\}/.test(log.message)) {
        throw new Error(`seed ${seed}: id o token crudo en la crónica ("${crudo ?? log.message}")`);
      }
    }
  }
  if (vistas === 0) {
    throw new Error('ninguna línea de crónica en 15 carreras');
  }
});

check('K4-C la rueda de prensa sale solo después de una final o de un escándalo', () => {
  let prensas = 0;
  for (const { seed, pausas } of carrerasK4c()) {
    pausas.forEach(({ sistema, decision }, i) => {
      if (decision.datos?.minijuego !== 'rueda_de_prensa') return;
      prensas += 1;
      const trasFinal = sistema === 'serie' && decision.datos.trasRonda === 'final';
      const anterior = pausas[i - 1];
      const trasEscandalo = sistema === 'eventos' && anterior?.sistema === 'eventos' && anterior.decision.datos?.evento?.escandalo === true;
      if (!trasFinal && !trasEscandalo) {
        throw new Error(`seed ${seed}: rueda de prensa fuera de una final o un escándalo (${sistema}, ${decision.datos.trasRonda ?? decision.datos.momento})`);
      }
    });
  }
  if (prensas === 0) {
    throw new Error('ninguna rueda de prensa en 40 carreras');
  }
});

check('K4-C la prueba en cada salto grande: primer fichaje en tier 2, en tier 1 y como import', () => {
  // Recuento independiente: los tiers en los que ya tuviste club y si ya fuiste import, leídos del estado en cada
  // pausa. Firmar por el mercado en un tier ≤ 2 que nunca tuviste (y que no está por debajo de uno que sí), o como
  // import por primera vez, tiene que frenar con la prueba ANTES de firmar.
  let saltos = 0;
  for (const { seed, pausas } of carrerasK4c()) {
    const tiers = new Set();
    let fuiImport = false;
    pausas.forEach(({ sistema, decision, respuesta, st }, i) => {
      if (st.career.currentOrg) {
        tiers.add(st.career.tier);
        if (st.career.contrato?.tipo === 'import') fuiImport = true;
      }
      if (sistema !== 'mercado' || decision.datos?.motivo === 'minijuego' || decision.datos?.motivo === 'traspaso' || !respuesta.opcionId || respuesta.negociar) return;
      const oferta = decision.opciones.find((o) => o.id === respuesta.opcionId);
      if (!oferta || oferta.tag === 'renovacion') return;
      const nuevoTier = oferta.tier <= 2 && !tiers.has(oferta.tier) && !(oferta.tier === 2 && tiers.has(1));
      const nuevoImport = oferta.datos?.tipo === 'import' && !fuiImport;
      if (!nuevoTier && !nuevoImport) return;
      saltos += 1;
      const siguiente = pausas[i + 1];
      if (siguiente?.sistema !== 'mercado' || siguiente.decision.datos?.momento !== 'tryout') {
        throw new Error(`seed ${seed}: firmó con ${oferta.org} (tier ${oferta.tier}${nuevoImport ? ', import' : ''}) sin la prueba del salto`);
      }
    });
  }
  if (saltos === 0) {
    throw new Error('ningún salto grande por el mercado en 40 carreras');
  }
});

// --- K4c-S: la prueba decide el contrato, el parche como adjunto y el Δp de plan en el instrumento (PLAN.md "K4c-H, hecho",
// "K4c-F, hecho" y "La palanca en su horizonte, medida") ---
const { esDecisionDeMinijuego: esMinijuegoK4cs } = await import('./estrategias.js');
const { hashCadena: hashCadenaK4cs } = await import('../core/numeros.js');
const { aplicar: aplicarMetaK4cs } = await import('../systems/meta.js');
const { deltaPDePlan } = await import('./simulate.js');

// La sonda de la prueba: en cada tryout REAL de carreras reales (el del amateur y el del mercado) se contesta el MISMO tryout con
// el peor resultado (0) y con el mejor (1), con los mismos números aleatorios (mismo rng sembrado por seed y split), y se mira si
// la firma se dio (`career.currentOrg` es la org de la oferta) y qué quedó del estado. La carrera principal sigue con la
// respuesta automática. Solo guarda lo que los checks necesitan (no el estado entero de antes).
// K4c (revisión): el respaldo de la prueba del mercado, recalculado a mano con la regla de PLAN.md (paso 3a): tu renovación si la
// hay; si no, la oferta mejor pagada que no pide prueba (`saltosDeFichaje` vacío); si no, ninguna. La org, o `null`.
const { saltosDeFichaje: saltosDeFichajeK4cR } = await import('../core/minijuegos.js');
function respaldoALaManoK4cR(state, otras) {
  const renovacion = otras.find((opcion) => opcion.tag === 'renovacion');
  if (renovacion) return renovacion.org;
  const sinPrueba = otras.filter((opcion) => saltosDeFichajeK4cR(state, opcion).length === 0);
  if (sinPrueba.length === 0) return null;
  return sinPrueba.reduce((mejor, opcion) => (opcion.salarioAnualUSD > mejor.salarioAnualUSD ? opcion : mejor)).org;
}

let sondaDeLaPruebaK4cs = null;
const SEEDS_SONDA_K4CS = 80;
const SEEDS_TOPE_SONDA_K4CS = 240;
const PRUEBAS_AMATEUR_FALLIDAS_SONDA_K4CS = 12;
function sondaDeLaPrueba() {
  if (sondaDeLaPruebaK4cs !== null) {
    return sondaDeLaPruebaK4cs;
  }
  const nombreDe = (org) => (typeof org === 'string' ? org : org?.nombre ?? null);
  const filas = [];
  // K6c-fix: las 80 seeds de siempre y, si no juntaron `PRUEBAS_AMATEUR_FALLIDAS_SONDA_K4CS` pruebas amateur fallidas (con la vara
  // en 0 para los que superan al club, y la propuesta del perfil que no te quema, quedaron 7), más seeds hasta el tope.
  const fallidasAmateur = () => filas.filter((f) => f.sistemaId === 'amateur' && !f.bajo.ficho).length;
  for (let seed = 1; seed <= SEEDS_TOPE_SONDA_K4CS && (seed <= SEEDS_SONDA_K4CS || fallidasAmateur() < PRUEBAS_AMATEUR_FALLIDAS_SONDA_K4CS); seed += 1) {
    const rng = mulberry32(seed);
    let st = createInitialState(seed, rng);
    for (let i = 0; i < 45 && !st.terminado; i += 1) {
      st = avanzarSplit(st, rng).state;
      while (st.pendiente) {
        const { sistemaId, decision } = st.pendiente;
        if (esMinijuegoK4cs(decision) && decision.datos.momento === 'tryout') {
          const oferta = nombreDe(decision.datos.oferta?.org);
          const contestar = (resultado) => {
            const rr = mulberry32(hashCadenaK4cs(`${seed}|${i}|prueba`));
            const despues = resolverDecision(structuredClone(st), { resultado }, rr);
            return { despues: despues.state, rr };
          };
          const bajo = contestar(0);
          const alto = contestar(1);
          // K4c (integración): la misma pausa del mercado con club, como si la oferta de la prueba fuera la única de la
          // mano (`datos.otras` vacío), con el mismo resultado y el mismo rng: el lado "sin nada" del check del tryout
          // fallido del mercado (ver ese check).
          let bajoSinOtras = null;
          if (sistemaId === 'mercado' && st.career.currentOrg !== null) {
            const sinOtras = structuredClone(st);
            sinOtras.pendiente.decision.datos.otras = [];
            sinOtras.pendiente.decision.datos.respaldo = null;
            const despues = resolverDecision(sinOtras, { resultado: 0 }, mulberry32(hashCadenaK4cs(`${seed}|${i}|prueba`))).state;
            bajoSinOtras = { ficho: despues.career.currentOrg === oferta, estado: despues };
          }
          // K4c (paso 3a): el respaldo que anuncia la prueba del mercado (la org, no el id) y la apuesta que lo muestra.
          const respaldo = sistemaId === 'mercado' && decision.datos.respaldo
            ? nombreDe(decision.datos.otras.find((opcion) => opcion.id === decision.datos.respaldo)?.org)
            : null;
          filas.push({
            seed, sistemaId, oferta, respaldo, apuesta: decision.datos.apuesta ?? '', vara: decision.datos.vara ?? null,
            respaldoALaMano: sistemaId === 'mercado' ? respaldoALaManoK4cR(st, decision.datos.otras ?? []) : null,
            hayOtras: (decision.datos.otras ?? []).length > 0,
            antes: { currentOrg: st.career.currentOrg, contrato: structuredClone(st.career.contrato), bonus: st.flags.bonusJerarquiaTryout ?? 0, racha: st.flags.splitsSinOfertaConsecutivos, nLogs: st.logs.length },
            bajo: { ficho: bajo.despues.career.currentOrg === oferta, estado: bajo.despues, rr: bajo.rr },
            alto: { ficho: alto.despues.career.currentOrg === oferta },
            bajoSinOtras
          });
        }
        st = resolverDecision(st, sistemaPorId(sistemaId).resolverAuto(st, decision, rng), rng).state;
      }
    }
  }
  sondaDeLaPruebaK4cs = filas;
  return filas;
}

check('K4c-S la prueba decide el contrato: P(firmar | resultado 1) > P(firmar | resultado 0) en el tryout del mercado y en el del amateur (mismo rng, tryouts reales)', () => {
  const filas = sondaDeLaPrueba();
  for (const sistemaId of ['mercado', 'amateur']) {
    const fs = filas.filter((f) => f.sistemaId === sistemaId);
    if (fs.length < 20) {
      throw new Error(`check vacío: ${fs.length} tryouts de ${sistemaId} en 60 carreras (hacen falta 20)`);
    }
    const p = (clave) => fs.filter((f) => f[clave].ficho).length / fs.length;
    const [pBajo, pAlto] = [p('bajo'), p('alto')];
    // K4c (paso 3a), regla 17: la brecha pedida era 0,3 fija, de cuando la prueba iba de 0,15 a 0,95 (0,8 declarada). Con
    // 0,65 / 0,95 la declarada ES 0,3, y la medida (mismo rng: la fracción de sorteos que cae entre las dos p, sobre ~70
    // tryouts) queda debajo la mitad de las veces (mercado: 0,681 contra 0,942). Se pide la mitad de la declarada: un motor
    // que no lee el resultado da 0.
    // K6c-fix: la del amateur ya no tira `probFirmaTryout` (K6c, "pasaste = firmás"): con la vara de tu nivel contra el club,
    // con 0 firma exactamente quien tenía la vara en 0 ("el club firma tu nivel, no tu día") y con 1 firma siempre. Se pide
    // eso, y que la prueba decida algún contrato (P(firmar | 0) < 1); la brecha de la mitad de la declarada sigue para el mercado.
    if (sistemaId === 'amateur') {
      const conVaraCero = fs.filter((f) => f.vara === 0).length / fs.length;
      if (pAlto !== 1 || Math.abs(pBajo - conVaraCero) > 1e-9 || !(pBajo < 1)) {
        throw new Error(`amateur: P(firmar | 0) = ${pBajo.toFixed(3)} (vara en 0: ${conVaraCero.toFixed(3)}) y P(firmar | 1) = ${pAlto.toFixed(3)} en ${fs.length} tryouts: con 0 tiene que firmar solo quien tenía la vara en 0, con 1 siempre, y la prueba tiene que decidir algún contrato`);
      }
      console.log(`     (informe) amateur: P(firmar | 0) = ${pBajo.toFixed(3)} (= las de vara 0), P(firmar | 1) = ${pAlto.toFixed(3)} en ${fs.length} tryouts`);
      continue;
    }
    const brechaMinima = (BALANCE.serie.probFirmaTryout.bueno - BALANCE.serie.probFirmaTryout.malo) / 2;
    if (!(pAlto >= pBajo + brechaMinima)) {
      throw new Error(`${sistemaId}: P(firmar | 0) = ${pBajo.toFixed(3)} y P(firmar | 1) = ${pAlto.toFixed(3)} en ${fs.length} tryouts: la prueba no decide el contrato (hace falta una brecha de ${brechaMinima.toFixed(3)}, la mitad de la declarada en BALANCE.serie.probFirmaTryout)`);
    }
    console.log(`     (informe) ${sistemaId}: P(firmar | 0) = ${pBajo.toFixed(3)}, P(firmar | 1) = ${pAlto.toFixed(3)} en ${fs.length} tryouts`);
  }
});

// K4c (paso 3a), regla 17: este check decía "la parada sigue con las demás" (re-presentaba mercado:oferta tras la prueba
// fallida). Eso era una segunda parada de mercado en la misma pretemporada, contra K4-D (seed 5, split 18 de "K4-D la
// pretemporada frena una sola vez"). Ahora la parada cierra en la misma pantalla con el respaldo que anunció la prueba.
// K6b-F: la prueba del mercado fallida sin respaldo no firma nada. Este mercado solo se abre con el contrato vencido (o sin club), así
// que terminás sin club (antes seguías en él con el contrato vencido: el limbo de K6). El contrato no cambia, salvo el aviso de no
// renovación, que se apaga al irte.
function sinFirmarNadaK6bf(antes, estado) {
  const sinAviso = (contrato) => JSON.stringify({ ...contrato, avisoNoRenovacion: false });
  return estado.career.currentOrg === null && sinAviso(estado.career.contrato) === sinAviso(antes.contrato);
}

check('K4c-S un tryout fallido del mercado se cae solo esa oferta: sin crédito, y la parada cierra ahí mismo con el respaldo que anunció la prueba (o por el camino de "sin ofertas"), sin re-abrir el mercado', () => {
  // K4c (revisión): con y sin club (antes solo con club; con el plan del amateur arreglado quedaban 3 en la muestra): lo que se
  // mira vale igual para un free agent, y el lado "sin otras ofertas" armado sigue siendo solo con club.
  const fallidos = sondaDeLaPrueba().filter((f) => f.sistemaId === 'mercado' && !f.bajo.ficho);
  if (fallidos.length < 5) {
    throw new Error(`check vacío: ${fallidos.length} tryouts fallidos del mercado (hacen falta 5)`);
  }
  let conRespaldo = 0;
  let sinNada = 0;
  const esRepresentada = (estado) => estado.pendiente?.sistemaId === 'mercado' && estado.pendiente.decision.datos?.motivo === 'oferta';
  const sinCredito = (f, estado, donde) => {
    if ((estado.flags.bonusJerarquiaTryout ?? 0) !== f.antes.bonus) {
      throw new Error(`${donde}: el tryout fallido dejó crédito de jerarquía (${estado.flags.bonusJerarquiaTryout})`);
    }
  };
  // Sin respaldo no se firma nada (K4c, revisión: tampoco por la racha sin ofertas, que la prueba fallida ya no mueve). K6b-F: con
  // el contrato vencido te vas del club (`sinFirmarNadaK6bf`).
  const sinRomperNada = (f, estado, donde) => {
    if (!sinFirmarNadaK6bf(f.antes, estado)) {
      throw new Error(`${donde}: el tryout fallido sin respaldo dejó el club o el contrato distinto (${f.antes.currentOrg} → ${estado.career.currentOrg})`);
    }
  };
  // El lado "sin nada" con club casi no sale solo (los tryouts fallidos con club traen siempre otra oferta: la renovación
  // u otras de afuera), así que también se prueba con la pausa real de cada tryout fallido con club sin las otras ofertas
  // (`bajoSinOtras` de la sonda: `datos.otras` vacío y sin respaldo, mismo resultado, mismo rng).
  let sinNadaArmadas = 0;
  for (const f of fallidos) {
    const { estado } = f.bajo;
    const donde = `seed ${f.seed} (${f.oferta})`;
    if (esRepresentada(estado)) {
      throw new Error(`${donde}: la prueba fallida re-abrió el mercado (una segunda parada en la misma pretemporada, contra K4-D)`);
    }
    sinCredito(f, estado, donde);
    if (f.bajoSinOtras && !f.bajoSinOtras.ficho) {
      if (esRepresentada(f.bajoSinOtras.estado)) {
        throw new Error(`${donde}, sin otras ofertas: la parada se re-presentó sin nada que ofrecer`);
      }
      sinCredito(f, f.bajoSinOtras.estado, `${donde}, sin otras ofertas`);
      sinRomperNada(f, f.bajoSinOtras.estado, `${donde}, sin otras ofertas`);
      sinNadaArmadas += 1;
    }
    if (f.respaldo) {
      conRespaldo += 1;
      // Regla 15: lo que anuncia la apuesta es lo que aplica el motor.
      if (!f.apuesta.includes(`Si no alcanza`) || !f.apuesta.includes(f.respaldo)) {
        throw new Error(`${donde}: la apuesta no anuncia el respaldo (${f.respaldo}): "${f.apuesta}"`);
      }
      if (estado.career.currentOrg !== f.respaldo) {
        throw new Error(`${donde}: la prueba anunció el respaldo ${f.respaldo} y el motor dejó ${estado.career.currentOrg}`);
      }
    } else {
      if (!f.apuesta.includes('Si no alcanza, esta ventana no firmás con nadie.')) {
        throw new Error(`${donde}: sin respaldo, la apuesta no dice que no firmás con nadie: "${f.apuesta}"`);
      }
      sinRomperNada(f, estado, donde);
      sinNada += 1;
    }
  }
  if (conRespaldo === 0 || sinNada + sinNadaArmadas === 0) {
    throw new Error(`check vacío: ${conRespaldo} pruebas fallidas que siguieron con el respaldo y ${sinNada} que se quedaron sin nada `
      + `(más ${sinNadaArmadas} armadas sin las otras ofertas; hacen falta de las dos)`);
  }
});

// K4c (revisión): el check de arriba tomaba el respaldo de `decision.datos.respaldo`, el mismo número que escribe el motor: con el
// mutante "cualquier oferta sirve de respaldo" (`const sinPrueba = otras;` en `respaldoDePrueba`) seguía verde. Este recalcula la regla.
check('K4c (revisión) el respaldo de la prueba del mercado es el de la regla, recalculado a mano: lo anuncia la apuesta y, si la prueba no alcanza, es con quien seguís', () => {
  let conRespaldo = 0;
  let sinRespaldo = 0;
  let distintoDeLaMejorPagada = 0;
  for (const f of sondaDeLaPrueba().filter((fila) => fila.sistemaId === 'mercado')) {
    const donde = `seed ${f.seed} (${f.oferta})`;
    if (f.respaldo !== f.respaldoALaMano) {
      throw new Error(`${donde}: la prueba anuncia el respaldo ${f.respaldo}; con la regla (renovación, si no la mejor pagada sin prueba) es ${f.respaldoALaMano}`);
    }
    if (f.respaldoALaMano === null ? !f.apuesta.includes('Si no alcanza, esta ventana no firmás con nadie.') : !f.apuesta.includes(f.respaldoALaMano)) {
      throw new Error(`${donde}: la apuesta no dice el respaldo de la regla (${f.respaldoALaMano}): "${f.apuesta}"`);
    }
    if (!f.bajo.ficho && f.respaldoALaMano !== null && f.bajo.estado.career.currentOrg !== f.respaldoALaMano) {
      throw new Error(`${donde}: la prueba no alcanzó y seguís en ${f.bajo.estado.career.currentOrg}, no en el respaldo de la regla (${f.respaldoALaMano})`);
    }
    if (f.respaldoALaMano === null) sinRespaldo += 1; else conRespaldo += 1;
    if (f.respaldoALaMano === null && f.hayOtras) distintoDeLaMejorPagada += 1;
  }
  if (conRespaldo === 0 || sinRespaldo === 0 || distintoDeLaMejorPagada === 0) {
    throw new Error(`check vacío: ${conRespaldo} pruebas con respaldo, ${sinRespaldo} sin, ${distintoDeLaMejorPagada} sin respaldo aunque había otras ofertas (las que pedían prueba)`);
  }
});

// K4c (revisión): "probaste y no alcanzó" es un caso propio. Antes la prueba fallida sin respaldo iba por `resolverEspera`: sumaba a
// `splitsSinOfertaConsecutivos` (azar seed 11: con seis ofertas en la mesa, "Nadie te ofrece nada hace 3 pretemporadas seguidas. Te
// quedás sin equipo.") y el declive la contaba como silencio (azar seed 16: "A los 18 el mercado te está diciendo que no", y el motivo
// "El mercado te venía diciendo que no").
const PRUEBA_FALLIDA_K4cR = 'Probaste y no alcanzó: esta ventana no firmás con nadie.';
const SILENCIO_K4cR = /Nadie te ofrece nada|El teléfono no suena|No queda nada que firmar/;
const DECLIVES_K4cR = 2;
const TOPE_SEEDS_DECLIVE_K4cR = 120;
check('K4c (revisión) probaste y no alcanzó: la prueba del mercado fallida sin respaldo no suma a la racha sin ofertas, no te deja libre por silencio y lo dice', () => {
  let reales = 0;
  let armadas = 0;
  for (const f of sondaDeLaPrueba().filter((fila) => fila.sistemaId === 'mercado')) {
    const casos = [];
    if (!f.bajo.ficho && !f.respaldo) casos.push(['real', f.bajo.estado]);
    if (f.bajoSinOtras && !f.bajoSinOtras.ficho) casos.push(['sin otras ofertas', f.bajoSinOtras.estado]);
    for (const [cual, estado] of casos) {
      const donde = `seed ${f.seed} (${f.oferta}, ${cual})`;
      const nuevos = estado.logs.slice(f.antes.nLogs).map((log) => log.message);
      if (estado.flags.splitsSinOfertaConsecutivos !== f.antes.racha) {
        throw new Error(`${donde}: la prueba fallida movió la racha sin ofertas (${f.antes.racha} → ${estado.flags.splitsSinOfertaConsecutivos})`);
      }
      if (!sinFirmarNadaK6bf(f.antes, estado)) {
        throw new Error(`${donde}: la prueba fallida sin respaldo tocó el club o el contrato (${f.antes.currentOrg} → ${estado.career.currentOrg})`);
      }
      if (!nuevos.some((m) => m.includes(`La prueba en ${f.oferta} no alcanza`) && m.includes(PRUEBA_FALLIDA_K4cR)) || nuevos.some((m) => SILENCIO_K4cR.test(m))) {
        throw new Error(`${donde}: el log no dice que probaste y no alcanzó, o lo cuenta como silencio: ${JSON.stringify(nuevos)}`);
      }
      if ((estado.flags.pruebasFallidas ?? []).at(-1) !== f.oferta) {
        throw new Error(`${donde}: la prueba fallida no quedó anotada (${JSON.stringify(estado.flags.pruebasFallidas)})`);
      }
      if (cual === 'real') reales += 1; else armadas += 1;
    }
  }
  // Los dos casos de la revisión, con `azar`: después de una prueba fallida sin respaldo ese split no dice "nadie te ofrece nada", y la
  // pregunta del declive (y el motivo, si te retirás) dicen que probaste y no alcanzó.
  let declives = 0;
  // K6a-M: [11, 16] -> [7, 8] (el stream cambió; buscadas igual que antes: `azar` con un declive después de una prueba fallida).
  // K6a (integración, regla 17): con el stream integrado [7, 8] quedaron sin declive. Ya no se fijan: se recorren seeds de `azar` en
  // ronda hasta ver `DECLIVES_K4cR` declives después de una prueba fallida, con tope `TOPE_SEEDS_DECLIVE_K4cR` (check vacío si no
  // llegan). Cada seed recorrida suma también a la otra mitad (ningún split dice silencio después de una prueba fallida).
  let seedsDeclive = 0;
  for (let seed = 1; seed <= TOPE_SEEDS_DECLIVE_K4cR && declives < DECLIVES_K4cR; seed += 1) {
    seedsDeclive = seed;
    const rng = mulberry32(seed);
    let st = createInitialState(seed, rng);
    for (let i = 0; i < 45 && !st.terminado; i += 1) {
      const nLogs = st.logs.length;
      st = avanzarSplit(st, rng).state;
      while (st.pendiente) {
        const { sistemaId, decision } = st.pendiente;
        if (sistemaId === 'retiro' && decision.datos.motivo === 'retiro_declive' && (st.flags.pruebasFallidas ?? []).length > 0) {
          const ultima = st.flags.pruebasFallidas.at(-1);
          const retirado = resolverDecision(structuredClone(st), { opcionId: 'retirarse' }, mulberry32(seed)).state;
          // K5c paso 3b-2 (regla 17): con dos pruebas fallidas el texto las nombra a las dos ("probaste con A y con B y no alcanzó",
          // `probasteCon` en `systems/retiro.js`); el check pedía "probaste con <la última>" y daba rojo con el texto correcto. Ahora:
          // la frase empieza en "probaste con", nombra cada org probada y cierra con la última y "no alcanzó".
          const probadas = [...new Set(st.flags.pruebasFallidas)];
          const diceLaPrueba = (texto, inicio) => texto.includes(`${inicio} con `) && texto.includes(`con ${ultima} y no alcanzó`)
            && probadas.every((org) => texto.includes(org));
          if (!diceLaPrueba(decision.descripcion, 'probaste') || !diceLaPrueba(retirado.motivoRetiro ?? '', 'Probaste')
            || /te está diciendo que no|te venía diciendo que no|teléfono dejó de sonar/.test(`${decision.descripcion} ${retirado.motivoRetiro} ${retirado.logs.at(-1).message}`)) {
            throw new Error(`azar seed ${seed}, split ${i}: el declive cuenta la prueba fallida como silencio: "${decision.descripcion}" / "${retirado.motivoRetiro}" / "${retirado.logs.at(-1).message}"`);
          }
          declives += 1;
        }
        st = resolverDecision(st, ESTRATEGIAS_K0.azar(sistemaPorId(sistemaId), st, decision, rng), rng).state;
      }
      const delSplit = st.logs.slice(nLogs).map((log) => log.message);
      const fallo = delSplit.findIndex((m) => m.includes(PRUEBA_FALLIDA_K4cR) || /no alcanza: se cae la oferta\. No queda nada/.test(m));
      if (fallo >= 0 && delSplit.slice(fallo).some((m) => SILENCIO_K4cR.test(m))) {
        throw new Error(`azar seed ${seed}, split ${i}: la prueba fallida se cuenta como silencio: ${JSON.stringify(delSplit.slice(fallo))}`);
      }
    }
  }
  if (reales + armadas < 5 || declives < DECLIVES_K4cR) {
    throw new Error(`check vacío: ${reales} pruebas fallidas sin respaldo reales, ${armadas} armadas sin otras ofertas, ${declives} declives con pruebas fallidas `
      + `(azar, seeds 1-${seedsDeclive}, tope ${TOPE_SEEDS_DECLIVE_K4cR}; hacen falta ${DECLIVES_K4cR})`);
  }
  console.log(`      ${reales} reales y ${armadas} armadas; ${declives} declives con pruebas fallidas en las seeds 1-${seedsDeclive} de azar`);
});

check('K4c-S un tryout fallido del amateur posterga la firma: seguís en la escalera, sin crédito, y después puede llegar otra oferta', () => {
  const fallidos = sondaDeLaPrueba().filter((f) => f.sistemaId === 'amateur' && !f.bajo.ficho);
  if (fallidos.length < 10) {
    throw new Error(`check vacío: ${fallidos.length} tryouts fallidos del amateur (hacen falta 10)`);
  }
  let firmaDespues = 0;
  fallidos.forEach((f, indice) => {
    const { estado } = f.bajo;
    // El split sigue después de la prueba: puede cortarse por otra causa (la familia, la edad), pero nunca por haber firmado.
    if (estado.career.currentOrg !== null || (!estado.terminado && estado.phase !== 'amateur')) {
      throw new Error(`seed ${f.seed}: el tryout fallido tenía que dejarte en la escalera (fase ${estado.phase}, club ${estado.career.currentOrg})`);
    }
    if ((estado.flags.bonusJerarquiaTryout ?? 0) !== f.antes.bonus) {
      throw new Error(`seed ${f.seed}: el tryout fallido dejó crédito de jerarquía (${estado.flags.bonusJerarquiaTryout})`);
    }
    if (indice < 12 && !estado.terminado && !estado.pendiente) {
      let s = estado;
      for (let k = 0; k < 10 && !s.terminado && s.phase === 'amateur'; k += 1) {
        s = avanzarSplitAuto(s, f.bajo.rr).state;
      }
      if (s.phase === 'profesional') {
        firmaDespues += 1;
      }
    }
  });
  if (firmaDespues === 0) {
    throw new Error('ninguna de las primeras 12 carreras con tryout fallido recibió otra oferta en 10 splits: la firma no se posterga, se pierde');
  }
});

// K4c (revisión): la prueba amateur fallida decía "[object Object] no te firma" (`decision.datos.oferta.org` es la org entera de
// `elegirOrgTier3`) y la apuesta no anunciaba qué pasa si no alcanza, como sí la del mercado (regla 15).
check('K4c (revisión) la prueba amateur anuncia qué pasa si no alcanza y el veredicto nombra la org; ningún texto de las pruebas dice "[object Object]"', () => {
  const filas = sondaDeLaPrueba();
  let fallidos = 0;
  for (const f of filas) {
    const donde = `seed ${f.seed} (${f.sistemaId}, ${f.oferta})`;
    const textos = [f.apuesta, ...f.bajo.estado.logs.map((log) => log.message)];
    const pendiente = f.bajo.estado.pendiente?.decision;
    if (pendiente) {
      textos.push(pendiente.titulo, pendiente.descripcion, pendiente.datos?.apuesta, ...(pendiente.opciones ?? []).flatMap((o) => [o.label, o.descripcion]));
    }
    const roto = textos.find((texto) => typeof texto === 'string' && texto.includes('[object Object]'));
    if (roto) throw new Error(`${donde}: "${roto}"`);
    if (f.sistemaId !== 'amateur') continue;
    // K6c-fix: con la vara en 0 no hay "si no alcanza": la apuesta dice que te firman aunque la prueba salga mal, y con la prueba
    // floja firmás (rojo con la apuesta de siempre, "decide si te firman... Necesitás 0%", en una vara 0).
    if (f.vara === 0) {
      if (!f.apuesta.includes('te firman aunque la prueba salga mal') || /Si no alcanza|decide si te firman/.test(f.apuesta) || !f.bajo.ficho) {
        throw new Error(`${donde}: con la vara en 0 la apuesta tiene que decir que te firman igual (y firmar): "${f.apuesta}" (firmó con la floja: ${f.bajo.ficho})`);
      }
      continue;
    }
    if (typeof f.oferta !== 'string' || !f.apuesta.includes('Si no alcanza, seguís en la escalera')) {
      throw new Error(`${donde}: la apuesta de la prueba amateur no anuncia qué pasa si no alcanza: "${f.apuesta}"`);
    }
    if (!f.bajo.ficho) {
      fallidos += 1;
      if (!f.bajo.estado.logs.some((log) => log.type === 'amateur' && log.message.includes(`${f.oferta} no te firma`))) {
        throw new Error(`${donde}: el veredicto de la prueba fallida no nombra la org`);
      }
    }
  }
  if (fallidos < 10) throw new Error(`check vacío: ${fallidos} pruebas amateur fallidas`);
});

check('K4c-S regla 15: el texto de la prueba dice lo que está en juego (el contrato y el crédito) y ningún veredicto promete la firma', () => {
  const entrada = MINIJUEGOS.find((m) => m.id === 'la_prueba');
  if (!/firm|contrato/i.test(entrada.apuesta) || !/crédito/i.test(entrada.apuesta)) {
    throw new Error(`la apuesta de la prueba tiene que nombrar el contrato (la firma) y el crédito: "${entrada.apuesta}"`);
  }
  for (const [nivel, frases] of Object.entries(entrada.veredictos)) {
    for (const frase of frases) {
      if (/alcanza para firmar|firmás igual|entrás igual|ya firmaste/i.test(frase)) {
        throw new Error(`el veredicto "${nivel}" promete la firma antes de que el motor la decida: "${frase}"`);
      }
    }
  }
  if (!entrada.descripciones.some((d) => /contrato/i.test(d))) {
    throw new Error('ninguna descripción de la prueba nombra el contrato que está en juego');
  }
});

check('K4c el renglón de parche va adjunto salvo que mueva a tu main de S/A a B/C o al revés (K4c-S: salvo que toque tu pool)', () => {
  // K4c (paso 3a) — regla 17: reemplaza a "salvo que un campeón de tu pool (el main incluido) cambie de tier" (K4c-S, 5caaa3c),
  // que dejaba el 81% de los parches como beat propio: casi no recortaba. Ahora solo abre beat el parche que te saca o te
  // devuelve el main (PLAN.md, "El parche se angosta").
  const tierDe = (lista, nombre) => lista.find((entrada) => entrada.name === nombre)?.tier ?? null;
  const buena = (tier) => tier === 'S' || tier === 'A';
  let adjuntos = 0;
  let propios = 0;
  let cambioDeTierQueNoEsElMain = 0;
  for (let seed = 1; seed <= 30; seed += 1) {
    const rng = mulberry32(seed);
    let st = createInitialState(seed, rng);
    for (let i = 0; i < 40 && !st.terminado; i += 1) {
      if ((st.player.championPool ?? []).length > 0) {
        // El sistema `meta` sobre el estado de antes del split, con un rng aparte: no toca la carrera.
        const r = aplicarMetaK4cs(structuredClone(st), mulberry32(hashCadenaK4cs(`${seed}|${i}|meta`)));
        const parche = r.logs[0];
        if (parche?.type !== 'meta') {
          throw new Error(`seed ${seed}, split ${i}: el primer log de meta tenía que ser el renglón del parche`);
        }
        // A mano, sin `parcheMueveTuMain`: el main es el de mayor maestría; ¿cruzó la frontera S/A | B/C entre la tier list
        // vieja y la nueva?
        const main = st.player.championPool.reduce((mejor, campeon) => (campeon.mastery > mejor.mastery ? campeon : mejor));
        const antes = tierDe(st.meta.tierList, main.name);
        const despues = tierDe(r.state.meta.tierList, main.name);
        const mueve = antes !== null && despues !== null && buena(antes) !== buena(despues);
        if ((parche.adjunto === true) === mueve) {
          throw new Error(`seed ${seed}, split ${i}: el parche ${mueve ? `mueve a tu main (${main.name}: ${antes} → ${despues}) y tiene que abrir su beat` : `no mueve a tu main (${main.name}: ${antes} → ${despues}) y tiene que ir adjunto`}, pero adjunto = ${parche.adjunto}`);
        }
        if (mueve) propios += 1; else adjuntos += 1;
        // La muestra que distingue la regla angosta de la vieja: un campeón del pool (no el main) que sí cambió de tier.
        if (!mueve && st.player.championPool.some((campeon) => {
          const a = tierDe(st.meta.tierList, campeon.name);
          const d = tierDe(r.state.meta.tierList, campeon.name);
          return a !== null && d !== null && a !== d;
        })) {
          cambioDeTierQueNoEsElMain += 1;
        }
      }
      st = avanzarSplitAuto(st, rng).state;
    }
  }
  if (propios < 3 || adjuntos < 20 || cambioDeTierQueNoEsElMain < 5) {
    throw new Error(`check vacío: ${propios} parches que mueven el main, ${adjuntos} que no y ${cambioDeTierQueNoEsElMain} que mueven un campeón del pool que no es el main (hacen falta 3, 20 y 5)`);
  }
});

check('K4c-S el instrumento expone el Δp de cada parada de plan (serie:plan e internacional:plan): mejor − peor pSerie declarada, recontado a mano', () => {
  const opciones = (...ps) => ps.map((pSerie) => ({ pSerie }));
  const dp = deltaPDePlan(opciones(0.55, 0.62, 0.50));
  if (Math.abs(dp - 0.12) > 1e-9 || deltaPDePlan(opciones(0.5)) !== null || deltaPDePlan(opciones(0.5, NaN)) !== null
    || deltaPDePlan([]) !== null || deltaPDePlan(undefined) !== null || deltaPDePlan([{ id: 'a' }, { id: 'b' }]) !== null) {
    throw new Error(`deltaPDePlan: [0,55 0,62 0,50] tenía que dar 0,12 (mejor − peor, no primera − última); dio ${dp}; con una sola opción, con NaN o sin pSerie tenía que dar null`);
  }
  let paradas = 0;
  for (const seed of [1, 2, 3]) {
    const aMano = [];
    const espia = (sistema, estado, decision, rngLocal) => {
      if (decision.datos?.motivo === 'plan') {
        const ps = decision.opciones.map((o) => o.pSerie);
        aMano.push({ tipo: `${sistema.id}:plan`, deltaP: Math.max(...ps) - Math.min(...ps) });
      }
      return ESTRATEGIAS_K0.criterio(sistema, estado, decision, rngLocal);
    };
    const { observacion } = correrCarreraSimulate(seed, 60, espia);
    if (JSON.stringify(observacion.planDeltaP) !== JSON.stringify(aMano)) {
      throw new Error(`seed ${seed}: planDeltaP no coincide con el recuento a mano (${JSON.stringify(observacion.planDeltaP).slice(0, 160)} vs ${JSON.stringify(aMano).slice(0, 160)})`);
    }
    const porTipo = (observacion.decisionesPorTipo['serie:plan'] ?? 0) + (observacion.decisionesPorTipo['internacional:plan'] ?? 0);
    if (porTipo !== observacion.planDeltaP.length) {
      throw new Error(`seed ${seed}: ${porTipo} paradas de plan y ${observacion.planDeltaP.length} filas de Δp`);
    }
    paradas += aMano.length;
  }
  if (paradas < 10) {
    throw new Error(`check vacío: ${paradas} paradas de plan en 3 carreras (hacen falta 10)`);
  }
});

// --- K4-C2: el pase de contenido sobre las bifurcaciones (PLAN.md "K4-C2") ---
// Las bifurcaciones nuevas viven en `data/events/caminos.json` (`category: 'caminos'`) y dejan su camino en
// `flags.caminos.*`; los eventos de seguimiento (los que no son bifurcación) lo leen con una `condition` común.
const caminosK4c2 = () => TODOS_LOS_EVENTOS.filter((e) => e.category === 'caminos');
const esFlagDeCamino = (path) => /^flags\.caminos\./.test(path);

// path -> Set de los valores que algún resultado de algún evento escribe.
function escriturasDeCaminoK4c2() {
  const escritas = new Map();
  for (const e of caminosK4c2()) {
    for (const o of e.options) {
      for (const x of o.outcomes) {
        for (const ef of x.effects) {
          if (ef.type === 'camino' && esFlagDeCamino(ef.path)) {
            if (!escritas.has(ef.path)) escritas.set(ef.path, new Set());
            escritas.get(ef.path).add(ef.valor);
          }
        }
      }
    }
  }
  return escritas;
}

check('K4-C2 cada opción de las bifurcaciones nuevas tiene su afinidad de perfil, y cada bifurcación empuja a más de un perfil', () => {
  const base = createInitialState(1, mulberry32(1));
  const forks = caminosK4c2().filter((e) => e.bifurcacion);
  if (forks.length < 7) {
    throw new Error(`esperaba al menos 7 bifurcaciones nuevas (región, contenido, rol, playoffs, conflicto, staff), hay ${forks.length}`);
  }
  const mag = BALANCE.perfil.pesoMagnitud;
  // K4-C2 (regla 15): la oferta de import se cierra si ninguna org de esa liga puede ficharte (en el estado inicial,
  // nunca). Los efectos de carrera no entran en la previa, así que el encaje se mide sin ellos.
  const deCarrera = new Set(['ofertaDeImport', 'cambiarRol', 'retirarse']);
  const sinEfectosDeCarrera = (e) => ({ ...e, options: e.options.map((o) => ({ ...o, outcomes: o.outcomes.map((x) => ({ ...x, effects: x.effects.filter((ef) => !deCarrera.has(ef.type)) })) })) });
  for (const evento of forks.map(sinEfectosDeCarrera)) {
    const vivas = opcionesConPrevia(base, evento);
    if (vivas.length !== evento.options.length) {
      throw new Error(`${evento.id}: una opción con gating propio no entra en esta prueba`);
    }
    const afinidades = new Set();
    for (const o of vivas) {
      const original = evento.options.find((x) => x.id === o.id);
      if (PERFILES_K4C.orden.includes(original.perfil)) {
        afinidades.add(original.perfil);
        continue;
      }
      if (o.previa.length === 0) {
        throw new Error(`${evento.id}/${o.id}: sin previa y sin \`perfil\` en el dato: no tiene afinidad`);
      }
      const encajes = PERFILES_K4C.orden.map((id) => {
        const p = PERFILES_K4C.perfiles[id];
        let valor = p.riesgo[o.riesgo] ?? 0;
        for (const fila of o.previa) {
          const familia = PERFILES_K4C.familiaDeCampo[fila.campo];
          if (familia) valor += (p.familias[familia] ?? 0) * (fila.signo === '-' ? -1 : 1) * (mag[fila.magnitud] ?? 0);
        }
        return { id, valor };
      }).sort((a, b) => b.valor - a.valor);
      if (!(encajes[0].valor > encajes[1].valor)) {
        throw new Error(`${evento.id}/${o.id}: empate entre ${encajes[0].id} y ${encajes[1].id} (${encajes[0].valor}): la afinidad no está definida (usá \`perfil\` en la opción)`);
      }
      afinidades.add(encajes[0].id);
    }
    if (afinidades.size < 2) {
      throw new Error(`${evento.id}: todas sus opciones tienen la misma afinidad (${[...afinidades][0]}): decidirla no corre el perfil`);
    }
  }
});

check('K4-C2 cada bifurcación nueva deja un flag en todos sus resultados, y algún evento lo lee con un valor que alguien escribe', () => {
  const escritas = escriturasDeCaminoK4c2();
  const forks = caminosK4c2().filter((e) => e.bifurcacion);
  const lecturas = new Map(); // path -> [{ evento, op, value }]
  for (const e of TODOS_LOS_EVENTOS) {
    for (const c of e.conditions) {
      if (esFlagDeCamino(c.field)) {
        if (!lecturas.has(c.field)) lecturas.set(c.field, []);
        lecturas.get(c.field).push({ evento: e, op: c.op, value: c.value });
      }
    }
  }
  for (const e of forks) {
    const escribe = new Set();
    for (const o of e.options) {
      for (const x of o.outcomes) {
        const caminos = x.effects.filter((ef) => ef.type === 'camino' && esFlagDeCamino(ef.path));
        if (caminos.length === 0) {
          throw new Error(`${e.id}/${o.id}: un resultado no deja su flag de camino`);
        }
        caminos.forEach((ef) => escribe.add(ef.path));
      }
    }
    for (const path of escribe) {
      const lectores = (lecturas.get(path) ?? []).filter((l) => l.evento.id !== e.id);
      if (lectores.length === 0) {
        throw new Error(`${e.id}: escribe ${path} y ningún otro evento lo lee`);
      }
    }
  }
  for (const [path, lista] of lecturas) {
    for (const l of lista) {
      if (l.op === 'eq' && !escritas.get(path)?.has(l.value)) {
        throw new Error(`${l.evento.id}: lee ${path} == "${l.value}" y ningún resultado escribe ese valor`);
      }
    }
  }
  const seguimientos = new Set([...lecturas.values()].flat().filter((l) => !l.evento.bifurcacion).map((l) => l.evento.id));
  if (seguimientos.size < 2) {
    throw new Error(`hacen falta al menos 2 eventos de seguimiento (no bifurcaciones) que lean un camino: hay ${seguimientos.size}`);
  }
});

check('K4-C2 los caminos se abren y los seguimientos se resuelven en carreras reales (40 carreras × 60)', () => {
  const carreras = carrerasK4c();
  const claves = Object.keys(createInitialState(1, mulberry32(1)).flags.caminos);
  for (const clave of claves) {
    if (!carreras.some((c) => c.final.flags.caminos[clave] !== null)) {
      throw new Error(`ninguna de las ${carreras.length} carreras dejó el camino "${clave}"`);
    }
  }
  const seguimientos = caminosK4c2().filter((e) => !e.bifurcacion);
  const vistos = seguimientos.filter((e) => carreras.some((c) => c.final.logs.some((log) => log.cronica && log.titulo === e.title)));
  if (vistos.length < 3) {
    throw new Error(`solo ${vistos.length} de ${seguimientos.length} eventos de seguimiento se resolvieron en ${carreras.length} carreras (${vistos.map((e) => e.id).join(', ')})`);
  }
});

// K4c (paso 3b), regla 17: se fue "K4-C2 las bifurcaciones frenan entre 4,5 y 7,5 veces por carrera (criterio, 40 carreras × 60; la meta es 5-7)"
// (reemplazado por "K4c meta del ritmo ...: las bifurcaciones por carrera, en promedio, están en [5, 9]", con la muestra de 400 × 60). Exigía
// el promedio de las 40 carreras de `carrerasK4c()` en [4,5, 7,5]; con K4c el promedio medido es 7,8 y la banda se re-basea.

// --- K4-C2 (regla 15): las bifurcaciones cambian la carrera de verdad (PLAN.md "K4-C2, tal como quedó") ---
// La promesa del texto y el efecto del dato tienen que coincidir. `promete` en la opción declara qué cambia; el patrón
// de palabras atrapa la opción que lo promete sin declararlo.
const PROMESAS_K4C2 = {
  region: { efecto: 'ofertaDeImport', patron: /firmar con|mudanza|te mudás|ir a corea|cambiás de liga|aceptan la cláusula/i },
  rol: { efecto: 'cambiarRol', patron: /línea nueva|volvés a tu línea|cambiás de línea/i },
  retiro: { efecto: 'retirarse', patron: /dejar de competir|te retirás|colgar el mouse/i }
};
const EFECTO_A_PROMESA_K4C2 = Object.fromEntries(Object.entries(PROMESAS_K4C2).map(([tipo, p]) => [p.efecto, tipo]));
const textoDeLogK4c2 = (log) => log.texto ?? log.mensaje ?? log.message ?? '';

check('K4-C2 regla 15: toda opción que promete mudanza, cambio de línea o retiro declara el efecto que lo hace, y ninguno se esconde', () => {
  let conPromesa = 0;
  for (const evento of TODOS_LOS_EVENTOS.filter((e) => e.bifurcacion || e.category === 'caminos')) {
    for (const opcion of evento.options) {
      const texto = `${opcion.label} ${opcion.descripcion ?? ''}`;
      for (const [tipo, { patron }] of Object.entries(PROMESAS_K4C2)) {
        if (patron.test(texto) && opcion.promete !== tipo) {
          throw new Error(`${evento.id}/${opcion.id}: el texto promete ${tipo} ("${texto}") pero la opción no declara promete: '${tipo}'`);
        }
      }
      if (opcion.promete !== undefined) {
        const promesa = PROMESAS_K4C2[opcion.promete];
        if (!promesa) {
          throw new Error(`${evento.id}/${opcion.id}: promete '${opcion.promete}' desconocido`);
        }
        if (!opcion.outcomes.some((x) => x.effects.some((ef) => ef.type === promesa.efecto))) {
          throw new Error(`${evento.id}/${opcion.id}: promete ${opcion.promete} y ningún resultado declara ${promesa.efecto}`);
        }
        conPromesa += 1;
      }
    }
  }
  for (const evento of TODOS_LOS_EVENTOS) {
    for (const opcion of evento.options) {
      for (const x of opcion.outcomes) {
        for (const ef of x.effects) {
          if (EFECTO_A_PROMESA_K4C2[ef.type] && opcion.promete !== EFECTO_A_PROMESA_K4C2[ef.type]) {
            throw new Error(`${evento.id}/${opcion.id}: declara ${ef.type} sin promete: '${EFECTO_A_PROMESA_K4C2[ef.type]}' (un efecto de carrera escondido)`);
          }
        }
      }
    }
  }
  if (conPromesa < 8) {
    throw new Error(`solo ${conPromesa} opciones con promesa de carrera; esperaba al menos 8 (región ×4, línea ×2, retiro ×2)`);
  }
});

// --- K5 (revisión): una bifurcación no pisa su propia promesa, los efectos de carrera solo viven en bifurcaciones y
// ninguna pantalla muestra el id crudo de una liga ---
// Una opción con efecto de carrera (`ofertaDeImport`, `cambiarRol`, `retirarse`) tiene que frenar: el perfil resuelve en
// automático todo lo que no es `bifurcacion: true`, y una mudanza, un cambio de línea o un retiro no se resuelven solos.
const EFECTOS_DE_CARRERA_K5R = ['ofertaDeImport', 'cambiarRol', 'retirarse'];
function efectosDeCarreraFueraDeBifurcacionK5r(eventos) {
  const problemas = [];
  for (const e of eventos) {
    if (e.bifurcacion === true) continue;
    for (const o of e.options) {
      const tipos = new Set(o.outcomes.flatMap((x) => x.effects.map((ef) => ef.type).filter((t) => EFECTOS_DE_CARRERA_K5R.includes(t))));
      if (tipos.size > 0) problemas.push(`${e.id}/${o.id}: ${[...tipos].join(', ')} en un evento sin \`bifurcacion: true\``);
    }
  }
  return problemas;
}

// Una segunda promesa de región mientras la primera sigue pendiente la pisa: `flags.ofertaDeImport` se escribe entera
// (`prometerImport`). La pretemporada la limpia, se firme o se caiga, así que el guard no bloquea para siempre.
function regionesSinGuardK5r(eventos) {
  const guard = (c) => c.field === 'flags.ofertaDeImport' && c.op === 'eq' && c.value === null;
  return eventos
    .filter((e) => e.options.some((o) => o.promete === 'region') && !e.conditions.some(guard))
    .map((e) => `${e.id}: promete una mudanza y no exige \`flags.ofertaDeImport == null\``);
}

check('K5 (revisión) los efectos de carrera solo viven en bifurcaciones, y una bifurcación de región no pisa una oferta de import pendiente', () => {
  const real = efectosDeCarreraFueraDeBifurcacionK5r(TODOS_LOS_EVENTOS);
  if (real.length > 0) {
    throw new Error(real.join(' · '));
  }
  const sinGuard = regionesSinGuardK5r(TODOS_LOS_EVENTOS);
  if (sinGuard.length > 0) {
    throw new Error(sinGuard.join(' · '));
  }
  const regiones = TODOS_LOS_EVENTOS.filter((e) => e.options.some((o) => o.promete === 'region'));
  if (regiones.length < 3) {
    throw new Error(`esperaba las 3 bifurcaciones de región, hay ${regiones.length}`);
  }
  // Mutantes (sobre copias): una bifurcación que pierde el flag, y una región que pierde el guard.
  const conCarrera = TODOS_LOS_EVENTOS.filter((e) => e.bifurcacion === true
    && e.options.some((o) => o.outcomes.some((x) => x.effects.some((ef) => EFECTOS_DE_CARRERA_K5R.includes(ef.type)))));
  for (const e of conCarrera) {
    const mutante = TODOS_LOS_EVENTOS.map((x) => (x.id === e.id ? { ...x, bifurcacion: false } : x));
    if (efectosDeCarreraFueraDeBifurcacionK5r(mutante).length === 0) {
      throw new Error(`mutante: ${e.id} sin bifurcacion:true y el check no lo ve`);
    }
  }
  for (const e of regiones) {
    const mutante = TODOS_LOS_EVENTOS.map((x) => (x.id === e.id ? { ...x, conditions: x.conditions.filter((c) => c.field !== 'flags.ofertaDeImport') } : x));
    if (regionesSinGuardK5r(mutante).length === 0) {
      throw new Error(`mutante: ${e.id} sin su guard y el check no lo ve`);
    }
  }
});

// Las líneas de la UI que escriben una liga en pantalla (texto, title, template) tienen que pasar por `nombreVisibleDeLiga`.
function usosDeLigaCrudaK5r(fuentes) {
  const problemas = [];
  for (const [archivo, texto] of Object.entries(fuentes)) {
    texto.split('\n').forEach((linea, i) => {
      if (/^\s*(\/\/|\*|\/\*)/.test(linea) || !/textContent|createTextNode|\.title\s*=|\$\{|\.join\(/.test(linea)) {
        return;
      }
      // Lo que pasa por el helper, y la liga usada solo como condición (`c.liga ? ... : ...`), no es texto en pantalla.
      const sinPermitidos = linea.replace(/nombreVisibleDeLiga\([^()]*\)/g, '').replace(/(\.liga\b|\bligaId\b)\s*\?(?![?.])/g, '');
      if (/(\.liga\b|\.ligaCampeon\b|\bligaId\b)/.test(sinPermitidos)) {
        problemas.push(`${archivo}:${i + 1}: ${linea.trim()}`);
      }
    });
  }
  return problemas;
}

check('K5 (revisión) ninguna pantalla muestra el id crudo de una liga ("EMEA_MASTERS", "LCK_CL"): el mercado, la tabla, el Mundial, el feed y los tops pasan por nombreVisibleDeLiga', () => {
  for (const liga of JSON.parse(fs.readFileSync(path.join(srcDir, 'data', 'leagues.json'), 'utf8'))) {
    if (nombreVisibleDeLiga(liga.id) !== liga.nombre) {
      throw new Error(`nombreVisibleDeLiga("${liga.id}") = "${nombreVisibleDeLiga(liga.id)}", esperaba "${liga.nombre}"`);
    }
  }
  if (nombreVisibleDeLiga('EMEA_MASTERS') !== 'EMEA Masters' || nombreVisibleDeLiga('LCK_CL') !== 'LCK CL') {
    throw new Error('los ids de las ligas de desarrollo no se traducen');
  }
  if (nombreVisibleDeLiga('XYZ') !== 'XYZ') {
    throw new Error('un id desconocido tiene que volver tal cual');
  }
  const fuentes = {};
  const recorrer = (dir) => {
    for (const entrada of fs.readdirSync(dir, { withFileTypes: true })) {
      const ruta = path.join(dir, entrada.name);
      if (entrada.isDirectory()) recorrer(ruta);
      else if (entrada.name.endsWith('.js')) fuentes[path.relative(srcDir, ruta).replace(/\\/g, '/')] = fs.readFileSync(ruta, 'utf8').replace(/\r\n/g, '\n');
    }
  };
  recorrer(uiDir);
  const crudos = usosDeLigaCrudaK5r(fuentes);
  if (crudos.length > 0) {
    throw new Error(`${crudos.length} línea(s) de la UI muestran una liga sin nombreVisibleDeLiga: ${crudos.slice(0, 4).join(' · ')}`);
  }
  // Mutante: sin la llamada, cada archivo que la usa tiene que saltar.
  const usan = Object.entries(fuentes).filter(([archivo, texto]) => archivo !== 'ui/formatoUi.js' && /nombreVisibleDeLiga\(/.test(texto));
  if (usan.length < 6) {
    throw new Error(`esperaba al menos 6 archivos de la UI que muestran ligas, hay ${usan.length}`);
  }
  for (const [archivo, texto] of usan) {
    const mutante = { [archivo]: texto.replace(/nombreVisibleDeLiga\(([^()]*)\)/g, '$1') };
    if (usosDeLigaCrudaK5r(mutante).length === 0) {
      throw new Error(`mutante: ${archivo} sin nombreVisibleDeLiga y el check no lo ve`);
    }
  }
});

// Estados de carrera real en una pretemporada, profesional, tier 1 o 2 (los de las bifurcaciones de región).
let pretemporadasProK4c2Cache = null;
function pretemporadasProK4c2(cantidad) {
  pretemporadasProK4c2Cache ??= (() => {
    const estados = [];
    for (let seed = 7100; estados.length < 25 && seed < 7400; seed += 1) {
      const rng = mulberry32(seed);
      let state = createInitialState(seed, rng);
      for (let i = 0; i < 45 && !state.terminado; i += 1) {
        state = avanzarSplitAuto(state, rng).state;
        // K4c (plan anual): la muestra pide equipo (`currentOrg`). Con el stream del plan, la seed 7101 caía en un agente
        // libre de tier 2 (sin compañeros), donde el swap de línea no aplica.
        if (state.phase === 'profesional' && !state.pendiente && state.player.splitCount % BALANCE.edad.splitsPorEdad === 0
          && [1, 2].includes(state.career.tier) && state.career.currentOrg && state.player.splitCount >= 24) {
          estados.push({ seed, state });
          break;
        }
      }
    }
    return estados;
  })();
  return pretemporadasProK4c2Cache.slice(0, cantidad);
}

check('K4-C2 regla 15: ofertaDeImport se firma por el mercado en la próxima pretemporada y terminás jugando en esa liga', () => {
  let firmadas = 0;
  let cerradas = 0;
  const lpl = TODOS_LOS_EVENTOS.find((e) => e.id === 'la_oferta_de_la_lpl');
  for (const { seed, state } of pretemporadasProK4c2(25)) {
    for (const liga of ['LCK', 'LPL', 'LEC', 'LCS']) {
      if (liga === state.career.liga) continue;
      const posible = ofertaDeImportPosible(state, liga);
      if (!posible.posible) {
        // La opción que lo promete no se puede tomar: sale cerrada con el motivo del mercado (regla 15).
        if (liga === 'LPL') {
          const decision = decisionDesdeEvento(state, lpl, { franja: 'normal', slot: 1 });
          const bloqueada = decision.opcionesBloqueadas.find((o) => o.gate === posible.motivo);
          if (!bloqueada || decision.opciones.some((o) => o.id === 'ir_por_la_plata')) {
            throw new Error(`seed ${seed}: la LPL no puede ficharte (${posible.motivo}) y "Firmar con la LPL" igual se ofrece`);
          }
          cerradas += 1;
        }
        continue;
      }
      const conOferta = { ...state, flags: { ...state.flags, ofertaDeImport: { ligas: [liga], clausula: 'salida' } } };
      const r = aplicarMercado(conOferta, mulberry32(seed));
      if (r.state.flags.ofertaDeImport !== null) {
        throw new Error(`seed ${seed}: la oferta de ${liga} sigue pendiente después de la pretemporada`);
      }
      const seCayo = r.logs.some((l) => /La mudanza se cae/.test(textoDeLogK4c2(l)));
      if (r.state.career.liga === liga) {
        if (r.state.career.contrato.clausula !== 'salida' || r.decision) {
          throw new Error(`seed ${seed}: firmó en ${liga} sin la cláusula de la oferta, o el mercado volvió a frenar`);
        }
        firmadas += 1;
      } else if (!seCayo) {
        throw new Error(`seed ${seed}: aceptó ir a ${liga} y sigue en ${r.state.career.liga} sin que se diga por qué`);
      }
    }
  }
  if (firmadas < 5 || cerradas < 1) {
    throw new Error(`firmadas ${firmadas} (mín. 5), opciones cerradas con motivo ${cerradas} (mín. 1)`);
  }
});

check('K4-C2 regla 15: cambiarRol te cambia de línea con pool y plantel coherentes, y volver a lo tuyo te devuelve', () => {
  const swap = TODOS_LOS_EVENTOS.find((e) => e.id === 'la_linea_que_te_piden');
  const vuelta = TODOS_LOS_EVENTOS.find((e) => e.id === 'la_linea_nueva_te_cambio');
  const casos = pretemporadasProK4c2(8);
  for (const { seed, state: crudo } of casos) {
    // Si la carrera del bot ya había cambiado de línea, se parte de su línea de hoy como la de origen.
    const state = { ...crudo, flags: { ...crudo.flags, rolDeOrigen: null } };
    const rolViejo = state.player.role;
    const poolViejo = state.player.championPool.map((c) => c.name).join(',');
    const ida = resolverOpcion(state, swap, 'aceptar_el_swap', mulberry32(seed)).state;
    const rolNuevo = ida.player.role;
    if (rolNuevo === rolViejo || !IDS_ROL.includes(rolNuevo)) {
      throw new Error(`seed ${seed}: aceptar el swap dejó la línea en ${rolNuevo}`);
    }
    const ajenos = ida.player.championPool.filter((c) => CAMPEONES.find((x) => x.name === c.name)?.role !== rolNuevo);
    if (ajenos.length > 0 || ida.player.championPool.length < BALANCE.campeones.poolMinimo) {
      throw new Error(`seed ${seed}: pool de ${rolNuevo} incoherente (${ida.player.championPool.map((c) => c.name).join(', ')})`);
    }
    const rolesCompaneros = ida.career.companeros.map((c) => c.role).sort().join(',');
    if (rolesCompaneros !== IDS_ROL.filter((r) => r !== rolNuevo).sort().join(',')) {
      throw new Error(`seed ${seed}: compañeros ${rolesCompaneros} con vos en ${rolNuevo}`);
    }
    const back = resolverOpcion(ida, vuelta, 'volver_a_lo_tuyo', mulberry32(seed)).state;
    if (back.player.role !== rolViejo || back.player.championPool.map((c) => c.name).join(',') !== poolViejo || back.flags.rolDeOrigen !== null) {
      throw new Error(`seed ${seed}: volver a lo tuyo no te devolvió a ${rolViejo} con tu pool`);
    }
  }
  if (casos.length < 5) {
    throw new Error(`solo ${casos.length} estados de prueba`);
  }
});

check('K4-C2 regla 15: retirarse termina la carrera por el camino del retiro, con el motivo en palabras; la ventana tiene su contenido', () => {
  const canal = TODOS_LOS_EVENTOS.find((e) => e.id === 'el_canal_de_tiempo_completo');
  const { seed, state } = pretemporadasProK4c2(1)[0];
  const r = resolverOpcion(state, canal, 'vivir_del_canal', mulberry32(seed));
  const st = r.state;
  if (st.phase !== 'retirado' || st.finAnticipado !== 'retiro_elegido'
    || !String(st.motivoRetiro).includes(MOTIVOS_DE_RETIRO.streaming) || st.flags.motivoRetiro !== undefined) {
    throw new Error(`vivir del canal dejó phase=${st.phase}, fin=${st.finAnticipado}, motivo=${st.motivoRetiro}`);
  }
  const textos = r.logs.map(textoDeLogK4c2).join(' | ');
  if (!textos.includes(MOTIVOS_DE_RETIRO.streaming) || /\bstreaming\b|retirarse/.test(textos)) {
    throw new Error(`el log no cuenta el motivo en palabras: ${textos}`);
  }
  const final = resolverOpcion({ ...state, flags: { ...state.flags, vueltasUsadas: BALANCE.retiro.vueltasMaximas } }, canal, 'vivir_del_canal', mulberry32(seed)).state;
  if (!final.terminado) {
    throw new Error('sin vueltas disponibles, retirarse no cerró la carrera');
  }
  // La ventana de vuelta: en la parada del "¿Volvés?", la bifurcación de la ventana (`la_llamada_del_manager`) sale.
  let llamadas = 0;
  for (let s = 1; s <= 40; s += 1) {
    const enVentana = {
      ...st,
      player: { ...st.player, splitCount: st.player.splitCount + BALANCE.edad.splitsPorEdad },
      flags: { ...st.flags, splitsEnVentana: BALANCE.edad.splitsPorEdad - 1, cooldownHasta: {} }
    };
    const v = aplicarRetiroK4c2(enVentana, mulberry32(s));
    if (v.decision?.datos?.evento?.id === 'la_llamada_del_manager') llamadas += 1;
  }
  if (llamadas === 0) {
    throw new Error('la_llamada_del_manager no sale nunca en la ventana de vuelta (40 tiradas)');
  }
});

// (Los tres custodios se mudaron al final del archivo: van después del último check — K5.)

// --- K3-B: los efectos que duran (PLAN.md "K3 — decisiones de spec") ---
//
// Estructura con la constante en 0: el juego queda idéntico, y eso lo prueba "K1 versión" (la huella del juego). Estos
// checks son estructurales: la regla en el aplicador de efectos, la curva y la ficha, con la fracción en 0 y en memoria
// con una positiva. Cada uno se probó en rojo contra su mutante sobre una copia (regla de proceso 7): el aplicador sin
// el gancho, la curva sin el bonus, un stat de curva fuera del bonus inicial, la constante neutra rota, una marca que
// pisa a las anteriores, el id crudo como origen y la ficha sin el umbral.
const STATS_DE_CURVA_K3B = Object.keys(BALANCE.atributos.curvas);
const FRACCION_K3B = 0.5;

function conFraccionPermanenteK3b(fraccion, fn) {
  const original = BALANCE.atributos.fraccionPermanente;
  BALANCE.atributos.fraccionPermanente = fraccion;
  try {
    return fn();
  } finally {
    BALANCE.atributos.fraccionPermanente = original;
  }
}

// Un evento a mano con un único efecto determinista sobre `path` (min === max), para no depender del contenido.
function eventoSinteticoK3b(path, delta) {
  return {
    id: 'k3b_sintetico_bootcamp',
    title: 'Bootcamp en Corea',
    description: 'Evento sintético de K3-B.',
    options: [
      { id: 'ir', label: 'Ir', weight: 1, outcomes: [{ weight: 1, texto: 'Volvés distinto.', effects: [{ type: 'stat', path, min: delta, max: delta, clamp: [0, 100] }] }] },
      { id: 'quedarse', label: 'Quedarte', weight: 1, outcomes: [{ weight: 1, texto: 'Te quedás.', effects: [] }] }
    ]
  };
}

function bonusCompletoK3b(player) {
  const claves = Object.keys(player.bonusPermanente ?? {});
  return claves.length === STATS_DE_CURVA_K3B.length
    && STATS_DE_CURVA_K3B.every((stat) => Number.isFinite(player.bonusPermanente[stat]));
}

check('K3-B bonusPermanente: completo con ceros al arrancar y completo (un número por stat de curva, ni uno más) en cada split de una carrera', () => {
  const inicial = createInitialState(1, mulberry32(1));
  if (!bonusCompletoK3b(inicial.player) || STATS_DE_CURVA_K3B.some((stat) => inicial.player.bonusPermanente[stat] !== 0)) {
    throw new Error(`el estado inicial no trae bonusPermanente completo con ceros: ${JSON.stringify(inicial.player.bonusPermanente)}`);
  }
  for (const [seed, fraccion] of [[1, 0], [2, FRACCION_K3B]]) {
    conFraccionPermanenteK3b(fraccion, () => {
      const rng = mulberry32(seed);
      let state = createInitialState(seed, rng);
      for (let split = 0; split < 40 && !state.terminado; split += 1) {
        state = avanzarSplitAuto(state, rng).state;
        if (!bonusCompletoK3b(state.player)) {
          throw new Error(`seed ${seed} (fracción ${fraccion}), split ${split + 1}: bonusPermanente incompleto: ${JSON.stringify(state.player.bonusPermanente)}`);
        }
      }
    });
  }
});

check('K3c fracciones calibradas: con fraccionPermanente y fraccionPermanentePractica de BALANCE (sin override) un efecto de evento y una rutina de práctica sobre un stat de curva suman exactamente fracción·(movimiento real) al bonus, con UNA marca, y una carrera larga deja marcas', () => {
  // Reemplaza a "K3-B neutro" (que exigía la fracción en 0: la constante neutra de la estructura de K3-B). K3c la calibró
  // (PLAN.md "La sonda de retención": 0,3 conserva >= 40% a 4 splits), y lo que el juego promete ahora es que un efecto
  // DURA: ni 0 (el efecto se evapora) ni un valor que no se vea en la marca. Va con el valor real de BALANCE, sin override
  // (los checks de K3-B con la fracción en memoria prueban la mecánica; este prueba la constante).
  const { fraccionPermanente, fraccionPermanentePractica } = BALANCE.atributos;
  for (const [nombre, fraccion] of [['fraccionPermanente', fraccionPermanente], ['fraccionPermanentePractica', fraccionPermanentePractica]]) {
    if (!(fraccion > 0 && fraccion <= 1)) {
      throw new Error(`${nombre} vale ${fraccion}: K3c la calibró en (0, 1]; en 0 los efectos no duran`);
    }
  }
  // El estado base sale con las dos fracciones en 0 (bonus en ceros, sin marcas): lo que se mida es del efecto.
  const base = conBalanceK3A([['atributos', 'fraccionPermanente', 0], ['atributos', 'fraccionPermanentePractica', 0]], () => correrCarrera(3, 18));
  if (base.career.registro.marcas.length !== 0 || STATS_DE_CURVA_K3B.some((s) => base.player.bonusPermanente[s] !== 0)) {
    throw new Error('el estado base ya trae bonus o marcas');
  }
  for (const stat of STATS_DE_CURVA_K3B) {
    const evento = eventoSinteticoK3b(`player.stats.${stat}`, 6);
    const { state } = resolverOpcion(base, evento, 'ir', mulberry32(5));
    const movido = state.player.stats[stat] - base.player.stats[stat];
    const esperado = fraccionPermanente * movido;
    if (esperado === 0) throw new Error(`sonda vacía: el efecto sintético no movió ${stat}`);
    if (Math.abs(state.player.bonusPermanente[stat] - esperado) > 1e-9) {
      throw new Error(`${stat}: el bonus quedó en ${state.player.bonusPermanente[stat]}, esperaba ${esperado} (${fraccionPermanente} × ${movido})`);
    }
    const otros = STATS_DE_CURVA_K3B.filter((s) => s !== stat && state.player.bonusPermanente[s] !== 0);
    if (otros.length > 0) throw new Error(`${stat}: el efecto movió el bonus de ${otros.join(', ')}`);
    const marcas = state.career.registro.marcas;
    const [marca] = marcas;
    if (marcas.length !== 1 || marca.stat !== stat || Math.abs(marca.delta - esperado) > 1e-9 || marca.origen !== 'Bootcamp en Corea') {
      throw new Error(`${stat}: esperaba UNA marca { ${stat}, ${esperado}, 'Bootcamp en Corea' }: ${JSON.stringify(marcas)}`);
    }
  }
  // La práctica, con su propia fracción.
  const practica = sistemaPorId('practica');
  const rutina = {
    id: 'k3c_bootcamp_sintetico', titulo: 'Bootcamp de prueba',
    reparto: { pulir: 0, nuevo: 0, mecanica: BALANCE.practica.puntos / 2, macro: BALANCE.practica.puntos / 2, descansar: 0 }
  };
  const desde = { ...base, player: { ...base.player, techoLesionMecanica: null, stats: { ...base.player.stats, mecanica: 50 } } };
  const despues = resolverPreparacion(desde, [rutina], rutina.id, mulberry32(77)).state;
  const ganancia = despues.player.stats.mecanica - desde.player.stats.mecanica;
  if (!(ganancia > 0)) throw new Error(`sonda vacía: la rutina no movió mecánica (${ganancia})`);
  const esperadoPractica = fraccionPermanentePractica * ganancia;
  const [marcaPractica] = despues.career.registro.marcas;
  if (Math.abs(despues.player.bonusPermanente.mecanica - esperadoPractica) > 1e-9 || despues.career.registro.marcas.length !== 1
      || Math.abs(marcaPractica.delta - esperadoPractica) > 1e-9 || marcaPractica.origen !== rutina.titulo) {
    throw new Error(`la práctica: bonus ${despues.player.bonusPermanente.mecanica}, esperaba ${esperadoPractica} (${fraccionPermanentePractica} × ${ganancia}) con UNA marca a nombre de la rutina: ${JSON.stringify(despues.career.registro.marcas)}`);
  }
  // Y una carrera larga, jugada sin overrides, deja marcas: la regla está enchufada a eventos y práctica reales.
  // K6c, segunda pasada (regla 17): la seed 3 ahora termina a los 4 splits sin firmar nunca (en casa dijeron que no), y una carrera
  // de 4 splits no es larga. Se toman, en ronda, las 3 primeras carreras que llegan a pro; lo que se mide no cambia.
  const CARRERAS_LARGAS_K3C = 3;
  const SEEDS_EN_RONDA_K3C = 30;
  let largas = 0;
  for (let seed = 1; seed <= SEEDS_EN_RONDA_K3C && largas < CARRERAS_LARGAS_K3C; seed += 1) {
    const fin = correrCarrera(seed, 60);
    if (fin.splitFichaje === null || fin.splitFichaje === undefined) continue;
    largas += 1;
    if (fin.career.registro.marcas.length === 0 || !STATS_DE_CURVA_K3B.some((stat) => fin.player.bonusPermanente[stat] > 0)) {
      throw new Error(`seed ${seed}: con las fracciones calibradas la carrera terminó sin marcas ni bonus`);
    }
  }
  if (largas < CARRERAS_LARGAS_K3C) throw new Error(`check vacío: ${largas} carreras que llegan a pro en las seeds 1-${SEEDS_EN_RONDA_K3C}`);
});

check('K3-B efecto con fracción positiva: suma fracción·delta al bonus del stat, anota UNA marca con el nombre visible del evento (no su id), y los stats que no son de curva no dejan nada', () => {
  // El estado base puede traer bonus y marcas (con las fracciones de K3c encendidas la carrera ya dejó algunas): lo que
  // se mide es el CAMBIO que produce el efecto, no el valor absoluto.
  const base = correrCarrera(3, 18);
  const marcasBase = base.career.registro.marcas;
  const cambioDeBonus = (state, stat) => state.player.bonusPermanente[stat] - base.player.bonusPermanente[stat];
  const marcasNuevas = (state) => state.career.registro.marcas.slice(marcasBase.length);
  const conservaLasAnteriores = (state) => JSON.stringify(state.career.registro.marcas.slice(0, marcasBase.length)) === JSON.stringify(marcasBase);
  conFraccionPermanenteK3b(FRACCION_K3B, () => {
    for (const stat of STATS_DE_CURVA_K3B) {
      const evento = eventoSinteticoK3b(`player.stats.${stat}`, 6);
      const { state } = resolverOpcion(base, evento, 'ir', mulberry32(5));
      const movido = state.player.stats[stat] - base.player.stats[stat];
      const esperado = FRACCION_K3B * movido;
      if (Math.abs(cambioDeBonus(state, stat) - esperado) > 1e-9 || esperado === 0) {
        throw new Error(`${stat}: el bonus cambió ${cambioDeBonus(state, stat)}, esperaba ${esperado} (fracción ${FRACCION_K3B} × ${movido})`);
      }
      const otros = STATS_DE_CURVA_K3B.filter((s) => s !== stat && cambioDeBonus(state, s) !== 0);
      if (otros.length > 0) {
        throw new Error(`${stat}: el efecto movió el bonus de ${otros.join(', ')}`);
      }
      const nuevas = marcasNuevas(state);
      if (nuevas.length !== 1 || !conservaLasAnteriores(state)) {
        throw new Error(`${stat}: esperaba UNA marca nueva (y las anteriores intactas), hay ${nuevas.length} nuevas`);
      }
      const [marca] = nuevas;
      if (marca.stat !== stat || Math.abs(marca.delta - esperado) > 1e-9 || marca.origen !== 'Bootcamp en Corea'
          || marca.anio !== base.calendario.anio || marca.origen === evento.id) {
        throw new Error(`${stat}: la marca no es { stat, delta, origen visible, anio }: ${JSON.stringify(marca)}`);
      }
    }
    // Un stat que no es de curva (macro, mentalidad) se mueve igual pero no deja nada permanente.
    for (const stat of ['macro', 'mentalidad', 'hype']) {
      const { state } = resolverOpcion(base, eventoSinteticoK3b(`player.stats.${stat}`, 6), 'ir', mulberry32(5));
      if (marcasNuevas(state).length !== 0 || STATS_DE_CURVA_K3B.some((s) => cambioDeBonus(state, s) !== 0)) {
        throw new Error(`${stat} no es un stat de curva y dejó bonus o marca`);
      }
    }
  });
});

check('K3-B efecto contra el clamp: el bonus y la marca cuentan lo que el stat de verdad se movió (después − antes), no la tirada — con un stat en 99 y un efecto +10, o en 1 y un efecto −10, el delta es fracción·(±1)', () => {
  // Protege el único punto de escritura de `events.js`: una marca anotada con la tirada previa al clamp (en vez de
  // `despues − antes`) pasaba todos los checks con stats lejos de los bordes. El estado base sale con las dos fracciones
  // en 0 (bonus en ceros, sin marcas): lo que se mida es del efecto.
  const base = conBalanceK3A([['atributos', 'fraccionPermanente', 0], ['atributos', 'fraccionPermanentePractica', 0]], () => correrCarrera(3, 18));
  const casos = [[BALANCE.stats.max - 1, 10, 1], [1, -10, -1]];
  conFraccionPermanenteK3b(FRACCION_K3B, () => {
    for (const stat of STATS_DE_CURVA_K3B) {
      for (const [valorInicial, tirada, movidoReal] of casos) {
        const desde = { ...base, player: { ...base.player, stats: { ...base.player.stats, [stat]: valorInicial } } };
        const { state } = resolverOpcion(desde, eventoSinteticoK3b(`player.stats.${stat}`, tirada), 'ir', mulberry32(5));
        const movido = state.player.stats[stat] - valorInicial;
        if (Math.abs(movido - movidoReal) > 1e-9) throw new Error(`${stat}: de ${valorInicial} con ${tirada} se movió ${movido}, el clamp debía dejarlo en ${movidoReal}`);
        const esperado = FRACCION_K3B * movido;
        const bonus = state.player.bonusPermanente[stat] - desde.player.bonusPermanente[stat];
        if (Math.abs(bonus - esperado) > 1e-9) throw new Error(`${stat}: de ${valorInicial} con ${tirada} el bonus cambió ${bonus}, esperaba fracción × (después − antes) = ${esperado}`);
        const marcas = state.career.registro.marcas;
        if (marcas.length !== 1 || Math.abs(marcas[0].delta - esperado) > 1e-9) {
          throw new Error(`${stat}: de ${valorInicial} con ${tirada} la marca es ${JSON.stringify(marcas)}, esperaba delta ${esperado}`);
        }
      }
    }
  });
});

check('K3-B 2b la práctica deja marca: con fraccionPermanentePractica > 0 (en memoria) la rutina de offseason suma fracción·(ganancia real, ya con el clamp) al bonus de mecánica, con UNA marca a nombre de la rutina; usa su propia fracción y no consume rng', () => {
  // Protege PLAN.md "K3-B 2b": la práctica y las rutinas también dejan marca, con su fracción propia y el nombre
  // visible de la rutina como origen; la ganancia que cuenta es la que de verdad movió el stat.
  const FRACCION = 0.5;
  // El estado base sale con las dos fracciones en 0 (con las de K3c encendidas la carrera ya trae marcas y bonus): lo que
  // se mida es de la rutina.
  const base = conBalanceK3A([['atributos', 'fraccionPermanente', 0], ['atributos', 'fraccionPermanentePractica', 0]], () => correrCarrera(3, 18));
  const practica = sistemaPorId('practica');
  const rutina = {
    id: 'k3b_bootcamp_sintetico', titulo: 'Bootcamp de prueba',
    reparto: { pulir: 0, nuevo: 0, mecanica: BALANCE.practica.puntos / 2, macro: BALANCE.practica.puntos / 2, descansar: 0 }
  };
  const decision = { datos: { rutinas: [rutina] } };
  const conMecanica = (mecanica) => ({ ...base, player: { ...base.player, techoLesionMecanica: null, stats: { ...base.player.stats, mecanica } } });
  const correr = (desde) => resolverPreparacion(desde, [rutina], rutina.id, mulberry32(77)).state;
  if (base.career.registro.marcas.length !== 0) throw new Error('el estado base ya trae marcas');
  for (const desde of [conMecanica(50), conMecanica(BALANCE.stats.max - 1)]) {
    const neutro = conBalanceK3A([['atributos', 'fraccionPermanentePractica', 0]], () => correr(desde));
    const conFraccion = conBalanceK3A([['atributos', 'fraccionPermanentePractica', FRACCION]], () => correr(desde));
    const ganancia = conFraccion.player.stats.mecanica - desde.player.stats.mecanica;
    if (!(ganancia > 0)) throw new Error(`sonda vacía: la rutina no movió mecánica (${ganancia})`);
    if (JSON.stringify(neutro.player.stats) !== JSON.stringify(conFraccion.player.stats)) {
      throw new Error('la fracción cambió los stats del receso (consumió rng o movió algo más que el bonus)');
    }
    if (neutro.career.registro.marcas.length !== 0 || STATS_DE_CURVA_K3B.some((stat) => neutro.player.bonusPermanente[stat] !== 0)) {
      throw new Error('con fraccionPermanentePractica 0 la práctica dejó bonus o marca');
    }
    const esperado = FRACCION * ganancia;
    if (Math.abs(conFraccion.player.bonusPermanente.mecanica - esperado) > 1e-9) {
      throw new Error(`bonus de mecánica ${conFraccion.player.bonusPermanente.mecanica}, esperaba ${esperado} (${FRACCION} × ganancia real ${ganancia})`);
    }
    const otros = STATS_DE_CURVA_K3B.filter((stat) => stat !== 'mecanica' && conFraccion.player.bonusPermanente[stat] !== 0);
    if (otros.length > 0) throw new Error(`la práctica movió el bonus de ${otros.join(', ')} (macro no es de curva)`);
    const marcas = conFraccion.career.registro.marcas;
    const [marca] = marcas;
    if (marcas.length !== 1 || marca.stat !== 'mecanica' || Math.abs(marca.delta - esperado) > 1e-9
        || marca.origen !== rutina.titulo || marca.anio !== desde.calendario.anio) {
      throw new Error(`esperaba UNA marca { mecanica, ${esperado}, '${rutina.titulo}', ${desde.calendario.anio} }: ${JSON.stringify(marcas)}`);
    }
  }
  // Su propia fracción: la de los eventos no la mueve.
  const soloEventos = conBalanceK3A([['atributos', 'fraccionPermanente', FRACCION], ['atributos', 'fraccionPermanentePractica', 0]], () => correr(conMecanica(50)));
  if (soloEventos.career.registro.marcas.length !== 0) throw new Error('la práctica usó fraccionPermanente (la de los eventos) en vez de la suya');
});

check('K3-B 2b un solo camino para las rutinas: la semana amateur (systems/amateur.js) y el receso (systems/practica.js) marcan con conMarcasDeRutina — fracción de la práctica, título visible de la rutina, solo la ganancia real —, y el aplicador de stats del minijuego pasa por conPermanencia con el nombre del minijuego', () => {
  const FRACCION = 0.5;
  const base = conBalanceK3A([['atributos', 'fraccionPermanente', 0], ['atributos', 'fraccionPermanentePractica', 0]], () => correrCarrera(3, 18));
  // El helper: gana mecánica (curva, cuenta), pierde laneo (curva, una pérdida no es de la práctica), sube hype (no es de curva).
  const antes = { ...base.player.stats, mecanica: 50, laneo: 50, hype: 50 };
  const despues = { ...antes, mecanica: 53, laneo: 47, hype: 60 };
  const conStats = { ...base, player: { ...base.player, stats: despues } };
  const marcado = conBalanceK3A([['atributos', 'fraccionPermanentePractica', FRACCION], ['atributos', 'fraccionPermanente', 0.9]], () => conMarcasDeRutinaK3B(conStats, antes, 'Bootcamp en tu propia pieza'));
  const [unica, ...otras] = marcado.career.registro.marcas;
  if (otras.length > 0 || !unica || unica.stat !== 'mecanica' || Math.abs(unica.delta - FRACCION * 3) > 1e-9 || unica.origen !== 'Bootcamp en tu propia pieza') {
    throw new Error(`conMarcasDeRutina esperaba UNA marca { mecanica, ${FRACCION * 3}, título } (fracción de la práctica, sin el laneo que bajó ni el hype): ${JSON.stringify(marcado.career.registro.marcas)}`);
  }
  if (marcado.player.bonusPermanente.laneo !== 0 || conBalanceK3A([['atributos', 'fraccionPermanentePractica', 0]], () => conMarcasDeRutinaK3B(conStats, antes, 'x')) !== conStats) {
    throw new Error('con la fracción de la práctica en 0 conMarcasDeRutina tiene que devolver el mismo estado');
  }
  // El cableado: las dos rutinas llaman al helper con el título de la rutina (el cierre del check de arriba prueba lo que
  // hace con una ganancia real en el receso; hoy ningún reparto amateur mueve un stat de curva, así que acá no hay
  // ganancia que medir y el cableado se lee del fuente).
  for (const archivo of ['amateur.js', 'practica.js']) {
    const fuente = fs.readFileSync(path.join(srcDir, 'systems', archivo), 'utf8');
    if (!/import \{ conMarcasDeRutina \} from '\.\.\/core\/curvas\.js'/.test(fuente) || !/conMarcasDeRutina\([^)]*rutina\.titulo\)/.test(fuente)) {
      throw new Error(`systems/${archivo} no marca con conMarcasDeRutina(…, rutina.titulo): su rutina no deja marca`);
    }
  }
  // Y las rutinas amateur de verdad corren con la fracción encendida sin romper nada y sin marcas falsas (ningún reparto
  // mueve un stat de curva).
  const { amateur } = estadosDeCarreraK3A();
  const sistemaAmateur = sistemaPorId('amateur');
  let corridas = 0;
  conBalanceK3A([['atributos', 'fraccionPermanentePractica', FRACCION]], () => {
    amateur.slice(0, 4).forEach((st, i) => {
      // K6a-A, regla 17: la semana ya no frena siempre (la resuelve el perfil y frena con un riesgo evitable): el menú se
      // arma donde frena (`menuQueFrenaH10`). Reemplaza a "aplicar del amateur sobre el estado de la carrera", que daba la
      // parada siempre (y con ella las rutinas a correr).
      const decision = menuQueFrenaH10(st);
      if (decision?.datos?.motivo !== 'reparto') return;
      for (const rutina of decision.datos.rutinas) {
        const r = sistemaAmateur.resolver(st, decision, { opcionId: rutina.id }, mulberry32(9950 + i)).state;
        const esperado = conMarcasDeRutinaK3B(r, st.player.stats, rutina.titulo);
        if (JSON.stringify(r.career.registro.marcas) !== JSON.stringify(esperado.career.registro.marcas)) {
          throw new Error(`"${rutina.titulo}": las marcas de la rutina amateur no son las de la ganancia real`);
        }
        corridas += 1;
      }
    });
  });
  if (corridas === 0) throw new Error('check vacío: ninguna rutina amateur corrió');
  // El aplicador de stats del minijuego (K3-B): un stat de curva deja bonus y marca con el nombre del minijuego y el
  // delta real tras el clamp; uno que no es de curva (mentalidad) y un campo de `career.` no dejan nada.
  const desde = { ...base, player: { ...base.player, stats: { ...base.player.stats, mecanica: BALANCE.stats.max - 1, mentalidad: 40 } }, career: { ...base.career, sinergia: 50 } };
  const aplicado = conFraccionPermanenteK3b(FRACCION, () => aplicarStatsDeMinijuegoK3B(desde, ['player.stats.mecanica', 'player.stats.mentalidad', 'career.sinergia'], 10, 'Bootcamp relámpago'));
  const marcas = aplicado.career.registro.marcas.slice(desde.career.registro.marcas.length);
  if (marcas.length !== 1 || marcas[0].stat !== 'mecanica' || Math.abs(marcas[0].delta - FRACCION * 1) > 1e-9 || marcas[0].origen !== 'Bootcamp relámpago') {
    throw new Error(`el aplicador de stats del minijuego esperaba UNA marca { mecanica, ${FRACCION}, 'Bootcamp relámpago' } con el delta real tras el clamp: ${JSON.stringify(marcas)}`);
  }
  if (aplicado.player.stats.mentalidad !== 50 || aplicado.career.sinergia !== 60) throw new Error('el aplicador del minijuego dejó de aplicar el delta a los stats que no son de curva');
});


check('K3-B la curva de edad converge a objetivo + bonus: con bonusPermanente b, cada stat de curva termina el split velocidad·b más arriba que sin él', () => {
  const base = correrCarrera(4, 18);
  const lugar = { ...base, player: { ...base.player, techoLesionMecanica: null, bonusPermanente: {}, stats: { ...base.player.stats, mecanica: 50, laneo: 50, teamfight: 50 } } };
  const b = 5;
  const conBonus = { ...lugar, player: { ...lugar.player, bonusPermanente: Object.fromEntries(STATS_DE_CURVA_K3B.map((stat) => [stat, b])) } };
  const sin = sistemaPorId('atributos').aplicar(lugar, mulberry32(9)).state;
  const con = sistemaPorId('atributos').aplicar(conBonus, mulberry32(9)).state;
  for (const [stat, config] of Object.entries(BALANCE.atributos.curvas)) {
    const diferencia = con.player.stats[stat] - sin.player.stats[stat];
    if (Math.abs(diferencia - config.velocidad * b) > 1e-9) {
      throw new Error(`${stat}: con bonus ${b} la diferencia es ${diferencia}, esperaba velocidad ${config.velocidad} × ${b} = ${config.velocidad * b}`);
    }
  }
  // Y el bonus no toca lo que no es de curva (macro/shotcalling/adaptabilidad siguen su propia regla).
  for (const stat of Object.keys(BALANCE.atributos.acumulativos)) {
    if (con.player.stats[stat] !== sin.player.stats[stat]) {
      throw new Error(`${stat} no es de curva y el bonus lo movió`);
    }
  }
});

check('K3-B registro.marcas solo crece a lo largo de una carrera (cada split conserva las anteriores tal cual), con marcas reales, y el bonus de cada stat es la suma de sus marcas', () => {
  conFraccionPermanenteK3b(FRACCION_K3B, () => {
    const idsDeEvento = new Set(TODOS_LOS_EVENTOS.map((evento) => evento.id));
    let marcasTotales = 0;
    for (const seed of [1, 2, 3, 4, 5]) {
      const rng = mulberry32(seed);
      let state = createInitialState(seed, rng);
      let previas = [];
      for (let split = 0; split < 60 && !state.terminado; split += 1) {
        state = avanzarSplitAuto(state, rng).state;
        const marcas = state.career.registro.marcas;
        if (marcas.length < previas.length || previas.some((marca, i) => JSON.stringify(marca) !== JSON.stringify(marcas[i]))) {
          throw new Error(`seed ${seed}, split ${split + 1}: registro.marcas no solo crece (${previas.length} → ${marcas.length}, o cambió una anterior)`);
        }
        previas = marcas;
      }
      for (const marca of previas) {
        const crudo = idsDeEvento.has(marca.origen) || /^[a-z0-9]+(_[a-z0-9]+)+$/.test(marca.origen);
        if (!STATS_DE_CURVA_K3B.includes(marca.stat) || !Number.isFinite(marca.delta) || marca.delta === 0
            || typeof marca.origen !== 'string' || marca.origen.length === 0 || crudo || !Number.isInteger(marca.anio)) {
          throw new Error(`seed ${seed}: marca inválida (o con id crudo como origen): ${JSON.stringify(marca)}`);
        }
      }
      for (const stat of STATS_DE_CURVA_K3B) {
        const suma = previas.filter((marca) => marca.stat === stat).reduce((total, marca) => total + marca.delta, 0);
        if (Math.abs(state.player.bonusPermanente[stat] - suma) > 1e-6) {
          throw new Error(`seed ${seed}: el bonus de ${stat} (${state.player.bonusPermanente[stat]}) no es la suma de sus marcas (${suma})`);
        }
      }
      marcasTotales += previas.length;
    }
    if (marcasTotales === 0) {
      throw new Error('ninguna carrera dejó una marca con la fracción positiva: el check no probaría nada');
    }
  });
});

check('K3-B la ficha lista solo las marcas cuyo acumulado (por stat, origen y año) redondea a >= 1 en valor absoluto, con ▲/▼, sin ids crudos, y nada cuando no hay', () => {
  const marcas = [
    { stat: 'mecanica', delta: 0.3, origen: 'Bootcamp en Corea', anio: 2028 },
    { stat: 'mecanica', delta: 0.3, origen: 'Bootcamp en Corea', anio: 2028 },
    { stat: 'laneo', delta: 0.4, origen: 'Scrims con el equipo grande', anio: 2029 },
    { stat: 'teamfight', delta: -1.8, origen: 'Lesión de muñeca', anio: 2030 },
    { stat: 'teamfight', delta: -0.9, origen: 'Lesión de muñeca', anio: 2030 },
    { stat: 'mecanica', delta: 4.2, origen: 'Mudanza al gaming house', anio: 2031 }
  ];
  const lista = loQueConstruiste({ marcas });
  const textos = lista.map((fila) => fila.texto);
  const esperado = [
    '▲ +4 mecánica — Mudanza al gaming house 2031',
    '▼ -3 teamfight — Lesión de muñeca 2030',
    '▲ +1 mecánica — Bootcamp en Corea 2028'
  ];
  if (JSON.stringify(textos) !== JSON.stringify(esperado)) {
    throw new Error(`la ficha lista ${JSON.stringify(textos)}, esperaba ${JSON.stringify(esperado)} (el laneo de 0,4 no redondea a 1 y no va)`);
  }
  for (const texto of textos) {
    if (/player\.|[a-z0-9]+_[a-z0-9_]+/.test(texto)) {
      throw new Error(`"${texto}" muestra un id crudo`);
    }
  }
  if (loQueConstruiste({ marcas: [] }).length !== 0 || loQueConstruiste({}).length !== 0) {
    throw new Error('sin marcas la lista no está vacía');
  }
  if (fichaCompleta(createInitialState(1, mulberry32(1))).construido.length !== 0) {
    throw new Error('el estado inicial trae marcas en la ficha');
  }
  const conMarcas = correrCarrera(2, 20);
  const inyectado = { ...conMarcas, career: { ...conMarcas.career, registro: { ...conMarcas.career.registro, marcas } } };
  // K5c paso 3b-2 (regla 17): `construido` suma, después de las marcas, la fila de lo que te sacaron los años
  // (`loQueTeSacaronLosAnios`, con `desgaste: true`). Con Final2 la seed 2 ya trae desgaste a los 20 splits y el largo dejó de
  // ser el de las marcas: se comparan las filas de las marcas, una por una y en orden, sin la del desgaste.
  const filasDeMarcas = fichaCompleta(inyectado).construido.filter((fila) => !fila.desgaste).map((fila) => fila.texto);
  if (JSON.stringify(filasDeMarcas) !== JSON.stringify(esperado)) {
    throw new Error(`fichaCompleta no expone lo que construiste: ${JSON.stringify(filasDeMarcas)}`);
  }
  const fuenteFicha = fs.readFileSync(path.join(srcDir, 'ui', 'components', 'ficha.js'), 'utf8');
  if (!fuenteFicha.includes("nombre: 'CONSISTENCIA'") || /nombre: 'MENTALIDAD'/.test(fuenteFicha)) {
    throw new Error("la barra de la mentalidad tiene que rotularse 'CONSISTENCIA' en la ficha (el id interno sigue siendo mentalidad)");
  }
});

// ============================================================================
// K4-A (PLAN.md "K4 — decisiones de spec", K4-A): el partido que importa. Se marca la fecha que DECIDE algo (la
// clasificación, tu archirrival, el clásico, la revancha), una por split, sin draft y con la previa a la vista.
// `puntero` y `presion` dejaron de marcar. Bloque B: el corrimiento del stream está aceptado (la huella cambia); estos
// checks son estructurales.
// ============================================================================

const MOTIVOS_K4A = ['define_clasificacion', 'archirrival', 'clasico', 'revancha'];

// Una liga sintética de 10 equipos con el formato de tier 1 (6 clasifican, 2 con bye) y UNA fecha por jugar: la última,
// contra R9. Las victorias de cada org son las de la tabla de hoy; los demás cruces de la jornada son parejos (p = 0,5).
function temporadaSinteticaK4A(victorias, { fechasQueFaltan = 1, orgPropia = 'Propio' } = {}) {
  const otros = ['R1', 'R2', 'R3', 'R4', 'R5', 'R6', 'R7', 'R8', 'R9'];
  const fila = (org, ganados) => ({ org, ganados, perdidos: 0 });
  const cruce = (local, visitante) => ({ local, visitante, fuerzaLocal: 50, fuerzaVisitante: 50 });
  return {
    calendario: Array.from({ length: fechasQueFaltan }, () => ({ rival: 'R9', fuerzaRival: 50 })),
    cruces: Array.from({ length: fechasQueFaltan }, () => [cruce('R1', 'R2'), cruce('R3', 'R4'), cruce('R5', 'R6'), cruce('R7', 'R8')]),
    registrosOtros: Object.fromEntries(otros.map((org, i) => [org, fila(org, victorias[i + 1])])),
    filaPropia: fila(orgPropia, victorias[0]),
    indice: 0,
    fuerzaPropia: 50
  };
}
const LIGA_K4A = { tier: 1, formatoPlayoffs: { clasifican: 6, byes: 2, bo: 5 } };
// [Propio, R1..R9]: Propio pelea el sexto puesto (8 victorias, R6 tiene 8,5 esperadas y R9 —su rival— 7).
const TABLA_QUE_DEFINE_K4A = [8, 12, 12, 12, 12, 12, 8, 5, 5, 7];
// Propio con 15 victorias: ganar o perder lo deja primero con bye.
const TABLA_QUE_NO_DEFINE_K4A = [15, 12, 12, 12, 12, 12, 8, 5, 5, 7];
// Propio lejos del corte, abajo: ganar o perder lo deja afuera.
const TABLA_QUE_NO_DEFINE_ABAJO_K4A = [0, 12, 12, 12, 12, 12, 8, 5, 5, 7];
// Propio con 12 victorias empatado con R1 y R2: ganar lo deja primero (bye a semis), perder tercero (cuartos).
const TABLA_DEL_BYE_K4A = [12, 12, 12, 10, 10, 10, 9, 5, 5, 6];

check('K4-A define_clasificacion: sale de la tabla y del fixture que falta (sin rng), tanto la entrada a playoffs como el bye', () => {
  // K6a-M: en el split que cierra la temporada, el único que siembra los playoffs.
  const estado = { player: { splitCount: BALANCE.edad.splitsPorEdad - 1 } };
  const t = temporadaSinteticaK4A(TABLA_QUE_DEFINE_K4A);
  const definicion = defineClasificacion(estado, LIGA_K4A, t);
  if (definicion?.siGana !== 'cuartos' || definicion?.siPierde !== null) {
    throw new Error(`con 8 victorias frente a un sexto de 8,5 esperadas, ganar es entrar por cuartos y perder es quedar afuera; devolvió ${JSON.stringify(definicion)}`);
  }
  const bye = defineClasificacion(estado, LIGA_K4A, temporadaSinteticaK4A(TABLA_DEL_BYE_K4A));
  if (bye?.siGana !== 'semis' || bye?.siPierde !== 'cuartos') {
    throw new Error(`ganar la fecha que da el bye es 'semis' y perderla 'cuartos'; devolvió ${JSON.stringify(bye)}`);
  }
  for (const [nombre, tabla] of [['arriba', TABLA_QUE_NO_DEFINE_K4A], ['abajo', TABLA_QUE_NO_DEFINE_ABAJO_K4A]]) {
    const sinDefinir = defineClasificacion(estado, LIGA_K4A, temporadaSinteticaK4A(tabla));
    if (sinDefinir !== null) {
      throw new Error(`con la tabla de ${nombre} la fecha no decide nada, pero devolvió ${JSON.stringify(sinDefinir)}`);
    }
  }
  // Una liga sin playoffs no tiene clasificación que definir.
  if (defineClasificacion(estado, { tier: 2 }, t) !== null) {
    throw new Error('una liga sin formatoPlayoffs no puede definir la clasificación');
  }
  // Lejos del final (falta más que la ventana) la proyección es una cuenta abierta: no se afirma.
  const lejos = temporadaSinteticaK4A(TABLA_QUE_DEFINE_K4A, { fechasQueFaltan: 60 });
  if (defineClasificacion(estado, LIGA_K4A, lejos) !== null) {
    throw new Error('fuera de la ventana de las últimas fechas no se marca el partido que define la clasificación');
  }
  // Pura y determinista: dos llamadas dan lo mismo y no tocan lo que reciben.
  const copia = JSON.stringify(t);
  if (JSON.stringify(defineClasificacion(estado, LIGA_K4A, t)) !== JSON.stringify(definicion) || JSON.stringify(t) !== copia) {
    throw new Error('defineClasificacion no es pura');
  }
});

check('K4-A prioridad: define_clasificacion > archirrival > clásico > revancha, y puntero, presión y rival de generación no marcan', () => {
  // K6a-M: en el split de cierre, el único donde una fecha puede definir la clasificación.
  const estado = (extra = {}) => ({
    player: { splitCount: BALANCE.edad.splitsPorEdad - 1 },
    career: { orgs: ['Propio'], currentOrg: 'Propio', ultimoEliminadoPor: null, ...extra.career },
    mundo: { rivales: [], archirrival: extra.archirrival ?? null }
  });
  const fecha = { rival: 'R9', fuerzaRival: 50 };
  const motivosDe = (st, tabla) => motivosDeFecha(st, LIGA_K4A, fecha, temporadaSinteticaK4A(tabla));
  const esperar = (nombre, obtenido, esperado) => {
    if (JSON.stringify(obtenido) !== JSON.stringify(esperado)) {
      throw new Error(`${nombre}: se esperaba ${JSON.stringify(esperado)}, devolvió ${JSON.stringify(obtenido)}`);
    }
  };
  const todo = estado({ archirrival: { org: 'R9', handle: 'Rival' }, career: { orgs: ['R9', 'Propio'], ultimoEliminadoPor: 'R9' } });
  esperar('con todo junto', motivoPrincipal(motivosDe(todo, TABLA_QUE_DEFINE_K4A)), 'define_clasificacion');
  esperar('sin definir la clasificación', motivoPrincipal(motivosDe(todo, TABLA_QUE_NO_DEFINE_K4A)), 'archirrival');
  esperar('clásico y revancha', motivoPrincipal(motivosDe(estado({ career: { orgs: ['R9', 'Propio'], ultimoEliminadoPor: 'R9' } }), TABLA_QUE_NO_DEFINE_K4A)), 'clasico');
  esperar('solo revancha', motivoPrincipal(motivosDe(estado({ career: { ultimoEliminadoPor: 'R9' } }), TABLA_QUE_NO_DEFINE_K4A)), 'revancha');
  // El rival es el puntero de la tabla (20 victorias): antes marcaba, ahora la fecha pasa resumida.
  esperar('contra el puntero', motivosDe(estado(), [15, 12, 12, 12, 12, 12, 8, 5, 5, 20]), ['parejo']);
  esperar('sin nada en juego', motivosDe(estado(), TABLA_QUE_NO_DEFINE_K4A), ['parejo']);
  esperar('la prioridad es la de la spec', PRIORIDAD_MOTIVOS, MOTIVOS_K4A);
});

// Carreras reales de `criterio` (seeds 1..100, 60 splits): por split, las fechas marcadas y por qué, las pausas de la
// temporada y si fue un split de tier 1 con playoffs.
const CARRERAS_K4A = 100;
// La meta de "define_clasificacion es alcanzable" (1 de cada 3 splits de cierre de tier 1) y su banda de ruido de muestra.
const META_DEFINE_K4A = 1 / 3;
const SIGMAS_RUIDO_DEFINE_K4A = 2;
let cosechaK4A = null;
function cosechaDeCarrerasK4A() {
  if (cosechaK4A) {
    return cosechaK4A;
  }
  const c = { splitsTier1: 0, splitsConDefine: 0, marcadasPorSplit: {}, motivosVistos: new Set(), principales: {}, pausas: {}, casos: [] };
  for (let seed = 1; seed <= CARRERAS_K4A; seed += 1) {
    const rng = mulberry32(seed);
    let state = createInitialState(seed, rng);
    for (let i = 0; i < 60 && !state.terminado; i += 1) {
      const antes = state.career.temporada;
      const splitAntes = state.player.splitCount;
      const principalesDelSplit = [];
      const responder = (sistema, st, decision, r) => {
        if (sistema.id === 'temporada') {
          const tipo = decision.datos?.motivo ?? 'x';
          c.pausas[tipo] = (c.pausas[tipo] ?? 0) + 1;
          const motivos = st.career.temporada.fechaEnCurso?.motivos ?? [];
          motivos.forEach((m) => c.motivosVistos.add(m));
          if (tipo === 'momento') {
            principalesDelSplit.push(motivoPrincipal(motivos));
            if (c.casos.length < 60) {
              c.casos.push({ st, decision });
            }
          }
        }
        return ESTRATEGIAS_K0.criterio(sistema, st, decision, r);
      };
      state = avanzarSplitAuto(state, rng, responder).state;
      const t = state.career.temporada;
      if (t === antes || !t) {
        continue;
      }
      c.marcadasPorSplit[t.marcadasHechas] = (c.marcadasPorSplit[t.marcadasHechas] ?? 0) + 1;
      principalesDelSplit.forEach((m) => { c.principales[m] = (c.principales[m] ?? 0) + 1; });
      const liga = ligaDeCarreraK3A(state);
      // K6a-M: solo el split de cierre, el único donde una fecha puede definir la clasificación.
      if (liga?.tier === 1 && liga.formatoPlayoffs && esCierreK6aM(splitAntes)) {
        c.splitsTier1 += 1;
        if (principalesDelSplit.includes('define_clasificacion')) {
          c.splitsConDefine += 1;
        }
      }
    }
  }
  cosechaK4A = c;
  return c;
}

// K6a-M reemplaza a "al menos 1 de cada 3 splits de tier 1 con playoffs" (con 300 splits de muestra): esa vara contaba los dos
// splits que no siembran, donde "si ganás, entrás a playoffs" era mentira. Ahora la misma meta, sobre los splits de cierre.
check(`K4-A define_clasificacion es alcanzable: al menos 1 de cada 3 splits de cierre de tier 1 (criterio, ${CARRERAS_K4A} carreras)`, () => {
  const { splitsTier1, splitsConDefine } = cosechaDeCarrerasK4A();
  if (splitsTier1 < 100) {
    throw new Error(`solo ${splitsTier1} splits de tier 1 con playoffs medidos: muestra insuficiente`);
  }
  // K5c paso 3b-2 (regla 17): la meta se lee con el ruido de la muestra (binomial, `SIGMAS_RUIDO_DEFINE_K4A` sigmas). Sin banda, la
  // vara caía con cualquier corrimiento: con las cartas de cierre del declive (K4c textos) pasó de 214/623 (34,3%) a 208/626 (33,2%),
  // una diferencia de medio sigma (≈ 1,9 puntos con n ≈ 625). El piso queda en ≈ 29,6%.
  const ruido = SIGMAS_RUIDO_DEFINE_K4A * Math.sqrt(META_DEFINE_K4A * (1 - META_DEFINE_K4A) / splitsTier1);
  if (splitsConDefine / splitsTier1 < META_DEFINE_K4A - ruido) {
    throw new Error(`define_clasificacion marcó ${splitsConDefine} de ${splitsTier1} splits de tier 1 con playoffs (1 cada ${(splitsTier1 / Math.max(1, splitsConDefine)).toFixed(1)}); la meta es 1 cada 3 o mejor, con ${SIGMAS_RUIDO_DEFINE_K4A} sigmas de ruido de muestra (piso ${(100 * (META_DEFINE_K4A - ruido)).toFixed(1)}%)`);
  }
});

check('K4-A a lo sumo una fecha marcada por split', () => {
  const { marcadasPorSplit } = cosechaDeCarrerasK4A();
  const conMasDeUna = Object.entries(marcadasPorSplit).filter(([n]) => Number(n) > 1).reduce((suma, [, cantidad]) => suma + cantidad, 0);
  if (conMasDeUna > 0) {
    throw new Error(`${conMasDeUna} splits con más de una fecha marcada (conteos: ${JSON.stringify(marcadasPorSplit)})`);
  }
  if ((marcadasPorSplit[1] ?? 0) < 100) {
    throw new Error(`solo ${marcadasPorSplit[1] ?? 0} splits con una fecha marcada: muestra insuficiente`);
  }
});

check('K4-A puntero y presión nunca marcan: toda fecha marcada lo es por uno de los cuatro motivos', () => {
  const { motivosVistos, principales } = cosechaDeCarrerasK4A();
  const fuera = [...motivosVistos].filter((m) => !MOTIVOS_K4A.includes(m));
  if (fuera.length > 0) {
    throw new Error(`fechas marcadas con motivos fuera de los cuatro: ${fuera.join(', ')}`);
  }
  const marcadas = Object.values(principales).reduce((suma, n) => suma + n, 0);
  if (marcadas < 200 || !principales.define_clasificacion || !principales.clasico || !principales.revancha) {
    throw new Error(`la muestra no pasó por los motivos que se pueden alcanzar: ${JSON.stringify(principales)}`);
  }
});

check('K4-A la fecha marcada no tiene draft: frena una sola vez, con el momento', () => {
  const { pausas, marcadasPorSplit } = cosechaDeCarrerasK4A();
  if (pausas.draft) {
    throw new Error(`${pausas.draft} pausas de draft en una fecha marcada (temporada:draft debería haber desaparecido)`);
  }
  const marcadas = marcadasPorSplit[1] ?? 0;
  if ((pausas.momento ?? 0) > marcadas) {
    throw new Error(`${pausas.momento} momentos para ${marcadas} fechas marcadas: la fecha frena más de una vez`);
  }
  const otras = Object.keys(pausas).filter((m) => m !== 'momento');
  if (otras.length > 0) {
    throw new Error(`la temporada pausó con ${otras.join(', ')}: solo debería frenar con el momento`);
  }
});

check('K4-A la previa de la fecha marcada dice por qué importa, sin ids crudos, y el "porQue" es el del motivo', () => {
  const { casos } = cosechaDeCarrerasK4A();
  if (casos.length < 30) {
    throw new Error(`solo ${casos.length} fechas marcadas cosechadas`);
  }
  const problemas = [];
  casos.forEach(({ st, decision }, i) => {
    const previa = previaDeDecision(st, decision);
    const texto = previa?.porQue;
    if (typeof texto !== 'string' || texto.length < 10) {
      problemas.push(`fecha ${i}: la previa no trae el porqué (${JSON.stringify(texto)})`);
      return;
    }
    if (/[a-z0-9]+_[a-z0-9_]+|undefined|null|NaN/.test(texto)) {
      problemas.push(`fecha ${i}: "${texto}" muestra un id crudo`);
    }
    const principal = motivoPrincipal(st.career.temporada.fechaEnCurso.motivos);
    const esperado = { define_clasificacion: /ganás|playoffs/, archirrival: /archirrival/, clasico: /ex equipo/, revancha: /revancha/ }[principal];
    if (!esperado.test(texto)) {
      problemas.push(`fecha ${i}: "${texto}" no habla del motivo ${principal}`);
    }
    if (!previa.subtitulo) {
      problemas.push(`fecha ${i}: la previa no trae el rótulo del partido`);
    }
  });
  fallarSiK2d(problemas);
});

// ---------------------------------------------------------------------------------------------------------------------
// K4c (plan anual, decisión del usuario 2026-10-03) — la práctica se decide en el cierre de año. Cada opción del cierre
// fija el plan del año que viene (`player.planAnual`: el juego, la cabeza o la marca, de `data/rutinas/planes.json`) y
// cada split pro entrena solo con su tramo del plan (`tramoDelPlan`); la pretemporada queda para el mercado.
// Regla 17: este bloque reemplaza a los cinco checks de K4-D —"la pretemporada frena una sola vez por año: a lo sumo
// una pausa de mercado o de práctica por split, con el mercado y la preparación en la misma, y la preparación del año
// queda resuelta", que exigía la preparación del receso adentro de la parada del mercado o en una parada propia de
// práctica; "la oferta elegida y la rutina elegida se aplican juntas, en una sola respuesta"; "los bots contestan la
// parada unificada con la regla de siempre (oferta + rutina)"; "regla 15: lo que muestra la carta de la rutina es lo
// que aplica el motor", que medía las rutinas de offseason; y "las cartas de la preparación hablan en cristiano", que
// leía components/mercado.js—. La preparación ya no se elige en la pretemporada: sale del plan.
// ---------------------------------------------------------------------------------------------------------------------
const { tramoDelPlan, lineaDePlan, entrenar: entrenarK4cP } = await import('../systems/practica.js');
const { IDS_PLAN: IDS_PLAN_K4cP, planPorId: planPorIdK4cP, planInicial: planInicialK4cP, textoDePlanInicial: textoDePlanInicialK4cP } =
  await import('../core/rutinas.js');

// Los tramos de cada plan, escritos a mano desde el dato (6 puntos al año, 3 splits, de a uno por destino en ronda: el
// de más puntos primero, en empate el orden pulir, nuevo, mecánica, macro, descansar). [posición 0, 1, 2].
const TRAMOS_A_MANO_K4cP = {
  juego: [{ mecanica: 1, macro: 1 }, { pulir: 1, nuevo: 1 }, { mecanica: 1, macro: 1 }],
  cabeza: [{ descansar: 1, pulir: 1 }, { macro: 1, descansar: 1 }, { descansar: 2 }],
  marca: [{ pulir: 1, nuevo: 1 }, { mecanica: 1, descansar: 1 }, { pulir: 2 }]
};
const DESTINOS_K4cP = ['pulir', 'nuevo', 'mecanica', 'macro', 'descansar'];
const completoK4cP = (parcial) => Object.fromEntries(DESTINOS_K4cP.map((destino) => [destino, parcial[destino] ?? 0]));

// Carreras de `criterio`, paso por paso (una vez para los tres checks de abajo): cada avance y cada decisión resuelta
// (`pasos`), y cada split cerrado con sus logs (`splits`).
let corridasK4cPCache = null;
function corridasK4cP() {
  if (corridasK4cPCache) return corridasK4cPCache;
  const pasos = [];
  const splits = [];
  for (let seed = 1; seed <= 10; seed += 1) {
    const rng = mulberry32(seed);
    let state = createInitialState(seed, rng);
    for (let i = 0; i < 60 && !state.terminado; i += 1) {
      const inicio = state;
      state = avanzarSplit(state, rng).state;
      pasos.push({ seed, split: i, antes: inicio, despues: state, sistemaId: null });
      while (state.pendiente) {
        const { sistemaId, decision } = state.pendiente;
        const respuesta = ESTRATEGIAS_K0.criterio(sistemaPorId(sistemaId), state, decision, rng);
        const antes = state;
        state = resolverDecision(state, respuesta, rng).state;
        pasos.push({ seed, split: i, antes, despues: state, sistemaId, decision, respuesta });
      }
      splits.push({ seed, split: i, inicio, fin: state, logs: state.logs.slice(inicio.logs.length) });
    }
  }
  corridasK4cPCache = { pasos, splits };
  return corridasK4cPCache;
}

check('K4c-P (a) la pretemporada frena solo por el mercado: ningún split tiene una parada de práctica y ninguna decisión trae la preparación del receso', () => {
  const { pasos, splits } = corridasK4cP();
  let paradasDeMercado = 0;
  for (const paso of pasos.filter((p) => p.sistemaId !== null)) {
    if (paso.sistemaId === 'practica' || paso.decision.datos?.motivo === 'practica') {
      throw new Error(`seed ${paso.seed}, split ${paso.split}: la práctica frenó (practica:practica)`);
    }
    if (paso.decision.datos?.preparacion || paso.respuesta?.rutinaId !== undefined) {
      throw new Error(`seed ${paso.seed}, split ${paso.split}: la parada de ${paso.sistemaId} trae la preparación del receso`);
    }
    if (paso.sistemaId === 'mercado') paradasDeMercado += 1;
  }
  const pretemporadasPro = splits.filter((s) => s.inicio.phase === 'profesional' && calcularContexto(s.inicio).ventana === 'pretemporada').length;
  if (pretemporadasPro < 40 || paradasDeMercado < 10) {
    throw new Error(`muestra corta: ${pretemporadasPro} pretemporadas pro, ${paradasDeMercado} paradas de mercado`);
  }
});

check('K4c-P (b) cada split pro entrena según el plan del año vigente: una línea por split con el plan y el tramo del dato (recuento a mano)', () => {
  // El tramo de cada plan y posición es el escrito a mano, y los tres tramos de un año suman el reparto del plan.
  for (const planId of IDS_PLAN_K4cP) {
    const plan = planPorIdK4cP(planId);
    const suma = completoK4cP({});
    for (let posicion = 0; posicion < BALANCE.edad.splitsPorEdad; posicion += 1) {
      const tramo = tramoDelPlan(plan, posicion);
      const esperado = completoK4cP(TRAMOS_A_MANO_K4cP[planId][posicion]);
      if (JSON.stringify(tramo) !== JSON.stringify(esperado)) {
        throw new Error(`${planId}, posición ${posicion}: el tramo es ${JSON.stringify(tramo)}, a mano ${JSON.stringify(esperado)}`);
      }
      for (const destino of DESTINOS_K4cP) suma[destino] += tramo[destino];
    }
    if (JSON.stringify(suma) !== JSON.stringify(completoK4cP(plan.reparto))) {
      throw new Error(`${planId}: los tramos del año suman ${JSON.stringify(suma)}, el plan es ${JSON.stringify(plan.reparto)}`);
    }
  }
  // En las carreras: el plan del log es el vigente al empezar el split (el cierre, que lo cambia, corre después de la
  // práctica), y la línea nombra lo que el tramo movió.
  const MARCA_DE_DESTINO = { pulir: 'maestría', mecanica: 'mecánica +', macro: 'macro +', descansar: 'consistencia +' };
  let contados = 0;
  const planesVistos = new Set();
  for (const s of corridasK4cP().splits) {
    const lineas = s.logs.filter((log) => log.type === 'practica');
    if (s.inicio.phase !== 'profesional' || s.fin.phase !== 'profesional') {
      // Un amateur no entrena con el plan (el fichaje lo hace pro después de la práctica); la vuelta de un retiro sí.
      if (s.inicio.phase === 'amateur' && lineas.length > 0) throw new Error(`seed ${s.seed}, split ${s.split}: entrenó siendo amateur`);
      continue;
    }
    const planId = s.inicio.player.planAnual;
    const plan = planPorIdK4cP(planId);
    if (lineas.length !== 1 || !lineas[0].message.startsWith(`Entrenaste según el plan del año: ${plan.titulo} (`) || !lineas[0].adjunto) {
      throw new Error(`seed ${s.seed}, split ${s.split}: esperaba UNA línea adjunta del plan "${plan.titulo}": ${JSON.stringify(lineas.map((l) => l.message))}`);
    }
    const tramo = TRAMOS_A_MANO_K4cP[planId][s.inicio.player.splitCount % BALANCE.edad.splitsPorEdad];
    for (const [destino, marca] of Object.entries(MARCA_DE_DESTINO)) {
      if ((tramo[destino] ?? 0) > 0 !== lineas[0].message.includes(marca)) {
        throw new Error(`seed ${s.seed}, split ${s.split} (${planId}): el tramo ${JSON.stringify(tramo)} y la línea "${lineas[0].message}" no coinciden en ${destino}`);
      }
    }
    contados += 1;
    planesVistos.add(planId);
  }
  if (contados < 150 || planesVistos.size < 2) {
    throw new Error(`muestra corta: ${contados} splits pro, planes vistos ${[...planesVistos].join(', ')}`);
  }
});

check('K4c-P (c) el plan del año cambia solo en el cierre: cada cierre fija el plan de la opción elegida y ningún otro paso lo toca', () => {
  let cierres = 0;
  let cambios = 0;
  for (const paso of corridasK4cP().pasos) {
    const antes = paso.antes.player.planAnual;
    const despues = paso.despues.player.planAnual;
    if (paso.sistemaId === 'edadCierre') {
      cierres += 1;
      // K4c (revisión): el cierre amateur no fija plan (ver el check (d)): el plan sigue el que estaba.
      const plan = paso.antes.phase === 'amateur'
        ? antes
        : paso.decision.datos.evento.options.find((opcion) => opcion.id === paso.respuesta.opcionId)?.plan;
      if (despues !== plan) throw new Error(`seed ${paso.seed}, split ${paso.split}: el cierre eligió "${paso.respuesta.opcionId}" (plan ${plan}) y el plan quedó en ${despues}`);
      if (despues !== antes) cambios += 1;
    } else if (despues !== antes) {
      // K6b-C2: un cierre de la cola que no frenó lo resuelve tu perfil adentro de este paso, y deja su línea (`cola: 'cierre'`)
      // con la opción que tomó: el plan tiene que ser el de esa opción.
      const narrado = paso.despues.logs.slice(paso.antes.logs.length).find((log) => log.cola === 'cierre');
      const evento = narrado && TODOS_LOS_EVENTOS.find((e) => e.cierreDeEdad && e.title === narrado.titulo);
      const plan = evento?.options.find((opcion) => opcion.id === narrado.opcionId)?.plan;
      if (!narrado || despues !== plan) {
        throw new Error(`seed ${paso.seed}, split ${paso.split}: el plan cambió de ${antes} a ${despues} fuera del cierre (${paso.sistemaId ?? 'el avance del split'})`);
      }
      cierres += 1;
      cambios += 1;
    }
  }
  if (cierres < 50 || cambios < 10) throw new Error(`muestra corta: ${cierres} cierres, ${cambios} cambios de plan`);
});

// K4c (revisión), regla 17 — reemplaza a "toda opción de cierre trae un plan válido, cada cierre ofrece al menos dos y los de la
// etapa pro los tres", que exigía el plan también en los cierres amateur: ese plan no se aplicaba nunca (`practica.js` no entrena
// fuera de `profesional`; con `criterio`, seeds 1-150, 520 cierres amateur con plan y el 79% sin un split pro el año siguiente).
// Protege, desde la revisión de K4c, que el cierre amateur no fije ni muestre plan y que al debutar valga el del perfil.
check('K4c-P (d) el dato y el arranque: los cierres pro traen un plan válido en cada opción y los tres planes; los amateur, ninguno (ni lo muestran ni lo fijan); el primer plan sale del perfil (T4), el inicio lo dice y vale hasta el primer cierre pro', () => {
  const eventos = TODOS_LOS_EVENTOS.filter((evento) => evento.cierreDeEdad);
  if (eventos.length === 0) throw new Error('no hay eventos de cierre');
  let amateurDelDato = 0;
  for (const evento of eventos) {
    const planes = evento.options.map((opcion) => opcion.plan);
    if ((evento.contexto?.etapa ?? []).includes('amateur')) {
      if (planes.some((plan) => plan !== undefined)) throw new Error(`${evento.id}: un cierre amateur trae plan (${planes.join(', ')})`);
      amateurDelDato += 1;
      continue;
    }
    if (planes.some((plan) => !IDS_PLAN_K4cP.includes(plan))) throw new Error(`${evento.id}: una opción sin plan válido (${planes.join(', ')})`);
    const distintos = new Set(planes).size;
    if (distintos < IDS_PLAN_K4cP.length) throw new Error(`${evento.id}: ofrece ${distintos} planes distintos`);
  }
  if (amateurDelDato === 0) throw new Error('no hay cierres amateur en el dato');
  // En las carreras: un cierre con la fase amateur no muestra plan en ninguna opción ni lo cambia, y el plan del primer split pro
  // es el del arranque (el del perfil) hasta que un cierre pro fije otro.
  let amateurJugados = 0;
  const debutVisto = new Set();
  for (const paso of corridasK4cP().pasos) {
    if (paso.sistemaId === 'edadCierre' && paso.antes.phase === 'amateur') {
      amateurJugados += 1;
      const conPlan = paso.decision.opciones.filter((opcion) => opcion.plan);
      if (conPlan.length > 0 || paso.despues.player.planAnual !== paso.antes.player.planAnual) {
        throw new Error(`seed ${paso.seed}, split ${paso.split}: el cierre amateur muestra plan (${conPlan.map((o) => o.plan.texto).join(' | ')}) o lo cambia (${paso.antes.player.planAnual} → ${paso.despues.player.planAnual})`);
      }
    }
    if (paso.antes.phase === 'amateur' && paso.despues.phase === 'profesional' && !debutVisto.has(paso.seed)) {
      debutVisto.add(paso.seed);
      const inicial = createInitialState(paso.seed, mulberry32(paso.seed)).player.planAnual;
      if (paso.despues.player.planAnual !== inicial) throw new Error(`seed ${paso.seed}: debutó con el plan ${paso.despues.player.planAnual}, el del perfil es ${inicial}`);
    }
  }
  if (amateurJugados < 5 || debutVisto.size < 5) throw new Error(`muestra corta: ${amateurJugados} cierres amateur, ${debutVisto.size} debuts`);
  for (const seed of [1, 2, 3, 4, 5, 6, 7, 8]) {
    const state = createInitialState(seed, mulberry32(seed));
    if (state.player.planAnual !== planInicialK4cP(state.player.perfil.actual) || !IDS_PLAN_K4cP.includes(state.player.planAnual)) {
      throw new Error(`seed ${seed}: el plan inicial es ${state.player.planAnual}, el perfil ${state.player.perfil.actual}`);
    }
  }
  const showman = createInitialState(3, mulberry32(3), { perfil: 'showman' });
  if (showman.player.planAnual !== 'marca') throw new Error(`showman arranca con ${showman.player.planAnual}, a mano "marca"`);
  for (const perfil of ['profesional', 'hambriento', 'showman', 'leal']) {
    const texto = textoDePlanInicialK4cP(perfil);
    if (!texto.includes(planPorIdK4cP(planInicialK4cP(perfil)).titulo) || /undefined|NaN/.test(texto)) throw new Error(`inicio (${perfil}): "${texto}"`);
  }
  const inicio = fs.readFileSync(path.join(srcDir, 'ui', 'screens', 'inicio.js'), 'utf8');
  if (!inicio.includes('textoDePlanInicial')) throw new Error('la pantalla de inicio no dice el primer plan');
});

check('K4c-P regla 15: cada opción del cierre dice el plan que fija, en cristiano y con la misma cuenta del motor, y components/decision.js la pinta sin calcular nada', () => {
  let opciones = 0;
  for (const paso of corridasK4cP().pasos.filter((p) => p.sistemaId === 'edadCierre')) {
    for (const opcion of paso.decision.opciones) {
      // El cierre amateur no fija plan, y no lo dice (check (d)).
      if (paso.antes.phase === 'amateur') continue;
      const planId = paso.decision.datos.evento.options.find((o) => o.id === opcion.id)?.plan;
      const esperado = lineaDePlan(paso.antes, planId);
      if (!opcion.plan || opcion.plan.texto !== esperado.texto || opcion.plan.id !== planId) {
        throw new Error(`seed ${paso.seed}, split ${paso.split}: la opción "${opcion.label}" no dice su plan (${JSON.stringify(opcion.plan)})`);
      }
      if (!opcion.plan.texto.includes(planPorIdK4cP(planId).titulo) || /undefined|NaN|player\.|[a-z0-9]+_[a-z0-9_]+/.test(opcion.plan.texto)) {
        throw new Error(`la línea del plan muestra "${opcion.plan.texto}"`);
      }
      opciones += 1;
    }
  }
  if (opciones < 100) throw new Error(`muestra corta: ${opciones} opciones de cierre`);
  const fuente = fs.readFileSync(path.join(srcDir, 'ui', 'components', 'decision.js'), 'utf8');
  if (!fuente.includes('opcion.plan.texto') || /BALANCE|balance\.js|planes\.json/.test(fuente)) {
    throw new Error('components/decision.js tiene que pintar opcion.plan.texto tal cual, sin leer BALANCE ni el dato');
  }
});

checkLento('K4c-P regla 15: lo que la carta del plan promete (efecto y cuánto dura) es lo que aplica el motor, de una vez y sumando los tramos del año', () => {
  // Reemplaza a "K4-D regla 15: lo que muestra la carta de la rutina (efecto y cuánto dura) es lo que aplica el motor"
  // (regla 17), que medía las rutinas de offseason: ahora la carta es la del plan, y el motor la aplica de a tramos.
  const previo = BALANCE.practica.ruidoPractica;
  const planes = IDS_PLAN_K4cP.map(planPorIdK4cP);
  try {
    // Sin ruido el motor aplica la media: la carta tiene que coincidir con el resultado, al decimal.
    BALANCE.practica.ruidoPractica = 0;
    const deCurva = Object.keys(BALANCE.atributos.curvas);
    let conPermanencia = 0;
    for (const seed of [2, 5, 9]) {
      const base = correrCarrera(seed, 14);
      if (base.phase !== 'profesional') continue;
      for (const plan of planes) {
        const carta = cartaDeRutina(base, plan);
        const deUna = resolverPreparacion(base, [plan], plan.id, mulberry32(seed)).state;
        let deATramos = base;
        for (let posicion = 0; posicion < BALANCE.edad.splitsPorEdad; posicion += 1) {
          deATramos = entrenarK4cP(deATramos, tramoDelPlan(plan, posicion), plan, mulberry32(seed + posicion)).state;
        }
        for (const [como, despues] of [['de una vez', deUna], ['a tramos', deATramos]]) {
          for (const efecto of carta.efectos) {
            const movido = despues.player.stats[efecto.stat] - base.player.stats[efecto.stat];
            if (Math.abs(movido - efecto.esperado) > 1e-9) {
              throw new Error(`${plan.id} ${como} (${efecto.stat}): la carta dice +${efecto.esperado}, el motor movió ${movido}`);
            }
          }
          for (const stat of deCurva) {
            const dura = despues.player.bonusPermanente[stat] - base.player.bonusPermanente[stat];
            const prometido = carta.efectos.filter((efecto) => efecto.stat === stat).reduce((suma, efecto) => suma + efecto.permanente, 0);
            if (Math.abs(dura - prometido) > 1e-9) {
              throw new Error(`${plan.id} ${como} (${stat}): la carta promete que te queda ${prometido}, el motor dejó ${dura}`);
            }
            if (prometido > 0) conPermanencia += 1;
          }
        }
        const total = carta.efectos.reduce((suma, efecto) => suma + efecto.permanente, 0);
        if (Math.abs(carta.permanenteTotal - total) > 1e-9) throw new Error(`${plan.id}: permanenteTotal no suma lo de cada efecto`);
      }
    }
    if (conPermanencia === 0) throw new Error('sonda vacía: ninguna carta promete algo que dura');
    // Y la fracción es la de la práctica, no otra: con la fracción en memoria la carta la sigue.
    const original = BALANCE.atributos.fraccionPermanentePractica;
    try {
      BALANCE.atributos.fraccionPermanentePractica = 0.5;
      const carta = cartaDeRutina(correrCarrera(2, 14), planPorIdK4cP('juego'));
      const efecto = carta.efectos.find((e) => e.stat === 'mecanica');
      if (!efecto || Math.abs(efecto.permanente - 0.5 * efecto.esperado) > 1e-9) {
        throw new Error('la carta no sigue a fraccionPermanentePractica');
      }
    } finally {
      BALANCE.atributos.fraccionPermanentePractica = original;
    }
    // Con una lesión que dejó techo de mecánica, la carta promete lo que el techo deja y el motor mueve eso mismo. El
    // techo va 1 punto arriba de la mecánica actual: corta todo plan que sin él prometería más de 1.
    const sinTecho = correrCarrera(5, 14);
    const lesionado = { ...sinTecho, player: { ...sinTecho.player, techoLesionMecanica: sinTecho.player.stats.mecanica + 1 } };
    let cortadas = 0;
    for (const plan of planes) {
      const libre = cartaDeRutina({ ...sinTecho, player: { ...sinTecho.player, techoLesionMecanica: null } }, plan)
        .efectos.find((e) => e.stat === 'mecanica');
      const efecto = cartaDeRutina(lesionado, plan).efectos.find((e) => e.stat === 'mecanica');
      if (!efecto) continue;
      const despues = resolverPreparacion(lesionado, [plan], plan.id, mulberry32(5)).state;
      const movido = despues.player.stats.mecanica - lesionado.player.stats.mecanica;
      if (Math.abs(movido - efecto.esperado) > 1e-9) {
        throw new Error(`${plan.id} con techo de lesión: la carta dice +${efecto.esperado} de mecánica, el motor movió ${movido}`);
      }
      if (efecto.esperado > 1 + 1e-9) {
        throw new Error(`${plan.id} con techo de lesión: la carta promete +${efecto.esperado}, por encima del techo (+1)`);
      }
      if (libre && libre.esperado > 1 + 1e-9) cortadas += 1;
    }
    if (cortadas === 0) throw new Error('sonda vacía: el techo de lesión no cortó ningún plan');
  } finally {
    BALANCE.practica.ruidoPractica = previo;
  }
});

// --- K5-B: la región se elige y es la dificultad (PLAN.md "K5 — decisiones de spec", K5-B; J10; D78) ---
const { regionesDeOrigen: regionesDeOrigenK5B, ligaDeOrigenElegible: ligaDeOrigenElegibleK5B } = await import('../core/mundo.js');

// La región que la seed sortea, leída de un arranque sin elección (un rng aparte: no toca la corrida medida).
function regionSorteadaK5B(seed) {
  return createInitialState(seed, mulberry32(seed)).mundo.regionIdOrigen;
}

// Una carrera de `criterio` con la región elegida. Devuelve el estado final.
function carreraConRegionK5B(seed, regionId, splits) {
  const rng = mulberry32(seed);
  let state = createInitialState(seed, rng, { regionOrigen: regionId });
  for (let i = 0; i < splits && !state.terminado; i += 1) {
    state = avanzarSplitAuto(state, rng, ESTRATEGIAS_K0.criterio).state;
  }
  return state;
}

check('K5-B región: elegir la región que la seed habría sorteado no corre el stream (huella de 40 seeds idéntica)', () => {
  const sinEleccion = calcularHuella(40, 30);
  const conEleccion = calcularHuella(40, 30, {
    mulberry32,
    createInitialState: (seed, rng) => createInitialState(seed, rng, { regionOrigen: regionSorteadaK5B(seed) }),
    avanzarSplitAuto
  });
  if (sinEleccion.hash !== conEleccion.hash) {
    const i = sinEleccion.lineas.findIndex((linea, k) => linea !== conEleccion.lineas[k]);
    throw new Error(`la huella cambia al elegir la región sorteada: seed ${i + 1} [${sinEleccion.lineas[i]}] contra [${conEleccion.lineas[i]}]`);
  }
  // Y la elección de verdad elige: cualquier región (LATAM incluida, que el sorteo nunca da) queda como origen.
  for (const opcion of regionesDeOrigenK5B()) {
    const state = createInitialState(7, mulberry32(7), { regionOrigen: opcion.regionId });
    if (state.mundo.regionIdOrigen !== opcion.regionId) {
      throw new Error(`elegí ${opcion.regionId} y el origen quedó ${state.mundo.regionIdOrigen}`);
    }
  }
  if (ligaDeOrigenElegibleK5B(LIGAS, 'XX') !== null || ligaDeOrigenElegibleK5B(LIGAS, null) !== null) {
    throw new Error('una región desconocida o vacía tiene que dejar el sorteo');
  }
});

check('K5-B región: el desafío diario ignora la elección (la región sale de la seed del día)', () => {
  const { seed, eleccion, desafio } = iniciarDesafio('2026-10-03');
  if (eleccion !== null) {
    throw new Error(`iniciarDesafio tiene que arrancar sin elección, trae ${JSON.stringify(eleccion)}`);
  }
  const state = createInitialState(seed, mulberry32(seed), eleccion, desafio);
  if (state.mundo.regionIdOrigen !== regionSorteadaK5B(seed)) {
    throw new Error(`el desafío arrancó en ${state.mundo.regionIdOrigen}, la seed sortea ${regionSorteadaK5B(seed)}`);
  }
  let rechazo = false;
  try {
    createInitialState(seed, mulberry32(seed), { regionOrigen: 'LAS' }, desafio);
  } catch {
    rechazo = true;
  }
  if (!rechazo) {
    throw new Error('el desafío con una región elegida tiene que rechazarse');
  }
  // La pantalla: la rama del desafío arma los argumentos con iniciarDesafio; la región elegida entra solo en el `else`.
  const app = fs.readFileSync(path.join(srcDir, 'ui', 'app.js'), 'utf8');
  const ramaDesafio = app.indexOf('iniciarDesafio(fechaDesafio)');
  const lecturaRegion = app.indexOf('regionOrigen: region');
  if (ramaDesafio < 0 || lecturaRegion < ramaDesafio || !/\} else \{/.test(app.slice(ramaDesafio, lecturaRegion))) {
    throw new Error('app.js: la región elegida tiene que entrar solo en la rama que no es el desafío');
  }
});

check('K5-B región: las líneas de dificultad no muestran ids crudos y dicen lo que dice el dato', () => {
  const regiones = regionesDeOrigenK5B();
  const ids = [...new Set(LIGAS.map((liga) => liga.regionId))];
  for (const opcion of regiones) {
    for (const texto of [opcion.region, opcion.texto]) {
      if (!texto || /_/.test(texto) || ids.some((id) => new RegExp(`\\b${id}\\b`).test(texto))) {
        throw new Error(`${opcion.regionId}: "${texto}" muestra un id crudo`);
      }
    }
  }
  const tier1 = regiones.filter((opcion) => !opcion.sinPrimera);
  const porPrestigio = [...tier1].sort((a, b) => b.prestigio - a.prestigio);
  const porDificultad = [...tier1].sort((a, b) => a.dificultad - b.dificultad);
  const esperado = [
    [porPrestigio[0], 'la más difícil para llegar a primera'],
    [porPrestigio.at(-1), 'la más fácil para llegar a primera'],
    [porDificultad[0], 'la más fácil para ganar el Mundial'],
    [porDificultad.at(-1), 'la más difícil para ganar el Mundial']
  ];
  for (const [opcion, frase] of esperado) {
    if (!opcion.texto.includes(frase)) {
      throw new Error(`${opcion.region}: "${opcion.texto}" tendría que decir "${frase}"`);
    }
  }
  const latam = regiones.filter((opcion) => opcion.sinPrimera);
  if (latam.length === 0 || latam.some((opcion) => !opcion.texto.includes('emigrando'))) {
    throw new Error('LATAM tiene que estar y decir que a primera se llega emigrando');
  }
  const inicio = fs.readFileSync(path.join(srcDir, 'ui', 'screens', 'inicio.js'), 'utf8');
  if (!/textContent = opcion\.region/.test(inicio) || !/elegida\.texto/.test(inicio)) {
    throw new Error('inicio.js tiene que pintar el nombre y la línea del dato, sin armar texto con el regionId');
  }
});

// La dificultad medida: con `criterio`, % de carreras que llegan a la primera DE SU REGIÓN (sin emigrar), 40 splits por región
// elegida. Tiene que subir con la `dificultad` (Corea: la más difícil de llegar). Tolerancia del orden: se comparan los pares cuya
// dificultad difiere en más de 0,15 (KR-CN y APAC-NA quedan afuera; APAC-NA está invertido en el dato: LCP tiene menos prestigio
// que LCS y también menos dificultad) y se acepta un empate de hasta 10 puntos.
//
// K6c-fix (K5-B se mide bien, PLAN.md §K6c, reglas del supervisor 2026-10-06; el mismo principio que el usuario eligió para NA en
// "K6c región fija"): 200 seeds por región (eran 40) y la brecha entre la región más fácil del Mundial y la más difícil se juzga
// contra Z σ de la diferencia, con el σ de esta muestra (eran 30 puntos fijos). Con 40 seeds la brecha de 30 salía con suerte: con
// 200 por región es ~22 puntos, igual en K6b (`58db231`: KR 56,0 contra APAC 77,5) que ahora, y su σ es ~4,6. Las tandas van en
// paralelo (`dev/regionFija.js`, medida `llegada`): el resultado no depende de cuántas sean. Rojo con el mutante "la región elegida
// no se respeta" (`core/mundo.js`, `ligaOrigen = ligaSorteada`).
const SEEDS_K5B = 200;
const SPLITS_K5B = 40;
const DELTA_DIFICULTAD_K5B = 0.15;
const TOLERANCIA_PP_K5B = 10;
// El mismo Z que `Z_RUIDO_METAS_C` (que se define más abajo, junto a las metas de K5c).
const Z_RUIDO_K5B = 2;
const TANDAS_MAX_K5B = 8;

// El juez: null si cumple, el motivo si no. `medidas`: { regionId, dificultad, sinPrimera, carreras, local, primera } (conteos).
function juezRegionK5B(medidas) {
  const pct = (m, clave) => (100 * m[clave]) / m.carreras;
  const tabla = medidas.map((m) => `${m.regionId} ${m.carreras > 0 ? `${pct(m, 'local').toFixed(0)}%/${pct(m, 'primera').toFixed(0)}%` : 'sin muestra'}`).join(' · ');
  if (medidas.length === 0 || medidas.some((m) => !(m.carreras > 0))) return `muestra vacía: ${tabla}`;
  const tier1 = medidas.filter((m) => !m.sinPrimera);
  for (const a of tier1) {
    for (const b of tier1) {
      if (b.dificultad - a.dificultad > DELTA_DIFICULTAD_K5B && !(pct(a, 'local') <= pct(b, 'local') + TOLERANCIA_PP_K5B)) {
        return `${a.regionId} (dificultad ${a.dificultad}) llega a su primera el ${pct(a, 'local').toFixed(1)}%, más que ${b.regionId} (${b.dificultad}) con ${pct(b, 'local').toFixed(1)}%: ${tabla}`;
      }
    }
  }
  const porDificultad = [...tier1].sort((x, y) => x.dificultad - y.dificultad);
  const [facil, dificil] = [porDificultad[0], porDificultad.at(-1)];
  const [pf, pd] = [pct(facil, 'local'), pct(dificil, 'local')];
  const sigma = Math.sqrt((pf * (100 - pf)) / facil.carreras + (pd * (100 - pd)) / dificil.carreras);
  if (!(pd - pf > Z_RUIDO_K5B * sigma)) {
    return `entre la región más fácil del Mundial (${facil.regionId}, ${pf.toFixed(1)}%) y la más difícil (${dificil.regionId}, ${pd.toFixed(1)}%) la diferencia de llegada ${(pd - pf).toFixed(1)} no pasa ${Z_RUIDO_K5B} σ (σ ${sigma.toFixed(2)}): ${tabla}`;
  }
  for (const m of medidas.filter((x) => x.sinPrimera)) {
    if (m.local !== 0 || !(m.primera > 0)) return `${m.regionId}: a primera se llega solo emigrando y en más del 0%: ${tabla}`;
  }
  return null;
}

// Lo medido al cerrar K6c-fix (200 × 40 por región, `criterio`), para el caso rápido del juez.
const MEDIDO_K5B = { KR: [111, 134], CN: [115, 137], EMEA: [139, 143], NA: [152, 152], APAC: [155, 155], BR: [151, 152], LAN: [0, 120], LAS: [0, 126] };

check('K6c-fix K5-B región, el juez: acepta lo medido y rechaza el orden dado vuelta, una brecha dentro del ruido y una muestra vacía', () => {
  const problemas = [];
  const con = (cambios = {}) => regionesDeOrigenK5B().map((opcion) => {
    const [local, primera] = cambios[opcion.regionId] ?? MEDIDO_K5B[opcion.regionId] ?? [0, 0];
    return { ...opcion, carreras: SEEDS_K5B, local, primera };
  });
  const motivoMedido = juezRegionK5B(con());
  if (motivoMedido !== null) problemas.push(`lo medido no cumple: ${motivoMedido}`);
  const tier1 = regionesDeOrigenK5B().filter((o) => !o.sinPrimera).sort((x, y) => x.dificultad - y.dificultad);
  const [facil, dificil] = [tier1[0].regionId, tier1.at(-1).regionId];
  const casos = [
    ['el orden dado vuelta', { [facil]: MEDIDO_K5B[dificil], [dificil]: MEDIDO_K5B[facil] }],
    ['la brecha dentro del ruido', { [facil]: [140, 160], [dificil]: [146, 160] }],
    ['LATAM llega a su primera', { LAN: [5, 120] }]
  ];
  for (const [nombre, cambios] of casos) {
    if (juezRegionK5B(con(cambios)) === null) problemas.push(`acepta ${nombre}`);
  }
  if (juezRegionK5B(con().map((m) => (m.regionId === facil ? { ...m, carreras: 0, local: 0, primera: 0 } : m))) === null) problemas.push('acepta una muestra vacía');
  if (juezRegionK5B([]) === null) problemas.push('acepta ninguna región');
  if (problemas.length > 0) throw new Error(problemas.join('; '));
});

checkLento(`K5-B región: la dificultad de cada región es monótona con su dificultad (y LATAM llega a primera solo emigrando) (criterio, ${SEEDS_K5B} × ${SPLITS_K5B} por región, la brecha por encima de ${Z_RUIDO_K5B} σ)`, () => {
  const tandas = Math.max(1, Math.min(TANDAS_MAX_K5B, os.cpus().length - 1));
  const medidas = regionesDeOrigenK5B().map((opcion) => ({
    ...opcion,
    ...JSON.parse(execFileSync(process.execPath, [
      path.join(srcDir, 'dev', 'regionFija.js'), '--paralelo', opcion.regionId, String(SEEDS_K5B), String(SPLITS_K5B), String(tandas), 'llegada'
    ], { encoding: 'utf8' }).trim().split('\n').pop())
  }));
  const motivo = juezRegionK5B(medidas);
  console.log(`      K5-B llegada a la primera propia / a cualquier primera (${SEEDS_K5B} × ${SPLITS_K5B}, ${tandas} tandas): ${medidas.map((m) => `${m.regionId} ${m.local}/${m.primera}`).join(' · ')}`);
  if (motivo !== null) throw new Error(motivo);
});

// D78: con `criterio` hay splits de LCK y de LPL (antes de K5-B, 0 en 400 carreras, Corea incluida: el calibre de la
// liga era su `prestigio`, 95/93, contra titulares de ~82/81). Coreanos y chinos elegidos, 60 seeds x 60 splits.
checkLento('K5-B D78: hay splits de LCK y de LPL con criterio (coreanos y chinos con nivel juegan su liga)', () => {
  for (const [regionId, ligaId] of [['KR', 'LCK'], ['CN', 'LPL']]) {
    let splits = 0;
    for (let seed = 1; seed <= 60; seed += 1) {
      const state = carreraConRegionK5B(seed, regionId, 60);
      splits += state.career.registro.porOrg.filter((fila) => fila.liga === ligaId).reduce((suma, fila) => suma + fila.splits, 0);
    }
    if (!(splits > 0)) {
      throw new Error(`${ligaId}: 0 splits en 60 carreras de ${regionId} con criterio`);
    }
  }
});

// Revisión de K5: `congelar` decide antes de que el mundo se mueva y la mano de ofertas se arma después; un asiento
// que recién era ofrecible con el mundo movido quedaba fuera de la mano (medido: 23,6% de los asientos ofrecibles en
// 320 decisiones de oferta de 60 carreras coreanas). `congelarAsientosOfrecibles` los congela también.
check('Revisión K5: en cada decisión de oferta, todo asiento ofrecible del estado post-mercado está congelado (y la mano sale de ahí)', () => {
  let decisiones = 0;
  for (let seed = 1; seed <= 12; seed += 1) {
    const rng = mulberry32(seed);
    let state = createInitialState(seed, rng, { regionOrigen: 'KR' });
    for (let k = 0; k < 45 && !state.terminado; k += 1) {
      let r = avanzarSplit(state, rng);
      while (r.state.pendiente) {
        const { sistemaId, decision } = r.state.pendiente;
        const pre = r.state.mundo.mercadoPretemporada;
        if (sistemaId === 'mercado' && decision.datos?.motivo === 'oferta' && pre) {
          decisiones += 1;
          const congelados = new Set(pre.congelados.filter((c) => c.rol === r.state.player.role).map((c) => c.org));
          const fuera = orgsQueTeFicharian(r.state).map((e) => e.org.nombre).filter((org) => !congelados.has(org));
          if (fuera.length) {
            throw new Error(`seed ${seed}, split ${r.state.player.splitCount}: ${fuera.join(', ')} es ofrecible y no está congelado`);
          }
        }
        r = resolverDecision(r.state, ESTRATEGIAS_K0.criterio(sistemaPorId(sistemaId), r.state, decision, rng), rng);
      }
      state = r.state;
    }
  }
  if (decisiones < 20) {
    throw new Error(`solo ${decisiones} decisiones de oferta en la muestra`);
  }
});

// --- K5-A: el Mundial de verdad (PLAN.md "K5 — decisiones de spec", K5-A) ---
// Las carreras de muestra corren el camino headless (el mismo pipeline del navegador) y anotan, split a split, la
// línea del campeón del mundo que escribe `escena`, el torneo que dejó `systems/internacional.js` y cuántas veces
// frenó el Mundial. Se corren una sola vez y las comparten los checks.
const MUNDIAL_K5 = await import('../core/internacional.js');
const { ETAPAS_SPLIT: ETAPAS_K5 } = await import('../systems/registro.js');
const { puntajeDeCarrera: puntajeK5 } = await import('../core/puntaje.js');
const { RESULTADOS_INTERNACIONALES: RESULTADOS_K5 } = await import('../core/registro.js');
const { avanzarSplitAuto: avanzarSplitAutoK5 } = await import('../core/pipeline.js');
const { previaDeDecision: previaDeDecisionK5 } = await import('../core/previaDePartido.js');
const { lineaDeLiga: lineaDeLigaK5r, lineaDeInternacional: lineaDeInternacionalK5r } = await import('../core/escena.js');
const SEEDS_K5 = 30;
const SPLITS_K5 = 60;
// La spec: "un split de Mundial no pasa de 4 interrupciones" (el número de la spec, no el de BALANCE: si alguien sube
// el tope en balance.js, este check lo ve).
const TOPE_PAUSAS_MUNDIAL_K5 = 4;
const LINEA_WORLDS_K5 = /^Worlds (\d+): se lo lleva (.+) \(([A-Z_]+)\)\.$/;

function correrCarreraK5(seed, { splits = SPLITS_K5 } = {}) {
  const rng = mulberry32(seed);
  let state = createInitialState(seed, rng);
  const porSplit = [];
  for (let i = 0; i < splits && !state.terminado; i += 1) {
    let pausasMundial = 0;
    let pDeLaPrevia = null;
    const antes = state.career.registro.internacionales.length;
    const resultado = avanzarSplitAutoK5(state, rng, (sistema, st, decision, r) => {
      if (sistema.id === 'internacional') {
        pausasMundial += 1;
      }
      const respuesta = sistema.resolverAuto(st, decision, r);
      if (decision.datos?.motivo === 'swiss') {
        pDeLaPrevia = previaDeDecisionK5(st, decision).opciones.find((o) => o.id === respuesta.opcionId).p;
      }
      return respuesta;
    });
    const tirado = resultado.logs.find((log) => log.etapa === 'swiss' && log.ronda === 5 && pDeLaPrevia !== null);
    state = resultado.state;
    const linea = resultado.logs.map((log) => LINEA_WORLDS_K5.exec(log.message)).find(Boolean) ?? null;
    porSplit.push({
      linea: linea ? { anio: Number(linea[1]), campeon: linea[2], liga: linea[3] } : null,
      torneo: state.internacional,
      pausasMundial,
      dosDos: pDeLaPrevia === null ? null : { previa: pDeLaPrevia, tirada: tirado?.p ?? null },
      jugo: state.career.registro.internacionales.length > antes
    });
  }
  return { seed, state, porSplit };
}

let carrerasK5 = null;
function carrerasDelMundialK5() {
  carrerasK5 ??= Array.from({ length: SEEDS_K5 }, (_, i) => correrCarreraK5(i + 1));
  return carrerasK5;
}

// Los torneos a verificar: los que dejaron las carreras (con y sin vos) y 200 Mundiales sin jugador por hash puro.
function torneosK5() {
  const vistos = carrerasDelMundialK5().flatMap((c) => c.porSplit.filter((s) => s.linea).map((s) => s.torneo));
  const puros = [];
  for (let seed = 1; seed <= 20; seed += 1) {
    const st = createInitialState(seed, mulberry32(seed));
    for (let anio = 2026; anio < 2036; anio += 1) {
      puros.push(MUNDIAL_K5.mundialSinJugador(st, anio));
    }
  }
  return [...vistos, ...puros];
}

check('K5-A el campeón del mundo del log es el del torneo (systems/escena.js ya no lo sortea aparte)', () => {
  let lineas = 0;
  let conVos = 0;
  for (const carrera of carrerasDelMundialK5()) {
    for (const split of carrera.porSplit.filter((s) => s.linea)) {
      const { linea, torneo } = split;
      if (!torneo || torneo.anio !== linea.anio || torneo.campeon !== linea.campeon) {
        throw new Error(`seed ${carrera.seed}: el log dice Worlds ${linea.anio} → ${linea.campeon}, el torneo `
          + `${torneo?.anio} → ${torneo?.campeon}`);
      }
      const liga = torneo.participantes.find((p) => p.nombre === torneo.campeon)?.liga;
      if (liga !== linea.liga) {
        throw new Error(`seed ${carrera.seed}: ${linea.campeon} sale como ${linea.liga} y jugó el Mundial por ${liga}`);
      }
      lineas += 1;
      conVos += split.jugo ? 1 : 0;
    }
    for (const entrada of carrera.state.career.registro.internacionales) {
      if ((entrada.resultado === 'campeon') !== (entrada.campeon === entrada.org)) {
        throw new Error(`seed ${carrera.seed}: tu registro dice ${entrada.resultado} y el campeón fue ${entrada.campeon}`);
      }
    }
  }
  if (lineas < SEEDS_K5 || conVos < 3) {
    throw new Error(`muestra chica: ${lineas} líneas de Worlds, ${conVos} con tu equipo adentro`);
  }
});

check('K5-A el Swiss del Mundial siempre termina 8 y 8, y el bracket sale de esos 8', () => {
  const torneos = torneosK5();
  for (const t of torneos) {
    const nombres = new Set(t.participantes.map((p) => p.nombre));
    if (t.participantes.length !== 16 || nombres.size !== 16) {
      throw new Error(`Mundial ${t.anio}: ${nombres.size} participantes distintos`);
    }
    const records = Object.values(t.swiss.record);
    const pasan = records.filter((r) => r.v === 3 && r.d < 3).length;
    const afuera = records.filter((r) => r.d === 3 && r.v < 3).length;
    if (pasan !== 8 || afuera !== 8) {
      throw new Error(`Mundial ${t.anio}: el Swiss terminó ${pasan} y ${afuera}`);
    }
    const alBracket = new Set(t.bracket.crucesCuartos.flatMap((c) => [c.a, c.b]));
    const conTres = new Set(t.participantes.filter((p) => t.swiss.record[p.nombre].v === 3).map((p) => p.nombre));
    if (alBracket.size !== 8 || [...alBracket].some((n) => !conTres.has(n))) {
      throw new Error(`Mundial ${t.anio}: al bracket fueron ${[...alBracket].join(', ')}`);
    }
    if (t.bracket.final?.[0]?.ganador !== t.campeon || t.fase !== 'terminado') {
      throw new Error(`Mundial ${t.anio}: el campeón (${t.campeon}) no es el que ganó la final`);
    }
  }
  if (torneos.length < 200) {
    throw new Error(`solo ${torneos.length} torneos en la muestra`);
  }
});

check('K5-A ningún cruce del Swiss se repite', () => {
  for (const t of torneosK5()) {
    const vistos = new Set();
    for (const ronda of t.swiss.rondas) {
      const enRonda = new Set();
      for (const c of ronda) {
        const clave = [c.a, c.b].sort().join(' vs ');
        if (vistos.has(clave)) {
          throw new Error(`Mundial ${t.anio}: ${clave} se cruzaron dos veces en el Swiss`);
        }
        if (enRonda.has(c.a) || enRonda.has(c.b) || c.a === c.b) {
          throw new Error(`Mundial ${t.anio}: un equipo juega dos veces en la ronda ${c.ronda}`);
        }
        vistos.add(clave);
        enRonda.add(c.a);
        enRonda.add(c.b);
      }
    }
  }
});

// Revisión de K5: `uniformeDeClave` terminaba en `h ^= h >>> 16`, que en JS da un int32 CON signo, así que el
// "uniforme" vivía en [-0,5; 0,5): el cruce ajeno le daba al primero del par alfabético P(mapa) = min(1, p + 0,5), el
// mismo cruce coincidía el 100% de los años con p = 0,5 y una org ganaba 277 de 500 Mundiales (seed 1). Las tres
// propiedades de abajo son las que ese bug rompía: medido antes del arreglo, media 0,002, acuerdo 1,000, 55% de títulos.
const MUNDIALES_HASH_K5 = 300;
// K5c paso 3b-2 (regla 17): 0,35 -> 0,45. Estos 300 Mundiales se juegan sobre el MISMO estado inicial (el mundo congelado): lo que
// mide el tope es la chance de un Mundial del más fuerte de ese mundo, no una dinastía. Con Final2 y la LPL en 91, en la seed 3 LNG
// (99, contra 97 del segundo) gana 111 de 300 (37%); en las seeds 1-10, de 17% a 37%. El bug del hash daba 55% (277 de 500). Que una
// org no se lleve el mundo se mide donde el mundo gira: abajo, con las carreras (`RECAMBIO_K5`).
const TOPE_TITULOS_DE_UNA_ORG_K5 = 0.45;
// K5c paso 3b-2: el recambio del mundo vivo. En carreras de `criterio`, el más fuerte del primer Mundial del mundo, `anios` Mundiales
// después: ¿sigue siendo el más fuerte? Con planteles que envejecen y se mueven, casi nunca.
// Medido al escribirlo (criterio, 60 × 60, Final2): sigue arriba en 5 de 55 carreras (9%) y la org que más gana se lleva 48 de 720
// Mundiales (6,7%). Con el mundo congelado (mutante: las fuerzas de las orgs no siguen a sus planteles) sigue arriba en 21 de 55
// (38%: no 100%, porque quién clasifica y la tabla de cada año igual cambian); el tope va en el medio.
// K5c (cierre, hallazgo de la revisión, regla 7): `topeDeUnaOrg` era la proporción de la org que más gana sobre los Mundiales de
// las 60 carreras JUNTAS (60 mundos distintos): una dinastía dentro de un mundo se diluía entre los otros 59 y la rama no podía
// fallar. Ahora mide, en cada mundo con más de `anios` Mundiales (los mismos que compara el recambio), la proporción de la org que
// más gana DENTRO de ese mundo, y el tope va sobre la media de esas proporciones. Medido al cerrar K5c (criterio, 60 × 60): 25,8% (55
// mundos); con las fuerzas de las orgs congeladas (mutante en `systems/plantel.js` y en `core/mercadoMundial.js`, las dos rutas que
// recalculan `org.fuerza` del plantel): 32,9%, y con el congelado solo en el mercado del mundo, 36,0%. Congelar solo `plantel.js` no
// lo mueve (25,6%): el mercado de la pretemporada vuelve a calcular la fuerza de cada plantel. El tope va en el medio de 25,8 y 32,9.
const RECAMBIO_K5 = { carreras: 60, splits: 60, anios: 8, maxSigueArriba: 0.25, topeDeUnaOrg: 0.29 };
const MUESTRA_MINIMA_RECAMBIO_K5 = 10;
check('K5-A el hash de los cruces ajenos es un uniforme en [0, 1): media ≈ 0,5, el mismo cruce no se repite año a año y el título sigue a la fuerza sin que una org se lleve el mundo', () => {
  let suma = 0;
  const N = 20000;
  for (let i = 0; i < N; i += 1) {
    const u = MUNDIAL_K5.uniformeDeClave(`validate|${i}|clave`);
    if (!(u >= 0 && u < 1)) {
      throw new Error(`uniformeDeClave dio ${u}, fuera de [0, 1)`);
    }
    suma += u;
  }
  if (Math.abs(suma / N - 0.5) > 0.02) {
    throw new Error(`la media de uniformeDeClave sobre ${N} claves es ${(suma / N).toFixed(4)} (esperado ≈ 0,5)`);
  }
  let iguales = 0;
  const ANIOS = 2000;
  for (let a = 0; a < ANIOS; a += 1) {
    const mapa = (anio) => MUNDIAL_K5.uniformeDeClave(`1|mundial|${anio}|cuartos|A|B|0`) < 0.5;
    iguales += mapa(2026 + a) === mapa(2027 + a) ? 1 : 0;
  }
  if (Math.abs(iguales / ANIOS - 0.5) > 0.05) {
    throw new Error(`el mismo cruce con p = 0,5 coincide el ${(100 * iguales / ANIOS).toFixed(1)}% de los años consecutivos (esperado ≈ 50%)`);
  }
  for (const seed of [1, 2, 3]) {
    const st = createInitialState(seed, mulberry32(seed));
    const titulos = new Map();
    let fuerzaCampeon = 0;
    let fuerzaCampo = 0;
    for (let a = 0; a < MUNDIALES_HASH_K5; a += 1) {
      const t = MUNDIAL_K5.mundialSinJugador(st, 2026 + a);
      titulos.set(t.campeon, (titulos.get(t.campeon) ?? 0) + 1);
      fuerzaCampeon += t.participantes.find((p) => p.nombre === t.campeon).fuerza;
      fuerzaCampo += t.participantes.reduce((s, p) => s + p.fuerza, 0) / t.participantes.length;
    }
    const [org, n] = [...titulos.entries()].sort((x, y) => y[1] - x[1])[0];
    if (n / MUNDIALES_HASH_K5 > TOPE_TITULOS_DE_UNA_ORG_K5) {
      throw new Error(`seed ${seed}: ${org} ganó ${n} de ${MUNDIALES_HASH_K5} Mundiales (tope ${TOPE_TITULOS_DE_UNA_ORG_K5 * 100}%)`);
    }
    if (fuerzaCampeon <= fuerzaCampo) {
      throw new Error(`seed ${seed}: la fuerza media del campeón (${(fuerzaCampeon / MUNDIALES_HASH_K5).toFixed(1)}) no supera la del campo (${(fuerzaCampo / MUNDIALES_HASH_K5).toFixed(1)})`);
    }
  }
  // El mundo vivo: los Mundiales del mundo que vio cada carrera (`mundialesDelMundo`, el campeón de `escenaAnual`).
  const { observaciones } = correrLoteJugabilidad(RECAMBIO_K5.carreras, RECAMBIO_K5.splits, 'criterio').crudos;
  const masFuerte = (fila) => [...fila.participantes].sort((x, y) => y.fuerza - x.fuerza || x.nombre.localeCompare(y.nombre))[0].nombre;
  let comparadas = 0;
  let sigueArriba = 0;
  // Por mundo: la proporción de los Mundiales de ESE mundo que se lleva su org más ganadora (y cuál fue la más alta, para el log).
  let sumaProporcionTop = 0;
  let peor = { org: 'nadie', n: 0, de: 0 };
  for (const o of observaciones) {
    const filas = o.mundialesDelMundo;
    if (filas.length > RECAMBIO_K5.anios) {
      comparadas += 1;
      sigueArriba += masFuerte(filas[0]) === masFuerte(filas[RECAMBIO_K5.anios]) ? 1 : 0;
      const titulos = new Map();
      for (const fila of filas) {
        titulos.set(fila.campeon, (titulos.get(fila.campeon) ?? 0) + 1);
      }
      const [org, n] = [...titulos.entries()].sort((x, y) => y[1] - x[1] || x[0].localeCompare(y[0]))[0];
      sumaProporcionTop += n / filas.length;
      if (n / filas.length > peor.n / Math.max(1, peor.de)) peor = { org, n, de: filas.length };
    }
  }
  const proporcionTopMedia = comparadas > 0 ? sumaProporcionTop / comparadas : 0;
  console.log(`      mundo vivo (criterio, ${RECAMBIO_K5.carreras} × ${RECAMBIO_K5.splits}): el más fuerte del primer Mundial sigue arriba ${RECAMBIO_K5.anios} años después en ${sigueArriba} de ${comparadas} carreras; la org que más gana dentro de su mundo se lleva en promedio el ${(100 * proporcionTopMedia).toFixed(1)}% de sus Mundiales (la que más: ${peor.org}, ${peor.n} de ${peor.de})`);
  if (comparadas < MUESTRA_MINIMA_RECAMBIO_K5) {
    throw new Error(`el recambio no se mide: ${comparadas} carreras con más de ${RECAMBIO_K5.anios} Mundiales (mínimo ${MUESTRA_MINIMA_RECAMBIO_K5})`);
  }
  // Las dos ramas se juntan: con el mundo congelado fallan las dos, y una no tapa a la otra.
  const problemasRecambio = [];
  if (sigueArriba / comparadas > RECAMBIO_K5.maxSigueArriba) {
    problemasRecambio.push(`el mundo no rota: el más fuerte del primer Mundial sigue arriba ${RECAMBIO_K5.anios} años después en ${sigueArriba} de ${comparadas} carreras (máximo ${RECAMBIO_K5.maxSigueArriba * 100}%)`);
  }
  if (proporcionTopMedia > RECAMBIO_K5.topeDeUnaOrg) {
    problemasRecambio.push(`en el mundo vivo la org que más gana dentro de su mundo se lleva en promedio el ${(100 * proporcionTopMedia).toFixed(1)}% de sus Mundiales (tope ${RECAMBIO_K5.topeDeUnaOrg * 100}%; la que más: ${peor.org}, ${peor.n} de ${peor.de})`);
  }
  if (problemasRecambio.length > 0) throw new Error(problemasRecambio.join('; '));
});

check('K5-A un split de Mundial no pasa de 4 interrupciones del Mundial (T9)', () => {
  let splitsConVos = 0;
  let conPausa = 0;
  for (const carrera of carrerasDelMundialK5()) {
    for (const split of carrera.porSplit.filter((s) => s.jugo)) {
      splitsConVos += 1;
      conPausa += split.pausasMundial > 0 ? 1 : 0;
      if (split.pausasMundial > TOPE_PAUSAS_MUNDIAL_K5) {
        throw new Error(`seed ${carrera.seed}, Mundial ${split.torneo.anio}: frenó ${split.pausasMundial} veces`);
      }
      if (split.torneo.interrupciones !== split.pausasMundial) {
        throw new Error(`seed ${carrera.seed}: el torneo cuenta ${split.torneo.interrupciones} pausas y el pipeline ${split.pausasMundial}`);
      }
    }
  }
  if (splitsConVos < 3 || conPausa === 0) {
    throw new Error(`muestra chica: ${splitsConVos} splits de Mundial con tu equipo, ${conPausa} con alguna pausa`);
  }
});

check('K5-A si no clasificás, cero tiradas: la huella es la de un árbol sin Mundial', () => {
  const sinMundial = [];
  for (let seed = 1; seed <= 80 && sinMundial.length < 4; seed += 1) {
    const carrera = seed <= SEEDS_K5 ? carrerasDelMundialK5()[seed - 1] : correrCarreraK5(seed);
    if (carrera.state.career.registro.internacionales.length === 0) {
      sinMundial.push(seed);
    }
  }
  if (sinMundial.length < 4) {
    throw new Error(`solo ${sinMundial.length} carreras sin Mundial en 80 seeds`);
  }
  const indice = ETAPAS_K5.findIndex((sistema) => sistema.id === 'internacional');
  const original = ETAPAS_K5[indice];
  const sinElMundial = (estado) => {
    const { internacional, ...resto } = estado;
    return JSON.stringify(resto);
  };
  for (const seed of sinMundial) {
    let conTorneo;
    let tiradas = 0;
    try {
      ETAPAS_K5[indice] = { ...original, aplicar: (st, rng) => original.aplicar(st, () => { tiradas += 1; return rng(); }) };
      conTorneo = correrCarreraK5(seed);
    } finally {
      ETAPAS_K5[indice] = original;
    }
    let arbolSinMundial;
    try {
      ETAPAS_K5.splice(indice, 1);
      arbolSinMundial = correrCarreraK5(seed);
    } finally {
      ETAPAS_K5.splice(indice, 0, original);
    }
    if (tiradas !== 0) {
      throw new Error(`seed ${seed}: sin clasificar, el Mundial tiró ${tiradas} veces`);
    }
    if (sinElMundial(conTorneo.state) !== sinElMundial(arbolSinMundial.state)) {
      throw new Error(`seed ${seed}: la carrera sin clasificar no es la del árbol sin Mundial`);
    }
  }
});

check('K5-A core/internacional.js es puro: mismo torneo dos veces, no toca el estado ni el rng', () => {
  const fuente = fs.readFileSync(path.join(srcDir, 'core', 'internacional.js'), 'utf8');
  if (/\brng\b|Math\.random/.test(fuente.replace(/\/\/.*$/gm, ''))) {
    throw new Error('core/internacional.js nombra un rng');
  }
  for (let seed = 1; seed <= 10; seed += 1) {
    const st = createInitialState(seed, mulberry32(seed));
    const foto = JSON.stringify(st);
    const lck = st.mundo.ligas.find((liga) => liga.id === 'LCK');
    const jugador = { nombre: lck.orgs[0].nombre, liga: 'LCK', fuerza: lck.orgs[0].fuerza, cupo: 1 };
    const jugarConVos = () => {
      let t = MUNDIAL_K5.crearMundial(st, 2030 + seed, jugador);
      let i = 0;
      while (MUNDIAL_K5.sigueEnSwiss(t, t.jugador)) {
        t = MUNDIAL_K5.jugarRondaSwiss(t, MUNDIAL_K5.emparejarRondaSwiss(t), { gano: i % 2 === 0 || i > 3, p: 0.5 });
        i += 1;
      }
      while (!MUNDIAL_K5.swissTerminado(t)) {
        t = MUNDIAL_K5.jugarRondaSwiss(t, MUNDIAL_K5.emparejarRondaSwiss(t));
      }
      t = t.bracket ? t : MUNDIAL_K5.sembrarBracket(t);
      for (let etapa = MUNDIAL_K5.etapaPendiente(t); etapa; etapa = MUNDIAL_K5.etapaPendiente(t)) {
        const tuyo = MUNDIAL_K5.cruceDe(MUNDIAL_K5.crucesDeEtapa(t, etapa), t.jugador);
        t = MUNDIAL_K5.jugarEtapaBracket(t, etapa, tuyo ? { gano: etapa !== 'final', marcador: etapa === 'final' ? [1, 3] : [3, 2] } : null);
      }
      return t;
    };
    for (const correr of [() => MUNDIAL_K5.mundialSinJugador(st, 2030 + seed), jugarConVos]) {
      if (JSON.stringify(correr()) !== JSON.stringify(correr())) {
        throw new Error(`seed ${seed}: el mismo Mundial salió distinto dos veces`);
      }
    }
    if (JSON.stringify(st) !== foto) {
      throw new Error(`seed ${seed}: core/internacional.js modificó el estado`);
    }
  }
});

check('K5-A regla 15: la previa del 2-2 del Swiss dice la p con la que se tira', () => {
  const dosDos = carrerasDelMundialK5().flatMap((c) => c.porSplit.map((s) => s.dosDos).filter(Boolean));
  for (const { previa, tirada } of dosDos) {
    if (tirada === null || Math.abs(previa - tirada) > 1e-12) {
      throw new Error(`la previa del 2-2 dice ${previa} y se tiró ${tirada}`);
    }
  }
  if (dosDos.length === 0) {
    throw new Error('ningún 2-2 en la muestra');
  }
});

// Revisión de K5 (P4): el cierre del Mundial daba el mismo hype a un campeón que a un cuartofinalista (binario: pasar
// el Swiss o no). Ahora sale de `mundial.hypePorResultado`, estrictamente creciente con hasta dónde llegaste.
check('Revisión K5: el hype del Mundial crece con el resultado (campeón > final > semis > cuartos > eliminado) y el cierre lo lee de esa tabla', () => {
  const orden = ['eliminado', 'cuartos', 'semis', 'final', 'campeon'];
  const tabla = BALANCE.mundial.hypePorResultado;
  if (Object.keys(tabla).sort().join() !== [...orden].sort().join()) {
    throw new Error(`hypePorResultado tiene ${Object.keys(tabla).join(', ')}; esperado ${orden.join(', ')}`);
  }
  for (let i = 1; i < orden.length; i += 1) {
    if (!(tabla[orden[i]] > tabla[orden[i - 1]])) {
      throw new Error(`hype de ${orden[i]} (${tabla[orden[i]]}) no supera al de ${orden[i - 1]} (${tabla[orden[i - 1]]})`);
    }
  }
  const fuente = fs.readFileSync(path.join(srcDir, 'systems', 'internacional.js'), 'utf8');
  if (!/hypePorResultado\[resultado\]/.test(fuente) || /hypePorTitulo|hypePorPodio/.test(fuente)) {
    throw new Error('systems/internacional.js no toma el hype del Mundial de hypePorResultado[resultado]');
  }
});

check('K5-A el puntaje de K1 maneja cada resultado del Mundial, en orden', () => {
  const { porResultado } = BALANCE.puntaje.internacional;
  const orden = ['eliminado', 'cuartos', 'semis', 'final', 'campeon'];
  for (let i = 1; i < orden.length; i += 1) {
    if (!(porResultado[orden[i]] > porResultado[orden[i - 1]])) {
      throw new Error(`porResultado.${orden[i]} (${porResultado[orden[i]]}) no supera a ${orden[i - 1]}`);
    }
  }
  const base = carrerasDelMundialK5().find((c) => c.state.terminado)?.state ?? carrerasDelMundialK5()[0].state;
  for (const resultado of RESULTADOS_K5) {
    const st = structuredClone(base);
    st.career.registro.internacionales.push({ torneo: 'Mundial', anio: st.calendario.anio, org: 'X', liga: 'LCK', resultado, camino: [] });
    puntajeK5(st);
  }
  const escritos = new Set(carrerasDelMundialK5().flatMap((c) => c.state.career.registro.internacionales.map((e) => e.resultado)));
  for (const resultado of escritos) {
    if (!RESULTADOS_K5.includes(resultado)) {
      throw new Error(`el Mundial escribió un resultado desconocido: ${resultado}`);
    }
  }
});

// K5 (revisión): el motor también habla de ligas (logs, titulares, descripciones y rótulos de decisión, hitos, nombre de
// un título). Ninguno puede traer el id crudo ("EMEA_MASTERS", "LCK_CL", "CD", "LCP_CHALLENGERS"): se ve el nombre.
const IDS_DE_LIGA_CON_OTRO_NOMBRE_K5r = LIGAS.filter((liga) => liga.id !== liga.nombre).map((liga) => liga.id);
const PATRON_ID_CRUDO_K5r = new RegExp(`(?<![A-Za-z0-9_])(${IDS_DE_LIGA_CON_OTRO_NOMBRE_K5r.join('|')})(?![A-Za-z0-9_])`);

// Los textos de la lista que traen un id de liga crudo (su nombre visible no cuenta: "LCK CL" no es "LCK_CL").
function textosConIdCrudoK5r(textos) {
  return textos.filter((texto) => typeof texto === 'string' && PATRON_ID_CRUDO_K5r.test(texto));
}

// Los textos que el motor le escribe al jugador en carreras de muestra: cada log, cada decisión (título, descripción,
// rótulo y descripción de cada opción), los hitos y el nombre de cada título. Las carreras juegan solas (resolverAuto).
function textosDelMotorK5r(seeds, splits) {
  const textos = [];
  for (let seed = 1; seed <= seeds; seed += 1) {
    const rng = mulberry32(seed);
    let state = createInitialState(seed, rng);
    for (let i = 0; i < splits && !state.terminado; i += 1) {
      const resultado = avanzarSplitAutoK5(state, rng, (sistema, st, decision, r) => {
        textos.push(decision.titulo, decision.descripcion);
        for (const opcion of decision.opciones ?? []) {
          textos.push(opcion.label, opcion.descripcion);
        }
        return sistema.resolverAuto(st, decision, r);
      });
      state = resultado.state;
      textos.push(...resultado.logs.map((log) => log.message));
    }
    textos.push(...state.career.hitos, ...state.career.registro.titulos.map((titulo) => titulo.nombre));
  }
  return textos.filter((texto) => typeof texto === 'string');
}

check('K5 (revisión) ningún texto del motor muestra el id crudo de una liga: logs, decisiones, hitos y titulares usan el nombre visible', () => {
  if (IDS_DE_LIGA_CON_OTRO_NOMBRE_K5r.length < 3) {
    throw new Error(`esperaba al menos 3 ligas con id distinto de su nombre, hay ${IDS_DE_LIGA_CON_OTRO_NOMBRE_K5r.length}`);
  }
  // El detector ve un id crudo y no confunde el nombre visible (mutante del propio check).
  const nombresVisibles = LIGAS.filter((liga) => liga.id !== liga.nombre).map((liga) => `Firmás en ${liga.nombre}.`);
  if (textosConIdCrudoK5r(nombresVisibles).length !== 0) {
    throw new Error('el detector marca como crudo un nombre visible');
  }
  for (const id of IDS_DE_LIGA_CON_OTRO_NOMBRE_K5r) {
    if (textosConIdCrudoK5r([`Te ganás el salto a ${id}. Sos agente libre.`, `Rueda de prensa de ${id}`]).length !== 2) {
      throw new Error(`mutante: el detector no ve "${id}" crudo`);
    }
  }
  // Los textos que arman las funciones puras, liga por liga.
  const puros = [];
  for (const liga of LIGAS) {
    const equipo = { nombre: 'Equipo Uno' };
    puros.push(lineaDeLigaK5r(liga, equipo, { nombre: 'Equipo Dos' }, '3-1'));
    puros.push(lineaDeInternacionalK5r(2030, { nombre: 'Equipo Uno', ligaId: liga.id }));
    puros.push(resolverTexto('Rueda de prensa de {liga}', { career: { liga: liga.id } }));
  }
  const crudosPuros = textosConIdCrudoK5r(puros);
  if (crudosPuros.length > 0) {
    throw new Error(`${crudosPuros.length} texto(s) de funciones puras con una liga cruda: ${crudosPuros.slice(0, 3).join(' · ')}`);
  }
  // Carreras de muestra: tienen que haber revisado textos, y entre ellos algunos de una liga con otro nombre (si no, el
  // check daría verde sin haber visto jamás un id).
  const textos = textosDelMotorK5r(12, 60);
  if (textos.length < 1000) {
    throw new Error(`el check revisó solo ${textos.length} textos: no corrió lo que dice`);
  }
  const crudos = textosConIdCrudoK5r(textos);
  if (crudos.length > 0) {
    throw new Error(`${crudos.length} texto(s) del motor con el id crudo de una liga (de ${textos.length} revisados): ${crudos.slice(0, 3).join(' · ')}`);
  }
  const nombresDeLigasConOtroId = LIGAS.filter((liga) => liga.id !== liga.nombre).map((liga) => liga.nombre);
  const conLigaVisible = textos.filter((texto) => nombresDeLigasConOtroId.some((nombre) => texto.includes(nombre))).length;
  if (conLigaVisible < 10) {
    throw new Error(`solo ${conLigaVisible} textos de la muestra nombran una liga de desarrollo: la muestra no ejercita el caso`);
  }
});

// Revisión de K5 (crash que encontró `agencia.js`, seed 4): "Split jugado con Rasgo Academy y otro pendiente sin fila
// con paiN Gaming". La secuencia: un evento te manda al banco (`flags.banquilloPendiente`) y en la pretemporada
// siguiente tu club ya juega la liga de desarrollo (bajó entero en `competitivo.js`, o el banco te agarró en tier 2)
// y es su org más débil. `resolverBanquillo` te "cedía" a tu propio club: `aceptarOferta` cerraba su fila, la org no
// cambiaba y `roster.js` (que abre la fila cuando cambia la org) no la abría nunca. Cada split jugado quedaba en
// `flags.splitJugadoSinFila`, sin fila, y el primer pase siguiente reventaba en `registrarSplitJugado`.
// El check, sin agencia: (1) sin dado, `academiaDelBanquillo` con tu club como el más débil de su liga; (2) en
// pretemporadas reales de tier 2, el banco forzado con tu plantel hundido (nivel mínimo: tu club queda último de la
// liga de desarrollo después del mercado del mundo) — el mercado no te cede a tu club y deja a `roster.js` la fila
// de la org nueva, y por el pipeline, dos splits después lo jugado está en la fila abierta de la org donde jugás.
// Cuenta los casos que discriminan (el banco se cobró y tu club era el más débil) y no pasa vacío.
const SEEDS_BANQUILLO_K5 = 60;
const MINIMO_DISCRIMINANTES_BANQUILLO_K5 = 3;
const LOG_BANQUILLO_K5 = /te manda a la academia|no hay academia donde jugar/;

function conPlantelHundidoK5(estado, org) {
  const plantel = estado.mundo.planteles?.[org];
  if (!plantel) {
    return null;
  }
  const hundido = Object.fromEntries(Object.entries(plantel).map(([rol, npc]) => [rol, { ...npc, nivel: 0 }]));
  return {
    ...estado,
    flags: { ...estado.flags, banquilloPendiente: true },
    mundo: { ...estado.mundo, planteles: { ...estado.mundo.planteles, [org]: hundido } }
  };
}

function esLaMasDebilK5(estado, org) {
  const dev = estado.mundo.ligas.find((liga) => liga.tier === 2 && liga.orgs.some((o) => o.nombre === org));
  return Boolean(dev) && [...dev.orgs].sort((a, b) => a.fuerza - b.fuerza)[0].nombre === org;
}

check('K5 (revisión) banquillo: la org que te sienta nunca es la que te toma en la liga de desarrollo, y el split siguiente se cuenta en una fila abierta de la org donde jugás', () => {
  let casos = 0;
  let discriminantes = 0;
  let unitario = false;
  for (let seed = 1; seed <= SEEDS_BANQUILLO_K5 && discriminantes < MINIMO_DISCRIMINANTES_BANQUILLO_K5; seed += 1) {
    const rng = mulberry32(seed);
    let estado = createInitialState(seed, rng);
    for (let split = 0; split < 50 && !estado.terminado && discriminantes < MINIMO_DISCRIMINANTES_BANQUILLO_K5; split += 1) {
      estado = avanzarSplitAuto(estado, rng).state;
      if (estado.phase !== 'profesional' || estado.pendiente || !estado.career.currentOrg || estado.career.tier !== 2
        || estado.player.splitCount % BALANCE.edad.splitsPorEdad !== 0) {
        continue;
      }
      const origen = estado.career.currentOrg;
      const donde = `seed ${seed}, split ${estado.player.splitCount} (${origen})`;

      // (1) Sin dado: con tu club como el más débil de su liga, la academia es otra org (la más débil de las demás).
      if (!unitario) {
        unitario = true;
        const ligas = estado.mundo.ligas.map((liga) => (liga.orgs.some((org) => org.nombre === origen)
          ? { ...liga, orgs: liga.orgs.map((org) => (org.nombre === origen ? { ...org, fuerza: Math.min(...liga.orgs.map((o) => o.fuerza)) - 1 } : org)) }
          : liga));
        const academia = academiaDelBanquillo({ ...estado, mundo: { ...estado.mundo, ligas } });
        const otras = ligas.find((liga) => liga.orgs.some((org) => org.nombre === origen)).orgs.filter((org) => org.nombre !== origen);
        if (!academia || academia.org.nombre === origen || academia.org.fuerza !== Math.min(...otras.map((org) => org.fuerza))) {
          throw new Error(`${donde}: con su club como el más débil, el banco lo manda a ${academia?.org.nombre ?? 'ningún lado'}`);
        }
      }

      // (2) El banco forzado con tu plantel hundido.
      const conBanco = conPlantelHundidoK5(estado, origen);
      if (!conBanco) {
        continue;
      }
      casos += 1;
      const tras = aplicarMercado(conBanco, mulberry32(seed * 100 + split)).state;
      if (tras.career.currentOrg === origen) {
        throw new Error(`${donde}: el banco lo cedió a su propio club`);
      }
      if (tras.career.currentOrg && (filaAbiertaK5(tras.career.registro) || tras.career.rosterDeOrg === tras.career.currentOrg)) {
        throw new Error(`${donde}: firmó con ${tras.career.currentOrg} y roster.js no va a abrir su fila (rosterDeOrg ${tras.career.rosterDeOrg})`);
      }

      // Por el pipeline: el split del banco y el siguiente.
      const rngPipeline = mulberry32(seed * 100 + split);
      const primero = avanzarSplitAuto(conBanco, rngPipeline);
      if (primero.logs.some((log) => LOG_BANQUILLO_K5.test(log.message ?? '')) && esLaMasDebilK5(primero.state, origen)) {
        discriminantes += 1;
      }
      const despues = primero.state.terminado ? primero.state : avanzarSplitAuto(primero.state, rngPipeline).state;
      if (despues.phase === 'profesional' && despues.career.currentOrg
        && (despues.flags.splitJugadoSinFila || filaAbiertaK5(despues.career.registro)?.org !== despues.career.currentOrg)) {
        throw new Error(`${donde}: dos splits después juega con ${despues.career.currentOrg}, fila abierta `
          + `${filaAbiertaK5(despues.career.registro)?.org ?? 'ninguna'}, sin fila ${JSON.stringify(despues.flags.splitJugadoSinFila)}`);
      }
    }
  }
  if (discriminantes < MINIMO_DISCRIMINANTES_BANQUILLO_K5 || !unitario) {
    throw new Error(`check vacío: ${casos} bancos forzados en tier 2, ${discriminantes} cobrados con su club como el más débil `
      + `(mín. ${MINIMO_DISCRIMINANTES_BANQUILLO_K5}) en ${SEEDS_BANQUILLO_K5} seeds`);
  }
});

// --- K4c (paso 3b): las metas del bloque B (el ritmo), como checks duros (PLAN.md K4c, "Las metas de §K.3c, fijadas en lo medido") ---
//
// Hasta K4c eran la PROPUESTA de §K.3c (≤ 80 interrupciones por carrera, ≤ 2 por split y ≤ 4 en playoffs/internacional, minijuegos
// 4-8, ≤ ~4,6 min de tiempo-máquina, bifurcaciones 4,5-7,5) y K4c midió lo que el juego hace con las perillas del ritmo en su sitio
// (`criterio`, 400 × 60, `c6f098f`). La calibración las fija en lo medido y cada una pasa a check duro, con las mismas constantes
// `META_K4_*` que el juez. Regla de proceso 17, qué protege cada uno: "el ritmo es de decisiones con algo en juego" (K.3c) — que la
// carrera no se llene de paradas (interrupciones), que un split no se te vaya en pausas (por split), que los minijuegos no
// desaparezcan ni sean la carrera (minijuegos), que lo que mira el jugador no sea una maratón (tiempo-máquina), que el plan de serie
// mueva la p (Δp) y que las bifurcaciones frenen lo justo (bifurcaciones). Un solo lote compartido: `criterio`, 400 × 60 (el
// tamaño de la medición de K4c), que se corre una vez y lo leen los cinco checks de abajo. Los tiempos son los del instrumento de
// `simulate.js` (beats × 700 ms): el tiempo real lo mide K6 en el navegador.
// Regla 17, las bandas de J5/J6 ("150-280 decisiones por carrera", "más drafts"): reemplazadas por K4 (D-B). No había un check de J5/J6 en
// este archivo (la FASE J se reorganizó en K antes de escribirlos: ver PLAN.md, §K.6); lo que las contradecía, "series sin ningún draft", se
// borró en K4-B con su línea de la regla 17. Las metas de decisiones de la FASE K son las de este bloque.
const CARRERAS_METAS_B = 400;
const META_K4_INTERRUPCIONES_CARRERA_MEDIANA = 90;
const META_K4_INTERRUPCIONES_SPLIT_REGULAR_P90 = 2;
const META_K4_INTERRUPCIONES_SPLIT_PLAYOFFS_P90 = 5;
// K5c (paso 3b-3) — regla 17: el p90 del split internacional pasa de <= 5 a <= 6, la meta del usuario (PLAN.md §K5c, "El paso 3,
// concreto"). Meta 5; medido 6 (criterio 1500 × 60, 2963 splits internacionales: p50 4, p90 6); re-basado por decisión del usuario
// 2026-10-05, K6 juzga. Lo subió el Mundial real de K5 (Swiss y bracket: más series por split internacional).
const META_K4_INTERRUPCIONES_SPLIT_INTERNACIONAL_P90 = 6;
const META_K4_MINIJUEGOS_MEDIANA = [3, 8];
const META_K4_TIEMPO_MAQUINA_MIN_MEDIANA = 6.5;
const META_K4_DELTA_P_PLAN_PP_MEDIANA = 5;
// K5c (paso 3b-3) — regla 17: el Δp mediano de las paradas de plan. Meta >= 5 pp; medido 4,87 pp (criterio 400 × 60, el σ y el n
// los imprime el check); re-basado por decisión del usuario 2026-10-05, K6 juzga: la banda pide >= 4,87 − 2 σ. Lo bajó Final2
// (planteles más parejos: la serie cambia menos con el plan).
const DELTA_P_PLAN_MEDIDO_K5C = 4.87;
const Z_RUIDO_DELTA_P_K5C = 2;
const META_K4_BIFURCACIONES_PROMEDIO = [5, 9];
// `deltaP` del instrumento es una diferencia de probabilidades (0-1); la meta se dice en puntos porcentuales.
const PUNTOS_PORCENTUALES_K4 = 100;
const { mediana: medianaMetasB, promedio: promedioMetasB, desvioMuestral: desvioMuestralMetasB } = await import('./simulate.js');

let loteMetasB = null;
function loteDeLasMetasB() {
  if (loteMetasB === null) {
    loteMetasB = correrLote(CARRERAS_METAS_B, SPLITS_LOTE_K0, 'criterio');
    afirmarRuidoIntactoK0(`después de correrLote(${CARRERAS_METAS_B}, criterio)`);
    const v = valoresDeLasMetasB(loteMetasB);
    console.log(`     (muestra: criterio, ${CARRERAS_METAS_B} × ${SPLITS_LOTE_K0}) interrupciones por carrera ${v.interrupcionesCarrera} (mediana), por split pro p90 ${v.splitRegularP90} / ${v.splitPlayoffsP90} / ${v.splitInternacionalP90} (regular / playoffs / internacional), minijuegos ${v.minijuegosMediana}, tiempo-máquina ${v.tiempoMaquinaMin} min, Δp de plan ${v.deltaPPlanPp} pp, bifurcaciones ${v.bifurcacionesPromedio}`);
  }
  return loteMetasB;
}

// Dos decimales (la mediana de una muestra vacía es `null`, que el juez rechaza).
const redondeoMetasB = (x) => (typeof x === 'number' && Number.isFinite(x) ? Number(x.toFixed(2)) : null);

function valoresDeLasMetasB(lote) {
  const observaciones = lote.crudos.observaciones;
  const deltas = observaciones.flatMap((o) => o.planDeltaP.map((fila) => fila.deltaP * PUNTOS_PORCENTUALES_K4));
  const porSplit = lote.ritmo.interrupcionesPorSplitPro;
  return {
    interrupcionesCarrera: lote.ritmo.interrupcionesPorCarrera.mediana,
    splitRegularP90: porSplit.regular.p90,
    splitPlayoffsP90: porSplit.playoffs.p90,
    splitInternacionalP90: porSplit.internacional.p90,
    minijuegosMediana: lote.ritmo.minijuegosPorCarrera.mediana,
    tiempoMaquinaMin: lote.ritmo.tiempoMaquinaMin.mediana,
    deltaPPlanPp: redondeoMetasB(medianaMetasB(deltas)),
    // K5c: el desvío de esa mediana, √(π/2)·s/√n sobre las n paradas de plan (la banda de ruido del re-base del Δp).
    deltaPPlanSigma: deltas.length > 1 ? redondeoMetasB(Math.sqrt(Math.PI / 2) * desvioMuestralMetasB(deltas) / Math.sqrt(deltas.length)) : null,
    deltaPPlanN: deltas.length,
    bifurcacionesPromedio: redondeoMetasB(promedioMetasB(observaciones.map((o) => o.bifurcaciones)))
  };
}

// El juez: null si la meta se cumple, el motivo si no. Un valor que no existe (muestra vacía) no cumple.
function juezDeLasMetasB(v) {
  const hay = (x) => typeof x === 'number' && Number.isFinite(x);
  const juzgar = (ok, motivo) => (ok ? null : motivo);
  const [miniMin, miniMax] = META_K4_MINIJUEGOS_MEDIANA;
  const [bifMin, bifMax] = META_K4_BIFURCACIONES_PROMEDIO;
  return {
    interrupcionesCarrera: juzgar(hay(v.interrupcionesCarrera) && v.interrupcionesCarrera <= META_K4_INTERRUPCIONES_CARRERA_MEDIANA,
      `la mediana de interrupciones por carrera es ${v.interrupcionesCarrera}, la meta es <= ${META_K4_INTERRUPCIONES_CARRERA_MEDIANA}`),
    splitRegular: juzgar(hay(v.splitRegularP90) && v.splitRegularP90 <= META_K4_INTERRUPCIONES_SPLIT_REGULAR_P90,
      `el p90 de interrupciones de un split regular es ${v.splitRegularP90}, la meta es <= ${META_K4_INTERRUPCIONES_SPLIT_REGULAR_P90}`),
    splitPlayoffs: juzgar(hay(v.splitPlayoffsP90) && v.splitPlayoffsP90 <= META_K4_INTERRUPCIONES_SPLIT_PLAYOFFS_P90,
      `el p90 de interrupciones de un split de playoffs es ${v.splitPlayoffsP90}, la meta es <= ${META_K4_INTERRUPCIONES_SPLIT_PLAYOFFS_P90}`),
    splitInternacional: juzgar(hay(v.splitInternacionalP90) && v.splitInternacionalP90 <= META_K4_INTERRUPCIONES_SPLIT_INTERNACIONAL_P90,
      `el p90 de interrupciones de un split internacional es ${v.splitInternacionalP90}, la meta es <= ${META_K4_INTERRUPCIONES_SPLIT_INTERNACIONAL_P90}`),
    minijuegos: juzgar(hay(v.minijuegosMediana) && v.minijuegosMediana >= miniMin && v.minijuegosMediana <= miniMax,
      `la mediana de minijuegos por carrera es ${v.minijuegosMediana}, la meta es ${miniMin}-${miniMax}`),
    tiempoMaquina: juzgar(hay(v.tiempoMaquinaMin) && v.tiempoMaquinaMin <= META_K4_TIEMPO_MAQUINA_MIN_MEDIANA,
      `la mediana del tiempo-máquina es ${v.tiempoMaquinaMin} min, la meta es <= ${META_K4_TIEMPO_MAQUINA_MIN_MEDIANA} min`),
    deltaPPlan: juzgar(hay(v.deltaPPlanPp) && hay(v.deltaPPlanSigma)
      && v.deltaPPlanPp >= Math.min(META_K4_DELTA_P_PLAN_PP_MEDIANA, DELTA_P_PLAN_MEDIDO_K5C) - Z_RUIDO_DELTA_P_K5C * v.deltaPPlanSigma,
      `el Δp mediano de las paradas de plan es ${v.deltaPPlanPp} pp (σ ${v.deltaPPlanSigma}, n ${v.deltaPPlanN}), la banda pide >= ${META_K4_DELTA_P_PLAN_PP_MEDIANA} pp, re-basada a ${DELTA_P_PLAN_MEDIDO_K5C} − ${Z_RUIDO_DELTA_P_K5C} σ`),
    bifurcaciones: juzgar(hay(v.bifurcacionesPromedio) && v.bifurcacionesPromedio >= bifMin && v.bifurcacionesPromedio <= bifMax,
      `las bifurcaciones por carrera son ${v.bifurcacionesPromedio} en promedio, la meta es ${bifMin}-${bifMax}`)
  };
}

// Son valores que CUMPLEN (los medidos en K4c, `c6f098f`).
const VALORES_DE_LAS_METAS_B_OK = {
  interrupcionesCarrera: 84, splitRegularP90: 2, splitPlayoffsP90: 5, splitInternacionalP90: 6, minijuegosMediana: 4,
  tiempoMaquinaMin: 5.9, deltaPPlanPp: 6.5, deltaPPlanSigma: 0.15, deltaPPlanN: 3000, bifurcacionesPromedio: 7.8
};
const CLAVE_DEL_JUEZ_B = {
  interrupcionesCarrera: 'interrupcionesCarrera', splitRegularP90: 'splitRegular', splitPlayoffsP90: 'splitPlayoffs',
  splitInternacionalP90: 'splitInternacional', minijuegosMediana: 'minijuegos', tiempoMaquinaMin: 'tiempoMaquina',
  deltaPPlanPp: 'deltaPPlan', bifurcacionesPromedio: 'bifurcaciones'
};

function problemasDeLasMetasB(claves) {
  const juicio = juezDeLasMetasB(valoresDeLasMetasB(loteDeLasMetasB()));
  return claves.map((clave) => juicio[clave]).filter((motivo) => motivo !== null);
}

check('K4c metas del bloque B: el juez acepta los valores medidos y rechaza, uno por uno, cada valor fuera de meta o inexistente (regla 7)', () => {
  const sano = Object.values(juezDeLasMetasB(VALORES_DE_LAS_METAS_B_OK)).filter((motivo) => motivo !== null);
  if (sano.length > 0) throw new Error(`el juez rechaza valores que cumplen: ${sano.join('; ')}`);
  // Cada valor malo mueve SOLO su meta: un valor justo afuera de la banda, uno de antes de K4c y uno inexistente.
  const malos = {
    interrupcionesCarrera: [91, 111, null], splitRegularP90: [3, 4, null], splitPlayoffsP90: [6, 7, null], splitInternacionalP90: [7, 8, null],
    minijuegosMediana: [2, 9, 11, null], tiempoMaquinaMin: [6.6, 8.1, null], deltaPPlanPp: [4.4, 1.9, null], bifurcacionesPromedio: [4.9, 9.1, 4.15, null]
  };
  for (const [campo, valores] of Object.entries(malos)) {
    for (const valor of valores) {
      const juicio = juezDeLasMetasB({ ...VALORES_DE_LAS_METAS_B_OK, [campo]: valor });
      const rechazados = Object.entries(juicio).filter(([, motivo]) => motivo !== null).map(([k]) => k);
      if (rechazados.length !== 1 || rechazados[0] !== CLAVE_DEL_JUEZ_B[campo]) {
        throw new Error(`${campo} = ${valor}: el juez rechazó [${rechazados.join(', ')}], tenía que rechazar solo ${CLAVE_DEL_JUEZ_B[campo]}`);
      }
    }
  }
  // Los bordes de cada banda cumplen (<= y >= son inclusivos).
  const bordes = {
    interrupcionesCarrera: [META_K4_INTERRUPCIONES_CARRERA_MEDIANA], splitRegularP90: [META_K4_INTERRUPCIONES_SPLIT_REGULAR_P90],
    splitPlayoffsP90: [META_K4_INTERRUPCIONES_SPLIT_PLAYOFFS_P90], splitInternacionalP90: [META_K4_INTERRUPCIONES_SPLIT_INTERNACIONAL_P90],
    minijuegosMediana: META_K4_MINIJUEGOS_MEDIANA, tiempoMaquinaMin: [META_K4_TIEMPO_MAQUINA_MIN_MEDIANA],
    deltaPPlanPp: [META_K4_DELTA_P_PLAN_PP_MEDIANA], bifurcacionesPromedio: META_K4_BIFURCACIONES_PROMEDIO
  };
  for (const [campo, valores] of Object.entries(bordes)) {
    for (const valor of valores) {
      const motivo = juezDeLasMetasB({ ...VALORES_DE_LAS_METAS_B_OK, [campo]: valor })[CLAVE_DEL_JUEZ_B[campo]];
      if (motivo !== null) throw new Error(`${campo} = ${valor} (el borde de la banda) no cumple: ${motivo}`);
    }
  }
});

// Reemplaza a "≤ 80 interrupciones por carrera" (propuesta de §K.3c), que exigía ≤ 80 con `criterio` (medido 84, 400 × 60): lo que queda
// arriba de 80 es el cierre de año, que el usuario decidió conservar con más peso (el plan anual), y el reparto amateur (100% de
// palanca). Protege "el ritmo es de decisiones con algo en juego" desde K4c (paso 3b).
checkLento(`K4c meta del ritmo (criterio, ${CARRERAS_METAS_B} × ${SPLITS_LOTE_K0}): la mediana de interrupciones por carrera es <= ${META_K4_INTERRUPCIONES_CARRERA_MEDIANA}`, () => {
  const problemas = problemasDeLasMetasB(['interrupcionesCarrera']);
  if (problemas.length > 0) throw new Error(problemas.join('; '));
});

// Reemplaza a "≤ 2 interrupciones por split pro; ≤ 4 en playoffs e internacional" (propuesta de §K.3c), que exigía ≤ 4 en playoffs e
// internacional (medido p90 5 en los dos): una serie de playoffs con plan, mapa decisivo y minijuego son 4-5 paradas con palanca. El regular
// se queda en p90 ≤ 2. Protege que ningún split se vuelva una maratón de pausas desde K4c (paso 3b).
checkLento(`K4c meta del ritmo (criterio, ${CARRERAS_METAS_B} × ${SPLITS_LOTE_K0}): el p90 de interrupciones por split pro es <= ${META_K4_INTERRUPCIONES_SPLIT_REGULAR_P90} en regular, <= ${META_K4_INTERRUPCIONES_SPLIT_PLAYOFFS_P90} en playoffs y <= ${META_K4_INTERRUPCIONES_SPLIT_INTERNACIONAL_P90} en internacional`, () => {
  const problemas = problemasDeLasMetasB(['splitRegular', 'splitPlayoffs', 'splitInternacional']);
  if (problemas.length > 0) throw new Error(problemas.join('; '));
});

// Reemplaza a "minijuegos por carrera, mediana 4-8" (propuesta de §K.3c), que exigía 4 de piso (medido 4): el piso baja a 3 como margen de
// muestra; que no sean decorativos lo cubre "El impacto de los minijuegos". Protege que los minijuegos ni desaparezcan ni sean la carrera.
checkLento(`K4c meta del ritmo (criterio, ${CARRERAS_METAS_B} × ${SPLITS_LOTE_K0}): la mediana de minijuegos por carrera está en [${META_K4_MINIJUEGOS_MEDIANA[0]}, ${META_K4_MINIJUEGOS_MEDIANA[1]}]`, () => {
  const problemas = problemasDeLasMetasB(['minijuegos']);
  if (problemas.length > 0) throw new Error(problemas.join('; '));
});

// Reemplaza a "tiempo-máquina ≤ ~4,6 min" (propuesta de §K.3c), que exigía ≤ ~4,6 (medido 5,9): el tiempo real lo mide K6 en el navegador.
// Protege que lo que el jugador mira (beats × 700 ms del instrumento) no crezca sin que alguien lo decida, desde K4c (paso 3b).
checkLento(`K4c meta del ritmo (criterio, ${CARRERAS_METAS_B} × ${SPLITS_LOTE_K0}): la mediana del tiempo-máquina es <= ${META_K4_TIEMPO_MAQUINA_MIN_MEDIANA} min`, () => {
  const problemas = problemasDeLasMetasB(['tiempoMaquina']);
  if (problemas.length > 0) throw new Error(problemas.join('; '));
});

// Reemplaza a "el plan de serie mueve la p" (propuesta de §K.3c, sin número), que exigía solo que la serie fuera un plan: el Δp (p de la
// mejor opción − p de la peor, de la `pSerie` que declara cada opción de `serie:plan` e `internacional:plan`), mediana ≥ 5 pp (medido ~6,5).
// Protege el ×3 del plan de serie de K4c (paso 3a): con ×1 la mediana era 1,9 pp.
checkLento(`K4c meta del ritmo (criterio, ${CARRERAS_METAS_B} × ${SPLITS_LOTE_K0}): el Δp mediano de las paradas de plan de serie es >= ${META_K4_DELTA_P_PLAN_PP_MEDIANA} pp`, () => {
  const problemas = problemasDeLasMetasB(['deltaPPlan']);
  if (problemas.length > 0) throw new Error(problemas.join('; '));
});

// Reemplaza a "las bifurcaciones frenan entre 4,5 y 7,5 veces por carrera" (K4-C2, 40 carreras; la propuesta de §K.3c era 4,5-7,5), que
// exigía ≤ 7,5 (medido 7,8 en 400 × 60): la banda pasa a [5, 9] con la muestra de 400 en vez de 40. Protege que solo frenen las
// bifurcaciones (K4-C) y que frenen lo justo, desde K4c (paso 3b).
checkLento(`K4c meta del ritmo (criterio, ${CARRERAS_METAS_B} × ${SPLITS_LOTE_K0}): las bifurcaciones por carrera, en promedio, están en [${META_K4_BIFURCACIONES_PROMEDIO[0]}, ${META_K4_BIFURCACIONES_PROMEDIO[1]}]`, () => {
  const problemas = problemasDeLasMetasB(['bifurcaciones']);
  if (problemas.length > 0) throw new Error(problemas.join('; '));
});

// --- K4c (paso 3b): el guardado VERSION 11 y la migración desde la 10 (T4: el estado completo) ---
//
// VERSION 10 es la de main (K5, forma '7128c450fa6c'); la 11 es la del plan anual: `player.planAnual` entra, `flags.preparacionDeSplit`
// se va, los logs ganan `adjunto` (opcional) y la pausa de la prueba del mercado lleva `respaldo` (el código lo calcula si falta). Un
// guardado de la 10 TIENE que cargar: `migrarDe10` lo completa con el plan del perfil, el mismo que el estado inicial. Regla 17, qué
// protege: "el guardado de la versión anterior no se pierde cuando cambia la forma del estado" (K.7 riesgo 3), desde K4c (paso 3b).
const { migrarDe10 } = await import('../core/guardado.js');
const { isDeepStrictEqual: sonIgualesK4cG } = await import('util');
const { planInicial: planInicialK4cG, IDS_PLAN: IDS_PLAN_K4cG } = await import('../core/rutinas.js');
const FORMA_DE_LA_VERSION_10_K4cG = '7128c450fa6c';
const PREPARACION_DE_SPLIT_VIEJA_K4cG = 4;
const SEEDS_GUARDADO_10_K4cG = [1, 2, 3, 4];
const SPLITS_GUARDADO_10_K4cG = 14;

// Lo que escribía el código de VERSION 10: sin `planAnual`, con `flags.preparacionDeSplit` y sin `adjunto` en los logs.
function guardadoDeLaVersion10K4cG(state, rng) {
  const datos = JSON.parse(serializarGuardado(state, rng));
  datos.version = 10;
  delete datos.state.player.planAnual;
  // K5c (VERSION 12): ni la 10 ni la 11 escribían los campos de la 12 (la migración los completa): `player.desgaste` de E, y la
  // cuenta de la presión de tier 2 y el marcador de los años pro de R.
  delete datos.state.player.desgaste;
  delete datos.state.flags.splitsTier2SinOfertaTier1;
  delete datos.state.career.splitPrimerContratoTier2;
  datos.state.flags.preparacionDeSplit = PREPARACION_DE_SPLIT_VIEJA_K4cG;
  // K4c (revisión): la 10 tampoco escribía `flags.pruebasFallidas` (la migración lo arranca vacío).
  delete datos.state.flags.pruebasFallidas;
  for (const log of datos.state.logs) {
    delete log.adjunto;
  }
  return JSON.stringify(datos);
}

// Lo que JSON conserva (el guardado pasa por JSON): sin `undefined`, y sin `adjunto` (que el código de VERSION 10 no escribía, y el
// guardado de prueba lo borra), y sin importar el orden de las claves al comparar.
const comoJsonK4cG = (valor) => JSON.parse(JSON.stringify(valor), (clave, hijo) => (clave === 'adjunto' ? undefined : hijo));

function conElRngDeK4cG(seed, estado) {
  const rng = mulberry32(seed);
  rng.restaurar(estado);
  return rng;
}

check('K4c guardado VERSION 11: la forma de la 10 sigue registrada, y un guardado de la 10 carga completo (plan del perfil, sin preparacionDeSplit) y sigue igual que el de la 11', () => {
  // K5c (integración de E y R): la 12 sale después de la 11. Reemplaza a "VERSION es 11 y la 12 se descarta", que fijaba la versión
  // actual: un guardado de la 10 se sigue cargando (pasa por `migrarDe10` y `migrarDe11`) y lo que viene después de la actual se descarta.
  if (VERSION_GUARDADO < 11 || FORMAS_CONOCIDAS[10] !== FORMA_DE_LA_VERSION_10_K4cG || FORMAS_CONOCIDAS[11] === FORMAS_CONOCIDAS[10]) {
    throw new Error(`VERSION ${VERSION_GUARDADO}, forma de la 10 ${FORMAS_CONOCIDAS[10]} (la de main es ${FORMA_DE_LA_VERSION_10_K4cG}), forma de la 11 ${FORMAS_CONOCIDAS[11]}`);
  }
  // Una versión que no es la actual ni una migrable (la 11, la 10) se sigue descartando entera.
  const rngVacio = mulberry32(1);
  const base = JSON.parse(serializarGuardado(createInitialState(1, rngVacio), rngVacio));
  for (const version of [2, 9, VERSION_GUARDADO + 1]) {
    if (deserializarGuardado(JSON.stringify({ ...base, version })) !== null) {
      throw new Error(`un guardado de VERSION ${version} cargó: solo la ${VERSION_GUARDADO}, la 11 y la 10 (migradas) se cargan`);
    }
  }
  let comparados = 0;
  for (const seed of SEEDS_GUARDADO_10_K4cG) {
    const rng = mulberry32(seed);
    let state = createInitialState(seed, rng);
    for (let i = 0; i < SPLITS_GUARDADO_10_K4cG && !state.terminado; i += 1) {
      // Mientras ningún cierre de año fijó otro plan, el que el guardado viejo no traía es exactamente el del perfil (y mientras
      // ninguna prueba falló sin respaldo, `pruebasFallidas` vacío).
      if (state.player.planAnual === planInicialK4cG(state.player.perfil.actual) && state.flags.pruebasFallidas.length === 0) {
        const datos = deserializarGuardado(guardadoDeLaVersion10K4cG(state, rng));
        if (datos === null) {
          throw new Error(`seed ${seed}, split ${i}: el guardado de VERSION 10 no cargó`);
        }
        if ('preparacionDeSplit' in datos.state.flags || !IDS_PLAN_K4cG.includes(datos.state.player.planAnual)) {
          throw new Error(`seed ${seed}, split ${i}: sin migrar (preparacionDeSplit ${'preparacionDeSplit' in datos.state.flags}, planAnual ${datos.state.player.planAnual})`);
        }
        if (!sonIgualesK4cG(datos.state, comoJsonK4cG(state))) {
          throw new Error(`seed ${seed}, split ${i}: el estado migrado no es el del guardado de la 11`);
        }
        // Y sigue igual: el mismo próximo split (estado, logs y RNG) que el de la versión nueva.
        const seguido = avanzarSplitAuto(state, conElRngDeK4cG(seed, rng.estado()));
        const rngMigrado = conElRngDeK4cG(datos.seed, datos.rngEstado);
        const recargado = avanzarSplitAuto(datos.state, rngMigrado);
        if (!sonIgualesK4cG(comoJsonK4cG(seguido), comoJsonK4cG(recargado))) {
          throw new Error(`seed ${seed}, split ${i}: el guardado migrado no juega el mismo split`);
        }
        comparados += 1;
      }
      state = avanzarSplitAuto(state, rng).state;
    }
  }
  if (comparados < 20) {
    throw new Error(`check vacío: ${comparados} guardados de la 10 comparados (hacen falta 20)`);
  }
  // Un guardado sin `planAnual` ni perfil conocido cae al plan por defecto en vez de tirar.
  const sinPerfil = migrarDe10({ flags: {}, player: {} });
  if (!IDS_PLAN_K4cG.includes(sinPerfil.player.planAnual)) {
    throw new Error(`un guardado sin perfil debería caer al plan por defecto, dio ${sinPerfil.player.planAnual}`);
  }
});

// --- K5c-R: el guardado VERSION 12 y la migración desde la 11 ---
//
// Regla 17, qué protege: "el guardado de la versión anterior no se pierde cuando cambia la forma del estado" (K.7 riesgo 3), para la
// 12 de K5c-R (`flags.splitsTier2SinOfertaTier1` y `career.splitPrimerContratoTier2`, que `migrarDe11` reconstruye del registro).
// Desde K5c-R.
const { migrarDe11: migrarDe11K5CR } = await import('../core/guardado.js');
// K6a-M: [1, 2, 3, 4] -> [1..6] (el stream cambió: con cuatro seeds quedaban 18 guardados con el marcador, hacen falta 20).
const SEEDS_GUARDADO_11_K5CR = [1, 2, 3, 4, 5, 6];
const SPLITS_GUARDADO_11_K5CR = 30;

// Lo que escribía el código de VERSION 11: sin los campos de la 12.
function guardadoDeLaVersion11K5CR(state, rng) {
  const datos = JSON.parse(serializarGuardado(state, rng));
  datos.version = 11;
  delete datos.state.flags.splitsTier2SinOfertaTier1;
  delete datos.state.career.splitPrimerContratoTier2;
  delete datos.state.career.splitsRetirado;
  return JSON.stringify(datos);
}

check('K5c-R guardado VERSION 12: la forma de la 11 sigue registrada, y un guardado de la 11 carga completo y sigue igual que el de la 12', () => {
  // K6b: la 13 migra la 11 por `migrarDe11` y `migrarDe12`; este check sigue valiendo para toda versión >= 12.
  if (VERSION_GUARDADO < 12 || FORMAS_CONOCIDAS[12] === undefined || FORMAS_CONOCIDAS[12] === FORMAS_CONOCIDAS[11]) {
    throw new Error(`VERSION ${VERSION_GUARDADO}, forma de la 11 ${FORMAS_CONOCIDAS[11]}, forma de la 12 ${FORMAS_CONOCIDAS[12]}`);
  }
  let comparados = 0;
  let conMarcador = 0;
  for (const seed of SEEDS_GUARDADO_11_K5CR) {
    const rng = mulberry32(seed);
    let state = createInitialState(seed, rng);
    for (let i = 0; i < SPLITS_GUARDADO_11_K5CR && !state.terminado; i += 1) {
      const datos = deserializarGuardado(guardadoDeLaVersion11K5CR(state, rng));
      if (datos === null) {
        throw new Error(`seed ${seed}, split ${i}: el guardado de VERSION 11 no cargó`);
      }
      // La única diferencia permitida: `career.splitsRetirado`. La 11 no lo cargaba, así que el migrado lo trae en 0 aunque el real tenga
      // k (los años de las ventanas viejas no se corrigen hacia atrás). El check exige ese 0 y compara todo lo demás con el real en 0.
      if (datos.state.career.splitsRetirado !== 0) {
        throw new Error(`seed ${seed}, split ${i}: el migrado trae splitsRetirado ${datos.state.career.splitsRetirado} y debería traer 0`);
      }
      // K5c paso 3b: lo mismo con la cuenta de la presión de tier 2. Con las perillas neutras (99) nunca subía y el real la tenía en 0;
      // con las de Final2 sube desde los 20, y la 11 no la contaba: `migrarDe11` la arranca en 0 (su doc) y el check exige ese 0.
      if (datos.state.flags.splitsTier2SinOfertaTier1 !== 0) {
        throw new Error(`seed ${seed}, split ${i}: el migrado trae la cuenta de la presión en ${datos.state.flags.splitsTier2SinOfertaTier1} y debería traer 0`);
      }
      const realSinRetirado = {
        ...state, career: { ...state.career, splitsRetirado: 0 }, flags: { ...state.flags, splitsTier2SinOfertaTier1: 0 }
      };
      if (!sonIgualesK4cG(datos.state, JSON.parse(JSON.stringify(realSinRetirado)))) {
        throw new Error(`seed ${seed}, split ${i}: el estado migrado no es el del guardado de la 12`);
      }
      const seguido = avanzarSplitAuto(realSinRetirado, conElRngDeK4cG(seed, rng.estado()));
      const recargado = avanzarSplitAuto(datos.state, conElRngDeK4cG(datos.seed, datos.rngEstado));
      if (!sonIgualesK4cG(comoJsonK4cG(seguido), comoJsonK4cG(recargado))) {
        throw new Error(`seed ${seed}, split ${i}: el guardado migrado no juega el mismo split`);
      }
      comparados += 1;
      conMarcador += state.career.splitPrimerContratoTier2 === null ? 0 : 1;
      state = avanzarSplitAuto(state, rng).state;
    }
  }
  if (comparados < 40 || conMarcador < 20) {
    throw new Error(`check vacío: ${comparados} guardados de la 11 comparados (hacen falta 40), ${conMarcador} con el marcador de los años pro (hacen falta 20)`);
  }
  // Un estado sin flags (un guardado roto a medias) se completa en vez de tirar.
  if (migrarDe11K5CR({}).flags.splitsTier2SinOfertaTier1 !== 0) {
    throw new Error('migrarDe11 sin flags no arranca la cuenta en 0');
  }
});

// K6b (integración): VERSION 13. Las fotos de la cola (`flags.seguisFirma`, `flags.finMercadoFirma`, `flags.vueltaFirma` y
// `flags.colaFirmas`) no existían en la 12; `migrarDe12` las arranca en "no hay foto". Los guardados de la 12 se hacen desde
// carreras reales (a 60 splits, para llegar a la cola y tener fotos de verdad) quitándoles lo que la 12 no escribía.
const { migrarDe12: migrarDe12K6B } = await import('../core/guardado.js');
const SEEDS_GUARDADO_12_K6B = [1, 2, 3, 4];
const SPLITS_GUARDADO_12_K6B = 60;
const FOTOS_VACIAS_K6B = { seguisFirma: null, finMercadoFirma: null, vueltaFirma: null, colaFirmas: { cierre: null, momento: null } };
const MINIMO_CON_FOTO_K6B = 5;
function guardadoDeLaVersion12K6B(state, rng) {
  const datos = JSON.parse(serializarGuardado(state, rng));
  datos.version = 12;
  for (const clave of Object.keys(FOTOS_VACIAS_K6B)) delete datos.state.flags[clave];
  return JSON.stringify(datos);
}
const tieneFotoK6B = (st) => st.flags.seguisFirma != null || st.flags.finMercadoFirma != null || st.flags.vueltaFirma != null
  || st.flags.colaFirmas?.cierre != null || st.flags.colaFirmas?.momento != null;

check('K6b guardado VERSION 13: la forma de la 12 (la de main) sigue registrada, y un guardado de la 12 carga completo (las fotos de la cola en "no hay foto") y sigue igual que el de la 13', () => {
  if (VERSION_GUARDADO !== 13 || FORMAS_CONOCIDAS[12] !== '859f8c5ba041' || FORMAS_CONOCIDAS[13] === undefined || FORMAS_CONOCIDAS[13] === FORMAS_CONOCIDAS[12]) {
    throw new Error(`VERSION ${VERSION_GUARDADO}, forma de la 12 ${FORMAS_CONOCIDAS[12]}, forma de la 13 ${FORMAS_CONOCIDAS[13]}`);
  }
  let comparados = 0;
  let conFoto = 0;
  let mutanteMuerde = 0;
  for (const seed of SEEDS_GUARDADO_12_K6B) {
    const rng = mulberry32(seed);
    let state = createInitialState(seed, rng);
    for (let i = 0; i < SPLITS_GUARDADO_12_K6B && !state.terminado; i += 1) {
      const json = guardadoDeLaVersion12K6B(state, rng);
      const datos = deserializarGuardado(json);
      if (datos === null) {
        throw new Error(`seed ${seed}, split ${i}: el guardado de VERSION 12 no cargó`);
      }
      const realSinFotos = { ...state, flags: { ...state.flags, ...FOTOS_VACIAS_K6B } };
      if (!sonIgualesK4cG(datos.state, JSON.parse(JSON.stringify(realSinFotos)))) {
        throw new Error(`seed ${seed}, split ${i}: el estado migrado no es el de la 13 con las fotos en null`);
      }
      // Mutante (regla 7): el mismo guardado sin `migrarDe12` no tiene la forma de la 13.
      mutanteMuerde += sonIgualesK4cG(JSON.parse(json).state, JSON.parse(JSON.stringify(realSinFotos))) ? 0 : 1;
      const seguido = avanzarSplitAuto(realSinFotos, conElRngDeK4cG(seed, rng.estado()));
      const recargado = avanzarSplitAuto(datos.state, conElRngDeK4cG(datos.seed, datos.rngEstado));
      if (!sonIgualesK4cG(comoJsonK4cG(seguido), comoJsonK4cG(recargado))) {
        throw new Error(`seed ${seed}, split ${i}: el guardado migrado no juega el mismo split`);
      }
      comparados += 1;
      conFoto += tieneFotoK6B(state) ? 1 : 0;
      state = avanzarSplitAuto(state, rng).state;
    }
  }
  if (comparados < 40 || conFoto < MINIMO_CON_FOTO_K6B) {
    throw new Error(`check vacío: ${comparados} guardados de la 12 comparados (hacen falta 40), ${conFoto} con alguna foto de la cola (hacen falta ${MINIMO_CON_FOTO_K6B})`);
  }
  if (mutanteMuerde !== comparados) {
    throw new Error(`el mutante (sin migrarDe12) pasa en ${comparados - mutanteMuerde} de ${comparados} guardados: el check no muerde`);
  }
  // Un estado sin flags (un guardado roto a medias) se completa en vez de tirar.
  const sinFlags = migrarDe12K6B({}).flags;
  if (sinFlags.seguisFirma !== null || sinFlags.colaFirmas.cierre !== null || sinFlags.colaFirmas.momento !== null) {
    throw new Error(`migrarDe12 sin flags no arranca las fotos en null: ${JSON.stringify(sinFlags)}`);
  }
  console.log(`      ${comparados} guardados de la 12 cargados y seguidos (${conFoto} con alguna foto de la cola); sin migrarDe12 fallan ${mutanteMuerde}`);
});

// K4c (revisión): un guardado de la 10 parado en la prueba del mercado traía la apuesta vieja (sin "si no alcanza": la prueba de la 10
// firmaba siempre), sin `respaldo` (y antes de K4c-S sin `otras`) y con la `preparacion`; uno parado en un cierre, las opciones sin la
// línea del plan y el evento sin el plan de cada opción (no lo mostraba ni lo fijaba). `migrarDe10` los rearma con lo de hoy (regla 15).
// Los guardados se hacen a mano desde las pausas reales de `criterio` (las carreras de K4c-P), quitándoles lo que la 10 no escribía.
const { lineaDePlan: lineaDePlanK4cG } = await import('../systems/practica.js');
check('K4c (revisión) guardado VERSION 10 parado en la prueba del mercado o en un cierre: la migración rearma la pausa con el respaldo, el plan y el texto de hoy', () => {
  const aLa10 = (paso, tocar) => {
    const datos = JSON.parse(serializarGuardado(paso.antes, mulberry32(paso.seed)));
    datos.version = 10;
    delete datos.state.player.planAnual;
    delete datos.state.flags.pruebasFallidas;
    datos.state.flags.preparacionDeSplit = -1;
    tocar(datos.state.pendiente.decision);
    const cargado = deserializarGuardado(JSON.stringify(datos));
    if (cargado === null) throw new Error(`seed ${paso.seed}, split ${paso.split}: el guardado de la 10 no cargó`);
    return cargado.state;
  };
  let cierres = 0;
  let pruebas = 0;
  for (const paso of corridasK4cP().pasos) {
    const donde = `seed ${paso.seed}, split ${paso.split} (${paso.sistemaId})`;
    if (paso.sistemaId === 'edadCierre' && paso.antes.phase === 'profesional' && paso.antes.player.planAnual === planInicialK4cG(paso.antes.player.perfil.actual)) {
      const migrado = aLa10(paso, (decision) => {
        for (const opcion of [...decision.opciones, ...decision.datos.evento.options]) delete opcion.plan;
      });
      const decision = migrado.pendiente.decision;
      for (const opcion of decision.opciones) {
        const planId = decision.datos.evento.options.find((o) => o.id === opcion.id)?.plan;
        if (!IDS_PLAN_K4cG.includes(planId) || opcion.plan?.texto !== lineaDePlanK4cG(migrado, planId)?.texto) {
          throw new Error(`${donde}: la opción "${opcion.label}" del cierre migrado no dice su plan (${JSON.stringify(opcion.plan)})`);
        }
      }
      if (!sonIgualesK4cG(comoJsonK4cG(decision), comoJsonK4cG(paso.decision))) throw new Error(`${donde}: el cierre migrado no es el que arma la 11`);
      const elegido = decision.datos.evento.options.find((o) => o.id === paso.respuesta.opcionId).plan;
      const resuelto = resolverDecision(migrado, paso.respuesta, mulberry32(paso.seed)).state;
      if (resuelto.player.planAnual !== elegido) throw new Error(`${donde}: el cierre migrado no fijó el plan elegido (${elegido} → ${resuelto.player.planAnual})`);
      cierres += 1;
    }
    if (paso.sistemaId === 'mercado' && paso.decision.datos.momento === 'tryout') {
      const vieja = (decision) => {
        decision.datos.apuesta = decision.datos.apuesta.split(' Si no alcanza')[0];
        decision.datos.preparacion = { rutinas: [], elegida: null };
        delete decision.datos.respaldo;
      };
      // Con `otras` (de K4c-S, antes del paso 3a): la misma pausa que arma la 11.
      const conOtras = aLa10(paso, vieja).pendiente.decision;
      if (!sonIgualesK4cG(comoJsonK4cG(conOtras), comoJsonK4cG(paso.decision))) {
        throw new Error(`${donde}: la prueba migrada no es la que arma la 11 (respaldo ${conOtras.datos.respaldo}, apuesta "${conOtras.datos.apuesta}")`);
      }
      // Sin `otras` (antes de K4c-S): no hay con quién seguir, y la apuesta lo dice.
      const sinOtras = aLa10(paso, (decision) => { vieja(decision); delete decision.datos.otras; delete decision.datos.carry; }).pendiente.decision;
      if (sinOtras.datos.respaldo !== null || !sinOtras.datos.apuesta.endsWith('Si no alcanza, esta ventana no firmás con nadie.') || 'preparacion' in sinOtras.datos) {
        throw new Error(`${donde}: la prueba migrada sin otras ofertas (respaldo ${sinOtras.datos.respaldo}, apuesta "${sinOtras.datos.apuesta}")`);
      }
      pruebas += 1;
    }
  }
  if (cierres < 3 || pruebas < 1) throw new Error(`check vacío: ${cierres} cierres pro y ${pruebas} pruebas del mercado`);
});

check('K4c guardado VERSION 11: un guardado de la 10 parado en la pausa de la práctica (que ya no existe) se reemplaza por un botón y sigue igual que un split sin pausa', () => {
  const posicion = ETAPAS_SPLIT.findIndex((sistema) => sistema.id === 'practica');
  const original = ETAPAS_SPLIT[posicion];
  // La pausa que escribía VERSION 10, hecha a mano: en un split pro, la etapa de la práctica frena sin entrenar.
  const pausaVieja = {
    presentacion: 'pretemporada',
    titulo: 'La pretemporada',
    descripcion: 'Elegí tu preparación.',
    opciones: [{ id: 'bootcamp_corea', label: 'Bootcamp' }, { id: 'descanso', label: 'Descanso' }],
    datos: { motivo: 'practica', rutinas: [] }
  };
  let comparados = 0;
  for (const seed of SEEDS_GUARDADO_10_K4cG) {
    const rng = mulberry32(seed);
    let state = createInitialState(seed, rng);
    for (let i = 0; i < SPLITS_GUARDADO_10_K4cG && !state.terminado && comparados === 0; i += 1) {
      if (state.phase === 'profesional' && state.player.planAnual === planInicialK4cG(state.player.perfil.actual)) {
        const estadoAntes = rng.estado();
        let guardado = null;
        ETAPAS_SPLIT[posicion] = { ...original, aplicar: (st, r) => (st.phase === 'profesional' ? { state: st, logs: [], decision: pausaVieja } : original.aplicar(st, r)) };
        try {
          const paso = avanzarSplit(state, rng);
          if (paso.state.pendiente?.sistemaId === 'practica') {
            guardado = guardadoDeLaVersion10K4cG(paso.state, rng);
          }
        } finally {
          ETAPAS_SPLIT[posicion] = original;
        }
        if (guardado === null) {
          break;
        }
        const datos = deserializarGuardado(guardado);
        const pendiente = datos?.state.pendiente;
        if (!pendiente || pendiente.sistemaId !== 'practica' || pendiente.decision.opciones.length !== 1 || pendiente.decision.opciones[0].id !== 'seguir') {
          throw new Error(`seed ${seed}: la pausa de la práctica no se reemplazó por el botón (${JSON.stringify(pendiente?.decision?.opciones)})`);
        }
        // Seguir (la respuesta del botón, y la del bot) cierra la pausa y termina el split como si nunca hubiera frenado.
        const rngLegado = conElRngDeK4cG(datos.seed, datos.rngEstado);
        let legado = { state: datos.state, logs: [] };
        while (legado.state.pendiente) {
          const { sistemaId, decision } = legado.state.pendiente;
          const respuesta = sistemaId === 'practica' ? { opcionId: 'seguir' } : sistemaPorId(sistemaId).resolverAuto(legado.state, decision, rngLegado);
          legado = resolverDecision(legado.state, respuesta, rngLegado);
        }
        const sinPausa = avanzarSplitAuto(state, conElRngDeK4cG(seed, estadoAntes));
        // La pausa vieja gastó una interrupción del cupo del split (`presupuesto.gastadas`); lo demás es idéntico.
        const sinCupo = (estado) => ({ ...estado, presupuesto: undefined });
        if (!sonIgualesK4cG(comoJsonK4cG(sinCupo(legado.state)), comoJsonK4cG(sinCupo(sinPausa.state))) || !JSON.stringify(legado.state.logs).includes('Entrenaste según el plan del año')) {
          throw new Error(`seed ${seed}: seguir desde la pausa vieja no dejó el estado de un split sin pausa`);
        }
        comparados += 1;
      }
      state = avanzarSplitAuto(state, rng).state;
    }
  }
  if (comparados === 0) {
    throw new Error('check vacío: ninguna carrera llegó a un split pro con el plan inicial para probar la pausa vieja');
  }
});

// ============================================================================
// K5c-E: el desgaste (PLAN.md, "K5c: decisiones de spec de la estructura")
// ============================================================================
//
// Pasado `edadPico + gracia`, los acumulativos pierden un término determinista por split y el bonus permanente decae una
// fracción (`BALANCE.atributos.desgaste`). Las perillas valen 0 en el repo (la huella del juego no se mueve: la prueba "K1
// versión"); estos checks las prenden EN MEMORIA, como `conUmbralK5C`, y las restauran.
// Seeds que juegan hasta pasado el pico. Eran fijas ([1, 2, 3, 7]: las seeds 4 y 10 terminaban a los 24 años, antes de que nada se
// gastara) y el stream de K6a las vació (con la integración el desgaste muerde en 1 de esas 4 y queda 1 veterano). Regla 17: se buscan
// en ronda, seeds 1 a `TOPE_SEEDS_K5CE`: `CUANTAS_SEEDS_K5CE` carreras donde el desgaste muerde (con las perillas prendidas) para los
// checks que miran la mordida, y `VETERANOS_K5CE` veteranos con bonus para el del veterano (check vacío si el tope no alcanza).
const TOPE_SEEDS_K5CE = 40;
const CUANTAS_SEEDS_K5CE = 4;
const VETERANOS_K5CE = 3;
const SPLITS_K5CE = 90;
const DESGASTE_K5CE = {
  graciaAnios: 2,
  perdidaPorSplit: { macro: 0.2, shotcalling: 0.25, adaptabilidad: 0.2 },
  aceleracionPorAnio: 0.1,
  fraccionBonusPorSplit: 0.1
};
const { aplicar: aplicarAtributosK5ce } = await import('../systems/atributos.js');
const {
  ORIGEN_DESGASTE: ORIGEN_DESGASTE_K5CE, hayDesgaste: hayDesgasteK5ce, aniosDeDesgaste: aniosDeDesgasteK5ce,
  perdidaDeAcumulativo: perdidaDeAcumulativoK5ce
} = await import('../core/curvas.js');
const { isDeepStrictEqual: sonIgualesK5ce } = await import('util');
const ACUMULATIVOS_K5CE = Object.keys(BALANCE.atributos.acumulativos);
const TEXTO_PRIMERA_VEZ_K5CE = /cobrar los años|Los años empiezan/;
// K5c paso 3b: el paso 3a prendió las perillas en el repo (Final2), así que "apagado" ya no es el repo: es este neutro, fijado EN
// MEMORIA (con pérdida, aceleración y fracción en 0 el sistema no toca nada). "Prendido" es el ejemplo de arriba (`DESGASTE_K5CE`,
// con gracia 2 para probar la gracia) en los checks del mecanismo, y los valores del repo (`DESGASTE_REAL_K5CE`, una copia tomada al
// cargar) en los de efecto: el veterano y lo que se ve.
const DESGASTE_NEUTRO_K5CE = {
  graciaAnios: 0,
  perdidaPorSplit: Object.fromEntries(Object.keys(BALANCE.atributos.desgaste.perdidaPorSplit).map((stat) => [stat, 0])),
  aceleracionPorAnio: 0,
  fraccionBonusPorSplit: 0
};
const DESGASTE_REAL_K5CE = structuredClone(BALANCE.atributos.desgaste);

function conDesgasteK5CE(valores, fn) {
  const d = BALANCE.atributos.desgaste;
  const previo = { ...d, perdidaPorSplit: { ...d.perdidaPorSplit } };
  Object.assign(d, { ...valores, perdidaPorSplit: { ...valores.perdidaPorSplit } });
  try {
    return fn();
  } finally {
    Object.assign(d, previo);
  }
}

// Una carrera con las perillas prendidas, split a split: `visita(antes, despues, logs)` en cada paso.
function carreraConDesgasteK5CE(seed, visita, valores = DESGASTE_K5CE) {
  const rng = mulberry32(seed);
  let state = createInitialState(seed, rng);
  for (let i = 0; i < SPLITS_K5CE && !state.terminado; i += 1) {
    const antes = state;
    const paso = conDesgasteK5CE(valores, () => avanzarSplitAuto(state, rng));
    state = paso.state;
    visita(antes, state, paso.logs);
  }
  return state;
}

// Las seeds de la ronda donde el desgaste muerde con esos valores (una vez por corrida y por valores: la búsqueda juega las carreras
// con las perillas prendidas).
const seedsQueMuerdenK5CE = new Map();
function seedsDelDesgasteK5CE(valores = DESGASTE_K5CE) {
  if (!seedsQueMuerdenK5CE.has(valores)) {
    const seeds = [];
    for (let seed = 1; seed <= TOPE_SEEDS_K5CE && seeds.length < CUANTAS_SEEDS_K5CE; seed += 1) {
      let mordio = false;
      carreraConDesgasteK5CE(seed, (antes, despues) => {
        mordio = mordio || hayDesgasteK5ce(despues.player);
      }, valores);
      if (mordio) {
        seeds.push(seed);
      }
    }
    seedsQueMuerdenK5CE.set(valores, seeds);
  }
  const seeds = seedsQueMuerdenK5CE.get(valores);
  if (seeds.length < CUANTAS_SEEDS_K5CE) {
    throw new Error(`check vacío: el desgaste mordió en ${seeds.length} carreras de las seeds 1-${TOPE_SEEDS_K5CE} (hacen falta ${CUANTAS_SEEDS_K5CE})`);
  }
  return seeds;
}

check('K5c-E neutro y gracia: misma seed con las perillas prendidas y apagadas da el mismo estado split por split hasta que el desgaste muerde la primera vez, y nunca muerde con edad <= edadPico + gracia', () => {
  let mordieron = 0;
  const seedsK5ce = seedsDelDesgasteK5CE();
  for (const seed of seedsK5ce) {
    const rngApagado = mulberry32(seed);
    let apagado = createInitialState(seed, rngApagado);
    let split = 0;
    let yaMordio = false;
    carreraConDesgasteK5CE(seed, (antes, despues) => {
      split += 1;
      apagado = conDesgasteK5CE(DESGASTE_NEUTRO_K5CE, () => avanzarSplitAuto(apagado, rngApagado)).state;
      const limite = despues.player.oculto.edadPico + DESGASTE_K5CE.graciaAnios;
      if (hayDesgasteK5ce(despues.player) && despues.age <= limite) {
        throw new Error(`seed ${seed}, split ${split}: el desgaste mordió con edad ${despues.age} <= edadPico + gracia (${limite})`);
      }
      if (!yaMordio && hayDesgasteK5ce(despues.player)) {
        yaMordio = true;
        mordieron += 1;
      }
      if (!yaMordio && !sonIgualesK5ce(comoJsonK4cG(despues), comoJsonK4cG(apagado))) {
        throw new Error(`seed ${seed}, split ${split}: antes de la primera mordida el estado con las perillas prendidas ya no es el del juego apagado`);
      }
    });
  }
  if (mordieron < seedsK5ce.length) {
    throw new Error(`check vacío: el desgaste mordió en ${mordieron} de ${seedsK5ce.length} carreras`);
  }
  console.log(`      seeds de la ronda donde muerde: ${seedsK5ce.join(', ')}`);
  // Y en seco, sobre un estado pro real: con la edad en cada tramo hasta el pico más la gracia el sistema da lo mismo que apagado,
  // y un año después muerde (un acumulativo queda más bajo).
  const rng = mulberry32(2);
  let estado = createInitialState(2, rng);
  for (let i = 0; i < 40 && !estado.terminado; i += 1) {
    estado = avanzarSplitAuto(estado, rng).state;
  }
  const limite = estado.player.oculto.edadPico + DESGASTE_K5CE.graciaAnios;
  const corrida = (edad, prendido) => {
    const conEdad = { ...estado, age: edad };
    const correr = () => aplicarAtributosK5ce(conEdad, conElRngDeK4cG(2, rng.estado())).state;
    return conDesgasteK5CE(prendido ? DESGASTE_K5CE : DESGASTE_NEUTRO_K5CE, correr);
  };
  for (const edad of [Math.floor(estado.player.oculto.edadPico) - 3, estado.player.oculto.edadPico, limite - 0.5, limite]) {
    if (!sonIgualesK5ce(comoJsonK4cG(corrida(edad, true)), comoJsonK4cG(corrida(edad, false)))) {
      throw new Error(`con edad ${edad} (edadPico ${estado.player.oculto.edadPico}, gracia ${DESGASTE_K5CE.graciaAnios}) el desgaste ya cambió el estado`);
    }
  }
  const pasado = corrida(limite + 1, true);
  if (!hayDesgasteK5ce(pasado.player) || pasado.player.stats.macro >= corrida(limite + 1, false).player.stats.macro) {
    throw new Error(`con edad ${limite + 1} (un año pasado del límite) el desgaste no mordió: ${JSON.stringify(pasado.player.desgaste)}`);
  }
  const anios = conDesgasteK5CE(DESGASTE_K5CE, () => [limite, limite + 1].map((edad) => aniosDeDesgasteK5ce(edad, estado.player.oculto)));
  if (anios[0] !== 0 || Math.abs(anios[1] - 1) > 1e-9) {
    throw new Error(`aniosDeDesgaste debe ser 0 hasta edadPico + gracia y contar años después: ${anios}`);
  }
});

check('K5c-E un veterano pasado del pico termina con cada acumulativo, el bonus permanente y el nivel más bajos que con las perillas apagadas, y el término crece (no baja) con la edad', () => {
  let veteranos = 0;
  let seedsRecorridas = 0;
  for (let seed = 1; seed <= TOPE_SEEDS_K5CE && veteranos < VETERANOS_K5CE; seed += 1) {
    seedsRecorridas = seed;
    const rng = mulberry32(seed);
    let estado = createInitialState(seed, rng);
    // K5c paso 3b: con Final2 las carreras terminan antes de los 45 splits (mediana de 26 años), así que el veterano es el último
    // estado profesional en juego de esos 45 splits (antes era el del split 45, y una carrera terminada se salteaba).
    let rngVeterano = null;
    let veterano = null;
    for (let i = 0; i < 45 && !estado.terminado; i += 1) {
      if (estado.phase === 'profesional') {
        veterano = estado;
        rngVeterano = rng.estado();
      }
      estado = avanzarSplitAuto(estado, rng).state;
    }
    if (!estado.terminado && estado.phase === 'profesional') {
      veterano = estado;
      rngVeterano = rng.estado();
    }
    if (!veterano || veterano.player.bonusPermanente.mecanica <= 0) {
      continue;
    }
    estado = veterano;
    // El mismo estado y el mismo rng, con la edad corrida 4 años pasada del límite: lo único que cambia es el desgaste (el del
    // repo, Final2, contra el neutro en memoria).
    const edad = Math.ceil(estado.player.oculto.edadPico + DESGASTE_REAL_K5CE.graciaAnios) + 4;
    const jugar = (prendido) => {
      const correr = () => {
        const rngLocal = conElRngDeK4cG(seed, rngVeterano);
        let st = { ...estado, age: edad };
        for (let i = 0; i < 6; i += 1) st = aplicarAtributosK5ce(st, rngLocal).state;
        return st;
      };
      return conDesgasteK5CE(prendido ? DESGASTE_REAL_K5CE : DESGASTE_NEUTRO_K5CE, correr);
    };
    const con = jugar(true);
    const sin = jugar(false);
    for (const stat of ACUMULATIVOS_K5CE) {
      if (!(con.player.stats[stat] < sin.player.stats[stat])) {
        throw new Error(`seed ${seed}: ${stat} con desgaste ${con.player.stats[stat]} no quedó debajo del apagado ${sin.player.stats[stat]}`);
      }
      if (!(con.player.desgaste[stat] > 0)) {
        throw new Error(`seed ${seed}: player.desgaste.${stat} no cuenta lo que se perdió (${con.player.desgaste[stat]})`);
      }
    }
    const sumaBonus = (st) => Object.values(st.player.bonusPermanente).reduce((total, valor) => total + valor, 0);
    if (!(sumaBonus(con) < sumaBonus(sin))) {
      throw new Error(`seed ${seed}: el bonus permanente con desgaste (${sumaBonus(con)}) no quedó debajo del apagado (${sumaBonus(sin)})`);
    }
    if (!(nivelDelJugador(con) < nivelDelJugador(sin))) {
      throw new Error(`seed ${seed}: el nivel con desgaste (${nivelDelJugador(con)}) no quedó debajo del apagado (${nivelDelJugador(sin)})`);
    }
    veteranos += 1;
  }
  if (veteranos < VETERANOS_K5CE) {
    throw new Error(`check vacío: ${veteranos} veteranos con bonus para comparar en las seeds 1-${seedsRecorridas} (hacen falta ${VETERANOS_K5CE})`);
  }
  console.log(`      ${veteranos} veteranos en las seeds 1-${seedsRecorridas}`);
  // La forma del término: 0 hasta el límite, y desde ahí no baja con la edad (con aceleración > 0 crece).
  const oculto = { edadPico: 24 };
  conDesgasteK5CE(DESGASTE_K5CE, () => {
    const perdidas = [20, 24, 25, 26, 27, 30, 34].map((edad) => perdidaDeAcumulativoK5ce('macro', edad, oculto));
    if (perdidas[0] !== 0 || perdidas[1] !== 0 || perdidas[2] !== 0 || perdidas[3] !== 0 || !(perdidas[4] > 0)) {
      throw new Error(`la pérdida debe valer 0 hasta edadPico + gracia (26) y mayor que 0 después: ${perdidas}`);
    }
    for (let i = 5; i < perdidas.length; i += 1) {
      if (!(perdidas[i] > perdidas[i - 1])) throw new Error(`la pérdida no crece con la edad: ${perdidas}`);
    }
  });
});

check('K5c-E con las perillas prendidas bonus = Σ marcas en cada split (el desgaste deja marcas negativas "Los años"), las marcas solo crecen y player.desgaste las cuenta', () => {
  let marcasDeDesgaste = 0;
  for (const seed of seedsDelDesgasteK5CE()) {
    let previas = [];
    let split = 0;
    carreraConDesgasteK5CE(seed, (antes, despues) => {
      split += 1;
      const marcas = despues.career.registro.marcas;
      if (marcas.length < previas.length || previas.some((marca, i) => marca !== marcas[i])) {
        throw new Error(`seed ${seed}, split ${split}: registro.marcas no solo crece`);
      }
      previas = marcas;
      for (const stat of Object.keys(despues.player.bonusPermanente)) {
        const delStat = marcas.filter((marca) => marca.stat === stat);
        const suma = delStat.reduce((total, marca) => total + marca.delta, 0);
        if (Math.abs(despues.player.bonusPermanente[stat] - suma) > 1e-6) {
          throw new Error(`seed ${seed}, split ${split}: el bonus de ${stat} (${despues.player.bonusPermanente[stat]}) no es la suma de sus marcas (${suma})`);
        }
        const gastado = delStat.filter((marca) => marca.origen === ORIGEN_DESGASTE_K5CE).reduce((total, marca) => total - marca.delta, 0);
        if (Math.abs(despues.player.desgaste[stat] - gastado) > 1e-6) {
          throw new Error(`seed ${seed}, split ${split}: player.desgaste.${stat} (${despues.player.desgaste[stat]}) no es lo que dicen las marcas de los años (${gastado})`);
        }
      }
      for (const [stat, valor] of Object.entries(despues.player.desgaste)) {
        if (!Number.isFinite(valor) || valor < 0) throw new Error(`seed ${seed}, split ${split}: player.desgaste.${stat} inválido (${valor})`);
      }
      if (Object.keys(despues.player.desgaste).length !== Object.keys(despues.player.bonusPermanente).length + ACUMULATIVOS_K5CE.length) {
        throw new Error(`seed ${seed}, split ${split}: player.desgaste incompleto: ${JSON.stringify(despues.player.desgaste)}`);
      }
    });
    for (const marca of previas.filter((m) => m.origen === ORIGEN_DESGASTE_K5CE)) {
      if (!(marca.delta < 0) || !Number.isInteger(marca.anio)) {
        throw new Error(`seed ${seed}: marca de desgaste inválida: ${JSON.stringify(marca)}`);
      }
      marcasDeDesgaste += 1;
    }
  }
  if (marcasDeDesgaste === 0) {
    throw new Error('ninguna carrera con el desgaste prendido dejó una marca de los años: el check no probaría nada');
  }
});

check('K5c-E se ve: la primera vez que muerde hay una línea en el split (una sola por carrera, ninguna sin desgaste) y la ficha, en "Lo que construiste", dice lo que te sacaron los años solo si es distinto de 0', () => {
  for (const seed of seedsDelDesgasteK5CE(DESGASTE_REAL_K5CE)) {
    let lineas = 0;
    let primerasMordidas = 0;
    const final = carreraConDesgasteK5CE(seed, (antes, despues, logs) => {
      const lineasDelSplit = logs.filter((log) => log.type === 'split' && !log.tecnico && TEXTO_PRIMERA_VEZ_K5CE.test(log.message)).length;
      lineas += lineasDelSplit;
      const primera = !hayDesgasteK5ce(antes.player) && hayDesgasteK5ce(despues.player);
      if (primera) primerasMordidas += 1;
      if (lineasDelSplit !== (primera ? 1 : 0)) {
        throw new Error(`seed ${seed}, split ${despues.player.splitCount}: ${lineasDelSplit} línea(s) del desgaste (primera vez: ${primera})`);
      }
    }, DESGASTE_REAL_K5CE);
    if (lineas !== 1 || primerasMordidas !== 1) {
      throw new Error(`seed ${seed}: ${lineas} líneas de primera vez y ${primerasMordidas} primeras mordidas (debe ser 1 y 1)`);
    }
    const ficha = fichaCompleta(final).construido;
    const delDesgaste = ficha.filter((fila) => fila.desgaste);
    if (delDesgaste.length !== 1 || !delDesgaste[0].texto.startsWith('▼') || !delDesgaste[0].texto.includes(ORIGEN_DESGASTE_K5CE)
        || ficha.some((fila) => !fila.desgaste && fila.origen === ORIGEN_DESGASTE_K5CE)) {
      throw new Error(`seed ${seed}: la ficha debe traer UNA línea de lo que te sacaron los años y no repetir las marcas: ${JSON.stringify(ficha.map((fila) => fila.texto))}`);
    }
    // Aunque no haya ninguna marca de decisiones, la línea (y con ella la sección) sigue ahí; y sin desgaste no hay ninguna.
    const sinMarcas = fichaCompleta({ ...final, career: { ...final.career, registro: { ...final.career.registro, marcas: [] } } }).construido;
    const ceros = Object.fromEntries(Object.keys(final.player.desgaste).map((stat) => [stat, 0]));
    const sinDesgaste = fichaCompleta({ ...final, player: { ...final.player, desgaste: ceros } }).construido;
    if (sinMarcas.length !== 1 || sinMarcas[0].desgaste !== true || sinDesgaste.some((fila) => fila.desgaste)) {
      throw new Error(`seed ${seed}: la línea de los años debe estar sola sin marcas (${sinMarcas.length}) y no estar con el desgaste en 0`);
    }
  }
  // Apagado (el neutro, en memoria; el repo ya lo tiene prendido): ni línea en el split ni línea en la ficha.
  const rng = mulberry32(1);
  let st = createInitialState(1, rng);
  for (let i = 0; i < 60 && !st.terminado; i += 1) {
    const paso = conDesgasteK5CE(DESGASTE_NEUTRO_K5CE, () => avanzarSplitAuto(st, rng));
    st = paso.state;
    if (paso.logs.some((log) => TEXTO_PRIMERA_VEZ_K5CE.test(log.message))) throw new Error('con las perillas apagadas salió la línea del desgaste');
  }
  if (fichaCompleta(st).construido.some((fila) => fila.desgaste)) throw new Error('con las perillas apagadas la ficha muestra el desgaste');
});

check('K5c-E guardado VERSION 12: la forma de la 11 sigue registrada tal cual, y un guardado de la 11 carga con player.desgaste en cero y juega el mismo próximo split', () => {
  if (VERSION_GUARDADO < 12 || FORMAS_CONOCIDAS[11] !== '13dd79e086e2' || FORMAS_CONOCIDAS[12] === FORMAS_CONOCIDAS[11]) {
    throw new Error(`VERSION ${VERSION_GUARDADO}, forma de la 11 ${FORMAS_CONOCIDAS[11]} (la de main es 13dd79e086e2), forma de la 12 ${FORMAS_CONOCIDAS[12]}`);
  }
  let comparados = 0;
  for (const seed of SEEDS_GUARDADO_10_K4cG) {
    const rng = mulberry32(seed);
    let state = createInitialState(seed, rng);
    for (let i = 0; i < SPLITS_GUARDADO_10_K4cG && !state.terminado; i += 1) {
      const datos = JSON.parse(serializarGuardado(state, rng));
      datos.version = 11;
      delete datos.state.player.desgaste;
      const cargado = deserializarGuardado(JSON.stringify(datos));
      if (cargado === null || !sonIgualesK5ce(comoJsonK4cG(cargado.state), comoJsonK4cG(state))) {
        throw new Error(`seed ${seed}, split ${i}: el guardado de la 11 no cargó igual que el estado de hoy (player.desgaste ${JSON.stringify(cargado?.state.player.desgaste)})`);
      }
      const seguido = avanzarSplitAuto(state, conElRngDeK4cG(seed, rng.estado()));
      const recargado = avanzarSplitAuto(cargado.state, conElRngDeK4cG(cargado.seed, cargado.rngEstado));
      if (!sonIgualesK5ce(comoJsonK4cG(seguido), comoJsonK4cG(recargado))) {
        throw new Error(`seed ${seed}, split ${i}: el guardado de la 11 no juega el mismo split`);
      }
      comparados += 1;
      state = avanzarSplitAuto(state, rng).state;
    }
  }
  if (comparados < 20) throw new Error(`check vacío: ${comparados} guardados de la 11 comparados (hacen falta 20)`);
  const rngVacio = mulberry32(1);
  const sinCampo = JSON.parse(serializarGuardado(createInitialState(1, rngVacio), rngVacio));
  sinCampo.version = 11;
  delete sinCampo.state.player.desgaste;
  if (Object.values(deserializarGuardado(JSON.stringify(sinCampo)).state.player.desgaste).some((valor) => valor !== 0)) {
    throw new Error('migrarDe11 debe arrancar player.desgaste en cero');
  }
});


// --- K5c-M, la élite se busca (PLAN.md "K5c — decisiones de spec de la estructura") ---
//
// Las orgs fuertes le ofrecen a la élite: el orden de la mano suma `k · f(nivel) · org.fuerza`
// (`mercado.elite.pesoFuerzaOrden`) y a la élite el club le perdona parte de los márgenes del asiento
// (`mercado.elite.rebajaMerito` y `rebajaDisputa`, cada una topeada en su margen). Las tres perillas salen en 0 (la huella de K1
// prueba el no-op exacto) y
// estos checks las encienden EN MEMORIA. La muestra: las pausas de mercado reales (`mercado:oferta`) de carreras de
// `criterio`, seeds 1 a `SEEDS_K5CM`, 60 splits.

// Un jugador con las seis stats de rol en `valor`: los pesos de cada rol suman 1, así que su nivel es `valor`. Es una
// declaración (no una `const`) porque el fixture del check de K0 del mercado, más arriba, la usa al cargar el módulo.
function statsParejasK5cM(valor) {
  return { mecanica: valor, macro: valor, teamfight: valor, laneo: valor, shotcalling: valor, adaptabilidad: valor };
}

const SEEDS_K5CM = 30;
// Los valores de ejemplo con los que se encienden las perillas (el barrido de K5c fija los de verdad).
const PESO_FUERZA_K5CM = 100000;
// Revisión de K5c: la rebaja son dos perillas (mérito y disputa), cada una topeada en su margen. Los valores de ejemplo son los topes
// (8 y 4: `forzarAsientoSobreNpc` y `margenSobreAlternativa`). Reemplaza a `REBAJA_ASIENTO_K5CM = 8` sobre los dos márgenes.
const REBAJAS_K5CM = { merito: 8, disputa: 4 };
const SIN_REBAJA_K5CM = { merito: 0, disputa: 0 };
// Medido al escribir el check (30 carreras, 33 pausas de élite con f = 1 y alguna oferta de tier 1, rng de la mano fijo):
// mediana de la fuerza de los clubes de tier 1 de la mano 73 con todo apagado, 79 con solo k, 76 con solo la rebaja y
// 83 con las dos. Los pisos de abajo quedan a la mitad de cada suba medida.
const SUBA_MINIMA_SOLO_K_K5CM = 3;
const SUBA_MINIMA_AMBAS_K5CM = 5;
// El jugador medio (f = 0) no se mueve por construcción: los dos términos valen 0. La tolerancia es un punto de fuerza,
// un escalón de la escala entera de `org.fuerza`: cualquier corrimiento de la mano de un jugador que la regla no toca
// lo saca de ahí (un mutante sin la compuerta de `f` lo corre ~3 puntos).
const TOLERANCIA_MEDIO_K5CM = 1;
// Cuántos clubes del mundo cuentan como "los más fuertes" para medir si la rebaja les abre asiento.
const TOP_MUNDO_K5CM = 10;
// K5c-M (a2), desde la integración de K6a: cuánto tiene que subir la rebaja los asientos de la élite en esos clubes (ver el check).
const SUBA_RELATIVA_A2_K5CM = 0.3;
const SUBA_ABSOLUTA_A2_K5CM = 3;

// Las cosechas se cachean por régimen de la casa: `real` (los valores definitivos) y `neutra` (K5c-M se mide con la casa neutra, D81).
const cosechasK5cM = { real: null, neutra: null };
const eliteK5cMPorRegimen = { real: null, neutra: null };
const seedsEliteK5cMPorRegimen = { real: SEEDS_K5CM, neutra: SEEDS_K5CM };
function pausasDeMercadoDeK5cM(regimen) {
  if (!cosechasK5cM[regimen]) {
    const cosecha = [];
    const correr = () => {
      for (let seed = 1; seed <= SEEDS_K5CM; seed += 1) {
        correrCarreraSimulate(seed, 60, (sistema, st, decision, rng) => {
          if (sistema.id === 'mercado' && decision.datos?.motivo === 'oferta') {
            cosecha.push({ seed, st, decision });
          }
          return ESTRATEGIAS_K0.criterio(sistema, st, decision, rng);
        });
      }
    };
    if (regimen === 'neutra') {
      conCasaNeutraK5cM(correr);
    } else {
      correr();
    }
    cosechasK5cM[regimen] = cosecha;
  }
  return cosechasK5cM[regimen];
}
function pausasDeMercadoK5cM() {
  return pausasDeMercadoDeK5cM('real');
}

// K5c paso 3b (regla 17): con Final2 (carreras más cortas, la LCK arriba) las 30 carreras de la cosecha dejan 9 pausas de élite y
// (a) y (a2) pedían 10. La élite se junta en ronda: a las pausas de élite de las seeds 1-`SEEDS_K5CM` se suman las de las seeds
// siguientes (mismas carreras de `criterio`, 60 splits) hasta `ELITE_MINIMA_K5CM` o hasta `TOPE_SEEDS_ELITE_K5CM`. El jugador medio
// sigue saliendo de la cosecha de siempre.
const ELITE_MINIMA_K5CM = 20;
const TOPE_SEEDS_ELITE_K5CM = 150;
function pausasDeEliteDeK5cM(regimen) {
  if (!eliteK5cMPorRegimen[regimen]) {
    const esElite = (st) => factorElite(nivelDelJugador(st)) >= 1;
    const elite = pausasDeMercadoDeK5cM(regimen).filter(({ st }) => esElite(st));
    const correr = () => {
      for (let seed = SEEDS_K5CM + 1; seed <= TOPE_SEEDS_ELITE_K5CM && elite.length < ELITE_MINIMA_K5CM; seed += 1) {
        seedsEliteK5cMPorRegimen[regimen] = seed;
        correrCarreraSimulate(seed, 60, (sistema, st, decision, rng) => {
          if (sistema.id === 'mercado' && decision.datos?.motivo === 'oferta' && esElite(st)) {
            elite.push({ seed, st, decision });
          }
          return ESTRATEGIAS_K0.criterio(sistema, st, decision, rng);
        });
      }
    };
    if (regimen === 'neutra') {
      conCasaNeutraK5cM(correr);
    } else {
      correr();
    }
    eliteK5cMPorRegimen[regimen] = elite;
  }
  return eliteK5cMPorRegimen[regimen];
}
function pausasDeEliteK5cM() {
  return pausasDeEliteDeK5cM('real');
}

// K5c paso 3b-1 (regla 17): el check prueba el MECANISMO de la élite con la casa neutra en memoria (`mercado.casa`: margenAlcanza 99 y
// fraccionCastigo 1, los valores neutros de K5c-H). Con los definitivos ("la casa primero", decisión del usuario) la mano de élite
// ya viene ordenada por la casa (~2,2 ofertas) y la perilla `k` no mueve la fuerza mediana (66,5 / 66,5 / 67): el efecto no se mide.
// La comparación sigue siendo apagado contra prendido de `mercado.elite` con la misma muestra, con los mismos umbrales.
const CASA_NEUTRA_K5CM = { margenAlcanza: 99, fraccionCastigo: 1 };
function conCasaNeutraK5cM(fn) {
  const casa = BALANCE.mercado.casa;
  const previasCasa = [casa.margenAlcanza, casa.fraccionCastigo];
  casa.margenAlcanza = CASA_NEUTRA_K5CM.margenAlcanza;
  casa.fraccionCastigo = CASA_NEUTRA_K5CM.fraccionCastigo;
  try {
    return fn();
  } finally {
    [casa.margenAlcanza, casa.fraccionCastigo] = previasCasa;
  }
}
function conPerillasEliteK5cM(pesoFuerza, rebaja, fn) {
  const elite = BALANCE.mercado.elite;
  const previas = [elite.pesoFuerzaOrden, elite.rebajaMerito, elite.rebajaDisputa];
  elite.pesoFuerzaOrden = pesoFuerza;
  elite.rebajaMerito = rebaja.merito;
  elite.rebajaDisputa = rebaja.disputa;
  try {
    return conCasaNeutraK5cM(fn);
  } finally {
    [elite.pesoFuerzaOrden, elite.rebajaMerito, elite.rebajaDisputa] = previas;
  }
}

// El estado de la pausa con TODOS los asientos de tu rol congelados para vos: así la mano la deciden solo
// `ofertaPosible` (con la rebaja) y el orden (con k), y no los asientos que el mundo congeló con las perillas apagadas.
function conTodoCongeladoK5cM(st) {
  const pre = st.mundo.mercadoPretemporada;
  if (!pre) {
    return st;
  }
  const congelados = st.mundo.ligas.flatMap((liga) => liga.orgs.map((org) => ({ org: org.nombre, liga: liga.id, rol: st.player.role })));
  return { ...st, mundo: { ...st.mundo, mercadoPretemporada: { ...pre, congelados } } };
}

// La fuerza de los clubes de tier 1 que te ofrecen (sin la renovación: tu club no entra por el orden), con un rng fijo.
function fuerzasTier1DeLaManoK5cM(st, pesoFuerza, rebaja) {
  return conPerillasEliteK5cM(pesoFuerza, rebaja, () => generarOfertas(st, mulberry32(SEEDS_K5CM)).ofertas
    .filter((oferta) => oferta.tier === 1 && oferta.tag !== 'renovacion')
    .map((oferta) => oferta.plantelEnLiga.fuerza));
}

check('K5c-M (a): con las perillas de élite encendidas en memoria, la élite recibe clubes de tier 1 más fuertes y el jugador medio la misma mano', () => {
  const grupos = { elite: [], medio: [] };
  const elite = new Set(pausasDeEliteK5cM());
  for (const pausa of new Set([...pausasDeMercadoK5cM(), ...pausasDeEliteK5cM()])) {
    const { st } = pausa;
    const f = factorElite(nivelDelJugador(st));
    const grupo = elite.has(pausa) ? 'elite' : (f === 0 && pausa.seed <= SEEDS_K5CM ? 'medio' : null);
    const congelado = conTodoCongeladoK5cM(st);
    if (grupo && fuerzasTier1DeLaManoK5cM(congelado, 0, SIN_REBAJA_K5CM).length > 0) {
      grupos[grupo].push(congelado);
    }
  }
  if (grupos.elite.length < 10 || grupos.medio.length < 10) {
    throw new Error(`muestra chica: ${grupos.elite.length} pausas de élite y ${grupos.medio.length} de nivel medio con ofertas de tier 1`);
  }
  const medianaDe = (estados, pesoFuerza, rebaja) => medianaSim(estados.flatMap((st) => fuerzasTier1DeLaManoK5cM(st, pesoFuerza, rebaja)));
  const config = [['apagado', 0, SIN_REBAJA_K5CM], ['solo k', PESO_FUERZA_K5CM, SIN_REBAJA_K5CM], ['solo rebaja', 0, REBAJAS_K5CM], ['ambas', PESO_FUERZA_K5CM, REBAJAS_K5CM]];
  const deElite = Object.fromEntries(config.map(([nombre, k, r]) => [nombre, medianaDe(grupos.elite, k, r)]));
  const medio = Object.fromEntries(config.map(([nombre, k, r]) => [nombre, medianaDe(grupos.medio, k, r)]));
  const resumen = `élite (${grupos.elite.length} pausas, seeds 1-${seedsEliteK5cMPorRegimen.real}) ${JSON.stringify(deElite)}; medio (${grupos.medio.length}) ${JSON.stringify(medio)}`;
  if (deElite['solo k'] - deElite.apagado < SUBA_MINIMA_SOLO_K_K5CM) {
    throw new Error(`con solo k = ${PESO_FUERZA_K5CM} la fuerza mediana de la élite sube menos de ${SUBA_MINIMA_SOLO_K_K5CM}: ${resumen}`);
  }
  if (deElite.ambas - deElite.apagado < SUBA_MINIMA_AMBAS_K5CM) {
    throw new Error(`con k y la rebaja la fuerza mediana de la élite sube menos de ${SUBA_MINIMA_AMBAS_K5CM}: ${resumen}`);
  }
  for (const [nombre] of config) {
    if (Math.abs(medio[nombre] - medio.apagado) > TOLERANCIA_MEDIO_K5CM) {
      throw new Error(`la mano del jugador medio se movió con "${nombre}": ${resumen}`);
    }
  }
  console.log(`      ${resumen}`);
});

// K5c-M (a2), informativo (D81): el conteo sobre la muestra real NO tiene umbral. Con el mercado calibrado (Final2, la casa, las reglas
// duras de import) la rebaja casi no abre asientos en los 10 clubes más fuertes (2 -> 3 con las perillas de ejemplo): K6 juzga. El
// mecanismo lo prueba el escenario armado de más abajo ("K5c-M (a2 armado)"). K5c-M se mide con la casa neutra (D81): con la casa
// encendida ordena K5c-H; la cosecha se hace siempre con la casa neutra, igual en `--rapido` y en `--solo`.
check('K5c-M (a2): con la rebaja encendida en memoria, cuántos asientos de los clubes más fuertes del mundo abre sobre la muestra (informativo, sin umbral)', () => {
  const cosecha = { true: pausasDeEliteDeK5cM('neutra'), false: pausasDeMercadoDeK5cM('neutra') };
  const contar = (rebaja, quiereElite) => conPerillasEliteK5cM(0, rebaja, () => {
    let pares = 0;
    let estados = 0;
    for (const { st } of cosecha[quiereElite]) {
      const f = factorElite(nivelDelJugador(st));
      if (quiereElite ? f < 1 : f > 0) {
        continue;
      }
      estados += 1;
      const fuerzas = st.mundo.ligas.filter((liga) => liga.tier === 1).flatMap((liga) => liga.orgs.map((org) => org.fuerza)).sort((a, b) => b - a);
      const corte = fuerzas[TOP_MUNDO_K5CM - 1];
      pares += orgsQueTeFicharian(st).filter((entrada) => entrada.liga.tier === 1 && entrada.org.fuerza >= corte).length;
    }
    return { pares, estados };
  });
  const elite = [contar(SIN_REBAJA_K5CM, true), contar(REBAJAS_K5CM, true)];
  const medio = [contar(SIN_REBAJA_K5CM, false), contar(REBAJAS_K5CM, false)];
  console.log(`      top ${TOP_MUNDO_K5CM} del mundo ofrecibles: élite ${elite[0].pares} -> ${elite[1].pares} (${elite[0].estados} pausas, seeds 1-${seedsEliteK5cMPorRegimen.neutra}), `
    + `medio ${medio[0].pares} -> ${medio[1].pares} (${medio[0].estados} pausas). D81: con el mercado calibrado, la rebaja casi no abre asientos top-10; K6 juzga`);
});

// Lo que la carta tiene que decir, armado acá de nuevo (no con `core/demanda.js:plantelEnLiga`): el puesto contando los
// clubes de la liga con más fuerza, y las palabras con los cortes de `mercado.plantelEnLiga`.
function lineaEsperadaK5cM(liga, org) {
  const puesto = 1 + liga.orgs.filter((otra) => otra.fuerza > org.fuerza).length;
  const de = liga.orgs.length;
  const nombre = nombreVisibleDeLiga(liga.id);
  const { fraccionArriba, fraccionAbajo } = BALANCE.mercado.plantelEnLiga;
  if (puesto === 1) {
    return { puesto, de, banda: 'primero', texto: `El plantel más fuerte de ${nombre}` };
  }
  if (puesto <= Math.ceil(de * fraccionArriba)) {
    return { puesto, de, banda: 'arriba', texto: `Plantel: ${puesto}.º de ${de} en ${nombre}` };
  }
  if (puesto > de - Math.ceil(de * fraccionAbajo)) {
    return { puesto, de, banda: 'abajo', texto: `Plantel: de los de abajo en ${nombre}` };
  }
  return { puesto, de, banda: 'medio', texto: `Plantel: mitad de tabla en ${nombre}` };
}

check('K5c-M (b): la carta de oferta dice el puesto real del plantel por fuerza en su liga (regla 15)', () => {
  const vistas = { primero: 0, arriba: 0, medio: 0, abajo: 0 };
  let ofertas = 0;
  const problemas = [];
  for (const { seed, st, decision } of pausasDeMercadoK5cM()) {
    for (const oferta of decision.opciones) {
      const liga = st.mundo.ligas.find((candidata) => candidata.id === oferta.liga);
      const org = liga?.orgs.find((candidata) => candidata.nombre === oferta.org);
      if (!org) {
        problemas.push(`seed ${seed}: ${oferta.org} no está en ${oferta.liga}`);
        continue;
      }
      const esperada = lineaEsperadaK5cM(liga, org);
      const dato = oferta.plantelEnLiga;
      const carta = lineaDePlantelDeOferta(oferta);
      if (dato?.puesto !== esperada.puesto || dato?.de !== esperada.de || dato?.fuerza !== org.fuerza || carta !== esperada.texto) {
        problemas.push(`seed ${seed}, ${oferta.org}: el motor dice ${JSON.stringify(dato)} y la carta "${carta}"; el plantel es ${esperada.puesto}.º de ${esperada.de} ("${esperada.texto}")`);
      }
      vistas[esperada.banda] += 1;
      ofertas += 1;
    }
  }
  if (problemas.length > 0) {
    throw new Error(`${problemas.length} de ${ofertas} ofertas: ${problemas.slice(0, 4).join(' | ')}`);
  }
  if (Object.values(vistas).some((n) => n === 0)) {
    throw new Error(`la muestra no pasó por las cuatro bandas de la carta: ${JSON.stringify(vistas)}`);
  }
  if (lineaDePlantelDeOferta({ id: 'vieja' }) !== null) {
    throw new Error('una oferta sin `plantelEnLiga` (un guardado de antes) tiene que dejar la carta sin la línea');
  }
  console.log(`      ${ofertas} ofertas, bandas ${JSON.stringify(vistas)}`);
});

check('K5c-M (c): criterio, si es de élite, elige el club más fuerte entre ofertas del mismo tier (y si no, la jerarquía de siempre)', () => {
  const oferta = (id, tier, hasta, fuerza) => ({
    id, org: id, tier, proyeccionJerarquia: { desde: 50, hasta }, salarioAnualUSD: 100, plantelEnLiga: { fuerza }
  });
  const decisionDe = (opciones) => ({ tipo: 'opciones', presentacion: 'mercado', opciones, datos: { motivo: 'oferta' } });
  const sistemaSinAuto = { id: 'mercado', resolverAuto() { throw new Error('no debería delegar'); } };
  const conNivel = (nivel) => ({ seed: 1, player: { splitCount: 1, role: 'mid', stats: statsParejasK5cM(nivel) }, logs: [] });
  const elegir = (nivel, opciones) => ESTRATEGIAS_K0.criterio(sistemaSinAuto, conNivel(nivel), decisionDe(opciones), rngProhibidoK0).opcionId;
  // La renovación en un club flojo (jerarquía alta) contra el cuarto nombre de un gigante, y uno de tier 2 más fuerte.
  const mano = [oferta('renovacion', 1, 70, 60), oferta('gigante', 1, 30, 92), oferta('medio', 1, 45, 75), oferta('tier2', 2, 80, 99)];
  // Medio punto a cada lado del umbral: la suma de los pesos en coma flotante no da el umbral exacto.
  const elite = NIVEL_ELITE_CRITERIO + 0.5;
  const noElite = NIVEL_ELITE_CRITERIO - 0.5;
  if (Math.abs(nivelDelJugador(conNivel(elite)) - elite) > 1e-9) {
    throw new Error('el fixture no da el nivel pedido');
  }
  if (elegir(elite, mano) !== 'gigante') {
    throw new Error(`con nivel ${elite} (élite) tenía que elegir el club más fuerte del tier 1, eligió ${elegir(elite, mano)}`);
  }
  if (elegir(noElite, mano) !== 'renovacion') {
    throw new Error(`con nivel ${noElite} tenía que elegir la mayor jerarquía del tier 1, eligió ${elegir(noElite, mano)}`);
  }
  // El tier sigue primero, y a igualdad de fuerza vuelve la jerarquía.
  if (elegir(elite, [oferta('t2', 2, 80, 99), oferta('t1', 1, 20, 50)]) !== 't1') {
    throw new Error('la élite tiene que seguir prefiriendo el tier 1 a un tier 2 más fuerte');
  }
  if (elegir(elite, [oferta('a', 1, 30, 80), oferta('b', 1, 60, 80)]) !== 'b') {
    throw new Error('a igualdad de fuerza la élite tiene que desempatar por la jerarquía');
  }
  // Con la marca de élite el comparador sigue antisimétrico y reflexivo en 0.
  for (const x of mano) {
    if (compararOfertasMercado(x, x, { elite: true }) !== 0) {
      throw new Error(`compararOfertasMercado(${x.id}, ${x.id}, élite) tenía que ser 0`);
    }
    for (const y of mano) {
      if (Math.sign(compararOfertasMercado(x, y, { elite: true })) !== -Math.sign(compararOfertasMercado(y, x, { elite: true }))) {
        throw new Error(`compararOfertasMercado con élite no es antisimétrico entre ${x.id} y ${y.id}`);
      }
    }
  }
});

// --- K6a-U: UI y textos del ensayo de K6 ------------------------------------------------------------------------------------
// Regla 7: cada check da rojo con su mutante (anotado debajo de cada uno). Regla 15: el texto dice lo que el motor hace. Nada de
// esto mueve el stream del motor: son textos, la forma de leer `state` para la pantalla y la seed que se escribe a mano.
const { interpretarSeed, hashCadena: hashCadenaK6AU } = await import('../core/numeros.js');
const { plural: pluralK6AU, faltan: faltanK6AU, haceDeEso: haceDeEsoK6AU } = await import('../core/formato.js');
const { ventanaVisibleDe, tableroDeSerie } = await import('../core/vistaDeCarrera.js');
const { vinetasDelAnio: vinetasDelAnioK6AU } = await import('../core/temporadaResumen.js');
const { etiquetaDeRanked: etiquetaDeRankedK6AU, servidorDeLaPartida: servidorK6AU } = await import('../core/ranked.js');
const { lineaDeHitoDeOferta, lineaDeMotivoDeOferta } = await import('../ui/components/mercado.js');
const { decisionPresionTier2: decisionPresionK6AU } = await import('../systems/mercado.js');
const { bandaDeArraigoFicha: bandaDeArraigoK6AU } = await import('../core/ficha.js');
const { resolverTexto: resolverTextoK6AU } = await import('../core/plantillas.js');

function archivosJsK6AU(dir) {
  return fs.readdirSync(dir, { withFileTypes: true }).flatMap((entrada) => {
    const ruta = path.join(dir, entrada.name);
    if (entrada.isDirectory()) {
      return archivosJsK6AU(ruta);
    }
    return entrada.name.endsWith('.js') ? [ruta] : [];
  });
}

check('K6a-U (a): un texto en la seed es la misma carrera cada vez (hash del motor) y un número sigue igual', () => {
  const pepe = interpretarSeed('pepe');
  if (pepe.seed !== hashCadenaK6AU('pepe') || !pepe.desdeTexto || pepe.seed === null) {
    throw new Error(`"pepe" tenía que ser hashCadena("pepe") = ${hashCadenaK6AU('pepe')}, dio ${JSON.stringify(pepe)}`);
  }
  if (interpretarSeed(' pepe ').seed !== pepe.seed || interpretarSeed('Pepe').seed === pepe.seed) {
    throw new Error('el texto se recorta pero distingue mayúsculas: " pepe " = "pepe" y "Pepe" es otra seed');
  }
  const esperados = { '123': 123, ' 42 ': 42, '-5.9': 5, '0': 0, '1e3': 1000 };
  for (const [crudo, seed] of Object.entries(esperados)) {
    const r = interpretarSeed(crudo);
    if (r.seed !== seed || r.desdeTexto) {
      throw new Error(`el número "${crudo}" tenía que seguir dando ${seed} (no texto), dio ${JSON.stringify(r)}`);
    }
  }
  for (const vacio of ['', '   ', null, undefined]) {
    if (interpretarSeed(vacio).seed !== null) {
      throw new Error(`vacío (${JSON.stringify(vacio)}) no es seed: la sortea el reloj`);
    }
  }
  // Mutante: que un texto devuelva `seed: null` (se ignora sin avisar, como antes) o que un número pase por el hash.
});

check('K6a-U (b): "te falta 1 puesto", el tiempo según la distancia real y ningún "te faltan N" a mano', () => {
  const esperado = [
    [faltanK6AU(1, 'puesto', 'puestos'), 'te falta 1 puesto'],
    [faltanK6AU(2, 'puesto', 'puestos'), 'te faltan 2 puestos'],
    [faltanK6AU(0, 'puesto', 'puestos'), 'te faltan 0 puestos'],
    [faltanK6AU(1, 'punto', 'puntos', 'Te'), 'Te falta 1 punto'],
    [pluralK6AU(1, 'trofeo', 'trofeos'), 'trofeo'],
    [pluralK6AU(0, 'trofeo', 'trofeos'), 'trofeos'],
    [haceDeEsoK6AU(0), 'Fue este mismo año'],
    [haceDeEsoK6AU(1), 'Fue el año pasado'],
    [haceDeEsoK6AU(2), 'Hace 2 años de eso'],
    [haceDeEsoK6AU(7), 'Hace 7 años de eso']
  ];
  const mal = esperado.filter(([dado, texto]) => dado !== texto).map(([dado, texto]) => `"${dado}" (debía decir "${texto}")`);
  if (mal.length > 0) {
    throw new Error(mal.join(' | '));
  }
  // El token de la plantilla resuelve contra el PRIMER título del registro: el del año anterior no dice "hace años".
  const conTitulo = (anioTitulo, anioHoy) => ({ career: { registro: { titulos: [{ anio: anioTitulo }, { anio: anioHoy }] } }, calendario: { anio: anioHoy } });
  const cita = TODOS_LOS_EVENTOS.find((evento) => evento.id === 'el_primer_titulo_que_contas');
  if (!cita || !cita.description.includes('{haceDeEso}') || /hace años/i.test(cita.description)) {
    throw new Error('la descripción de "el primer título que contás" tiene que usar {haceDeEso}, no un "hace años" fijo');
  }
  const dicho = (estado) => resolverTextoK6AU(cita.description, estado);
  if (!dicho(conTitulo(2030, 2031)).includes('Fue el año pasado.') || dicho(conTitulo(2030, 2031)).includes('años de eso')) {
    throw new Error(`el título del año anterior tenía que decir "Fue el año pasado": ${dicho(conTitulo(2030, 2031))}`);
  }
  if (!dicho(conTitulo(2026, 2031)).includes('Hace 5 años de eso.')) {
    throw new Error(`el título de hace 5 años tenía que decir "Hace 5 años de eso": ${dicho(conTitulo(2026, 2031))}`);
  }
  // Ningún texto del motor ni de la UI escribe "te faltan ${n}" a pelo (el verbo no concuerda con el 1).
  const aMano = /[Tt]e faltan \$\{/;
  const raiz = path.join(__dirname, '..');
  const culpables = archivosJsK6AU(raiz)
    .filter((ruta) => !ruta.endsWith(path.join('dev', 'validate.js')) && !ruta.endsWith(path.join('core', 'formato.js')))
    .filter((ruta) => aMano.test(fs.readFileSync(ruta, 'utf8')))
    .map((ruta) => path.relative(raiz, ruta));
  if (culpables.length > 0) {
    throw new Error(`"te faltan \${n}" escrito a mano (usar faltan() de core/formato.js): ${culpables.join(', ')}`);
  }
  // Mutante: `faltan` que diga siempre "faltan", `haceDeEso` que devuelva "Hace años de eso", o volver al ternario del sustantivo.
});

check('K6a-U (c): el cierre de año dice el rango, y con 0-0 el archirrival no "va ganando"', () => {
  const base = createInitialState(1, mulberry32(1));
  if (base.phase !== 'amateur') {
    throw new Error(`el fixture supone un arranque amateur y la fase es ${base.phase}`);
  }
  const conDuelo = (tuyos, suyos) => ({ ...base, mundo: { ...base.mundo, archirrival: { handle: 'Mirfin90', org: 'Shopify Rebellion', duelo: { tuyos, suyos } } } });
  const lineaDe = (estado, icono) => vinetasDelAnioK6AU(estado).find((v) => v.icono === icono).texto;
  const cero = lineaDe(conDuelo(0, 0), '⚡');
  if (/ganando|ventaja/.test(cero) || !/Mirfin90/.test(cero) || !/ninguno de los dos ganó un trofeo/.test(cero)) {
    throw new Error(`con 0-0 nadie va ganando, y dice: "${cero}"`);
  }
  const casos = [[3, 1, 'vas ganando el duelo'], [1, 3, 'te lleva ventaja'], [2, 2, 'parejo']];
  for (const [tuyos, suyos, frase] of casos) {
    if (!lineaDe(conDuelo(tuyos, suyos), '⚡').includes(frase)) {
      throw new Error(`${tuyos}-${suyos} tenía que decir "${frase}": ${lineaDe(conDuelo(tuyos, suyos), '⚡')}`);
    }
  }
  if (!lineaDe(conDuelo(0, 1), '⚡').includes('1 trofeo contra')) {
    throw new Error(`"1 trofeos": ${lineaDe(conDuelo(0, 1), '⚡')}`);
  }
  const rango = etiquetaDeRankedK6AU(base.player.ranked, servidorK6AU(base));
  const equipo = lineaDe(base, '🏆');
  if (!equipo.includes(rango) || /SoloQ: \d+ LP/.test(equipo)) {
    throw new Error(`el cierre del amateur tenía que decir el rango "${rango}" y no los puntos crudos: "${equipo}"`);
  }
  // Mutante: volver a `${Math.round(soloqElo)} LP`, o `tuyos >= suyos` para el "vas ganando".
});

check('K6a-U (d): las líneas de la carta de oferta salen del mismo dato y no se contradicen (regla 15)', () => {
  const st = createInitialState(3, mulberry32(3));
  const base = st.mundo.ligas.find((liga) => liga.tier === 1);
  // Una liga de diez clubes con una fuerza por banda, y un prestigio altísimo: con la regla vieja (fuerza contra prestigio)
  // TODA carta decía "margen para mandar vos", hasta la del plantel más fuerte.
  const fuerzas = [90, 80, 70, 60, 55, 50, 40, 30, 20, 10];
  const liga = { ...base, prestigio: 500, orgs: fuerzas.map((fuerza, i) => ({ nombre: `Club ${i + 1}`, fuerza })) };
  const vistas = new Set();
  const problemas = [];
  for (const org of liga.orgs) {
    const oferta = construirOferta(st, liga, org, 'lateral', mulberry32(9));
    const esperada = lineaEsperadaK5cM(liga, org);
    vistas.add(esperada.banda);
    const dicho = (cual) => `${org.nombre} (${esperada.banda}): ${cual}`;
    const fuerte = esperada.banda === 'primero' || esperada.banda === 'arriba';
    if (oferta.plantelEnLiga.banda !== esperada.banda) {
      problemas.push(dicho(`el motor da la banda ${oferta.plantelEnLiga.banda}`));
    }
    if (fuerte && (!/competir por un lugar/.test(oferta.riesgo ?? '') || /mandar|hacerte grande/.test(oferta.riesgo ?? ''))) {
      problemas.push(dicho(`plantel fuerte y la carta dice "${oferta.riesgo}"`));
    }
    if (esperada.banda === 'abajo' && !/margen para hacerte grande/.test(oferta.riesgo ?? '')) {
      problemas.push(dicho(`plantel flojo y la carta dice "${oferta.riesgo}"`));
    }
    if (esperada.banda === 'medio' && !/parejo/.test(oferta.riesgo ?? '')) {
      problemas.push(dicho(`plantel parejo y la carta dice "${oferta.riesgo}"`));
    }
    // La jerarquía: la frase sigue al `hasta` de la misma tarjeta, y no habla de un draft que ya no existe.
    const bajo = oferta.proyeccionJerarquia.hasta < BALANCE.serie.jerarquiaMinimaParaSeguirLlamada;
    if (bajo !== /pesan poco/.test(oferta.proyeccionPicks) || /draft|elegir tu campeón/.test(oferta.proyeccionPicks)) {
      problemas.push(dicho(`jerarquía ${oferta.proyeccionJerarquia.hasta} y la carta dice "${oferta.proyeccionPicks}"`));
    }
    // El arraigo de llegada: el número y la banda de la cuenta, sin "casi de cero" junto a "tu fama te precede".
    const etiqueta = oferta.arraigoInicial.etiqueta;
    if (!etiqueta.includes(`${oferta.arraigoInicial.valor}/100`) || !etiqueta.includes(bandaDeArraigoK6AU(oferta.arraigoInicial.valor).label) || /fama te precede/.test(etiqueta)) {
      problemas.push(dicho(`el arraigo vale ${oferta.arraigoInicial.valor} y la carta dice "${etiqueta}"`));
    }
  }
  if (vistas.size < 4) {
    problemas.push(`el fixture no pasó por las cuatro bandas: ${[...vistas].join(', ')}`);
  }
  // La otra mitad de la frase de la jerarquía: la renovación (tu propio club) conserva la jerarquía de hoy, y ahí sí se llega
  // por encima del umbral. Con 90 las llamadas "cuentan enteras"; con 30, "pesan poco"; ninguna habla de un draft.
  for (const jerarquia of [30, 90]) {
    const propio = { ...st, career: { ...st.career, currentOrg: 'Club 1', jerarquia } };
    const renovacion = construirOferta(propio, liga, liga.orgs[0], 'renovacion', mulberry32(9));
    const bajoRenovacion = jerarquia < BALANCE.serie.jerarquiaMinimaParaSeguirLlamada;
    if (bajoRenovacion !== /pesan poco/.test(renovacion.proyeccionPicks) || (!bajoRenovacion && !/cuentan enteras/.test(renovacion.proyeccionPicks))
      || /draft|elegir tu campeón/.test(renovacion.proyeccionPicks)) {
      problemas.push(`renovación con jerarquía ${jerarquia}: la carta dice "${renovacion.proyeccionPicks}"`);
    }
  }
  // La carta muestra el motivo del club tal cual viene del motor, y el hito con el verbo que concuerda.
  if (lineaDeMotivoDeOferta({ motivoDemanda: 'mejorás claramente sobre Fulano' }) !== 'Por qué te quieren: mejorás claramente sobre Fulano.' || lineaDeMotivoDeOferta({}) !== null) {
    problemas.push(`la línea del motivo: ${lineaDeMotivoDeOferta({ motivoDemanda: 'mejorás claramente sobre Fulano' })}`);
  }
  if (lineaDeHitoDeOferta({ progresoHito: { faltan: 1, hacia: 'Ídolo' } }) !== 'Te falta 1 punto para Ídolo'
    || lineaDeHitoDeOferta({ progresoHito: { faltan: 24, hacia: 'Ídolo' } }) !== 'Te faltan 24 puntos para Ídolo') {
    problemas.push('el hito no concuerda el verbo con el número');
  }
  if (problemas.length > 0) {
    throw new Error(`${problemas.length} problema(s): ${problemas.slice(0, 4).join(' | ')}`);
  }
  // Mutante: `riesgo` contra `liga.prestigio` como antes (rojo en el plantel más fuerte), el texto del draft en `proyeccionPicks`,
  // el "casi de cero: tu fama te precede" del arraigo, o `lineaDeMotivoDeOferta` devolviendo null.
});

check('K6a-U (e): la barra de fase y el panel de la serie dicen lo que pasa, no el estado del arranque del split', () => {
  const base = createInitialState(1, mulberry32(1));
  const en = (cambios) => ({ ...base, contexto: { ...base.contexto, ventana: 'pretemporada' }, ...cambios });
  const ventanas = [
    ['una parada del mercado en la pretemporada sigue siendo pretemporada', en({ pendiente: { sistemaId: 'mercado' } }), 'pretemporada'],
    ['el partido decisivo de la tabla es temporada regular, aunque el split arrancó en pretemporada', en({ pendiente: { sistemaId: 'temporada' } }), 'regular'],
    ['una serie en curso son playoffs', en({ serie: { ...base.serie, activa: true } }), 'playoffs'],
    ['la parada de una serie son playoffs', en({ pendiente: { sistemaId: 'serie' } }), 'playoffs'],
    ['una serie del bracket del Mundial es el internacional', en({ serie: { ...base.serie, activa: true, torneo: 'mundial' } }), 'internacional'],
    ['el 2-2 del Swiss es el internacional', en({ pendiente: { sistemaId: 'internacional' }, internacional: { partidoEnCurso: { rival: 'X' } } }), 'internacional']
  ];
  const mal = ventanas.filter(([, estado, esperada]) => ventanaVisibleDe(estado) !== esperada)
    .map(([que, estado, esperada]) => `${que}: dice ${ventanaVisibleDe(estado)} y era ${esperada}`);
  const domestica = { ...base.serie, activa: false, postSerie: true, torneo: null, ronda: 'final' };
  const mundial = { jugador: 'Mi club', anio: base.calendario.anio, partidoEnCurso: null };
  const paneles = [
    ['el Swiss no es una serie: panel del Swiss', en({ serie: domestica, internacional: { ...mundial, partidoEnCurso: { rival: 'X' } } }), 'swiss'],
    ['la final doméstica recién cerrada se ve', en({ serie: domestica }), 'serie'],
    ['la final doméstica ya no es el momento si tu equipo está en el Mundial de este año', en({ serie: domestica, internacional: mundial }), null],
    ['pero el Mundial de otro año no la tapa', en({ serie: domestica, internacional: { ...mundial, anio: mundial.anio - 1 } }), 'serie'],
    ['y un Mundial en el que no jugás tampoco', en({ serie: domestica, internacional: { ...mundial, jugador: null } }), 'serie'],
    ['la serie del Mundial en curso se ve', en({ serie: { ...base.serie, activa: true, torneo: 'mundial' }, internacional: mundial }), 'serie'],
    ['sin serie, sin panel', en({}), null]
  ];
  mal.push(...paneles.filter(([, estado, esperado]) => tableroDeSerie(estado) !== esperado)
    .map(([que, estado, esperado]) => `${que}: dice ${tableroDeSerie(estado)} y era ${esperado}`));
  if (mal.length > 0) {
    throw new Error(`${mal.length} problema(s): ${mal.slice(0, 4).join(' | ')}`);
  }
  // Mutante: `ventanaVisibleDe` que devuelva `state.contexto.ventana` a pelo, o `tableroDeSerie` que no mire `internacional`.
});

check('K6a-U (f): la presión de tier 2 no dice "Seguís en" otra liga ni repite lo que ya dijo, y el desgaste no habla "en el comms"', () => {
  const ligas = [{ id: 'emea', nombre: 'EMEA Masters' }, { id: 'lckcl', nombre: 'LCK CL' }, { id: 'lcsa', nombre: 'LCS Academy' }];
  const estado = (libre) => ({
    age: 27,
    career: { currentOrg: libre ? null : 'Club X', liga: libre ? null : 'emea', tier: 2, registro: { porOrg: [{ tier: 2, liga: 'emea' }] } },
    mundo: { ligas },
    flags: { splitsTier2SinOfertaTier1: 4 }
  });
  const una = decisionPresionK6AU(estado(false), [{ liga: 'lckcl', tier: 2 }], []);
  const seguirUna = una.opciones.find((o) => o.id === 'seguir').label;
  const dos = decisionPresionK6AU(estado(false), [{ liga: 'lckcl', tier: 2 }, { liga: 'lcsa', tier: 2 }], []);
  const seguirDos = dos.opciones.find((o) => o.id === 'seguir').label;
  if (seguirUna !== 'Seguís abajo: LCK CL te quiere' || seguirDos !== 'Seguís abajo: LCK CL o LCS Academy te quieren') {
    throw new Error(`la opción de seguir dice "${seguirUna}" y "${seguirDos}"`);
  }
  const libreSinOfertas = decisionPresionK6AU(estado(true), [], []);
  if (/nadie te está llamando/.test(libreSinOfertas.descripcion) || !libreSinOfertas.descripcion.includes('quedaste sin equipo')
    || (libreSinOfertas.descripcion.match(/¿/g) ?? []).length !== 1) {
    throw new Error(`el free agent sin ofertas repite lo que ya dijo: "${libreSinOfertas.descripcion}"`);
  }
  const atributos = fs.readFileSync(path.join(__dirname, '..', 'systems', 'atributos.js'), 'utf8');
  if (/en el comms/.test(atributos)) {
    throw new Error('el texto del desgaste del shotcalling dice "en el comms" (se dice "en comms")');
  }
  // Mutante: volver a `Seguís en ${ligas}`, a "Y nadie te está llamando" para el free agent, o a "en el comms".
});

// K5c (paso 3b-3) — las metas de §K.3a y §K.3b como checks duros (PLAN.md §K5c, "Decisión del usuario (2026-10-05): cerrar y
// que K6 juzgue"). K5c cierra con los valores fijados (Final2 + LPL 91, `44d4ab4`). Una regla para todas:
// - la banda de una meta [lo, hi] es la meta con su banda de ruido: [lo - Z·σ, hi + Z·σ] (Z = 2, ~95%; σ el desvío de la
//   muestra: el de una proporción, 100·√(p(1-p)/n), o el de una mediana, √(π/2)·s/√n), con el n que dice cada check;
// - una meta que NO llega se re-basa a lo medido (`rebase`): la banda va de la meta a lo medido, más el ruido. Lo que se
//   acerca a la meta pasa; lo que se aleja más que lo medido, o pasa de largo la meta, falla. Cada re-base lleva su línea de
//   la regla 17 ("meta X; medido Y; re-basado por decisión del usuario 2026-10-05, K6 juzga") y está en la tabla de deuda.
// Medido en `k5c-paso3` (`873fc80`), `node --max-old-space-size=12288 src/dev/simulate.js 1500 60 <bot>`. Re-medido al cerrar K5c
// sobre el head final (después de `48ba628`, las cartas de cierre del declive, que corrieron el stream): los números de abajo.
const CARRERAS_METAS_C = 1500;
const Z_RUIDO_METAS_C = 2;
// El desvío de la mediana de una muestra grande: √(π/2)·s/√n (eficiencia asintótica de la mediana bajo normalidad).
const FACTOR_DESVIO_MEDIANA = Math.sqrt(Math.PI / 2);
const METAS_C = {
  // §K.3b "No llega a pro ~20% (como hoy)". Medido 21,5 (n 1500, σ 1,06). Cumple.
  // Regla 17, corrimiento declarado de K6c (el plan del año del amateur): medido 22,6 (n 1500, σ 1,08; banda vieja [17,84, 22,16]).
  // `criterio` pasa toda prueba (juega 0,85 y la vara tope es 0,8), así que la vara por nivel no lo mueve: lo mueve el plan del año
  // (600 × 60: 22,8 en K6b, 24,7 en la primera pasada, 24,5 en la segunda). La banda va de la meta a lo medido: [17,84, 24,76].
  noLlegaAPro: { meta: [20, 20], rebase: 22.6, texto: 'no llega a pro (%)' },
  // §K.3b "Llega a tier 1 ~55-65%". Regla 17: meta 55-65; medido 74,6 (n 1500, σ 1,12); re-basado por decisión del usuario
  // 2026-10-05, K6 juzga (endurecer el acceso a tier 1 baja el Mundial, que está justo en 7%: es la frontera medida).
  llegaATier1: { meta: [55, 65], rebase: 74.6, texto: 'llega a tier 1 (%)' },
  // §K.3b "Gana al menos un título doméstico ~30%". Regla 17: meta 30; medido 55,7 (n 1500, σ 1,28); re-basado por decisión
  // del usuario 2026-10-05, K6 juzga.
  ganaTitulo: { meta: [30, 30], rebase: 55.7, texto: 'gana un título de primera (%)' },
  // §K.3b "Top 20 del mundo alguna vez ~15%". Regla 17: meta 15; medido 36,4 (n 1500, σ 1,24); re-basado por decisión del
  // usuario 2026-10-05, K6 juzga.
  top20: { meta: [15, 15], rebase: 36.4, texto: 'entra al Top 20 del mundo (%)' },
  // §K.3b "Gana al menos un Mundial >= 7% en promedio" (meta del usuario). Medido 7,1 (n 1500, σ 0,66). Cumple, justo:
  // el piso de 7 − 2σ es tolerancia de ruido documentada, y si lo medido queda debajo de 7 el check lo avisa a la vista (no falla).
  ganaMundial: { meta: [7, Infinity], texto: 'gana un Mundial (%)' },
  // §K.3b "desde Corea, más fácil (~12-15%)". Regla 17: meta 12-15; medido 9,9 (n 332, σ 1,64); re-basado por decisión del
  // usuario 2026-10-05, K6 juzga (desde K5c-H cada uno juega en su casa, y la LCK es la primera más dura de entrar).
  // Desde la revisión de K6c se juzga con la región fija ("K6c región fija", 3000 seeds), no con la submuestra del lote.
  ganaMundialCorea: { meta: [12, 15], rebase: 9.9, texto: 'gana un Mundial desde Corea (%)' },
  // §K.3b "desde NA, más difícil (~3-5%)". Regla 17: meta 3-5; medido 7,3 con la región fija (219 de 3000, σ 0,47; en K6b,
  // `58db231`, 6,18 de 3300: ya estaba arriba, la submuestra del lote de 194 daba 3,6 por suerte); re-basado por decisión del
  // usuario 2026-10-06 ("medir bien, aceptar ~7%"): dos tercios de los Mundiales desde NA se ganan importado a LPL/LCK (K5c-H).
  // Se juzga con la región fija ("K6c región fija"), igual que Corea. Corrimiento declarado de K6c.
  ganaMundialNA: { meta: [3, 5], rebase: 7.3, texto: 'gana un Mundial desde Norteamérica (%)' },
  // §K.3b "El nuevo Faker ~2-3% en promedio". Regla 17: meta 2-3; medido 1,2 (n 1500, σ 0,28); re-basado por decisión del
  // usuario 2026-10-05, K6 juzga.
  nuevoFaker: { meta: [2, 3], rebase: 1.2, texto: 'el nuevo Faker (%)' },
  // §K.3b "el nuevo Faker >= 30% entre los de nivel pico de élite (top 3%)". Regla 17: meta >= 30; medido 12,0 (n 100, σ 3,25: 45 de las 1500 y 55 de 1446 carreras extra);
  // re-basado por decisión del usuario 2026-10-05, K6 juzga. La élite es el 3% de la corrida (45 de 1500, donde medía 11,1, σ 4,68:
  // la banda bajaba a ~1,7 y casi no podía fallar): se agranda en rondas con el mismo corte hasta 100 (`MUESTRA_ELITE_METAS_C`; cuesta ~3,5
  // minutos en la validación completa: 1446 carreras a ~0,15 s). Banda [5,5, ∞).
  nuevoFakerElite: { meta: [30, Infinity], rebase: 12, texto: 'el nuevo Faker entre la élite de nivel pico (%)' },
  // §K.3a "Ganaste un Mundial y ganás otro: P(2 o más | 1) >= 35-40%". Regla 17: meta >= 35; medido 16,8 (n 107, σ 3,61);
  // re-basado por decisión del usuario 2026-10-05, K6 juzga.
  pDosOMasDadoUno: { meta: [35, Infinity], rebase: 16.8, texto: 'P(2 o más Mundiales | 1) (%)' },
  // §K.3a "Tu equipo es claramente el más fuerte del Mundial y lo gana ~50%". Regla 17: "claramente" (margen >= 10 sobre el
  // mejor de los otros 15) se dio en 4 de 2963 Mundiales jugados (criterio 1500 × 60, en `873fc80`): sin muestra. Se mide sobre "el más
  // fuerte" (tu fuerza > la del mejor rival): medido 57,5 (n 87, σ 5,3). Cumple ~50 con su ruido.
  elMasFuerteGana: { meta: [50, 50], texto: 'el más fuerte del Mundial lo gana (%)' },
  // §K.3b "Carrera pro mediana ~4-6 años". Regla 17: meta 4-6; medido 8,83 (n 1178 pros, σ 0,13; p10 4, p90 12); re-basado por decisión del
  // usuario 2026-10-05, K6 juzga.
  carreraMediana: { meta: [4, 6], rebase: 8.83, texto: 'carrera pro mediana (años)' },
  // §K.3b "Llega a la línea forzosa de los 34 < 5%". Medido 5,6 (n 1178 pros, σ 0,67): arriba del 5 nominal, adentro de la banda
  // (techo 5 + 2σ = 6,34; en `873fc80` medía 4,8). Cumple con su ruido, con 0,74 puntos de margen (~1,1 σ).
  lineaForzosa: { meta: [-Infinity, 5], texto: 'llega a la línea forzosa de los 34 (% de los pros)' }
};
// §K.3b "Se estanca en tier 2/3: ~10% más, y lo producen las malas decisiones (con `criterio` bastante menos, con `malas`
// bastante más)". El ~10% es el del jugador "normal" (`azar`). Medido al cerrar K5c azar 10,1 (n 1500, σ 0,78); criterio 3,9; malas 15,3.
// Regla 17: meta ~10; medido al cerrar K6b azar 12,5 (n 1500, σ 0,85); criterio 4,9; malas 16,9. Corrimiento declarado de K6b: la
// carta única que cambia de liga, de región o de tier ahora frena (revisión de K6b, caso `cambio`) y `azar` puede rechazarla y quedarse
// sin club, y la vuelta del retiro sin club cambió (va al mercado de su pretemporada y el automático no vuelve debajo del 20% de chance).
// La banda va de la meta a lo medido, con su ruido: [10 − Zσ, 12,5 + Zσ] (≈ [8,29, 14,21] con σ 0,85). `criterio` y `malas` siguen
// separados de `azar` por más de Z σ de la diferencia (4,9 y 16,9 contra 12,5).
const META_C_ESTANCADO_AZAR_PCT = 10;
const META_C_ESTANCADO_AZAR_REBASE_PCT = 12.5;
// La meta del usuario (2026-10-05, PLAN.md §K5c "El paso 3, concreto"): la LCK gana >= 25% de los Mundiales del mundo y es la
// primera con un margen >= 5 puntos sobre la segunda. El 25% va sin banda (el número del usuario). El margen va con su banda de
// ruido, >= 5 − 2σ (hallazgo de la revisión al cerrar K5c: sin banda, un corrimiento del stream lo ponía rojo sin que nada
// cambiara), con σ calculado en cada corrida contando cada carrera como un conglomerado (`sigmaDelMargenMetasC`). Medido al cerrar
// K5c: LCK 51,6 / LPL 43,8 / LEC 3,9 (17867 Mundiales del mundo en 1500 carreras), margen 7,74 con σ 0,84 por carrera (0,73
// contando cada Mundial como independiente; el ≈ 2,5 que decía este comentario estaba sobreestimado): piso 5 − 1,68 = 3,32.
const META_C_LCK_REPARTO_PCT = 25;
const META_C_LCK_MARGEN_PP = 5;
const LIGA_CANDIDATA_DEL_MUNDIAL = 'LCK';
// Las regiones de origen de las dos metas por región (`mundo.regionOrigen`, la clave de `mundialReal.porRegion`).
const REGION_FACIL_METAS_C = 'Corea';
const REGION_DIFICIL_METAS_C = 'Norteamérica';
const {
  desvioMuestral: desvioMuestralMetasC, duracionProDe: duracionProDeMetasC, correrCarrera: correrCarreraMetasC, esNuevoFaker: esNuevoFakerMetasC,
  nivelPicoDe: nivelPicoDeMetasC, corteDeElite: corteDeEliteMetasC, ligaDelCampeonMundial: ligaDelCampeonMetasC
} = await import('./simulate.js');
const { ESTRATEGIAS: ESTRATEGIAS_METAS_C } = await import('./estrategias.js');

// K5c (cierre, hallazgo de la revisión): la élite de nivel pico (el top 3% de la corrida) en 1500 carreras son ~45, y con esa
// muestra la banda de la meta re-basada bajaba a ~3: casi no podía fallar. Se agranda en rondas: las seeds que siguen a la corrida
// (1501, 1502, ...) con `criterio` y el MISMO corte de nivel pico (el de las 1500), hasta juntar `minima` carreras de élite o
// `maxExtra` carreras extra. De cada carrera extra queda solo si entra a la élite y si es el nuevo Faker (nada en memoria).
const MUESTRA_ELITE_METAS_C = { minima: 100, maxExtra: 6000 };
function eliteAgrandadaMetasC(resultados, observaciones, estrategia) {
  const corte = corteDeEliteMetasC(resultados);
  let elite = 0;
  let fakers = 0;
  resultados.forEach((estado, i) => {
    if (nivelPicoDeMetasC(estado) < corte) return;
    elite += 1;
    fakers += esNuevoFakerMetasC(estado, observaciones[i]) ? 1 : 0;
  });
  let extra = 0;
  while (elite < MUESTRA_ELITE_METAS_C.minima && extra < MUESTRA_ELITE_METAS_C.maxExtra) {
    extra += 1;
    const { state, observacion } = correrCarreraMetasC(CARRERAS_METAS_C + extra, SPLITS_LOTE_K0, ESTRATEGIAS_METAS_C[estrategia]);
    if (nivelPicoDeMetasC(state) < corte) continue;
    elite += 1;
    fakers += esNuevoFakerMetasC(state, observacion) ? 1 : 0;
  }
  return { valor: elite > 0 ? Number((100 * fakers / elite).toFixed(1)) : null, n: elite, extra, corte };
}

// El σ del margen LCK − segunda, contando cada carrera (cada mundo) como un conglomerado: los Mundiales de un mismo mundo no son
// independientes. Estimador de razón: margen = Σ(a_i − b_i) / ΣW_i, σ = 100·√Σ(a_i − b_i − margen·W_i)² / ΣW_i.
function sigmaDelMargenMetasC(observaciones, segundaLiga) {
  const filas = observaciones.map((o) => {
    const ligas = (o?.mundialesDelMundo ?? []).map(ligaDelCampeonMetasC);
    return { d: ligas.filter((l) => l === LIGA_CANDIDATA_DEL_MUNDIAL).length - ligas.filter((l) => l === segundaLiga).length, w: ligas.length };
  });
  const W = filas.reduce((suma, f) => suma + f.w, 0);
  if (W === 0) return null;
  const margen = filas.reduce((suma, f) => suma + f.d, 0) / W;
  return 100 * Math.sqrt(filas.reduce((suma, f) => suma + (f.d - margen * f.w) ** 2, 0)) / W;
}

const sigmaDeProporcion = (pctValor, n) => (n > 0 && Number.isFinite(pctValor) ? 100 * Math.sqrt((pctValor / 100) * (1 - pctValor / 100) / n) : null);

function bandaDeMetaC(clave, sigma) {
  const { meta: [lo, hi], rebase } = METAS_C[clave];
  return [Math.min(lo, rebase ?? lo) - Z_RUIDO_METAS_C * sigma, Math.max(hi, rebase ?? hi) + Z_RUIDO_METAS_C * sigma];
}

const redondeoMetasC = (x) => (Number.isFinite(x) ? Number(x.toFixed(2)) : x);

// El juez: null si cumple, el motivo si no. `v[clave]` = { valor, sigma } (las metas de `METAS_C`); las relaciones traen lo
// suyo. Un valor o un σ que no existe (muestra vacía) no cumple.
function juezDeLasMetasC(v) {
  const hay = (x) => typeof x === 'number' && Number.isFinite(x);
  const juicio = {};
  for (const clave of Object.keys(METAS_C)) {
    const { valor, sigma } = v[clave] ?? {};
    if (!hay(valor) || !hay(sigma)) {
      juicio[clave] = `${METAS_C[clave].texto}: sin valor o sin muestra (${valor}, σ ${sigma})`;
      continue;
    }
    const [desde, hasta] = bandaDeMetaC(clave, sigma);
    const { meta: [lo, hi], rebase } = METAS_C[clave];
    juicio[clave] = valor >= desde && valor <= hasta ? null
      : `${METAS_C[clave].texto} = ${valor}, la banda es [${redondeoMetasC(desde)}, ${redondeoMetasC(hasta)}] (meta [${lo}, ${hi}]${rebase === undefined ? '' : `, re-basada a ${rebase}`}, σ ${redondeoMetasC(sigma)})`;
  }
  // Los estancados: `azar` ~10% con su ruido, `criterio` bastante menos y `malas` bastante más ("bastante" = más que Z σ de la
  // diferencia).
  const e = v.estancados ?? {};
  const sigmaE = (a, b) => Math.sqrt(sigmaDeProporcion(a, e.n) ** 2 + sigmaDeProporcion(b, e.n) ** 2);
  const sigmaAzar = sigmaDeProporcion(e.azar, e.n);
  const bandaAzar = [
    Math.min(META_C_ESTANCADO_AZAR_PCT, META_C_ESTANCADO_AZAR_REBASE_PCT) - Z_RUIDO_METAS_C * sigmaAzar,
    Math.max(META_C_ESTANCADO_AZAR_PCT, META_C_ESTANCADO_AZAR_REBASE_PCT) + Z_RUIDO_METAS_C * sigmaAzar
  ];
  juicio.estancadoAzar = hay(e.azar) && hay(sigmaAzar) && e.azar >= bandaAzar[0] && e.azar <= bandaAzar[1] ? null
    : `azar se estanca en tier 2/3 el ${e.azar}%, la banda es [${redondeoMetasC(bandaAzar[0])}, ${redondeoMetasC(bandaAzar[1])}] (meta ~${META_C_ESTANCADO_AZAR_PCT}%, re-basada a ${META_C_ESTANCADO_AZAR_REBASE_PCT}, σ ${redondeoMetasC(sigmaAzar)}, n ${e.n})`;
  juicio.estancadoCriterio = hay(e.criterio) && hay(e.azar) && e.criterio <= e.azar - Z_RUIDO_METAS_C * sigmaE(e.criterio, e.azar) ? null
    : `criterio se estanca el ${e.criterio}% y azar el ${e.azar}%: criterio tiene que quedar más de ${Z_RUIDO_METAS_C} σ abajo (σ ${redondeoMetasC(sigmaE(e.criterio, e.azar))})`;
  juicio.estancadoMalas = hay(e.malas) && hay(e.azar) && e.malas >= e.azar + Z_RUIDO_METAS_C * sigmaE(e.malas, e.azar) ? null
    : `malas se estanca el ${e.malas}% y azar el ${e.azar}%: malas tiene que quedar más de ${Z_RUIDO_METAS_C} σ arriba (σ ${redondeoMetasC(sigmaE(e.malas, e.azar))})`;
  // "Depende de la región": desde Corea se gana más que desde NA, por más que el ruido de la diferencia.
  const r = v.porRegion ?? {};
  const sigmaR = Math.sqrt((sigmaDeProporcion(r.facil, r.nFacil) ?? NaN) ** 2 + (sigmaDeProporcion(r.dificil, r.nDificil) ?? NaN) ** 2);
  juicio.regionOrdenada = hay(r.facil) && hay(r.dificil) && hay(sigmaR) && r.facil - r.dificil >= Z_RUIDO_METAS_C * sigmaR ? null
    : `desde ${REGION_FACIL_METAS_C} se gana el Mundial el ${r.facil}% y desde ${REGION_DIFICIL_METAS_C} el ${r.dificil}%: tiene que ser más fácil por más de ${Z_RUIDO_METAS_C} σ (σ ${redondeoMetasC(sigmaR)})`;
  // La meta del usuario, sin banda.
  const m = v.mundoMundial ?? {};
  juicio.lckReparto = hay(m.lck) && m.lck >= META_C_LCK_REPARTO_PCT ? null
    : `la ${LIGA_CANDIDATA_DEL_MUNDIAL} gana el ${m.lck}% de los Mundiales del mundo, la meta del usuario es >= ${META_C_LCK_REPARTO_PCT}%`;
  // El margen: los 5 puntos nominales del usuario con su banda de ruido (>= 5 − Z σ, σ del margen por carrera). Sin σ, no cumple.
  const pisoMargen = hay(m.sigmaMargen) ? META_C_LCK_MARGEN_PP - Z_RUIDO_METAS_C * m.sigmaMargen : NaN;
  juicio.lckMargen = hay(m.lck) && hay(m.segunda) && hay(pisoMargen) && m.lck - m.segunda >= pisoMargen ? null
    : `la ${LIGA_CANDIDATA_DEL_MUNDIAL} gana el ${m.lck}% y la segunda (${m.segundaLiga}) el ${m.segunda}%: la meta del usuario es primera por >= ${META_C_LCK_MARGEN_PP} puntos (piso con ruido ${redondeoMetasC(pisoMargen)}, σ ${m.sigmaMargen})`;
  return juicio;
}

// Los valores de las metas sobre los lotes (criterio, y azar y malas para los estancados), cada uno corrido una vez y soltado:
// quedan solo los números (tres lotes de 1500 con sus crudos no tienen por qué vivir juntos en memoria).
let valoresMetasC = null;
function valoresDeLasMetasC() {
  if (valoresMetasC !== null) return valoresMetasC;
  const estancado = {};
  let v = null;
  for (const bot of ['criterio', 'azar', 'malas']) {
    const lote = correrLote(CARRERAS_METAS_C, SPLITS_LOTE_K0, bot);
    afirmarRuidoIntactoK0(`después de correrLote(${CARRERAS_METAS_C}, ${bot})`);
    estancado[bot] = lote.embudo.estancadoT2T3;
    if (bot !== 'criterio') continue;
    const n = lote.crudos.resultados.length;
    const pros = lote.crudos.resultados.filter((st) => st.splitFichaje !== null);
    const aniosPro = pros.map((st) => duracionProDeMetasC(st) / BALANCE.edad.splitsPorEdad);
    const mr = lote.mundialReal;
    const region = (nombre) => mr.porRegion[nombre] ?? { ganaMundialPct: null, carreras: 0 };
    const prop = (valor, nMuestra) => ({ valor, sigma: sigmaDeProporcion(valor, nMuestra), n: nMuestra });
    const ligas = Object.entries(lote.mundoMundial.titulosPorLiga).sort((a, b) => b[1].pct - a[1].pct);
    const otras = ligas.filter(([liga]) => liga !== LIGA_CANDIDATA_DEL_MUNDIAL);
    const p21 = mr.total.pDosOMasDadoUno;
    v = {
      // K6b (integración): la cola de la carrera y las leyendas se miden sobre este mismo lote de `criterio` (el check "K6b-C meta de
      // la cola"): con 400 carreras el promedio no separaba al mutante de la banda por 1 σ.
      colaK6BC: lote.ritmo.colaDeCarrera, leyendaK6BC: lote.ritmo.leyenda,
      noLlegaAPro: prop(lote.embudo.noLlegaAPro, n),
      llegaATier1: prop(lote.embudo.llegaATier1, n),
      ganaTitulo: prop(lote.embudo.ganaTituloDomestico, n),
      top20: prop(lote.embudo.top20, n),
      ganaMundial: prop(mr.total.ganaMundialPct, n),
      ganaMundialCorea: prop(region(REGION_FACIL_METAS_C).ganaMundialPct, region(REGION_FACIL_METAS_C).carreras),
      ganaMundialNA: prop(region(REGION_DIFICIL_METAS_C).ganaMundialPct, region(REGION_DIFICIL_METAS_C).carreras),
      nuevoFaker: prop(mr.total.nuevoFakerPct, n),
      nuevoFakerElite: (() => {
        const e = eliteAgrandadaMetasC(lote.crudos.resultados, lote.crudos.observaciones, bot);
        return { ...prop(e.valor, e.n), extra: e.extra };
      })(),
      pDosOMasDadoUno: prop(p21.p === null ? null : redondeoMetasC(100 * p21.p), p21.n),
      elMasFuerteGana: prop(mr.total.elMasFuerte.pctGana, mr.total.elMasFuerte.mundiales),
      carreraMediana: {
        valor: redondeoMetasC(lote.longevidad.aniosCarreraPro.mediana),
        sigma: aniosPro.length > 1 ? FACTOR_DESVIO_MEDIANA * desvioMuestralMetasC(aniosPro) / Math.sqrt(aniosPro.length) : null,
        n: aniosPro.length
      },
      lineaForzosa: prop(lote.longevidad.pctTerminaEnLineaForzosa34, pros.length),
      porRegion: {
        facil: region(REGION_FACIL_METAS_C).ganaMundialPct, nFacil: region(REGION_FACIL_METAS_C).carreras,
        dificil: region(REGION_DIFICIL_METAS_C).ganaMundialPct, nDificil: region(REGION_DIFICIL_METAS_C).carreras
      },
      mundoMundial: {
        mundiales: lote.mundoMundial.mundiales,
        lck: lote.mundoMundial.titulosPorLiga[LIGA_CANDIDATA_DEL_MUNDIAL]?.pct,
        segunda: otras[0]?.[1].pct,
        segundaLiga: otras[0]?.[0],
        sigmaMargen: redondeoMetasC(sigmaDelMargenMetasC(lote.crudos.observaciones, otras[0]?.[0])),
        // La mejor del oeste puede ganar (> 0): se reporta, no se exige (PLAN.md §K5c, "El paso 3, concreto").
        reparto: ligas.map(([liga, { pct }]) => `${liga} ${pct}`).join(' / ')
      }
    };
  }
  afirmarRuidoIntactoK0('después de la élite agrandada de las metas C');
  valoresMetasC = { ...v, estancados: { ...estancado, n: CARRERAS_METAS_C } };
  const lineas = Object.keys(METAS_C).map((clave) => {
    const { valor, sigma, n } = valoresMetasC[clave];
    const [desde, hasta] = bandaDeMetaC(clave, sigma ?? NaN);
    return `${clave} ${valor} (n ${n}, σ ${redondeoMetasC(sigma)}, banda [${redondeoMetasC(desde)}, ${redondeoMetasC(hasta)}])`;
  });
  console.log(`     (muestra: ${CARRERAS_METAS_C} × ${SPLITS_LOTE_K0} por bot) ${lineas.join(' · ')} · estancados criterio/azar/malas `
    + `${estancado.criterio}/${estancado.azar}/${estancado.malas} · élite ${valoresMetasC.nuevoFakerElite.n} carreras (${valoresMetasC.nuevoFakerElite.extra} extra) `
    + `· Mundiales del mundo ${valoresMetasC.mundoMundial.mundiales}: ${valoresMetasC.mundoMundial.reparto} · margen ${LIGA_CANDIDATA_DEL_MUNDIAL} − `
    + `${valoresMetasC.mundoMundial.segundaLiga} ${redondeoMetasC(valoresMetasC.mundoMundial.lck - valoresMetasC.mundoMundial.segunda)} (nominal `
    + `${META_C_LCK_MARGEN_PP}, σ ${valoresMetasC.mundoMundial.sigmaMargen}, piso ${redondeoMetasC(META_C_LCK_MARGEN_PP - Z_RUIDO_METAS_C * valoresMetasC.mundoMundial.sigmaMargen)})`);
  return valoresMetasC;
}

function problemasDeLasMetasC(claves) {
  const juicio = juezDeLasMetasC(valoresDeLasMetasC());
  return claves.map((clave) => juicio[clave]).filter((motivo) => motivo !== null);
}

// Los valores medidos (k5c-paso3 al cerrar K5c, criterio/azar/malas 1500 × 60): cumplen.
const VALORES_DE_LAS_METAS_C_OK = {
  noLlegaAPro: { valor: 21.5, sigma: 1.06 }, llegaATier1: { valor: 74.6, sigma: 1.12 }, ganaTitulo: { valor: 55.7, sigma: 1.28 },
  top20: { valor: 36.4, sigma: 1.24 }, ganaMundial: { valor: 7.1, sigma: 0.66 }, ganaMundialCorea: { valor: 9.9, sigma: 1.64 },
  ganaMundialNA: { valor: 3.6, sigma: 1.34 }, nuevoFaker: { valor: 1.2, sigma: 0.28 }, nuevoFakerElite: { valor: 12, sigma: 3.25 },
  pDosOMasDadoUno: { valor: 16.8, sigma: 3.61 }, elMasFuerteGana: { valor: 57.5, sigma: 5.3 }, carreraMediana: { valor: 8.83, sigma: 0.13 },
  lineaForzosa: { valor: 5.6, sigma: 0.67 },
  // Cierre de K6b: los estancados, re-medidos (corrimiento declarado de K6b, ver META_C_ESTANCADO_AZAR_REBASE_PCT).
  estancados: { criterio: 4.9, azar: 12.5, malas: 16.9, n: 1500 },
  porRegion: { facil: 9.9, nFacil: 332, dificil: 3.6, nDificil: 194 },
  mundoMundial: { lck: 51.6, segunda: 43.8, segundaLiga: 'LPL', sigmaMargen: 0.84 }
};

check('K5c metas del bloque C: el juez acepta los valores medidos y rechaza, uno por uno, cada valor fuera de su banda o inexistente (regla 7)', () => {
  const ok = VALORES_DE_LAS_METAS_C_OK;
  const sano = Object.values(juezDeLasMetasC(ok)).filter((motivo) => motivo !== null);
  if (sano.length > 0) throw new Error(`el juez rechaza valores que cumplen: ${sano.join('; ')}`);
  const rechazaSolo = (clave, valores, que) => {
    const rechazados = Object.entries(juezDeLasMetasC(valores)).filter(([, motivo]) => motivo !== null).map(([k]) => k);
    if (rechazados.length !== 1 || rechazados[0] !== clave) {
      throw new Error(`${que}: el juez rechazó [${rechazados.join(', ')}], tenía que rechazar solo ${clave}`);
    }
  };
  const PASO_AFUERA = 0.01;
  // Cada meta: un valor justo afuera de cada borde finito de su banda (con el σ medido) y uno inexistente no cumplen; los
  // bordes sí (inclusivos).
  for (const clave of Object.keys(METAS_C)) {
    const { sigma } = ok[clave];
    const [desde, hasta] = bandaDeMetaC(clave, sigma);
    const afuera = [...(Number.isFinite(desde) ? [desde - PASO_AFUERA] : []), ...(Number.isFinite(hasta) ? [hasta + PASO_AFUERA] : []), null];
    for (const valor of afuera) {
      rechazaSolo(clave, { ...ok, [clave]: { valor, sigma } }, `${clave} = ${valor}`);
    }
    rechazaSolo(clave, { ...ok, [clave]: { valor: ok[clave].valor, sigma: null } }, `${clave} sin σ`);
    for (const borde of [desde, hasta].filter(Number.isFinite)) {
      if (juezDeLasMetasC({ ...ok, [clave]: { valor: borde, sigma } })[clave] !== null) throw new Error(`${clave} = ${borde} (el borde) no cumple`);
    }
  }
  // Una meta re-basada: el valor de la meta misma cumple (acercarse a la meta nunca falla) y uno que la pasa de largo, no.
  rechazaSolo('llegaATier1', { ...ok, llegaATier1: { valor: 50, sigma: 1.13 } }, 'llegaATier1 = 50 (pasó de largo la meta 55-65)');
  if (juezDeLasMetasC({ ...ok, llegaATier1: { valor: 60, sigma: 1.13 } }).llegaATier1 !== null) throw new Error('llegaATier1 = 60 (en la meta) no cumple');
  // Cierre de K6b: la banda de azar va de la meta (10) a lo medido (12,5): 15 se pasa por arriba y 8 por abajo; la meta misma cumple.
  rechazaSolo('estancadoAzar', { ...ok, estancados: { ...ok.estancados, azar: 15, malas: 20 } }, 'azar 15');
  rechazaSolo('estancadoAzar', { ...ok, estancados: { ...ok.estancados, azar: 8 } }, 'azar 8');
  if (juezDeLasMetasC({ ...ok, estancados: { ...ok.estancados, azar: META_C_ESTANCADO_AZAR_PCT } }).estancadoAzar !== null) throw new Error('azar en la meta (' + META_C_ESTANCADO_AZAR_PCT + ') no cumple');
  rechazaSolo('estancadoCriterio', { ...ok, estancados: { ...ok.estancados, criterio: 11 } }, 'criterio 11');
  rechazaSolo('estancadoMalas', { ...ok, estancados: { ...ok.estancados, malas: 11 } }, 'malas 11');
  rechazaSolo('regionOrdenada', { ...ok, porRegion: { ...ok.porRegion, facil: 5 } }, 'Corea 5 contra NA 3,1');
  const mm = ok.mundoMundial;
  rechazaSolo('lckReparto', { ...ok, mundoMundial: { ...mm, lck: 24, segunda: 18 } }, 'LCK 24');
  // El margen: el piso es 5 − 2σ (con σ 0,84, 3,32). Justo debajo del piso no cumple; justo arriba y los 5 nominales sí; sin σ, no.
  const pisoMargen = META_C_LCK_MARGEN_PP - Z_RUIDO_METAS_C * mm.sigmaMargen;
  rechazaSolo('lckMargen', { ...ok, mundoMundial: { ...mm, lck: 25, segunda: 25 - pisoMargen + PASO_AFUERA } }, `margen ${pisoMargen - PASO_AFUERA}`);
  rechazaSolo('lckMargen', { ...ok, mundoMundial: { ...mm, sigmaMargen: null } }, 'margen sin σ');
  for (const margen of [pisoMargen + PASO_AFUERA, META_C_LCK_MARGEN_PP]) {
    if (juezDeLasMetasC({ ...ok, mundoMundial: { ...mm, lck: 25, segunda: 25 - margen } }).lckMargen !== null) {
      throw new Error(`LCK 25 contra ${25 - margen} (margen ${margen}, justo arriba del piso o el nominal) no cumple`);
    }
  }
});

